/* ============================================================
   ACCOUNTANCY BY ABHINASH — APPLICATION LOGIC
   Sections: State & Storage | Utilities | Router | Views |
   Equation Tools | Search | Gamification | Floating Tools
   ============================================================ */

/* ---------------------------------------------------------
   1. STATE & PERSISTENCE (localStorage-backed)
   --------------------------------------------------------- */
const STORE_KEY = "abhinash_accountancy_v1";

const defaultState = {
  theme: "light",
  colorTheme: "classic",
  fontScale: 1,
  colorblind: false,
  highContrast: false,
  reduceMotion: false,
  soundOn: true,
  xp: 0,
  xpGained: 0,             // lifetime running total of every positive XP award (never decreases)
  xpDeducted: 0,           // lifetime running total of every XP penalty (never decreases)
  streak: 0,
  lastActiveDate: null,
  studySeconds: 0,
  chapterProgress: { intro: 0, terms: 0, tbase: 0, basis: 0, eq: 0, dc: 0, jr: 0, lg: 0, cb: 0, sp2: 0, brs: 0, gst: 0, tb: 0, dep: 0, pres: 0, roe: 0, fs: 0, adj: 0 },
  solved: {},              // { "eq-12": {correct:true, attempts:1, time:34} }
  bookmarks: [],
  mistakes: [],            // ids of missed questions (legacy — kept for compatibility)
  mistakeBook: {},         // { key: { key, question, chapter, chapterLabel, topic, type,
                            //   studentAnswer, correctAnswer, explanation, firstMistakeAt,
                            //   lastAttemptAt, mistakeCount, correctAfterMistakeCount,
                            //   correctStreak, status: "review"|"improved"|"mastered" } }
  badges: [],
  bestScores: {},
  activityLog: [],         // Recent Activity — structured clickable entries:
                           // { id, at, type, text, route, tab, qid, qidNoun,
                           //   chapterId, difficulty, status, key }. Plain
                           // legacy { text, at } rows are still accepted.
  xpOnce: {},              // XP once/daily claims — the anti-farming registry
                           // read/written only through the gates below and
                           // ui-features.js (once-ever claims are permanent,
                           // per-day counters are pruned on load)
  aboutToastDone: false,   // the first-visit "About this website" toast has been shown
  panelPositions: {},      // { floatingCalc: {top, left}, scratchPad: {...}, pomodoroPanel: {...} } — persisted drag positions
  aiChats: [],             // [{ id, title, messages: [{role,text,image?,ts}], updatedAt, chapterContext }]
  aiActiveChatId: null,
  lastChapterViewed: null,
  userName: null,          // set via first-visit welcome flow; null = not onboarded yet
  selectedClass: null,     // "11" | "12" — the class chosen in the first-visit selector
                           // (or adopted from a direct chapter link). null = undecided.
  classSelectedAt: null,   // when the class choice was made (for the settings display)
  c12Activities: {},       // Class 12 chapter activities already completed & awarded
                           // ({ chId: true }) — the one-XP-per-activity registry
  guide: {},               // v94 guided-learning records, keyed by chapter route id:
                           // { learnAt, understandAt, rememberAt,            (real
                           //   readiness: { picked, correct, at },            activity
                           //   recall: { "<i>": true|false },                 timestamps)
                           //   lastTab, lastTabAt, lastStudiedAt }            (navigation)
                           // Practise-stage completion is NEVER stored here —
                           // it is computed from STATE.solved via chapterProgress.
  onboardedAt: null,
  notificationsEnabled: false,
  notifyHour: 8,           // 0-23, local hour; daily reminder arrives within this hour
  notificationsPromptDismissed: false,
};

let STATE = loadState();
// Backfill chapterProgress for any chapter added after a user's state was
// first saved (e.g. this new "intro" chapter) — a plain Object.assign
// merge in loadState() won't add missing keys to an existing nested object.
// v83: covers BOTH classes, so a new student's Class 12 chapters are
// tracked from the very first load and Class 11 keeps its history.
(ClassRegistry.chapterIdsOf("11").concat(ClassRegistry.chapterIdsOf("12"))).forEach(c => { if (typeof STATE.chapterProgress[c] !== "number") STATE.chapterProgress[c] = 0; });
// Migration safety: existing saved state (from before Chapter 5 existed)
// has a chapterProgress object that fully overwrote the default via the
// shallow Object.assign in loadState(), so it may be missing the "cb"
// key entirely. Backfill it so per-chapter averages never turn into NaN.
if (STATE.chapterProgress && STATE.chapterProgress.cb === undefined) STATE.chapterProgress.cb = 0;

function loadState() {
  try {
    const raw = localStorage.getItem(STORE_KEY);
    if (!raw) return structuredClone(defaultState);
    const parsed = JSON.parse(raw);
    const merged = Object.assign(structuredClone(defaultState), parsed);
    if (!Array.isArray(merged.bookmarks)) merged.bookmarks = [];
    else merged.bookmarks = [...new Set(merged.bookmarks)];   // one entry per question, ever
    /* Recent Activity can hold rows from any older release: plain
       strings, nulls or objects without text. Keep anything readable
       (plain strings still render as non-clickable history), drop
       only what is corrupt, and never let a bad log crash the page. */
    if (!Array.isArray(merged.activityLog)) merged.activityLog = [];
    else merged.activityLog = merged.activityLog.filter(e =>
      (typeof e === "string" && e.trim()) ||
      (e && typeof e === "object" && typeof e.text === "string" && e.text.trim()));
    /* XP registry: must be an object; stale per-day counters older
       than a few days are pruned so the saved state stays small.
       Once-ever claims are never pruned. */
    if (!merged.xpOnce || typeof merged.xpOnce !== "object") merged.xpOnce = {};
    if (typeof window !== "undefined" && window.UIFeatures) UIFeatures.prune(merged.xpOnce, Date.now(), 4);
    if (typeof merged.aboutToastDone !== "boolean") merged.aboutToastDone = !!merged.aboutToastDone;
    /* Class selection: only the two known values survive a reload;
       anything else (older states, corrupt data) resets to undecided
       so the selector can re-ask instead of crashing navigation. */
    if (merged.selectedClass !== "11" && merged.selectedClass !== "12") merged.selectedClass = null;
    return merged;
  } catch (e) {
    return structuredClone(defaultState);
  }
}
function saveState() {
  try { localStorage.setItem(STORE_KEY, JSON.stringify(STATE)); } catch (e) { /* storage full or blocked */ }
  // Every Mistake Book change (record / review / delete / clear / reset) ends in saveState(),
  // so refreshing the alert here keeps it correct without wiring each call site separately.
  refreshMistakeAlert();
}

/* ---------------------------------------------------------
   1b. CLASS SYSTEM (v83) — Class 11 / Class 12
   One site, two syllabuses. STATE.selectedClass decides which
   chapter list every screen shows. All rules live here:

   - activeClass()      "11" | "12" | null (undecided)
   - activeChapters()   the chapter directory for the chosen class
   - needsClassSelection()  true only for a brand-new visitor who
     has never chosen a class and has never used the site
   - adoptClassFromRoute()  a direct chapter link silently selects
     that chapter's class — never a prompt loop
   - setActiveClass()   persists the choice, resets transient
     per-screen filters, rebuilds the sidebar chapter list

   Progress, bookmarks, mistakes and solved answers are keyed by
   chapter/question ids, and the two classes' ids never collide
   (asserted in tests/class-system-tests.js), so switching
   classes can never reset or mix a student's Class 11 record.
   --------------------------------------------------------- */
function activeClass() {
  return ClassRegistry.normalizeClass(STATE.selectedClass);
}
function activeChapters() {
  return ClassRegistry.chaptersOf(activeClass() || ClassRegistry.CLASS_11);
}
function activeChapterIds() {
  return activeChapters().map(c => c.id);
}
function activeChapterMap() {
  const map = {};
  activeChapters().forEach(c => { map[c.id] = c; });
  return map;
}
/* Any class's chapter meta (used where a stored record may point at
   the other class, e.g. a bookmarked question opened after switching). */
function chapterMetaOf(id) { return ClassRegistry.chapterMeta(id); }
function chapterTitleOf(id) {
  const m = ClassRegistry.chapterMeta(id);
  return m ? m.name : (id || "");
}
/* Chapter chip background class — the same `c-<id>-soft` naming the
   Class 11 chapters use; Class 12 variables are defined in styles.css. */
function chapterSoftVar(id) { return "c-" + id + "-soft"; }

/* A student who already used the site (name, XP, progress, anything)
   predates the class selector — their content was always Class 11, so
   adopt it silently instead of asking. A visitor with no saved usage
   at all is a genuine first-timer and gets the selector on home. */
function ensureClassForBoot() {
  if (activeClass()) return activeClass();
  const usedBefore = !!(STATE.userName || STATE.xp || STATE.bookmarks.length ||
    Object.keys(STATE.mistakeBook || {}).length ||
    Object.values(STATE.chapterProgress || {}).some(p => p > 0));
  if (usedBefore) {
    STATE.selectedClass = ClassRegistry.CLASS_11;
    saveState();
    return activeClass();
  }
  return null;   // undecided first-timer — selector shows on home
}
function needsClassSelection() {
  if (activeClass()) return false;
  return ensureClassForBoot() === null;
}

/* Transient, per-screen filters that would leak the wrong class's
   chapters into the next screen after a switch. */
function resetClassScopedFilters() {
  if (typeof quizState !== "undefined" && quizState) { quizState.chapters = ["all"]; }
  if (typeof flashState !== "undefined" && flashState) { flashState.chapter = "all"; }
  if (typeof iqState !== "undefined" && iqState) { iqState.chapter = "all"; }
}

let CLASS_SWITCH_TOAST = true;   // silent when adopting from a direct link
function setActiveClass(cls, opts) {
  opts = opts || {};
  const next = ClassRegistry.normalizeClass(cls);
  if (!next) return null;
  const changed = STATE.selectedClass !== next;
  STATE.selectedClass = next;
  if (changed) STATE.classSelectedAt = Date.now();
  saveState();
  if (changed) resetClassScopedFilters();
  if (typeof rebuildChapterNav === "function") rebuildChapterNav();
  refreshFlashChapterLabels();
  refreshQuizChapterLabels();
  if (typeof refreshSearchIndex === "function") refreshSearchIndex();
  if (typeof updateNavProgress === "function") updateNavProgress();
  if (changed && opts.toast !== false && CLASS_SWITCH_TOAST && typeof toast === "function") {
    toast("Switched to " + ClassRegistry.CLASS_META[next].shortLabel +
      " — your other class's progress is saved.");
  }
  if (opts.rerender !== false && typeof renderRoute === "function") renderRoute();
  return next;
}

/* Direct visit to a chapter route (or the Class 12 chapter index):
   open the class that page belongs to, silently and persistently —
   no repeated prompts. */
function adoptClassFromRoute(route) {
  let cls = null;
  if (route === "chapters-list-12") cls = ClassRegistry.CLASS_12;
  else if (route && route.indexOf("ch-") === 0) cls = ClassRegistry.classOfChapterId(route.slice(3));
  if (!cls) return false;
  if (STATE.selectedClass === cls) return false;
  const hadChoice = !!activeClass();
  STATE.selectedClass = cls;
  STATE.classSelectedAt = Date.now();
  saveState();
  resetClassScopedFilters();
  if (typeof rebuildChapterNav === "function") rebuildChapterNav();
  refreshFlashChapterLabels();
  refreshQuizChapterLabels();
  if (typeof refreshSearchIndex === "function") refreshSearchIndex();
  return !hadChoice;   // only "newly adopted", for logging/tests
}

/* ---------------------------------------------------------
   2. UTILITIES
   --------------------------------------------------------- */
/* ---------------------------------------------------------
   1c. PWA INSTALLABILITY — capture the browser's install prompt
   so the Home page can offer a real "Install" button instead of
   relying on the user to find their browser's menu option.
   --------------------------------------------------------- */
let deferredInstallPrompt = null;
window.addEventListener("beforeinstallprompt", (e) => {
  e.preventDefault();
  deferredInstallPrompt = e;
});
window.addEventListener("appinstalled", () => {
  deferredInstallPrompt = null;
  localStorage.setItem("aba_install_dismissed", "1");
});
function isStandalone() {
  return window.matchMedia("(display-mode: standalone)").matches || window.navigator.standalone === true;
}
function isIOS() {
  return /iphone|ipad|ipod/i.test(navigator.userAgent) && !window.MSStream;
}

/* ---------------------------------------------------------
   1d. NOTIFICATIONS (v87) — genuine Web Push, server-scheduled.
   The full subscription lifecycle (capability check → permission →
   service worker → VAPID key → subscribe → server confirm) lives in
   push-manager.js (window.ABAPush). This block only keeps the thin
   wrappers the rest of app.js already calls, plus a LOCAL fallback
   reminder timer that runs only when server push is NOT active
   (legacy/edge cases) — server push is always the primary system.
   --------------------------------------------------------- */

function pushSupported() {
  if (window.ABAPush) return ABAPush.status().supported;
  return "Notification" in window;
}
function currentTzOffsetMinutes() {
  // JS getTimezoneOffset() is UTC-minus-local (backwards from how people
  // think about it) — flip the sign so +330 really means "IST, 5.5h ahead".
  return -new Date().getTimezoneOffset();
}
function buildNotifyContext() {
  const order = activeChapterIds();
  const chapterMap = activeChapterMap();
  const contId = pickContinueTarget ? pickContinueTarget() : order.find(id => (STATE.chapterProgress[id] || 0) < 100);
  const ch = chapterMap[contId];
  return {
    name: STATE.userName || null,
    tzOffsetMinutes: currentTzOffsetMinutes(),
    notifyHour: STATE.notifyHour,
    streak: STATE.streak || 0,
    chapterContext: ch ? { id: ch.id, name: ch.name } : null,
  };
}

/* LOCAL fallback reminder — fires only while THIS page is open, and
   only when server push is not handling delivery (ABAPush inactive).
   It is the honest last-resort path, never the primary system. */
let localReminderTimer = null;
function localReminderBody() {
  const ctx = buildNotifyContext();
  const name = ctx.name ? ", " + ctx.name : "";
  const streak = ctx.streak > 0 ? ` You're on a ${ctx.streak}-day streak — keep it alive!` : "";
  const ch = ctx.chapterContext ? ` Continue: ${ctx.chapterContext.name}.` : "";
  return `Hi${name} — time for today's Accountancy practice.${streak}${ch}`;
}
async function localReminderShow(tag) {
  try {
    if (!pushSupported() || Notification.permission !== "granted") return;
    const opts = { body: localReminderBody(), icon: "/assets/brand/icon-192.png", tag: tag || "daily-reminder" };
    // Android Chrome only shows notifications from a service worker —
    // use it when available, fall back to a direct Notification.
    if (navigator.serviceWorker && navigator.serviceWorker.ready) {
      try {
        const reg = await navigator.serviceWorker.ready;
        await reg.showNotification("Accountancy By Abhinash", opts);
        return;
      } catch (e) { /* fall through */ }
    }
    void new Notification("Accountancy By Abhinash", opts);
  } catch (e) { /* a blocked notification must never break the page */ }
}
function localReminderSchedule() {
  if (localReminderTimer) { clearTimeout(localReminderTimer); localReminderTimer = null; }
  // Server push active → the scheduled backend owns delivery; no local timer.
  if (window.ABAPush && ABAPush.isActive()) return;
  if (!STATE.notificationsEnabled || !pushSupported()) return;
  const now = new Date();
  const target = new Date(now);
  const hour = Number.isInteger(STATE.notifyHour) ? STATE.notifyHour : 18;
  target.setHours(hour, 0, 0, 0);
  if (target.getTime() <= now.getTime()) target.setDate(target.getDate() + 1);
  const ms = Math.min(target.getTime() - now.getTime(), 24 * 3600 * 1000);
  localReminderTimer = setTimeout(() => { localReminderShow(); localReminderSchedule(); }, ms);
}
/* Thin wrappers — real server-confirmed flows live in push-manager.js. */
async function subscribeToPush() {
  if (!window.ABAPush) { toast("Notifications are unavailable right now.", "error", "bell-off"); return false; }
  const res = await ABAPush.enable();
  return !!(res && res.ok);
}
async function unsubscribeFromPush() {
  if (localReminderTimer) { clearTimeout(localReminderTimer); localReminderTimer = null; }
  if (window.ABAPush) await ABAPush.disable();
  else { STATE.notificationsEnabled = false; saveState(); }
}
async function sendTestPush() {
  if (!window.ABAPush) { toast("Notifications are unavailable right now.", "error", "bell-off"); return; }
  await ABAPush.test();
}

function fmtINR(n) {
  if (n === null || n === undefined || isNaN(n)) return "—";
  return "₹" + Number(n).toLocaleString("en-IN");
}
function escapeHtml(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

/* ---------------------------------------------------------
   1b. PERSONALIZATION — name, time-based greeting, welcome flow
   --------------------------------------------------------- */
function getGreeting() {
  const h = new Date().getHours();
  if (h >= 5 && h < 12) return { text: "Good morning", icon: "sunrise" };
  if (h >= 12 && h < 17) return { text: "Good afternoon", icon: "sun" };
  if (h >= 17 && h < 21) return { text: "Good evening", icon: "sunset" };
  return { text: "Good night", icon: "moon-star" };
}
function greetingLine() {
  const g = getGreeting();
  // A real Lucide icon instead of a raw emoji character — emoji glyph
  // support varies wildly across Android OEM fonts and was rendering as
  // a blank "tofu" box on at least one real device, which an icon from
  // the site's own icon system never will.
  const iconHtml = `<i data-lucide="${g.icon}" class="greeting-icon"></i>`;
  return STATE.userName ? `${g.text}, ${escapeHtml(STATE.userName)} ${iconHtml}` : `${g.text} ${iconHtml}`;
}
function firstName() {
  if (!STATE.userName) return "";
  return STATE.userName.trim().split(/\s+/)[0];
}
function showWelcomeModal() {
  const overlay = el("div", "welcome-modal-overlay");
  overlay.id = "welcomeModalOverlay";
  overlay.innerHTML = `
    <div class="welcome-modal" role="dialog" aria-modal="true" aria-labelledby="wmTitle">
      <div class="wm-mark" aria-hidden="true">
        <img src="/assets/brand/icon-192.png" alt="" width="52" height="52" style="border-radius:14px;">
      </div>
      <h2 id="wmTitle">Welcome to Accountancy By Abhinash 👋</h2>
      <p>What should we call you? This just personalizes your dashboard — nothing is sent anywhere, it stays on this device.</p>
      <input type="text" id="wmNameInput" maxlength="40" placeholder="Enter your name" autocomplete="off" aria-label="Your name">
      <button class="btn-primary ripple-surface" id="wmContinueBtn"><i data-lucide="arrow-right"></i> Continue</button>
      <button type="button" class="wm-skip" id="wmSkipBtn">Skip for now</button>
    </div>
  `;
  document.body.appendChild(overlay);
  icons();
  const input = $("#wmNameInput", overlay);

  const closeOverlay = () => {
    overlay.classList.add("closing");
    setTimeout(() => overlay.remove(), STATE.reduceMotion ? 0 : 220);
    renderRoute();
  };

  /* v87 — no permission prompt inside the welcome modal. Notifications
     are introduced instead by the optional onboarding card on Home
     ("Stay on Track with Accountancy"), which never fires the browser
     prompt by itself and is dismissed with one tap. */
  const finish = (name) => {
    STATE.userName = name ? name.slice(0, 40) : "Student";
    STATE.onboardedAt = Date.now();
    saveState();
    if (name) toast(`Welcome, ${firstName()}!`, "success", "sparkles");
    closeOverlay();
  };
  $("#wmContinueBtn", overlay).addEventListener("click", () => finish(input.value.trim()));
  $("#wmSkipBtn", overlay).addEventListener("click", () => finish(""));
  input.addEventListener("keydown", e => { if (e.key === "Enter") finish(input.value.trim()); });
  setTimeout(() => input.focus(), STATE.reduceMotion ? 0 : 250);
}

/* ---------------------------------------------------------
   FIRST-VISIT CLASS SELECTOR (v83) — Class 11 / Class 12.
   Shown on home only while the student has never chosen a class and
   has never used the site (see needsClassSelection). A visitor who
   arrives on a direct chapter link never sees it: that link adopts
   its own class silently. The choice is persisted in the same
   localStorage record as everything else, so it is asked once; if
   storage is blocked the in-memory state still holds for the session.
   --------------------------------------------------------- */
let classSelOverlayEl = null;
function showClassSelector() {
  if (classSelOverlayEl) return;                    // already on screen
  if (!needsClassSelection()) return;               // decided already
  if ($("#welcomeModalOverlay")) return;            // don't stack on the welcome flow
  const overlay = el("div", "welcome-modal-overlay");
  overlay.id = "classSelOverlay";
  const meta = ClassRegistry.CLASS_META;
  overlay.innerHTML = `
    <div class="welcome-modal" role="dialog" aria-modal="true" aria-labelledby="csTitle">
      <div class="wm-mark" aria-hidden="true">
        <img src="/assets/brand/icon-192.png" alt="" width="52" height="52" style="border-radius:14px;">
      </div>
      <h2 id="csTitle">Which class are you studying?</h2>
      <p>Pick your class to see the right chapters, questions and revision material. You can switch any time from the sidebar or Settings — your progress in each class is kept separately.</p>
      <div class="cls-options">
        <button type="button" class="cls-option" data-cls="${meta["11"].id}">
          <span class="cls-option-num">XI</span>
          <span class="cls-option-name">${meta["11"].shortLabel}</span>
          <span class="cls-option-blurb">${meta["11"].blurb}</span>
        </button>
        <button type="button" class="cls-option" data-cls="${meta["12"].id}">
          <span class="cls-option-num">XII</span>
          <span class="cls-option-name">${meta["12"].shortLabel}</span>
          <span class="cls-option-blurb">${meta["12"].blurb}</span>
        </button>
      </div>
      <p class="cls-hint">Not sure? Class 12 covers partnership firms and company accounts; Class 11 covers the accounting process and sole proprietorship. You can change this later.</p>
    </div>
  `;
  document.body.appendChild(overlay);
  classSelOverlayEl = overlay;
  icons();

  const choose = (cls) => {
    setActiveClass(cls, { toast: false, rerender: false });
    overlay.classList.add("closing");
    setTimeout(() => { overlay.remove(); classSelOverlayEl = null; }, STATE.reduceMotion ? 0 : 220);
    toast(`You're all set — ${ClassRegistry.CLASS_META[cls].shortLabel} selected.`, "success", "graduation-cap");
    renderRoute();                                   // re-render home for the chosen class
    // The existing first-visit "name" welcome flow runs right after
    // the class is known, so the two first-visit steps never overlap.
    if (!STATE.userName) setTimeout(() => showWelcomeModal(), STATE.reduceMotion ? 100 : 450);
    else maybeShowAboutToast();
  };
  $all(".cls-option", overlay).forEach(btn => {
    btn.addEventListener("click", () => choose(btn.dataset.cls));
  });
  setTimeout(() => { const b = $(".cls-option", overlay); if (b) b.focus(); }, STATE.reduceMotion ? 0 : 250);
}
function $(sel, root = document) { return root.querySelector(sel); }
function $all(sel, root = document) { return Array.from(root.querySelectorAll(sel)); }
function el(tag, cls, html) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html !== undefined) e.innerHTML = html;
  return e;
}
function icons() { if (window.lucide) lucide.createIcons(); }

/* ---------------------------------------------------------
   BOOKMARKS — one implementation shared by every question card.
   Single source of truth: STATE.bookmarks (already persisted by
   saveState → localStorage). Cards render their button through
   bookmarkButtonHTML() and toggle through toggleBookmark(), so the
   icon can never disagree with the Bookmarks page.

   Why the old per-card code never showed the state: Lucide swaps every
   <i data-lucide> for an <svg> the first time icons() runs, so the old
   `btn.querySelector("i").setAttribute(...)` found nothing (and threw)
   AFTER the array had already changed — the list updated, the icon didn't.
   --------------------------------------------------------- */
function isBookmarked(key) { return STATE.bookmarks.includes(key); }
function bookmarkAttr(v) { return String(v).replace(/&/g, "&amp;").replace(/"/g, "&quot;"); }
function bookmarkButtonAttrs(on) {
  return `class="icon-btn sm bookmark-btn${on ? " is-bookmarked" : ""}" data-act="bookmark" aria-pressed="${on}" aria-label="${on ? "Remove bookmark" : "Bookmark this question"}" title="${on ? "Bookmarked — click to remove" : "Bookmark"}"`;
}
function bookmarkButtonHTML(key, extraStyle) {
  const on = isBookmarked(key);
  return `<button type="button" ${bookmarkButtonAttrs(on)} data-bm-key="${bookmarkAttr(key)}"${extraStyle ? ` style="${bookmarkAttr(extraStyle)}"` : ""}><i data-lucide="${on ? "bookmark-check" : "bookmark"}"></i></button>`;
}
function paintBookmarkButton(btn, on, animate) {
  btn.classList.toggle("is-bookmarked", on);
  btn.setAttribute("aria-pressed", String(on));
  btn.setAttribute("aria-label", on ? "Remove bookmark" : "Bookmark this question");
  btn.title = on ? "Bookmarked — click to remove" : "Bookmark";
  btn.innerHTML = `<i data-lucide="${on ? "bookmark-check" : "bookmark"}"></i>`;
  if (animate && on && !STATE.reduceMotion) { btn.classList.remove("bm-pop"); void btn.offsetWidth; btn.classList.add("bm-pop"); }
}
function toggleBookmark(key, sourceBtn) {
  const nowOn = !isBookmarked(key);
  // push only when absent / filter removes every copy → duplicates are impossible
  if (nowOn) STATE.bookmarks.push(key); else STATE.bookmarks = STATE.bookmarks.filter(k => k !== key);
  saveState();
  const sel = `button[data-bm-key="${CSS.escape(String(key))}"]`;
  document.querySelectorAll(sel).forEach(b => paintBookmarkButton(b, nowOn, b === sourceBtn));
  if (sourceBtn && !sourceBtn.matches(sel)) paintBookmarkButton(sourceBtn, nowOn, true);
  icons();
  return nowOn;
}

/* ---------------------------------------------------------
   MISTAKE ALERT (top bar) — a read-only window onto the Mistake Book.
   Source of truth: STATE.mistakeBook. "Pending" = status "review",
   exactly what the Mistake Book page counts as "Unreviewed" (it now
   calls mbPendingCount() too, so the two can never disagree).
   --------------------------------------------------------- */
function mbPendingCount() {
  const book = STATE.mistakeBook || {};
  let n = 0;
  for (const k in book) if (book[k] && book[k].status === "review") n++;
  return n;
}
function refreshMistakeAlert() {
  const pill = document.getElementById("mistakeAlert");
  if (!pill) return;
  const n = mbPendingCount();
  if (pill.dataset.count === String(n)) return;           // nothing changed → no DOM work
  const prev = pill.dataset.count === undefined ? null : parseInt(pill.dataset.count, 10);
  pill.dataset.count = String(n);
  pill.dataset.state = n ? "pending" : "clear";
  const text = n === 0 ? "Nothing to review" : `${n} to review`;
  document.getElementById("mistakeAlertStatus").textContent = text;
  const bubble = document.getElementById("mistakeAlertBubble");
  bubble.textContent = n > 9 ? "9+" : String(n);
  bubble.hidden = n === 0;
  pill.setAttribute("aria-label", `Mistake Alert: ${text}. Open your Mistake Book.`);
  pill.title = n === 0 ? "Mistake Alert — nothing to review. Open your Mistake Book." : `Mistake Alert — ${text}. Open your Mistake Book.`;
  if (prev !== null && n > prev) pulseElement(pill);      // draw the eye only when a NEW mistake lands
}

/* In-product confirmation dialog — replaces the browser's native confirm(). Returns a Promise<boolean>.
   Focus starts on the safe choice (Cancel), Esc / backdrop click cancel, focus returns to the trigger. */
function uiConfirm(message, opts = {}) {
  const { title = "Are you sure?", confirmLabel = "Confirm", cancelLabel = "Cancel", tone = "danger" } = opts;
  return new Promise((resolve) => {
    const prevFocus = document.activeElement;
    const overlay = document.createElement("div");
    overlay.className = "confirm-overlay";
    const uid = "cd" + Math.random().toString(36).slice(2, 8);
    overlay.innerHTML = `
      <div class="confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="${uid}t" aria-describedby="${uid}d">
        <div class="confirm-icon ${tone}"><i data-lucide="${tone === "danger" ? "alert-triangle" : "help-circle"}"></i></div>
        <h2 id="${uid}t"></h2>
        <p id="${uid}d"></p>
        <div class="confirm-actions">
          <button type="button" class="btn-ghost" data-act="cancel"></button>
          <button type="button" class="${tone === "danger" ? "btn-danger-solid" : "btn-primary"}" data-act="ok"></button>
        </div>
      </div>`;
    overlay.querySelector("h2").textContent = title;
    overlay.querySelector("p").textContent = message;
    overlay.querySelector('[data-act="cancel"]').textContent = cancelLabel;
    overlay.querySelector('[data-act="ok"]').textContent = confirmLabel;
    document.body.appendChild(overlay);
    icons();
    const cancelBtn = overlay.querySelector('[data-act="cancel"]');
    const okBtn = overlay.querySelector('[data-act="ok"]');
    function close(result) {
      document.removeEventListener("keydown", onKey, true);
      overlay.classList.add("is-leaving");
      setTimeout(() => overlay.remove(), STATE && STATE.reduceMotion ? 0 : 140);
      if (prevFocus && prevFocus.focus) { try { prevFocus.focus({ preventScroll: true }); } catch (e) {} }
      resolve(result);
    }
    function onKey(e) {
      if (e.key === "Escape") { e.preventDefault(); e.stopPropagation(); close(false); }
      else if (e.key === "Tab") {           // keep focus inside the dialog
        e.preventDefault();
        (document.activeElement === cancelBtn ? okBtn : cancelBtn).focus();
      }
    }
    document.addEventListener("keydown", onKey, true);
    cancelBtn.addEventListener("click", () => close(false));
    okBtn.addEventListener("click", () => close(true));
    overlay.addEventListener("mousedown", (e) => { if (e.target === overlay) close(false); });
    requestAnimationFrame(() => cancelBtn.focus());
  });
}

/* ---------------------------------------------------------
   TOAST NOTIFICATION SYSTEM — one shared utility for the whole site.
   toast(message, type, icon, opts)
     type  : "success" | "error" | "xp" | "badge" | "info" | "warning"
     opts  : { title, duration (ms), dismissible (default true) }
   Behaviour: smooth entry/exit, duplicate suppression while a copy is
   on screen (re-renders never re-announce the same message), a short
   stack of at most 3 so toasts never bury the page, a close button,
   and role=status / role=alert so screen readers hear it once.
   --------------------------------------------------------- */
function toast(msg, type = "success", icon = "check-circle", opts = {}) {
  const root = $("#toastRoot");
  if (!root || msg === undefined || msg === null || msg === "") return null;
  const text = String(msg);
  const duration = opts.duration || (type === "error" ? 4600 : 3200);
  const dupKey = (type || "") + "|" + text;

  const scheduleHide = (t) => setTimeout(() => {
    if (!t.isConnected || t.classList.contains("leaving")) return;
    t.classList.add("leaving");
    setTimeout(() => t.remove(), 300);
  }, duration);

  /* Same message already on screen → refresh its timer instead of
     stacking a duplicate. */
  const existing = Array.prototype.find.call(root.children, c => c.dataset.toastKey === dupKey);
  if (existing) {
    clearTimeout(existing._hideTimer);
    existing._hideTimer = scheduleHide(existing);
    return existing;
  }

  const titleHtml = opts.title ? `<b class="toast-title">${opts.title}</b>` : "";
  const t = el("div", `toast ${type || "info"}`,
    `<i data-lucide="${icon || "info"}"></i>` +
    `<div class="toast-body">${titleHtml}<span class="toast-msg">${text}</span></div>` +
    (opts.dismissible === false ? "" :
      `<button type="button" class="toast-close" aria-label="Dismiss notification"><i data-lucide="x"></i></button>`));
  t.dataset.toastKey = dupKey;
  t.setAttribute("role", (type === "error" || type === "warning") ? "alert" : "status");
  root.appendChild(t);
  /* Keep the stack short — never cover controls or content. */
  while (root.children.length > 3) root.removeChild(root.firstElementChild);
  const closeBtn = t.querySelector(".toast-close");
  if (closeBtn) closeBtn.addEventListener("click", () => {
    clearTimeout(t._hideTimer);
    if (!t.isConnected || t.classList.contains("leaving")) return;
    t.classList.add("leaving");
    setTimeout(() => t.remove(), 300);
  });
  t._hideTimer = scheduleHide(t);
  icons();
  return t;
}

/* XP awarded for a correct first attempt at a question; XP deducted
   for an incorrect first attempt. Applied consistently everywhere a
   question is checked for correctness — never on a second attempt at
   the same question (see the `!STATE.solved[key]` guards at each
   call site), so refreshing, double-clicking, or reopening a page
   can never re-trigger either the gain or the penalty. */
const XP_WRONG_PENALTY = 1;

/* UIF is ui-features.js — the pure, tested rule book behind XP gating,
   activity dedupe and section planning. Loaded before app.js. */
const UIF = window.UIFeatures;

function addXP(amount, reason) {
  STATE.xp = Math.max(0, STATE.xp + amount);
  if (amount > 0) STATE.xpGained += amount;
  else if (amount < 0) STATE.xpDeducted += Math.abs(amount);
  saveState();
  const xpEl = $("#xpCount");
  if (xpEl) xpEl.textContent = STATE.xp;
  if (amount !== 0) pulseElement(xpEl && xpEl.closest(".xp-pill"));
  if (amount < 0) {
    toast(`${amount} XP — ${reason}`, "error", "alert-circle");
  } else if (amount > 0) {
    toast(`+${amount} XP — ${reason}`, "xp", "sparkles");
  }
  /* amount === 0 means nothing was actually awarded — no success
     toast, no pill pulse (honesty: a reward message must always
     mean real XP moved). */
  checkBadges();
  /* v87 — feed the real weekly-summary XP counter (positive awards). */
  if (window.ABAPush && amount > 0) ABAPush.noteXp(amount);
  return STATE.xp;
}

/* ---------------------------------------------------------
   XP GATES — one consistent rule book (ui-features.js):
     • awardXPOnce(key, …)   pays at most once per key, EVER
     • awardXPDaily(key, …)  pays at most once per key per day
     • xpBumpDaily(key, max) at most `max` paid claims per day
   Question XP keeps its established rule (first attempt decides,
   guarded by STATE.solved at each call site). These gates close the
   replay/farm loops: restarting a deck, re-running a quiz, spamming
   a tool or re-asking the tutor can never mint unlimited XP. When a
   gate is closed, addXP is simply not called — no toast, no reward.
   --------------------------------------------------------- */
function awardXPOnce(key, amount, reason) {
  if (!UIF.awardOnce(STATE.xpOnce, key, Date.now())) return false;
  saveState();
  if (amount) addXP(amount, reason);
  return true;
}
function awardXPDaily(key, amount, reason) {
  if (!UIF.awardDaily(STATE.xpOnce, key, Date.now())) return false;
  saveState();
  if (amount) addXP(amount, reason);
  return true;
}
function xpBumpDaily(key, max) {
  const ok = UIF.bumpDaily(STATE.xpOnce, key, max, Date.now());
  if (ok) saveState();
  return ok;
}
function xpDailyLeft(key, max) { return UIF.dailyLeft(STATE.xpOnce, key, max, Date.now()); }
function xpClaimed(key) { return UIF.isClaimed(STATE.xpOnce, key); }

/* ---------------------------------------------------------
   v94 GUIDED LEARNING — state helpers for the LEARN →
   UNDERSTAND → PRACTISE → REMEMBER journey. Chapter content
   lives in guided-learning.js (window.GuidedLearn); every
   record written here comes from a genuine student action:
     learnAt       the readiness check was submitted
     understandAt  a theory checkpoint was answered correctly
     rememberAt    the chapter recall set was completed
     lastTab       a chapter tab was opened (where they were)
     lastStudiedAt last real activity on this chapter
   Practise-stage completion is NEVER stored — it is computed
   from STATE.solved through STATE.chapterProgress.
   --------------------------------------------------------- */
const GL = window.GuidedLearn;

function guideRec(chId) {
  if (!STATE.guide || typeof STATE.guide !== "object") STATE.guide = {};
  if (!STATE.guide[chId] || typeof STATE.guide[chId] !== "object") STATE.guide[chId] = {};
  return STATE.guide[chId];
}

/* One-time stage marker — returns true only on the fresh
   transition, so milestones and toasts can never fire twice. */
function markGuideStage(chId, field) {
  const r = guideRec(chId);
  if (r[field]) return false;
  r[field] = Date.now();
  saveState();
  return true;
}

/* Last genuine activity on this chapter. Prefers the v94 record;
   for students who studied before v94 it falls back to the newest
   real activity-log row for this chapter. Never invented. */
function guideLastStudied(chId) {
  const r = (STATE.guide && STATE.guide[chId]) || null;
  if (r && typeof r.lastStudiedAt === "number" && r.lastStudiedAt > 0) return r.lastStudiedAt;
  let max = 0;
  (Array.isArray(STATE.activityLog) ? STATE.activityLog : []).forEach(a => {
    const e = UIF.normalizeActivity(a);
    if (!e || !(e.at > 0)) return;
    const fromRoute = (e.route && e.route.indexOf("ch-") === 0) ? e.route.slice(3) : null;
    if ((e.chapterId || fromRoute) === chId && e.at > max) max = e.at;
  });
  return max || null;
}

/* Chapter tab chips on the current page (chapter routes only). */
function glTabChips() { return $all("#view-root .chip[data-tab]"); }
function glActiveTab() {
  const a = document.querySelector("#view-root .chip[data-tab].active");
  return a ? a.dataset.tab : null;
}
function glClickTab(tab) {
  const chip = glTabChips().find(c => c.dataset.tab === tab);
  if (chip) { chip.click(); return true; }
  return false;
}

/* Re-render the live roadmap after a stage event without a tab switch. */
function refreshRoadmap() {
  const rm = document.querySelector("#view-root .gl-roadmap");
  if (rm && rm.dataset.ch) updateJourneyStepper(rm, rm.dataset.ch, glActiveTab());
}

/* Brief scale-pulse used to draw the eye to a value that just changed
   (XP total, Mistake Alert count) without needing a full toast every time. */
function pulseElement(el) {
  if (!el || STATE.reduceMotion) return;
  el.classList.remove("pulse-once");
  void el.offsetWidth; // restart animation if triggered again quickly
  el.classList.add("pulse-once");
}

/* Recent Activity — one recording system for the whole site.
   Accepts a plain string (legacy call sites) or a structured object:
     logActivity({ type: "practice", key: "q|intro-3",
       text: "Introduction to Accounting Q3 solved (easy)",
       route: "ch-intro", tab: "Practice Bank", qid: 3,
       difficulty: "easy", status: "solved" })
   Entries are normalized (corrupt rows dropped, ids assigned) and
   deduplicated by a stable key, so re-practising an activity
   refreshes its row instead of stacking a duplicate. */
function logActivity(input) {
  const entry = UIF.normalizeActivity(input, { now: Date.now() });
  if (!entry) return;
  STATE.activityLog = UIF.pushActivity(STATE.activityLog, entry, UIF.ACTIVITY_LIMIT);
  saveState();
  /* v87 — feed the real (never invented) weekly-summary counters. */
  if (window.ABAPush) ABAPush.noteActivity(entry);
}

function touchStreak() {
  const today = new Date().toDateString();
  if (STATE.lastActiveDate === today) return;
  const yesterday = new Date(Date.now() - 86400000).toDateString();
  const wasFirstVisitEver = STATE.lastActiveDate === null;
  STATE.streak = (STATE.lastActiveDate === yesterday) ? STATE.streak + 1 : 1;
  STATE.lastActiveDate = today;
  saveState();
  if (!wasFirstVisitEver && STATE.streak > 1) {
    toast(`${STATE.streak}-day streak — keep it up`, "xp", "flame");
    playNotificationSound();
  }
}

/* Achievements live in achievements.js: declarative criteria, stable
   ids, and idempotent awarding (awardNew() pushes the id the moment
   it awards, so this can be called from every XP/progress update
   without ever counting the same achievement twice). */
function checkBadges() {
  if (typeof Achievements === "undefined") return [];
  const earned = Achievements.awardNew(STATE);   // already recorded in STATE.badges
  if (!earned.length) return [];
  saveState();
  if (earned.length === 1) toast(`Achievement unlocked: ${earned[0].name}`, "badge", "award");
  else toast(`${earned.length} achievements unlocked`, "badge", "award");
  launchConfetti();
  playAchievementSound();
  /* v87 — optional local (page-open) notification, category-gated and
     deduped by the browser via the achievement's stable tag. */
  if (window.ABAPush) ABAPush.achievementUnlocked(earned);
  return earned;
}

/* Event-driven achievements (e.g. passing an Exam Mode paper) are
   granted explicitly, never derived from a stored total, so a
   security-terminated attempt can never unlock one. */
function grantAchievement(id) {
  if (typeof Achievements === "undefined") return null;
  const a = Achievements.grant(STATE, id);   // null when already earned
  if (!a) return null;
  saveState();
  toast(`Achievement unlocked: ${a.name}`, "badge", "award");
  launchConfetti();
  playAchievementSound();
  if (window.ABAPush) ABAPush.achievementUnlocked([a]);
  return a;
}

/* ---- Confetti (lightweight canvas) ---- */
function launchConfetti() {
  if (STATE.reduceMotion) return; // celebratory motion is exactly what reduced-motion users want skipped
  const canvas = $("#confettiCanvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  canvas.width = window.innerWidth; canvas.height = window.innerHeight;
  const colors = ["#B8863B", "#2D6A4F", "#3D4F91", "#B23A2F"];
  const gravity = 0.12;
  const drag = 0.995;
  const pieces = Array.from({ length: 90 }, () => ({
    x: Math.random() * canvas.width, y: -20 - Math.random() * 200,
    vx: (Math.random() - 0.5) * 5, vy: 1 + Math.random() * 3,
    size: 4 + Math.random() * 5, color: colors[Math.floor(Math.random() * colors.length)],
    rot: Math.random() * 360, vr: (Math.random() - 0.5) * 12,
    wobble: Math.random() * Math.PI * 2, wobbleSpeed: 0.05 + Math.random() * 0.05
  }));
  const totalFrames = 150;
  let frame = 0;
  function tick() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    frame++;
    const fadeStart = totalFrames - 30;
    const alpha = frame > fadeStart ? Math.max(0, 1 - (frame - fadeStart) / 30) : 1;
    pieces.forEach(p => {
      p.vy = (p.vy + gravity) * drag;
      p.vx *= drag;
      p.wobble += p.wobbleSpeed;
      p.x += p.vx + Math.sin(p.wobble) * 0.6; // gentle side-to-side drift, like real paper falling
      p.y += p.vy; p.rot += p.vr;
      ctx.save(); ctx.globalAlpha = alpha; ctx.translate(p.x, p.y); ctx.rotate(p.rot * Math.PI / 180);
      ctx.fillStyle = p.color; ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size*0.6);
      ctx.restore();
    });
    if (frame < totalFrames) requestAnimationFrame(tick); else ctx.clearRect(0,0,canvas.width,canvas.height);
  }
  tick();
}

/* ---- Ripple effect ---- */
function attachRipple(container) {
  container.addEventListener("click", function (e) {
    const target = e.target.closest(".ripple-surface");
    if (!target) return;
    const rect = target.getBoundingClientRect();
    const r = el("span", "ripple-el");
    const size = Math.max(rect.width, rect.height);
    r.style.width = r.style.height = size + "px";
    r.style.left = (e.clientX - rect.left - size / 2) + "px";
    r.style.top = (e.clientY - rect.top - size / 2) + "px";
    target.appendChild(r);
    setTimeout(() => r.remove(), 650);
  });
}

/* ---------------------------------------------------------
   2b. SOUND ENGINE — synthesized via Web Audio API, so the
       app stays a self-contained set of files with no audio
       assets to load. Respects STATE.soundOn at all times.

       Redesigned for a subtle, premium, modern feel: every
       sound is short, low-volume, and passed through a gentle
       lowpass filter to soften the harmonics that make raw
       synthesized tones feel harsh, tinny, or arcade-like.
       Each interaction category has its own distinct, but
       related, timbre so the whole set feels like one
       coherent sound identity rather than a grab-bag of beeps.
       Pitches are randomized slightly on repeatable sounds
       (click, tab) so rapid interaction never sounds robotic
       or fatiguing.
   --------------------------------------------------------- */
let AUDIO_CTX = null;
function getAudioCtx() {
  if (!AUDIO_CTX) {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return null;
    AUDIO_CTX = new Ctx();
  }
  if (AUDIO_CTX.state === "suspended") AUDIO_CTX.resume();
  return AUDIO_CTX;
}

/* Shared helper: one soft, filtered oscillator "note" with a fast,
   click-free attack and a smooth exponential decay. Every sound in
   this file is built from one or more calls to this, which keeps
   the whole set consistent in character (same envelope shape, same
   gentle low-pass warmth) while letting pitch/gain/duration vary
   per interaction. `start` is an offset in seconds from `now`. */
function playTone(ctx, now, { freq, start = 0, dur = 0.12, gain = 0.045, type = "sine", filterFreq = 2400 }) {
  const t0 = now + start;
  const osc = ctx.createOscillator();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, t0);

  const filter = ctx.createBiquadFilter();
  filter.type = "lowpass";
  filter.frequency.setValueAtTime(filterFreq, t0);
  filter.Q.setValueAtTime(0.7, t0);

  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.linearRampToValueAtTime(gain, t0 + Math.min(0.012, dur * 0.25));
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);

  osc.connect(filter);
  filter.connect(g);
  g.connect(ctx.destination);
  osc.start(t0);
  osc.stop(t0 + dur + 0.04);
  return osc;
}

/* BUTTON CLICK — a single, very soft, short tap. Pitch wobbles a
   few Hz each time so a burst of clicks never sounds mechanical. */
function playClickSound() {
  if (!STATE.soundOn) return;
  const ctx = getAudioCtx();
  if (!ctx) return;
  const now = ctx.currentTime;
  const base = 600 + Math.random() * 35;
  playTone(ctx, now, { freq: base, dur: 0.055, gain: 0.04, type: "sine", filterFreq: 2100 });
}

/* TAB / MENU INTERACTION — a touch lower and slightly softer than
   the button click, with a faint second partial a fifth above, so
   switching tabs or nav items reads as "moving to a new place"
   rather than "pressing a button". */
function playTabSound() {
  if (!STATE.soundOn) return;
  const ctx = getAudioCtx();
  if (!ctx) return;
  const now = ctx.currentTime;
  const base = 440 + Math.random() * 25;
  playTone(ctx, now, { freq: base, dur: 0.07, gain: 0.035, type: "sine", filterFreq: 1700 });
  playTone(ctx, now, { start: 0.014, freq: base * 1.5, dur: 0.08, gain: 0.018, type: "sine", filterFreq: 1900 });
}

/* CORRECT ANSWER — a warm, brief two-note upward interval. Softer
   and shorter than a full "achievement" chime, since this fires
   often (every correct answer) and must never grow tiresome. */
function playSuccessSound() {
  if (!STATE.soundOn) return;
  const ctx = getAudioCtx();
  if (!ctx) return;
  const now = ctx.currentTime;
  playTone(ctx, now, { freq: 523.25, dur: 0.15, gain: 0.05, filterFreq: 2500 });          // C5
  playTone(ctx, now, { start: 0.065, freq: 659.25, dur: 0.19, gain: 0.05, filterFreq: 2700 }); // E5
}

/* INCORRECT ANSWER — one soft, brief downward tone. Informational,
   not harsh: a plain sine through a low-pass filter, never a buzzy
   or square/triangle "wrong" arcade sound. */
function playErrorSound() {
  if (!STATE.soundOn) return;
  const ctx = getAudioCtx();
  if (!ctx) return;
  const now = ctx.currentTime;
  const osc = ctx.createOscillator();
  osc.type = "sine";
  osc.frequency.setValueAtTime(300, now);
  osc.frequency.exponentialRampToValueAtTime(232, now + 0.16);

  const filter = ctx.createBiquadFilter();
  filter.type = "lowpass";
  filter.frequency.setValueAtTime(1400, now);

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.linearRampToValueAtTime(0.045, now + 0.015);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.19);

  osc.connect(filter);
  filter.connect(gain);
  gain.connect(ctx.destination);
  osc.start(now);
  osc.stop(now + 0.22);
}

/* QUIZ / EXAM COMPLETION — a gentle three-note upward resolve.
   Distinct from a single correct answer (longer, three notes,
   settles on a held final note) without becoming a fanfare. */
function playCompletionSound() {
  if (!STATE.soundOn) return;
  const ctx = getAudioCtx();
  if (!ctx) return;
  const now = ctx.currentTime;
  const notes = [
    { freq: 493.88, start: 0.00, dur: 0.16 }, // B4
    { freq: 587.33, start: 0.11, dur: 0.18 }, // D5
    { freq: 783.99, start: 0.23, dur: 0.36 }  // G5 — held, the "resolve"
  ];
  notes.forEach(n => playTone(ctx, now, { ...n, gain: 0.045, filterFreq: 2600 }));
}

/* ACHIEVEMENT / SUCCESS MILESTONE — badge unlocks and chapter
   mastery. A soft, layered bell-like chime (root + soft fifth +
   faintly detuned octave for a little shimmer), longer and gentler
   than any other sound in the set, reserved for genuinely special
   moments so it never becomes routine. */
function playAchievementSound() {
  if (!STATE.soundOn) return;
  const ctx = getAudioCtx();
  if (!ctx) return;
  const now = ctx.currentTime;
  const root = 587.33; // D5
  [
    { mult: 1,     gain: 0.045, dur: 0.55 },
    { mult: 1.5,   gain: 0.03,  dur: 0.5  },
    { mult: 2.006, gain: 0.02,  dur: 0.45 } // very slightly detuned octave for shimmer, not dissonance
  ].forEach((n, i) => playTone(ctx, now, { start: i * 0.02, freq: root * n.mult, dur: n.dur, gain: n.gain, filterFreq: 3200 }));
}

/* IMPORTANT NOTIFICATION — reserved for rare, meaningful pings
   (e.g. the once-a-day streak notice) rather than every toast, so
   it stays noticeable instead of blending into routine feedback.
   A simple two-note soft "ping" distinct from the click/tab family. */
function playNotificationSound() {
  if (!STATE.soundOn) return;
  const ctx = getAudioCtx();
  if (!ctx) return;
  const now = ctx.currentTime;
  playTone(ctx, now, { freq: 740, dur: 0.13, gain: 0.045, filterFreq: 3000 });
  playTone(ctx, now, { start: 0.09, freq: 880, dur: 0.16, gain: 0.032, filterFreq: 3200 });
}

/* The intro sound — a short, soft rising three-note chime played
   once, right as the preloader appears (its reveal animation lasts
   under a second; the exact preloader hide time depends on real
   app-readiness, not a fixed duration). Same notes/timing as
   before, softened to match the rest of the redesigned set. */
function playIntroSound() {
  if (!STATE.soundOn) return;
  const ctx = getAudioCtx();
  if (!ctx) return;
  const now = ctx.currentTime;
  const notes = [
    { freq: 392.0,  start: 0.0,  dur: 0.5 },  // G4
    { freq: 523.25, start: 0.25, dur: 0.55 }, // C5
    { freq: 659.25, start: 0.55, dur: 0.9 }   // E5, held — resolves as the brand text lands
  ];
  notes.forEach(n => playTone(ctx, now, { ...n, gain: 0.045, filterFreq: 2400 }));
}

/* Global delegated click-sound handler — fires for any click on a
   button, .chip, .nav-item, or [data-sound] element, anywhere in the
   app, without needing per-element listeners. A user gesture is
   required to unlock AudioContext on some browsers, which this
   naturally satisfies since it only runs in response to a click.
   Tab/menu-style elements (.chip, .nav-item) get the softer,
   navigation-flavoured sound; everything else gets the plain click. */
function attachClickSound(container) {
  container.addEventListener("click", (e) => {
    const target = e.target.closest("button, .chip, .nav-item, [data-sound], .theme-swatch, .ripple-surface");
    if (!target || target.disabled) return;
    if (target.matches(".chip, .nav-item")) playTabSound();
    else playClickSound();
  }, { capture: true });
}

/* ---------------------------------------------------------
   3. THEME / SETTINGS
   --------------------------------------------------------- */
function applyTheme() {
  document.documentElement.classList.toggle("dark", STATE.theme === "dark");
  document.documentElement.setAttribute("data-color-theme", STATE.colorTheme || "classic");
  $("#themeIconMoon").hidden = STATE.theme === "dark";
  $("#themeIconSun").hidden = STATE.theme !== "dark";
  document.documentElement.classList.toggle("reduce-motion", STATE.reduceMotion);
  document.documentElement.classList.toggle("high-contrast", STATE.highContrast);
  document.documentElement.classList.toggle("colorblind-mode", STATE.colorblind);
  document.documentElement.style.fontSize = (16 * STATE.fontScale) + "px";
  const themeToggle = $("#themeToggle");
  if (themeToggle) themeToggle.setAttribute("aria-pressed", String(STATE.theme === "dark"));
}
$("#themeToggle").addEventListener("click", () => {
  STATE.theme = STATE.theme === "dark" ? "light" : "dark";
  saveState(); applyTheme();
});

/* ---------------------------------------------------------
   4. ROUTER
   --------------------------------------------------------- */
/* Query string of the current route (split off in renderRoute) so a
   view can read ?id=... from its URL (e.g. ?id=ACC-... on a route
   that names a certificate). */
let routeQueryString = "";

/* -------------------------------------------------------------
   ADMIN REPORT — #admin-report
   A private operator page: every attempt, result and certificate
   held in the examination store, read live through the token-gated
   `admin` action of exam-api. Deliberately NOT linked from any
   student navigation — reached by URL only. The token lives in
   this tab's sessionStorage and is never persisted to localStorage.
   ------------------------------------------------------------- */
function admWhen(v) {
  if (!v) return "—";
  const d = new Date(v);
  if (isNaN(d.getTime())) return "—";
  return d.toLocaleString(undefined, { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
}
function admDur(sec) {
  if (sec === null || sec === undefined) return "—";
  const m = Math.floor(sec / 60), s = sec % 60;
  return m ? m + "m " + s + "s" : s + "s";
}
function renderAdminReport(root) {
  const TOKEN_KEY = "abhinash_admin_token";
  const wrap = el("div", "adm-page");
  wrap.appendChild(el("div", "adm-hero",
    '<p class="adm-eyebrow">ADMINISTRATION</p><h1>Examination Report</h1>' +
    '<p class="adm-sub">Every attempt, result and certificate recorded by the examination service, read live from the store. This page is not linked from student navigation and requires the admin token.</p>'));
  const body = el("div", "adm-body");
  wrap.appendChild(body);
  root.appendChild(wrap);

  const readToken = () => { try { return sessionStorage.getItem(TOKEN_KEY) || ""; } catch (e) { return ""; } };
  const writeToken = (t) => { try { sessionStorage.setItem(TOKEN_KEY, t); } catch (e) { /* private mode */ } };
  const forgetToken = () => { try { sessionStorage.removeItem(TOKEN_KEY); } catch (e) {} };

  function renderGate(message) {
    body.innerHTML = "";
    const card = el("div", "adm-token-card");
    card.innerHTML =
      "<h2>Admin token required</h2>" +
      '<p class="adm-sub">' + escapeHtml(message || "Enter the admin token to open the report. The token is kept only in this tab and is never stored on the device.") + "</p>" +
      '<div class="adm-token-row">' +
      '<input type="password" id="admTokenInput" placeholder="Admin token" autocomplete="off" aria-label="Admin token">' +
      '<button class="btn-primary" id="admOpenBtn">Open report</button></div>';
    body.appendChild(card);
    const input = $("#admTokenInput", card);
    const open = () => {
      const v = input.value.trim();
      if (!v) { input.focus(); return; }
      writeToken(v);
      renderShell();
    };
    $("#admOpenBtn", card).addEventListener("click", open);
    input.addEventListener("keydown", (e) => { if (e.key === "Enter") open(); });
    input.focus();
    icons();
  }

  async function renderShell() {
    body.innerHTML = "";
    const bar = el("div", "adm-bar");
    bar.innerHTML =
      '<div class="adm-bar-info"><span id="admStamp">Reading the store…</span></div>' +
      '<div class="adm-bar-actions">' +
      '<button class="btn-ghost" id="admRefreshBtn"><i data-lucide="refresh-cw"></i> Refresh</button>' +
      '<button class="btn-ghost" id="admOutBtn">Sign out</button></div>';
    body.appendChild(bar);
    const summary = el("div", "adm-summary");
    body.appendChild(summary);
    const content = el("div", "adm-content");
    content.innerHTML = '<p class="adm-status">Reading the store…</p>';
    body.appendChild(content);
    // One delegated listener per shell — certificate links anywhere in
    // the report open that certificate on the local certificate view.
    content.addEventListener("click", (e) => {
      const b = e.target.closest("[data-cert]");
      if (b) examOpenHistoricalCertificate(b.dataset.cert);
    });
    icons();
    $("#admRefreshBtn", bar).addEventListener("click", () => loadReport(summary, content, $("#admStamp", bar)));
    $("#admOutBtn", bar).addEventListener("click", () => { forgetToken(); renderGate("Signed out — the token was cleared from this tab."); });
    await loadReport(summary, content, $("#admStamp", bar));
  }

  async function loadReport(summaryEl, contentEl, stampEl) {
    stampEl.textContent = "Reading the store…";
    const r = await examApi("admin", { token: readToken(), op: "report" });
    if (r.status === 401) { forgetToken(); renderGate("That token was not accepted. Check it and try again."); return; }
    if (!r.ok || !r.body || !r.body.ok) {
      stampEl.textContent = "Could not read the report";
      contentEl.innerHTML = '<p class="adm-status is-error">' + escapeHtml((r.body && r.body.error) || "The examination service did not answer. Try again.") + "</p>";
      return;
    }
    const d = r.body;
    const s = d.summary;
    stampEl.textContent = "Updated " + admWhen(d.generatedAt) + (d.truncated ? " · lists show the latest 200 — the summary covers everything" : "");

    summaryEl.innerHTML = [
      ["Attempts", s.attempts],
      ["Today (IST)", s.attemptsToday],
      ["Submitted", s.submitted],
      ["Pass rate", s.passRate + "%"],
      ["Certificates", s.certificates + " · " + s.certsPass + " pass / " + s.certsFail + " fail"],
      ["Candidates", s.candidates]
    ].map((p) => '<div class="adm-stat"><span>' + p[0] + "</span><b>" + escapeHtml(String(p[1])) + "</b></div>").join("");

    const cell = (v) => (v === null || v === undefined ? "—" : escapeHtml(String(v)));
    const resultBadge = (rs) => rs ? '<span class="adm-badge ' + (rs === "PASS" ? "is-pass" : "is-fail") + '">' + rs + "</span>" : "—";
    const attemptRow = (a) => {
      const paper = ExamRules.getPaper(a.paperId);
      const statusCls = a.status === "submitted" ? "is-done" : a.status === "active" ? "is-live" : "is-void";
      return "<tr>" +
        '<td data-label="Started">' + admWhen(a.startedAt) + "</td>" +
        '<td data-label="Candidate"><b>' + escapeHtml(a.candidateName) + "</b>" + (a.schoolName ? "<small>" + escapeHtml(a.schoolName) + "</small>" : "") + "</td>" +
        '<td data-label="Paper">' + escapeHtml(paper ? paper.title : (a.paperId || "—")) + "</td>" +
        '<td data-label="Status"><span class="adm-badge ' + statusCls + '">' + escapeHtml(a.status) + "</span></td>" +
        '<td data-label="Marks">' + (a.marks === null ? "—" : cell(a.marks) + " / " + cell(a.maxMarks)) + "</td>" +
        '<td data-label="%">' + (a.percentage === null ? "—" : cell(a.percentage) + "%") + "</td>" +
        '<td data-label="Grade">' + cell(a.grade) + "</td>" +
        '<td data-label="Result">' + resultBadge(a.resultStatus) + "</td>" +
        '<td data-label="Time">' + admDur(a.timeTakenSeconds) + "</td>" +
        '<td data-label="Certificate">' + (a.certId ? '<button class="adm-link" data-cert="' + escapeHtml(a.certId) + '">' + escapeHtml(a.certId) + "</button>" : "—") + "</td>" +
        "</tr>";
    };
    const certRow = (c) => "<tr>" +
      '<td data-label="ID"><span class="adm-mono">' + escapeHtml(c.id) + "</span>" + (c.status === "revoked" ? ' <span class="adm-badge is-void">revoked</span>' : "") + "</td>" +
      '<td data-label="Kind">' + (c.resultStatus === "PASS" ? "Achievement" : "Completion") + "</td>" +
      '<td data-label="Candidate"><b>' + escapeHtml(c.candidateName) + "</b>" + (c.schoolName ? "<small>" + escapeHtml(c.schoolName) + "</small>" : "") + "</td>" +
      '<td data-label="Examination">' + escapeHtml(c.examTitle) + "</td>" +
      '<td data-label="Marks">' + cell(c.marksObtained) + " / " + cell(c.maxMarks) + "</td>" +
      '<td data-label="%">' + cell(c.percentage) + "%</td>" +
      '<td data-label="Grade">' + cell(c.grade) + "</td>" +
      '<td data-label="Result">' + resultBadge(c.resultStatus) + "</td>" +
      '<td data-label="Issued">' + admWhen(c.issuedAt) + "</td>" +
      '<td data-label="Open"><button class="adm-link" data-cert="' + escapeHtml(c.id) + '">Open</button></td>' +
      "</tr>";

    contentEl.innerHTML = "";
    const aSec = el("section", "adm-section");
    aSec.innerHTML = '<h2>Attempts <span class="adm-count">' + d.attempts.length + "</span></h2>" +
      (d.attempts.length
        ? '<div class="adm-table-wrap"><table class="adm-table"><thead><tr><th>Started</th><th>Candidate</th><th>Paper</th><th>Status</th><th>Marks</th><th>%</th><th>Grade</th><th>Result</th><th>Time</th><th>Certificate</th></tr></thead><tbody>' + d.attempts.map(attemptRow).join("") + "</tbody></table></div>"
        : '<p class="adm-status">No attempts recorded yet — the first student to start an examination will appear here.</p>');
    contentEl.appendChild(aSec);

    const cSec = el("section", "adm-section");
    cSec.innerHTML = '<h2>Issued certificates <span class="adm-count">' + d.certificates.length + "</span></h2>" +
      (d.certificates.length
        ? '<div class="adm-table-wrap"><table class="adm-table"><thead><tr><th>ID</th><th>Kind</th><th>Candidate</th><th>Examination</th><th>Marks</th><th>%</th><th>Grade</th><th>Result</th><th>Issued</th><th>Open</th></tr></thead><tbody>' + d.certificates.map(certRow).join("") + "</tbody></table></div>"
        : '<p class="adm-status">No certificates issued yet.</p>');
    contentEl.appendChild(cSec);
    icons();
  }

  if (readToken()) renderShell(); else renderGate();
}

