/* Class 12 chapter routes (v83) — registered from the chapter
   registry so the router, route titles and bottom-nav map can never
   drift from the data. All 13 chapters render through the shared,
   data-driven Class 12 chapter renderer (renderC12Chapter). */
ClassRegistry.chapterIdsOf("12").forEach(id => {
  routes["ch-" + id] = renderC12Chapter;
  ROUTE_TITLES["ch-" + id] = chapterTitleOf(id);
  BOTTOM_NAV_MAP["ch-" + id] = "chapters-list";
});

/* v83 — the Class 12 chapter-index page (prerendered at
   /class-12-accountancy/) reuses the class-aware chapter list; the
   route adopts Class 12 through adoptClassFromRoute before render. */
routes["chapters-list-12"] = function (root) { renderChaptersList(root); };
ROUTE_TITLES["chapters-list-12"] = "Class 12 Accountancy Chapters";
BOTTOM_NAV_MAP["chapters-list-12"] = "chapters-list";

function animateProgressBars(container) {
  const bars = container.querySelectorAll(".progress-fill[data-target]");
  if (!bars.length) return;
  if (STATE.reduceMotion) {
    bars.forEach(b => { b.style.width = b.dataset.target + "%"; });
    return;
  }
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      bars.forEach(b => { b.style.width = b.dataset.target + "%"; });
    });
  });
}

function navigate(route, query) {
  // Exam security lives in the real navigation path, not in isolated
  // listeners: every internal link, nav item, sidebar entry, bottom
  // nav and search result goes through here, so none of them can
  // bypass it. While a paper is running the navigation is BLOCKED
  // before the hash changes: the student must return to the paper,
  // submit it, or explicitly terminate the attempt first.
  if (examState && examState.status === EXAM_STATUS.ACTIVE && String(route).split("?")[0] !== EXAM_ROUTE) {
    examNavigationBlocked(route);
    return;
  }
  /* `query` is an optional deep-link (?ch=jr, ?id=…) kept in the hash
     for the view to read via routeQueryString. */
  const target = query ? String(route) + "?" + query : route;
  window.location.hash = target;
  /* SEO: keep the URL path in step with public routes so a shared link
     always names the page it shows (e.g. /class-11-accountancy/journal/).
     The hash still carries the route (exam guard, hashchange router);
     crawlers ignore fragments and see the canonical path page. Private
     views keep the current path and live purely in the hash. A route may
     carry a deep-link query (?ch=jr, ?open=…) — the canonical path is
     resolved from the bare route name only. */
  if (window.Seo && Seo.pathFor) {
    const bare = String(route).split("?")[0];
    const p = Seo.pathFor(bare);
    const want = p ? p + "#" + target : null;
    if (want && want !== window.location.pathname + window.location.hash) {
      history.replaceState(null, "", want);
    }
  }
}
window.addEventListener("hashchange", renderRoute);

function renderRoute() {
  /* Route = hash first (SPA navigation, exam mode), then the stable
     public URL path (direct load / refresh of a prerendered page like
     /class-11-accountancy/journal/), then home. A hash may carry a
     query (e.g. ?id=ACC-SEP2026-0010 naming a certificate). The
     query is split off before the route
     lookup and kept in routeQueryString for the view to read. */
  const rawRoute = window.location.hash.replace("#", "")
    || (window.Seo && Seo.routeForPath ? Seo.routeForPath(window.location.pathname) : null)
    || "home";
  const qAt = rawRoute.indexOf("?");
  const route = qAt === -1 ? rawRoute : rawRoute.slice(0, qAt);
  routeQueryString = qAt === -1 ? "" : rawRoute.slice(qAt + 1);
  // Back/Forward navigation, a pasted hash and any other route change
  // land here too — the same guard, so nothing escapes it: the hash is
  // put back on the examination route and the student is told why.
  if (examState && examState.status === EXAM_STATUS.ACTIVE && route !== EXAM_ROUTE) {
    examNavigationBlocked(route);
    if ((window.location.hash || "").replace(/^#/, "").split("?")[0] !== EXAM_ROUTE) {
      window.location.hash = EXAM_ROUTE;   // hashchange → the paper renders again
    }
    return;
  }
  /* v83 — a direct link to a chapter page (Class 11 or Class 12)
     silently opens that chapter's class. It runs after the exam guard
     above so an active paper is never interrupted, and it never
     prompts: adoption is a plain persisted choice. */
  adoptClassFromRoute(route);
  const fn = routes[route] || renderHome;
  // A maximized whiteboard covers the whole screen — closing it on
  // navigation stops it silently blocking whatever page comes next.
  // A small floating whiteboard doesn't cover content, so it's left open,
  // same as the calculator/scratch pad/pomodoro already behave.
  const wbPanel = $("#whiteboardPanel");
  if (wbPanel && !wbPanel.hidden && wbPanel.classList.contains("wb-maximized")) closePanel("whiteboardPanel");
  $all(".nav-item").forEach(n => n.classList.toggle("active", n.dataset.route === route));
  $all(".bottom-nav-item").forEach(n => n.classList.toggle("active", n.dataset.route === (BOTTOM_NAV_MAP[route] || "more")));
  const titleEl = $("#topbarPageTitle");
  if (titleEl) titleEl.textContent = ROUTE_TITLES[route] || "Accountancy By Abhinash";
  /* Title, meta description, canonical, OG/Twitter tags, breadcrumbs and
     JSON-LD are owned by seo.js so metadata always matches the route. */
  if (window.Seo && Seo.applyRoute) {
    Seo.applyRoute(route);
  } else {
    document.title = `${ROUTE_TITLES[route] || "Accountancy By Abinash"} | Accountancy By Abinash`;
  }
  /* v83 — LIVE tab title vs crawler title. Shared screens (chapter
     index, quiz, flashcards, formula sheet, important questions, exam
     mode, AI tutor, about) keep their canonical v82 URL and their
     crawler-facing title in seo-config/robots/sitemap — but at
     runtime they render the ACTIVE class's content, so a Class 12
     student must never read a "Class 11" label in the tab title.
     Chapter pages are deliberately excluded: their content is one
     fixed class, so their title is correct for every visitor, and
     og/twitter/canonical tags stay untouched — they describe the
     URL, not the session. */
  if (activeClass() === ClassRegistry.CLASS_12 && LIVE_CLASS_TITLE_ROUTES[route]) {
    let live = String(document.title || "");
    if (route === "chapters-list") {
      /* Mirror the Class 12 chapter index's own crawler title (built
         from the registry so the chapter count can never go stale). */
      live = "Class 12 Accountancy Notes: All " +
        ClassRegistry.chaptersOf(ClassRegistry.CLASS_12).length +
        " CBSE Chapters | Accountancy By Abinash";
    } else {
      live = live
        .replace(/Class 11 Accountancy/g, "Class 12 Accountancy")
        .replace(/Class 11(?! & 12)/g, "Class 12");
      /* "(500+)" counts the Class 11 quiz bank; the Class 12 bank is
         smaller, so the honest live title simply drops the figure. */
      if (route === "quiz") live = live.replace(/ \(500\+\)/, "");
    }
    document.title = live;
  }
  $(".topbar").classList.remove("search-open");
  const root = $("#view-root");
  root.classList.add("view-leaving");
  setTimeout(() => {
    root.innerHTML = "";
    // Routes like AI Tutor add layout-specific classes (e.g. ai-route-root)
    // directly onto #view-root. Reset back to the base class before the
    // next route renders, or those classes leak into every page after it.
    root.className = "view-root";
    fn(root);
    icons();
    animateProgressBars(root);
    // Semantics only (no visual change): every page should expose exactly one level-1 heading to assistive tech.
    if (!root.classList.contains("ai-route-root") && !root.querySelector("h1")) {
      const firstHeading = root.querySelector("h2");
      if (firstHeading) { firstHeading.setAttribute("role", "heading"); firstHeading.setAttribute("aria-level", "1"); }
    }
    root.classList.remove("view-leaving");
    root.classList.add("view-entering");
    // Force a reflow so the entering animation reliably restarts even
    // when navigating quickly between routes with the same class present.
    void root.offsetWidth;
    root.classList.remove("view-entering");
    finishPreloader();
    if (isMobileNav()) closeSidebar();
    /* v82 hooks — section/chapter navigation footer, a pending Recent
       Activity deep-open, and the first-visit toast (home only). */
    afterRouteRender(root, route);
    window.scrollTo({ top: 0, behavior: STATE.reduceMotion ? "auto" : "smooth" });
  }, 110);
  touchStreak();
  updateNavProgress();
}

/* ============================================================
   SECTION NAVIGATION + RECENT ACTIVITY OPENING (v82)
   ------------------------------------------------------------
   • afterRouteRender() — one hook after every route render: appends
     the Next Section / Next Chapter footer to chapter pages, runs a
     pending Recent Activity deep-open, schedules the one-time
     first-visit toast on home.
   • openActivity() — resolves a Recent Activity row to its exact
     destination (question card, section, quiz, deck, exam, …) using
     the structured data logActivity() stored, with a friendly
     message when the target no longer exists.
   ============================================================ */

/* Bare route name of the page we are on — same resolution order as
   renderRoute (hash, then the public path, then home). */
function currentRoute() {
  const raw = window.location.hash.replace("#", "")
    || (window.Seo && Seo.routeForPath ? Seo.routeForPath(window.location.pathname) : null)
    || "home";
  return raw.split("?")[0];
}

/* One-shot deep-open target set by openActivity() and consumed by the
   next chapter render (or the next tab switch into place). */
let PENDING_OPEN = null;   // { tab, qid, noun } or { iq: { chapterId, idx } }

function flashHighlight(node) {
  if (!node) return;
  try {
    node.scrollIntoView({ behavior: STATE.reduceMotion ? "auto" : "smooth", block: "center" });
  } catch (e) { node.scrollIntoView(); }
  node.classList.remove("activity-flash");
  void node.offsetWidth;                       // restart the highlight
  node.classList.add("activity-flash");
  setTimeout(() => node.classList.remove("activity-flash"), 2600);
}

/* Find the question/activity card whose .q-id reads e.g. "Q3",
   "Case 2", "Scenario 4" — matched case-insensitively. */
function findQCard(root, noun, qid) {
  if (qid == null) return null;
  const want = (String(noun || "Q") + " " + qid).replace(/\s+/g, " ").trim().toLowerCase();
  const wantAlt = ("q" + qid).toLowerCase();
  const bare = String(qid).toLowerCase();
  const cards = root.querySelectorAll(".q-card");
  for (let i = 0; i < cards.length; i++) {
    const idEl = cards[i].querySelector(".q-id");
    if (!idEl) continue;
    const got = (idEl.textContent || "").replace(/\s+/g, " ").trim().toLowerCase();
    if (got === want || got === wantAlt || got === bare) return cards[i];
  }
  return null;
}

function consumePendingOpen() {
  const pending = PENDING_OPEN;
  if (!pending) return;
  PENDING_OPEN = null;                         // one-shot: never re-fires later
  const route = currentRoute();

  if (pending.iq) {
    if (route !== "important-questions") return;
    const card = document.getElementById("iqcard-" + pending.iq.chapterId + "-" + pending.iq.idx);
    if (card) flashHighlight(card);
    else toast("That important question is no longer available.", "info", "unlink");
    return;
  }
  if (route.indexOf("ch-") !== 0) return;
  const root = $("#view-root");
  if (!root) return;

  const tabOK = ensureActivityTab(pending.tab);
  if (pending.qid == null) {
    /* Tab-only target: the section itself is the destination. If that
       section no longer exists (renamed/removed in an update), say so
       rather than pretending the student asked for another one. */
    if (pending.tab && !tabOK) {
      toast("That section is no longer available — opened Practice Bank instead.", "info", "unlink");
    }
    return;
  }

  let attempts = 0;
  const tryScroll = () => {
    const card = findQCard(root, pending.noun, pending.qid);
    if (card) { flashHighlight(card); return; }
    /* Not on screen yet — a practice filter may be narrowed. Try the
       "All" chip once; if the card still isn't there, say so honestly
       (the right chapter and section ARE open, but the exact question
       could not be found). */
    if (attempts === 0) {
      attempts++;
      const allChip = Array.prototype.slice.call(root.querySelectorAll(".chip"))
        .find(c => (c.textContent || "").trim() === "All" && !c.classList.contains("active"));
      if (allChip) { allChip.click(); setTimeout(tryScroll, 70); return; }
    }
    toast("Couldn't jump to that exact question — its section is open instead.", "info", "unlink");
  };
  setTimeout(tryScroll, 70);
}

/* Switch a chapter to the given tab chip (falls back to the chapter's
   "Practice Bank" when the exact tab no longer exists).
   Returns true when the EXACT requested tab was activated. */
function ensureActivityTab(tab) {
  const root = $("#view-root");
  if (!root) return false;
  const chips = Array.prototype.slice.call(root.querySelectorAll(".chip[data-tab]"));
  if (!chips.length) return false;
  let target = tab ? chips.find(c => c.dataset.tab === tab) : null;
  if (target) {
    if (!target.classList.contains("active")) target.click();   // showTab() renders synchronously
    return true;
  }
  if (tab && tab !== "Practice Bank") {
    const fb = chips.find(c => c.dataset.tab === "Practice Bank");
    if (fb) {
      if (!fb.classList.contains("active")) fb.click();
      return false;                         // exact section gone → caller may tell the student
    }
  }
  return false;
}

/* Open a Recent Activity entry at its exact destination. */
function openActivity(entry) {
  if (!entry) return;
  const route = entry.route;
  if (!route || !routes[route]) {
    toast("This activity is no longer available — it may have been removed in an update.", "info", "unlink");
    return;
  }
  const before = window.location.hash;

  if (entry.type === "iq" && entry.chapterId != null) {
    PENDING_OPEN = { iq: { chapterId: entry.chapterId, idx: entry.qid } };
    navigate(route, "ch=" + encodeURIComponent(entry.chapterId));
  } else if (route.indexOf("ch-") === 0 && (entry.tab || entry.qid != null)) {
    PENDING_OPEN = { tab: entry.tab, qid: entry.qid, noun: entry.qidNoun || "Q" };
    navigate(route);
  } else if (route === "flashcards" && entry.chapterId) {
    navigate(route, "ch=" + encodeURIComponent(entry.chapterId));   // opens the right deck filter
  } else {
    navigate(route);
  }
  /* Already on this route: no hashchange fires, so render directly —
     the pending open is consumed by afterRouteRender(). */
  if (window.location.hash === before) renderRoute();
}

/* ---- Next Section / Next Chapter footer (chapter pages only) ---- */
function getChapterTabs(root) {
  const active = root.querySelector(".chip[data-tab].active") || root.querySelector(".chip[data-tab]");
  if (!active || !active.parentElement) return { chips: [], index: -1 };
  const chips = Array.prototype.slice.call(active.parentElement.querySelectorAll(".chip[data-tab]"));
  return { chips: chips, index: chips.indexOf(active) };
}

function appendSectionNav(root, route) {
  const chapters = activeChapters();
  const titles = {};
  chapters.forEach(c => { titles[c.id] = c.name; });
  const tabsInfo = getChapterTabs(root);
  const plan = UIF.planSectionNav({
    route: route,
    chapters: chapters.map(c => c.id),   // syllabus order of the ACTIVE class only
    tabTitles: tabsInfo.chips.map(c => c.dataset.tab),
    tabIndex: tabsInfo.index,
    chapterTitles: titles
  });
  let bar = document.getElementById("sectionNavFooter");
  if (!plan) { if (bar) bar.remove(); return; }
  if (!bar) {
    bar = document.createElement("div");
    bar.id = "sectionNavFooter";
    bar.className = "section-nav";
    bar.setAttribute("role", "navigation");
    bar.setAttribute("aria-label", "Section and chapter navigation");
    root.appendChild(bar);
  }
  if (plan.kind === "section") {
    bar.innerHTML = `
      <button type="button" class="section-nav-btn ripple-surface" data-nav="section" data-target-index="${plan.nextIndex}">
        <span class="section-nav-kicker">Section ${plan.current} of ${plan.total}</span>
        <span class="section-nav-label">Next Section: ${escapeHtml(plan.nextTitle)} <i data-lucide="arrow-right"></i></span>
      </button>`;
  } else if (plan.kind === "chapter") {
    bar.innerHTML = `
      <button type="button" class="section-nav-btn next-chapter ripple-surface" data-nav="chapter" data-target-route="${plan.nextRoute}">
        <span class="section-nav-kicker">Final section of this chapter</span>
        <span class="section-nav-label">Next Chapter: ${escapeHtml(plan.nextTitle)} <i data-lucide="arrow-right"></i></span>
      </button>`;
  } else {
    bar.innerHTML = `
      <button type="button" class="section-nav-btn final ripple-surface" data-nav="final">
        <span class="section-nav-kicker">Final section of the final chapter</span>
        <span class="section-nav-label">Back to all chapters <i data-lucide="list"></i></span>
      </button>`;
  }
  bar.onclick = (e) => {
    const btn = e.target.closest(".section-nav-btn");
    if (!btn) return;
    const kind = btn.dataset.nav;
    if (kind === "section") {
      const info = getChapterTabs(root);
      const target = info.chips[parseInt(btn.dataset.targetIndex, 10)];
      if (!target) return;
      target.click();                          // showTab() switches the panel
      setTimeout(() => {
        target.scrollIntoView({ behavior: STATE.reduceMotion ? "auto" : "smooth", block: "center" });
      }, 0);
    } else if (kind === "chapter") {
      navigate(btn.dataset.targetRoute);
    } else {
      navigate("chapters-list");
    }
  };
  icons();
}

/* The single post-render hook (called from renderRoute). */
function afterRouteRender(root, route) {
  try {
    if (route.indexOf("ch-") === 0) appendSectionNav(root, route);
    consumePendingOpen();
    if (route === "home") {
      /* v83 — the first-visit class selector owns home until a class is
         chosen; the "About this website" toast waits its turn (and for
         returning students shows exactly as it always did). */
      if (needsClassSelection()) showClassSelector();
      else {
        maybeShowAboutToast();
        /* v87 — optional notification onboarding card (no browser
           prompt fires until the student presses Enable). */
        if (window.ABAPush) ABAPush.maybeShowOnboardingCard(root);
      }
    }
  } catch (err) {
    console.error("afterRouteRender:", err);
  }
}

/* Tab chips inside a chapter re-render their panel synchronously —
   update the footer after the click finishes (and consume a pending
   activity open that just clicked its own tab). */
document.addEventListener("click", (e) => {
  const chip = e.target && e.target.closest ? e.target.closest(".chip[data-tab]") : null;
  if (!chip) return;
  const route = currentRoute();
  if (route.indexOf("ch-") !== 0) return;
  const root = $("#view-root");
  if (!root || !root.contains(chip)) return;
  setTimeout(() => { appendSectionNav(root, route); }, 0);
});

/* ---------------------------------------------------------
   FIRST-VISIT TOAST (6A) — "About this website", once ever, ~2.6 s
   after the home page has rendered. The flag is persisted the moment
   it shows, so navigating away and back (or a new session) never
   re-triggers it. If storage is blocked the in-memory flag still
   holds for the session; if the student leaves home before the timer
   fires, it simply waits for the next home visit.
   --------------------------------------------------------- */
let aboutToastTimer = null;
function maybeShowAboutToast() {
  if (STATE.aboutToastDone || aboutToastTimer) return;
  if (needsClassSelection()) return;          // class not chosen yet — selector first
  const clsMeta = ClassRegistry.CLASS_META[activeClass() || "11"];
  aboutToastTimer = setTimeout(() => {
    aboutToastTimer = null;
    if (currentRoute() !== "home") return;
    if (STATE.aboutToastDone) return;
    if (needsClassSelection()) return;
    STATE.aboutToastDone = true;
    saveState();
    toast(`Your free learning platform for ${clsMeta.label} concepts, practice questions, revision, flashcards, and more.`,
      "info", "info", { title: "About this website", duration: 9000 });
  }, 2600);
}

$all(".nav-item").forEach(n => n.addEventListener("click", (e) => {
  /* Public nav items are real <a href> links for crawlers; the click is
     handled in-app so navigation stays instant. */
  if (n.tagName === "A") e.preventDefault();
  navigate(n.dataset.route);
}));
$all(".bottom-nav-item").forEach(n => n.addEventListener("click", (e) => {
  if (n.tagName === "A") e.preventDefault();
  closeRadialNav();
  navigate(n.dataset.route);
}));

/* ---------------------------------------------------------
   CRAWLABLE INTERNAL LINKS — footer directory, prerendered page
   content and any other in-app <a href="/class-11-accountancy/...">
   link. Crawlers see ordinary anchors; a normal click is turned into
   an in-app route change so students never wait for a full reload.
   Modifier-clicks and new-tab targets are left to the browser.
   --------------------------------------------------------- */
document.addEventListener("click", (e) => {
  if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
  const a = e.target && e.target.closest ? e.target.closest("a[href]") : null;
  if (!a || a.target === "_blank" || a.hasAttribute("download")) return;
  const href = a.getAttribute("href") || "";
  if (href.charAt(0) !== "/" || !window.Seo || !Seo.routeForPath) return;
  let p;
  try { p = new URL(a.href, window.location.origin).pathname; } catch { return; }
  const r = Seo.routeForPath(p);
  if (!r || r === "home" && p === "/" && window.location.hash.replace("#", "") === "home") {
    /* fall through to navigate() below for home too — it is cheap */
  }
  if (!r) return;
  e.preventDefault();
  navigate(r);
});

function closeRadialNav() {
  const nav = $("#bottomNav"), toggle = $("#radialNavToggle");
  if (!nav || !toggle) return;
  nav.classList.remove("open");
  toggle.setAttribute("aria-expanded", "false");
  toggle.setAttribute("aria-label", "Open navigation menu");
}
function toggleRadialNav(e) {
  e.stopPropagation();
  const nav = $("#bottomNav"), toggle = $("#radialNavToggle");
  if (!nav || !toggle) return;
  const open = nav.classList.toggle("open");
  toggle.setAttribute("aria-expanded", String(open));
  toggle.setAttribute("aria-label", open ? "Close navigation menu" : "Open navigation menu");
}
const radialToggle = $("#radialNavToggle");
if (radialToggle) radialToggle.addEventListener("click", toggleRadialNav);
document.addEventListener("pointerdown", e => {
  const nav = $("#bottomNav");
  if (nav && nav.classList.contains("open") && !nav.contains(e.target)) closeRadialNav();
});

/* ---------------------------------------------------------
   SIDEBAR / HAMBURGER — two deliberately separate behaviours, one button.
   • ≤ 860px  : off-canvas DRAWER — hamburger opens/closes it; overlay tap,
                Escape, the ✕ button and any navigation close it.
   • ≥ 861px  : persistent side menu that EXPANDS (icons + labels) and
                COLLAPSES (compact icon rail). The choice is remembered in
                its own tiny localStorage key so a toggle never has to
                re-serialise the whole app state, and index.html applies it
                before first paint so a refresh never flashes/jumps.
   All motion is CSS (width / transform / opacity) — JS only flips classes.
   --------------------------------------------------------- */
const SIDEBAR_PREF_KEY = "aba_sidebar_collapsed";
const NAV_MOBILE_MQ = window.matchMedia("(max-width: 860px)");
function isMobileNav() { return NAV_MOBILE_MQ.matches; }
function isSidebarCollapsed() { return document.documentElement.classList.contains("sb-collapsed"); }

function syncSidebarToggleState() {
  const btn = $("#sidebarToggle"), sb = $("#sidebar");
  if (!btn || !sb) return;
  const mobile = isMobileNav();
  const open = mobile ? sb.classList.contains("open") : !isSidebarCollapsed();
  btn.setAttribute("aria-expanded", String(open));
  btn.setAttribute("aria-controls", "sidebar");
  btn.setAttribute("aria-label", mobile ? (open ? "Close menu" : "Open menu") : (open ? "Collapse sidebar" : "Expand sidebar"));
  // A collapsed rail shows icons only, so give each item a native tooltip; remove them when labels are visible.
  const rail = !mobile && !open;
  sb.querySelectorAll(".nav-item").forEach(n => {
    if (rail) { const l = n.querySelector("span:not(.nav-progress):not(.nav-new-badge)"); if (l) n.title = l.textContent.trim(); }
    else n.removeAttribute("title");
  });
}
function closeSidebar() {
  $("#sidebar").classList.remove("open");
  $("#sidebarOverlay").classList.remove("open");
  document.documentElement.classList.remove("mobile-nav-open");
  syncSidebarToggleState();
}
function openSidebar() {
  if (!isMobileNav()) return;
  $("#sidebar").classList.add("open");
  $("#sidebarOverlay").classList.add("open");
  document.documentElement.classList.add("mobile-nav-open");
  syncSidebarToggleState();
}
let sidebarAnimTimer = null;
function setSidebarCollapsed(collapsed) {
  const root = document.documentElement;
  root.classList.add("sb-anim");                       // promotes the layer only while the transition runs
  root.classList.toggle("sb-collapsed", collapsed);
  clearTimeout(sidebarAnimTimer);
  sidebarAnimTimer = setTimeout(() => root.classList.remove("sb-anim"), 320);
  try { localStorage.setItem(SIDEBAR_PREF_KEY, collapsed ? "1" : "0"); } catch (e) { /* storage blocked */ }
  syncSidebarToggleState();
}
function toggleSidebar() {
  if (isMobileNav()) { $("#sidebar").classList.contains("open") ? closeSidebar() : openSidebar(); }
  else setSidebarCollapsed(!isSidebarCollapsed());
}

function updateNavProgress() {
  $all(".nav-progress").forEach(p => {
    const ch = p.dataset.progress;
    p.textContent = (STATE.chapterProgress[ch] || 0) + "%";
  });
}

/* ---------------------------------------------------------
   SIDEBAR CHAPTER NAV + CLASS SWITCHER (v83)
   The static Class 11 chapter links in index.html stay untouched
   for crawlers and for the Class 11 student; when Class 12 is the
   active class the chapter group is swapped for the Class 12 list
   (real crawlable hrefs), and switching back restores the original
   markup byte-for-byte. Handlers are (re)bound after every swap.
   --------------------------------------------------------- */
function bindChapterNavItems(group) {
  $all(".nav-item", group).forEach(n => {
    if (n.dataset.navBound === "1") return;
    n.dataset.navBound = "1";
    n.addEventListener("click", (e) => {
      if (n.tagName === "A") e.preventDefault();
      navigate(n.dataset.route);
    });
  });
}
function rebuildChapterNav() {
  const group = document.getElementById("chaptersNavGroup");
  if (!group) return;
  if (group.dataset.c11html === undefined) group.dataset.c11html = group.innerHTML;
  const cls = activeClass() || ClassRegistry.CLASS_11;
  if (cls === ClassRegistry.CLASS_11) {
    group.innerHTML = group.dataset.c11html;
    $all(".nav-item", group).forEach(n => delete n.dataset.navBound);   // fresh nodes, fresh binding
  } else {
    group.innerHTML = ClassRegistry.chaptersOf("12").map(ch => `
      <a class="nav-item" data-route="ch-${ch.id}" data-progress="${ch.id}" href="/class-12-accountancy/${ch.slug}/">
        <i data-lucide="${ch.icon}"></i><span>${ch.short || ch.name}</span>
        <span class="nav-progress" data-progress="${ch.id}">${(STATE.chapterProgress[ch.id] || 0)}%</span>
      </a>`).join("");
  }
  bindChapterNavItems(group);
  updateNavProgress();
  const route = typeof currentRoute === "function" ? currentRoute() : "";
  $all(".nav-item", group).forEach(n => n.classList.toggle("active", n.dataset.route === route));
  const switchHost = document.getElementById("classSwitchHost");
  if (switchHost) syncClassSwitchBar(switchHost);
  icons();
}

/* Compact Class 11 / Class 12 segmented control at the top of the
   sidebar (mirrored in Settings). Switching keeps every class's
   progress and jumps home so the whole dashboard is in context. */
function buildClassSwitchBar(host) {
  host.innerHTML = `
    <div class="class-switch" role="group" aria-label="Choose class">
      <button type="button" class="class-switch-btn" data-cls="11" aria-pressed="false">Class 11</button>
      <button type="button" class="class-switch-btn" data-cls="12" aria-pressed="false">Class 12</button>
    </div>
    <p class="class-switch-note">Progress in each class is saved separately.</p>`;
  $all(".class-switch-btn", host).forEach(btn => {
    btn.addEventListener("click", () => {
      const want = btn.dataset.cls;
      if (want === (activeClass() || ClassRegistry.CLASS_11)) return;
      setActiveClass(want, { rerender: false, toast: false });
      toast(`Switched to ${ClassRegistry.CLASS_META[want].shortLabel}. Your other class's progress is saved.`, "success", "repeat");
      navigate("home");
    });
  });
  syncClassSwitchBar(host);
}
function syncClassSwitchBar(host) {
  const cls = activeClass();
  $all(".class-switch-btn", host).forEach(btn => {
    const on = btn.dataset.cls === cls;
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.classList.toggle("active", on);
  });
}

const CHAPTER_BANK = { intro: () => APP_DATA.intro.numericals, terms: () => APP_DATA.terms.numericals, tbase: () => APP_DATA.tbase.numericals, basis: () => APP_DATA.basis.numericals, eq: () => APP_DATA.equation.numericals, dc: () => APP_DATA.debitCredit.numericals, jr: () => APP_DATA.journal.numericals, lg: () => getLedgerPracticePool(), cb: () => APP_DATA.cashBook.numericals, sp2: () => APP_DATA.specialBooks2.numericals, brs: () => APP_DATA.brs.numericals, gst: () => APP_DATA.gst.numericals, tb: () => APP_DATA.tb.numericals, dep: () => APP_DATA.dep.numericals, pres: () => APP_DATA.pres.numericals, roe: () => APP_DATA.roe.numericals, fs: () => APP_DATA.fs.numericals, adj: () => APP_DATA.adj.numericals };
/* v83 — Class 12 practice banks live in the merged per-chapter
   content (APP_DATA[<chapter id>].numericals). Registered from the
   chapter registry so ids can never drift between the two files. */
ClassRegistry.chapterIdsOf("12").forEach(id => {
  CHAPTER_BANK[id] = () => (APP_DATA[id] || {}).numericals || [];
});
function computeChapterProgress(chId) {
  const bank = CHAPTER_BANK[chId] ? CHAPTER_BANK[chId]() : null;
  if (!bank || !bank.length) return 0;
  const solvedCount = Object.keys(STATE.solved).filter(k => k.startsWith(chId + "-")).length;
  return Math.round((solvedCount / bank.length) * 100);
}
function refreshProgress() {
  const CH_NAMES = { intro: "Introduction to Accounting", terms: "Basic Accounting Terms", tbase: "Theory Base of Accounting", basis: "Bases of Accounting", eq: "Accounting Equation", dc: "Rules of Debit & Credit", jr: "Journal", lg: "Ledger", cb: "Special Purpose Books 1 - Cash Book", sp2: "Special Purpose Books 2 - Other Books", brs: "Bank Reconciliation Statement (BRS)", gst: "Accounting of GST", tb: "Trial Balance", dep: "Depreciation", pres: "Provisions and Reserves", roe: "Rectification of Errors", fs: "Financial Statements of Sole Proprietorship", adj: "Adjustment in Preparation of Financial Statements" };
  // BOTH classes are recomputed every time so progress stays correct
  // no matter which class is on screen (and a class switch never has
  // to "catch up" the other list). Class 12 names fall back to the
  // chapter registry.
  ClassRegistry.chapterIdsOf("11").concat(ClassRegistry.chapterIdsOf("12")).forEach(id => {
    const chName = CH_NAMES[id] || chapterTitleOf(id);
    const before = STATE.chapterProgress[id] || 0;
    const after = computeChapterProgress(id);
    STATE.chapterProgress[id] = after;
    if (before < 100 && after >= 100) {
      // The chapter-completion celebration (confetti, sound, the
      // "Chapter Completed" / "Full Syllabus Completed" achievements)
      // now comes from the achievement system, so it can never be
      // earned twice for the same chapter. Only the XP reward is
      // applied directly here — and only the first time.
      addXP(25, `${chName} mastered`);
      logActivity({
        type: "chapter", key: "chdone|" + id,
        text: `Completed every learning stage in ${chName} 🎉`,
        route: "ch-" + id, status: "completed"
      });
    }
  });
  saveState();
  updateNavProgress();
}

/* ---------------------------------------------------------
   5. HOME VIEW
   --------------------------------------------------------- */
// Which chapter + what to do next, given the student's actual local
// progress. Prefers the chapter they were last on (if unfinished), then
// falls back to the first incomplete chapter in syllabus order, then
// treats a fully-complete student as ready for revision.
function pickContinueTarget() {
  const order = activeChapterIds();
  const last = STATE.lastChapterViewed;
  // The last-viewed chapter only counts if it belongs to the class on
  // screen — otherwise a Class 11 student switching to Class 12 would
  // be sent straight back to a Class 11 chapter.
  if (last && order.indexOf(last) !== -1 && (STATE.chapterProgress[last] || 0) < 100) return last;
  const firstIncomplete = order.find(id => (STATE.chapterProgress[id] || 0) < 100);
  return firstIncomplete || (order.indexOf(last) !== -1 ? last : null) || order[0] || "intro";
}
/* ---------------------------------------------------------
   3b. ABOUT THIS WEBSITE — a welcome + guide page. Reuses the
   same design tokens as the rest of the app (no parallel style
   system) and stays skimmable: short explanations up front,
   <details> for anything deeper, real "try it" buttons that
   jump straight into the feature being described.
   --------------------------------------------------------- */
function renderAbout(root) {
  const contId = pickContinueTarget();

  const logoWrap = el("div", "");
  logoWrap.style.cssText = "background:#fff; border-radius:var(--radius-md); padding:20px; display:flex; justify-content:center; margin-bottom:24px; border:1px solid var(--line);";
  logoWrap.innerHTML = `<img src="/assets/logo-full.png" alt="Accountancy By Abhinash — Class ${activeClass() || "11"}" width="900" height="313" style="max-width:320px; width:100%; height:auto;">`;
  root.appendChild(logoWrap);

  /* Quick start hero — class-aware copy (v83): the page describes
     whichever class is on screen, never a hardcoded one. */
  const aboutCls = activeClass() || ClassRegistry.CLASS_11;
  const aboutMeta = ClassRegistry.CLASS_META[aboutCls];
  const hero = el("section", "continue-hero");
  hero.innerHTML = `
    <span class="ch-eyebrow">New here? Start in 3 steps</span>
    <h2 style="margin-top:10px;">1️⃣ Choose a chapter · 2️⃣ Learn &amp; practice · 3️⃣ Take a quiz and review mistakes</h2>
    <p class="ch-sub">Accountancy By Abhinash is a free, interactive learning platform for CBSE ${escapeHtml(aboutMeta.label)} — no account, no email, no password. Studying both classes? Switch any time from the sidebar; each class keeps its own progress.</p>
    <button class="btn-primary ripple-surface" id="aboutStartBtn" style="margin-top:6px;"><i data-lucide="arrow-right"></i> Start Learning</button>
  `;
  root.appendChild(hero);

  /* What is this website */
  root.appendChild(sectionTitle("What is this website?"));
  const whatCard = el("div", "card-solid");
  whatCard.style.padding = "24px";
  const whatChapterList = aboutCls === "12"
    ? "Partnership Fundamentals, Goodwill, Change in Profit-Sharing Ratio, Admission, Retirement &amp; Death, Dissolution, Accounting for Share Capital, Accounting for Debentures, Financial Statements of a Company, Analysis of Financial Statements, Accounting Ratios, the Cash Flow Statement and Computerised Accounting"
    : "Introduction to Accounting, the Accounting Equation, Rules of Debit &amp; Credit, Journal, Ledger, Special Purpose Books 1 - Cash Book, Special Purpose Books 2 - Other Books, Bank Reconciliation Statement (BRS), Accounting of GST, Trial Balance, and Depreciation";
  const whatTools = aboutCls === "12"
    ? "interactive tools (valuation and settlement calculation benches, revaluation and realisation statement builders, classifiers and match-up labs)"
    : "interactive tools (a Depreciation Lab, and detective-style \"solve the case\" challenges for Bank Reconciliation, GST billing, and Trial Balance)";
  whatCard.innerHTML = `
    <p style="font-size:0.92rem; line-height:1.65; margin:0 0 14px;"><b>Accountancy By Abhinash</b> is an interactive learning platform built to help ${escapeHtml(aboutMeta.label)} students learn, practice, revise, and understand Accountancy in one place — instead of jumping between a textbook, a YouTube video, a doubt-solving app, and a separate revision notebook.</p>
    <p style="font-size:0.92rem; line-height:1.65; margin:0 0 14px; color:var(--ink-soft);">It brings together chapter learning, theory and concepts, numerical practice, ${whatTools}, quizzes, flashcards, formula revision, important questions, a timed Exam Mode with downloadable certificates, a Mistake Book that automatically tracks and helps you revisit every wrong answer, bookmarks, performance tracking, and an AI-powered tutor — all covering ${whatChapterList}.</p>
    <p style="font-size:0.95rem; line-height:1.65; margin:0; font-weight:600;">Learn. Practice. Understand. Improve.</p>
  `;
  root.appendChild(whatCard);

  /* Creator section */
  root.appendChild(sectionTitle("Who made this"));
  const creatorCard = el("div", "card-solid");
  creatorCard.style.cssText = "padding:30px 26px; text-align:center;";
  creatorCard.innerHTML = `
    <img src="/assets/brand/icon-192.png" alt="" width="48" height="48" style="border-radius:12px; margin-bottom:14px;">
    <p style="font-size:0.78rem; text-transform:uppercase; letter-spacing:0.08em; color:var(--ink-faint); margin:0 0 6px;">Designed &amp; developed by</p>
    <h3 style="font-family:var(--font-head); font-size:1.3rem; margin:0 0 10px;">D. Abhinash Reddy</h3>
    <p style="font-size:0.86rem; color:var(--ink-soft); max-width:520px; margin:0 auto 14px; line-height:1.6;">Built through <b>Vibe Coding</b> — an approach where ideas, creativity, problem-solving, and AI-assisted development come together to turn an idea into a working digital product.</p>
    <p style="font-size:0.86rem; color:var(--ink-soft); max-width:520px; margin:0 auto; line-height:1.6;">Accountancy By Abhinash was created with one goal: make Accountancy learning more organized, interactive, and easier to understand. It's a personal project, not a company product — and it's still evolving.</p>
  `;
  root.appendChild(creatorCard);

  /* How to use — step journey */
  root.appendChild(sectionTitle("How to use this website"));
  const steps = [
    { icon: "book-open", title: "1. Start with a chapter", body: "Pick Accounting Equation, Rules of Debit &amp; Credit, Journal, or Ledger. Understand the concepts before jumping into hard questions." },
    { icon: "lightbulb", title: "2. Learn the concepts", body: "Each chapter's Theory and Concepts tabs cover the definitions, rules, and logic — the goal is understanding <i>why</i> an account is debited or credited, not memorizing answers." },
    { icon: "pencil-line", title: "3. Practice", body: "Try Journal entries and numerical questions yourself before revealing the solution." },
    { icon: "bot", title: "4. Ask the AI Tutor when confused", body: "Stuck, or not sure why something is debited or credited? Ask the AI Tutor — it's a learning assistant, not just an answer generator." },
    { icon: "help-circle", title: "5. Test your knowledge", body: "Use Quiz, chapter tests, or Exam Mode to check whether you actually understand the topic." },
    { icon: "layers", title: "6. Revise", body: "Flashcards for quick memory checks, the Formula Sheet for rules and formulas, Important Questions for exam prep, your Mistake Book for anything you got wrong, and Bookmarks for anything you flagged for a second look." },
    { icon: "bar-chart-3", title: "7. Track progress", body: "XP, streak, chapter progress, and questions solved answer three questions: what have I learned, what am I weak in, and what should I study next." },
  ];
  const stepsWrap = el("div", "");
  stepsWrap.style.cssText = "display:flex; flex-direction:column; gap:10px;";
  steps.forEach(s => {
    const row = el("div", "focus-item");
    row.style.cursor = "default";
    row.innerHTML = `<span class="fi-icon"><i data-lucide="${s.icon}"></i></span><span><b>${s.title.replace(/^\d+\.\s/, "")}</b><br><span style="color:var(--ink-soft); font-weight:400;">${s.body}</span></span>`;
    stepsWrap.appendChild(row);
  });
  root.appendChild(stepsWrap);

  /* Best learning path */
  root.appendChild(sectionTitle("The best way to study here"));
  const pathCard = el("div", "card-solid");
  pathCard.style.padding = "24px";
  const pathStages = ["Learn", "Understand", "Practice", "Ask Questions", "Take a Quiz", "Review Mistakes", "Revise", "Improve"];
  pathCard.innerHTML = `
    <p style="font-size:0.86rem; color:var(--ink-soft); margin:0 0 16px;">Don't try to use every feature at once. Follow this order, one chapter at a time:</p>
    <div class="journey-stepper" style="margin-bottom:4px;">
      ${pathStages.map((s, i) => `<div class="journey-step js-done" style="min-width:76px;"><span class="js-dot">${i+1}</span><span class="js-label">${s}</span></div>${i < pathStages.length-1 ? '<div class="js-connector"></div>' : ''}`).join("")}
    </div>
  `;
  root.appendChild(pathCard);

  /* Meet the AI Tutor — interactive prompts */
  root.appendChild(sectionTitle("Meet your Accountancy AI Tutor"));
  const aiCard = el("div", "card-solid");
  aiCard.style.padding = "24px";
  const aiPrompts = [
    "Why is Cash debited in this transaction?",
    "Explain this Journal entry like I'm a beginner.",
    "Give me a hint without revealing the answer.",
    "Give me a similar practice question on the Accounting Equation.",
  ];
  aiCard.innerHTML = `
    <p style="font-size:0.9rem; line-height:1.6; margin:0 0 16px;">The AI Tutor is designed to help you <b>understand</b> Accountancy — not just hand you answers. Try tapping one of these:</p>
    <div class="focus-list" id="aiPromptList"></div>
    <button class="btn-ghost ripple-surface" id="aboutTryAI" style="margin-top:16px;"><i data-lucide="bot"></i> Open AI Tutor</button>
  `;
  root.appendChild(aiCard);
  const promptList = $("#aiPromptList", aiCard);
  aiPrompts.forEach(p => {
    const item = el("div", "focus-item");
    item.innerHTML = `<span class="fi-icon"><i data-lucide="message-circle"></i></span><span>"${p}"</span><i data-lucide="chevron-right" style="margin-left:auto; width:16px; height:16px; color:var(--ink-faint);"></i>`;
    item.addEventListener("click", () => askAIAbout(p, null));
    promptList.appendChild(item);
  });

  /* Study tools */
  root.appendChild(sectionTitle("Study tools"));
  const toolsCard = el("div", "card-solid");
  toolsCard.style.padding = "24px";
  toolsCard.innerHTML = `
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(220px,1fr)); gap:16px; font-size:0.86rem; line-height:1.55;">
      <div><b><i data-lucide="calculator" style="width:14px;height:14px; vertical-align:-2px;"></i> Calculator</b><br><span style="color:var(--ink-soft);">Scientific calculator: type with your keyboard, history, memory, DEG/RAD.</span></div>
      <div><b><i data-lucide="notebook-pen" style="width:14px;height:14px; vertical-align:-2px;"></i> Scratch Pad</b><br><span style="color:var(--ink-soft);">Rough working, temporary notes, or jotting a thought.</span></div>
      <div><b><i data-lucide="timer" style="width:14px;height:14px; vertical-align:-2px;"></i> Pomodoro</b><br><span style="color:var(--ink-soft);">Focused study sessions with built-in breaks.</span></div>
      <div><b><i data-lucide="maximize" style="width:14px;height:14px; vertical-align:-2px;"></i> Fullscreen</b><br><span style="color:var(--ink-soft);">A more focused, distraction-free view.</span></div>
    </div>
    <p style="font-size:0.8rem; color:var(--ink-faint); margin:16px 0 0;">On mobile, find these under <b>More → Study tools</b>. On desktop, they're pinned to the bottom of the sidebar.</p>
  `;
  root.appendChild(toolsCard);

  /* Personalization + Progress */
  root.appendChild(sectionTitle("Personalization, progress &amp; XP"));
  const persCard = el("div", "card-solid");
  persCard.style.padding = "24px";
  persCard.innerHTML = `
    <p style="font-size:0.88rem; line-height:1.6; margin:0 0 12px;"><b>Your name</b> is asked once, on your first visit, so the dashboard can greet you naturally — "Good evening, ${STATE.userName ? escapeHtml(firstName()) : "Abhinash"}" — based on the time of day on your device. It's stored only on this device, not sent anywhere, and you can change or clear it any time in Settings.</p>
    <p style="font-size:0.88rem; line-height:1.6; margin:0 0 12px;"><b>XP</b> reflects your learning activity. <b>Streak</b> encourages studying consistently. <b>Progress</b> shows how far through a chapter's learning journey you are. <b>Achievements</b> celebrate meaningful milestones, like finishing a chapter. None of these are meant to pressure you — they're just a way to see your own consistency.</p>
    <p style="font-size:0.88rem; line-height:1.6; margin:0;">Everything — name, XP, progress, quiz history, bookmarks, AI Tutor chats — lives in your browser's local storage. Nothing requires an account, and nothing leaves your device.</p>
  `;
  root.appendChild(persCard);

  /* FAQ */
  root.appendChild(sectionTitle("FAQ"));
  const faqs = [
    ["Is this website free to use?", "Yes — it's a personal project with no payment or subscription anywhere on the site."],
    ["Do I need to create an account?", "No. On your first visit you're asked what to call you (optional), and that's stored locally on your device — there's no email or password."],
    ["Can I use this on mobile?", "Yes, the whole site is responsive, and it can be installed on your phone's home screen like an app (look for \"Add to Home Screen\" / \"Install\" in your browser menu)."],
    ["What should I do if I don't understand a question?", "Open the AI Tutor — either from the sidebar, or tap \"Ask AI about this\" directly on the question — or go back and re-read that chapter's Theory and Concepts tabs."],
    ["Can I track my progress?", "Yes — see the Progress tab for XP, streak, accuracy, chapter completion, and badges earned."],
    ["Can I reset my progress?", "Yes, from Settings → Progress data. You can reset just your progress (keeps your name and preferences), or wipe everything on the device."],
    ["What happens when I get a question wrong?", "It's automatically added to your Mistake Book, with your answer, the correct answer, and the explanation — so you can come back and review exactly what tripped you up, across every chapter."],
    ["Can I earn a certificate?", "Yes — complete a Full Syllabus Examination in Exam Mode covering all chapters, and you'll earn a certificate with your grade, which you can view or download any time from My Certificates on your Progress page."],
    ["Does this website support Dark Mode?", "Yes — toggle it from the sidebar or Settings; your preference is remembered on this device."],
  ];
  const faqWrap = el("div", "card-solid");
  faqWrap.style.padding = "8px 24px";
  faqs.forEach(([q, a], i) => {
    const d = document.createElement("details");
    d.className = "faq-item";
    if (i > 0) d.style.borderTop = "1px solid var(--line)";
    d.innerHTML = `<summary>${q}</summary><div class="faq-answer"><p>${a}</p></div>`;
    faqWrap.appendChild(d);
  });
  root.appendChild(faqWrap);

  /* Closing CTA */
  const closing = el("div", "continue-hero");
  closing.style.marginTop = "40px";
  closing.innerHTML = `
    <span class="ch-eyebrow">Ready?</span>
    <h2>Let's get started</h2>
    <p class="ch-sub">Jump back into ${(activeChapters().find(c=>c.id===contId)||{}).name || "your chapter"}, or explore from the dashboard.</p>
    <button class="btn-primary ripple-surface" id="aboutStartBtn2"><i data-lucide="play"></i> Continue Learning</button>
  `;
  root.appendChild(closing);

  /* v93 — the intro "quick look" video block (heading, card and
     player) was removed here entirely — not CSS-hidden. Nothing else
     on the page referenced it; assets/video/* files are kept on disk
     but are no longer linked from any page. */

  attachRipple(root);
  const goStart = () => navigate(`ch-${contId}`);
  $("#aboutStartBtn").addEventListener("click", goStart);
  $("#aboutStartBtn2").addEventListener("click", goStart);
  $("#aboutTryAI").addEventListener("click", () => navigate("ai-tutor"));
}

/* ============================================================
   HOME — FEATURE CAROUSEL
   A compact, landscape showcase that introduces the platform.
   Design notes:
   - One shared viewport (.hc-viewport) with a landscape aspect
     ratio fixes the slide geometry, so switching slides can never
     change the carousel's height and every slide stays landscape
     on desktop, tablet and phone.
   - Each slide paints its own deep gradient panel with light text,
     so the carousel deliberately contrasts with the pale page
     around it while keeping one consistent design language.
   - Every call-to-action opens a real feature: named routes for
     pages, the real sidebar panels for the study-desk tools.
   - Auto-advance pauses on hover/focus/off-screen, and a single
     global cleanup tears down the previous instance's timer and
     listeners when the student comes back home, so no duplicate
     timers or handlers can ever stack up.
   ============================================================ */
const HOME_CAROUSEL_INTERVAL_MS = 7000;
let homeCarouselCleanup = null;

function buildHomeCarousel(overallPct, cont, contProgress, contId) {
  /* One live carousel at a time: returning home used to stack
     "aba:reducemotion" listeners and leave orphaned intervals
     auto-advancing detached DOM. Tear the previous one down first. */
  if (homeCarouselCleanup) { try { homeCarouselCleanup(); } catch (e) { /* ignore */ } homeCarouselCleanup = null; }

  /* Opens one of the always-available study-desk panels by clicking
     its real toggle in the sidebar — no fake routes, no re-implementation. */
  const openStudyDeskTool = (toggleId) => {
    const btn = document.getElementById(toggleId);
    if (btn) { btn.click(); return; }
    toast("The study desk tools live in the sidebar on every page.", "success", "layout-dashboard");
  };

  /* v83 — the free-learning slide speaks about the class on screen
     (chapter counts, CTA target), so a Class 12 student never reads
     Class 11 copy. */
  const clsMeta = ClassRegistry.CLASS_META[activeClass() || "11"];
  const clsChapters = activeChapters();
  const clsFirst = clsChapters[0] || { id: "intro", name: "Introduction to Accounting" };
  /* v86 — every slide speaks the class on screen: copy, chip lists and
     the SVG illustrations all read the active class, so a Class 12
     student never sees a Class 11 topic, tool or chapter count. */
  const isC12 = activeClass() === ClassRegistry.CLASS_12;
  const SLIDES = [
    {
      id: "free",
      theme: "free",
      eyebrow: `Free learning platform · CBSE ${clsMeta.shortLabel}`,
      heading: `Learn ${clsMeta.shortLabel} Accountancy — Completely Free`,
      headingMini: `${clsMeta.shortLabel} Accountancy, Free`,
      body: `Clear explanations, guided examples and interactive practice across all ${clsChapters.length} chapters. No fees, no locked lessons, no surprises.`,
      bodyMini: `All ${clsChapters.length} chapters with guided practice. No fees, ever.`,
      actions: [
        { label: `Start with Chapter 1 — ${clsFirst.short || clsFirst.name}`, icon: "book-open", kind: "primary", run: () => navigate("ch-" + clsFirst.id) }
      ],
      art: artFreeLearning
    },
    {
      id: "tutor",
      theme: "tutor",
      eyebrow: "Two intelligent tools",
      heading: isC12 ? "AI Tutor + Guided Practise" : "AI Tutor + Accounting Cycle Generator",
      headingMini: isC12 ? "AI Tutor + Practise" : "AI Tutor + Cycle Generator",
      body: isC12
        ? "Ask any Class 12 question — admission, goodwill, forfeiture, a cash-flow computation — and get a step-by-step answer, or work an interactive case in the chapter itself."
        : "Ask any accounting question and get a step-by-step answer — or type a single transaction and watch it flow from journal all the way to final accounts.",
      bodyMini: isC12
        ? "Ask any Class 12 question and get a step-by-step answer."
        : "Ask anything, or type a transaction and watch it flow to final accounts.",
      actions: isC12 ? [
        { label: "Open the AI Tutor", icon: "bot", kind: "primary", run: () => navigate("ai-tutor") },
        { label: "Important Questions", icon: "file-text", kind: "secondary", run: () => navigate("important-questions") }
      ] : [
        { label: "Open the AI Tutor", icon: "bot", kind: "primary", run: () => navigate("ai-tutor") },
        { label: "Accounting Cycle Generator", icon: "repeat", kind: "secondary", run: () => navigate("accounting-cycle") }
      ],
      art: artTutorCycle
    },    {
      id: "mistakes",
      theme: "mistakes",
      eyebrow: "Mistake Book · Progress",
      heading: "Learn From Every Mistake",
      headingMini: "Learn From Every Mistake",
      body: "Questions you get wrong are saved automatically, turned into revision sessions, and tracked on your progress dashboard until you master them.",
      bodyMini: "Wrong answers become revision sessions — tracked until mastered.",
      actions: [
        { label: "Open Mistake Book", icon: "brain", kind: "primary", run: () => navigate("mistake-book") }
      ],
      art: artMistakesProgress
    },
    {
      id: "tools",
      theme: "tools",
      eyebrow: "Study & practice tools",
      heading: "A Full Toolkit for Accountancy",
      headingMini: "A Full Practice Toolkit",
      body: isC12
        ? "Mind maps, quizzes, flashcards, a practice bank, formula sheets and the chapter's interactive labs — every drill your revision needs, organised in one place."
        : "Mind maps, quizzes, flashcards, a practice bank, formula sheets and detective games — every drill your revision needs, organised in one place.",
      bodyMini: "Quizzes, flashcards, mind maps and more — all in one place.",
      /* v86 — the tool chips name the REAL activities of the active
         class: Class 11 keeps its three detective labs, Class 12 lists
         its own interactive case labs instead. */
      chips: isC12
        ? ["Mind Maps", "Quizzes", "Flashcards", "Practice Bank", "Important Questions", "Formula Sheet", "Appropriation Journal Lab", "Revaluation Statement Builder", "Ratio Match-Up"]
        : ["Mind Maps", "Quizzes", "Flashcards", "Practice Bank", "Important Questions", "Formula Sheet", "Accounting in Action", "Term Detective", "BRS Detective"],
      actions: [
        { label: "Browse practice tools", icon: "layers", kind: "primary", run: () => navigate("practice-hub") }
      ],
      art: artStudyTools
    },
    {
      id: "exam",
      theme: "exam",
      eyebrow: "Exam Mode · Certificate",
      heading: "Practise Under Exam Conditions",
      headingMini: "Exam Practice + Certificate",
      body: "A timed, distraction-free paper with instant scoring and worked solutions — and a digital certificate when you meet the requirements.",
      bodyMini: "Timed papers, instant results, and a certificate.",
      actions: [
        { label: "Go to Exam Mode", icon: "timer", kind: "primary", run: () => navigate("exam-mode") }
      ],
      art: artExamCertificate
    },
    {
      id: "desk",
      theme: "desk",
      eyebrow: "Built-in study desk",
      heading: "Your Study Desk, All in One Place",
      headingMini: "Your Study Desk",
      body: "Calculator, scratch pad, pomodoro timer and whiteboard — floating beside your lessons on every page, so you never lose focus.",
      bodyMini: "Calculator, notes, timer and whiteboard — always one tap away.",
      chips: [
        { label: "Calculator", toolId: "floatingCalcToggle" },
        { label: "Scratch Pad", toolId: "scratchPadToggle" },
        { label: "Pomodoro Timer", toolId: "pomodoroToggle" },
        { label: "Digital Whiteboard", toolId: "whiteboardToggle" }
      ],
      chipsAreTools: true,
      actions: [
        { label: "Open the study desk", icon: "layout-dashboard", kind: "primary", run: () => openStudyDeskTool("floatingCalcToggle") }
      ],
      art: artStudyDesk
    }
  ];

  const wrap = el("section", "home-carousel");
  wrap.setAttribute("role", "region");
  wrap.setAttribute("aria-roledescription", "carousel");
  wrap.setAttribute("aria-label", "Platform features");

  const viewport = el("div", "hc-viewport");
  const track = el("div", "hc-track");
  viewport.appendChild(track);

  const dots = el("div", "hc-dots");
  dots.setAttribute("role", "tablist");
  dots.setAttribute("aria-label", "Choose a slide");

  const prevBtn = el("button", "hc-nav hc-prev", `<i data-lucide="chevron-left"></i>`);
  prevBtn.type = "button";
  prevBtn.setAttribute("aria-label", "Previous slide");
  const nextBtn = el("button", "hc-nav hc-next", `<i data-lucide="chevron-right"></i>`);
  nextBtn.type = "button";
  nextBtn.setAttribute("aria-label", "Next slide");

  const pauseBtn = el("button", "hc-pause", `<i data-lucide="pause"></i>`);
  pauseBtn.type = "button";
  pauseBtn.setAttribute("aria-label", "Pause auto-advance");
  pauseBtn.setAttribute("aria-pressed", "false");

  let index = 0;
  let timer = null;
  let userPaused = false;
  let hoverPaused = false;
  let offscreen = false;
  const reduceMotion = () => STATE && STATE.reduceMotion;

  SLIDES.forEach((s, i) => {
    const slide = el("article", `hc-slide hc-slide--${s.theme}${s.headingMini ? " hc-has-mini" : ""}`);
    slide.setAttribute("role", "group");
    slide.setAttribute("aria-roledescription", "slide");
    slide.setAttribute("aria-label", `${i + 1} of ${SLIDES.length}`);
    slide.setAttribute("aria-hidden", i === 0 ? "false" : "true");
    if (i !== 0) slide.setAttribute("inert", "");

    const chipsHtml = s.chips
      ? `<ul class="hc-chips" aria-label="Included tools">${s.chips.map(c =>
          s.chipsAreTools
            ? `<li><button type="button" class="hc-chip-tool" data-hc-tool="${c.toolId}">${c.label}</button></li>`
            : `<li>${c}</li>`
        ).join("")}</ul>`
      : "";
    /* Wide and mini copy are siblings (never nested): CSS shows exactly
       one of them per breakpoint, and the hidden one is fully removed
       from layout so it cannot clip or overflow the fixed-height frame. */
    const headingHtml = `<span class="hc-t-wide">${s.heading}</span><span class="hc-t-mini">${s.headingMini || s.heading}</span>`;
    const bodyHtml = `<span class="hc-t-wide">${s.body}</span><span class="hc-t-mini">${s.bodyMini || s.body}</span>`;

    slide.innerHTML = `
      <div class="hc-copy">
        <span class="hc-eyebrow">${s.eyebrow}</span>
        <h2 class="hc-heading">${headingHtml}</h2>
        <p class="hc-body">${bodyHtml}</p>
        ${chipsHtml}
        <div class="hc-actions">
          ${s.actions.map((a, ai) => `<button type="button" class="hc-btn hc-btn--${a.kind} ripple-surface" data-hc-action="${ai}"><i data-lucide="${a.icon}"></i><span>${a.label}</span></button>`).join("")}
        </div>
      </div>
      <div class="hc-art" aria-hidden="true">${s.art()}</div>
    `;

    slide.querySelectorAll("[data-hc-action]").forEach(btn => {
      const act = s.actions[Number(btn.dataset.hcAction)];
      btn.addEventListener("click", () => act.run());
    });
    if (s.chipsAreTools) {
      slide.querySelectorAll("[data-hc-tool]").forEach(btn => {
        btn.addEventListener("click", () => openStudyDeskTool(btn.dataset.hcTool));
      });
    }

    track.appendChild(slide);

    const dot = el("button", "hc-dot");
    dot.type = "button";
    dot.setAttribute("role", "tab");
    dot.setAttribute("aria-label", `Slide ${i + 1}: ${s.heading}`);
    dot.setAttribute("aria-selected", i === 0 ? "true" : "false");
    dot.addEventListener("click", () => goTo(i, true));
    dots.appendChild(dot);
  });

  const live = el("div", "hc-live");
  live.setAttribute("aria-live", "polite");
  live.setAttribute("aria-atomic", "true");

  wrap.appendChild(viewport);
  wrap.appendChild(prevBtn);
  wrap.appendChild(nextBtn);
  wrap.appendChild(pauseBtn);
  wrap.appendChild(dots);
  wrap.appendChild(live);

  function render() {
    const slides = track.children;
    for (let i = 0; i < slides.length; i++) {
      const active = i === index;
      slides[i].classList.toggle("is-active", active);
      slides[i].setAttribute("aria-hidden", active ? "false" : "true");
      if (active) slides[i].removeAttribute("inert");
      else slides[i].setAttribute("inert", "");
    }
    Array.from(dots.children).forEach((d, i) => {
      d.classList.toggle("is-active", i === index);
      d.setAttribute("aria-selected", i === index ? "true" : "false");
      d.tabIndex = i === index ? 0 : -1;
    });
    // Slide the track so the active slide is the one actually on screen.
    // The track uses the same transition for every slide, and the shared
    // viewport fixes the height, so nothing between slides can jump.
    track.style.transform = `translateX(-${index * 100}%)`;
  }

  function announce() {
    live.textContent = `Slide ${index + 1} of ${SLIDES.length}: ${SLIDES[index].heading}`;
  }

  function goTo(i, fromUser) {
    index = (i + SLIDES.length) % SLIDES.length;
    render();
    announce();
    if (fromUser) restartTimer();
  }

  function next() { goTo(index + 1, false); }
  function prev() { goTo(index - 1, false); }

  function canAutoAdvance() { return !userPaused && !hoverPaused && !offscreen && !reduceMotion() && !document.hidden; }
  function startTimer() {
    if (!canAutoAdvance()) return;
    stopTimer();
    timer = setInterval(() => { next(); }, HOME_CAROUSEL_INTERVAL_MS);
    wrap.classList.remove("is-paused");
  }
  function stopTimer() {
    if (timer) { clearInterval(timer); timer = null; }
  }
  function restartTimer() { stopTimer(); startTimer(); }
  function pauseTemporarily() { hoverPaused = true; stopTimer(); wrap.classList.add("is-paused"); }
  function resumeTemporarily() { hoverPaused = false; startTimer(); }

  // The pause button lives inside `wrap`, so hovering/clicking it fires
  // mouseenter/focusin → hoverPaused. An explicit pause/unpause must win over
  // that transient state: otherwise unpausing silently no-ops (startTimer still
  // sees hoverPaused and bails) and the button looks broken. Clearing
  // hoverPaused in both directions keeps the two flags from fighting; a fresh
  // mouseenter re-arms the hover pause later.
  function syncPauseOwnedState() {
    hoverPaused = false;
    if (userPaused) { stopTimer(); wrap.classList.add("is-paused"); }
    else startTimer();
  }

  prevBtn.addEventListener("click", () => { prev(); restartTimer(); });
  nextBtn.addEventListener("click", () => { next(); restartTimer(); });

  pauseBtn.addEventListener("click", () => {
    userPaused = !userPaused;
    pauseBtn.setAttribute("aria-pressed", String(userPaused));
    pauseBtn.setAttribute("aria-label", userPaused ? "Resume auto-advance" : "Pause auto-advance");
    pauseBtn.innerHTML = `<i data-lucide="${userPaused ? "play" : "pause"}"></i>`;
    syncPauseOwnedState();
    icons();
  });

  wrap.addEventListener("mouseenter", pauseTemporarily);
  wrap.addEventListener("mouseleave", resumeTemporarily);
  wrap.addEventListener("focusin", pauseTemporarily);
  wrap.addEventListener("focusout", (e) => { if (!wrap.contains(e.relatedTarget)) resumeTemporarily(); });

  wrap.addEventListener("keydown", (e) => {
    if (e.key === "ArrowLeft") { e.preventDefault(); prev(); restartTimer(); }
    else if (e.key === "ArrowRight") { e.preventDefault(); next(); restartTimer(); }
    else if (e.key === "Home") { e.preventDefault(); goTo(0, true); }
    else if (e.key === "End") { e.preventDefault(); goTo(SLIDES.length - 1, true); }
  });

  // Touch swipe
  let touchStartX = 0, touchStartY = 0, touching = false;
  wrap.addEventListener("touchstart", (e) => {
    if (e.touches.length !== 1) return;
    touching = true;
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
    pauseTemporarily();
  }, { passive: true });
  wrap.addEventListener("touchend", (e) => {
    if (!touching) return;
    touching = false;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStartX;
    const dy = t.clientY - touchStartY;
    if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) {
      if (dx < 0) next(); else prev();
    }
    resumeTemporarily();
  }, { passive: true });
  wrap.addEventListener("touchcancel", () => { touching = false; resumeTemporarily(); }, { passive: true });

  // Keep reduced-motion in sync if the user toggles it mid-session
  const motionHandler = () => { if (reduceMotion()) stopTimer(); else if (!userPaused && !hoverPaused) startTimer(); };
  window.addEventListener("aba:reducemotion", motionHandler);

  // No autoplay (and no interval work at all) while the carousel is
  // scrolled out of view or the tab is hidden.
  let io = null;
  if ("IntersectionObserver" in window) {
    io = new IntersectionObserver((entries) => {
      offscreen = !entries[0].isIntersecting;
      if (offscreen) stopTimer(); else startTimer();
    }, { threshold: 0.1 });
    io.observe(wrap);
  }
  const onVisibility = () => { if (document.hidden) stopTimer(); else startTimer(); };
  document.addEventListener("visibilitychange", onVisibility);

  homeCarouselCleanup = () => {
    stopTimer();
    window.removeEventListener("aba:reducemotion", motionHandler);
    document.removeEventListener("visibilitychange", onVisibility);
    if (io) io.disconnect();
  };

  render();
  startTimer();
  icons();
  return wrap;
}

/* ---- Carousel illustration helpers (inline SVG, hand-composed,
       no external assets, no network requests) ---- */

/* A four-point sparkle star — the recurring "learning" motif. */
function hcStar(x, y, r, fill, opacity) {
  const k = r * 0.24;
  return `<path d="M${x},${y - r} C${x + k},${y - k} ${x + k},${y - k} ${x + r},${y} C${x + k},${y + k} ${x + k},${y + k} ${x},${y + r} C${x - k},${y + k} ${x - k},${y + k} ${x - r},${y} C${x - k},${y - k} ${x - k},${y - k} ${x},${y - r} Z" fill="${fill}" opacity="${opacity}"/>`;
}

/* Soft depth blobs behind every composition. */
function hcGlow(x, y, rx, ry, color, opacity) {
  return `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${color}" opacity="${opacity}"/>`;
}

