function artTutorCycle() {
  // Left: AI tutor chat. Right: the accounting cycle as a living ring.
  const cx = 344, cy = 158, R = 80;
  const nodes = [
    { a: -90, n: "1", cap: "Transactions" },
    { a: -18, n: "2", cap: "Journal" },
    { a: 54,  n: "3", cap: "Ledger" },
    { a: 126, n: "4", cap: "Trial Balance" },
    { a: 198, n: "5", cap: "Final Accounts" }
  ];
  const pos = (a) => ({ x: cx + R * Math.cos(a * Math.PI / 180), y: cy + R * Math.sin(a * Math.PI / 180) });
  const nodeSvg = nodes.map(nd => {
    const p = pos(nd.a);
    return `<g>
      <circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="21" fill="var(--hc-card-2)" stroke="var(--hc-acc)" stroke-width="2"/>
      <text x="${p.x.toFixed(1)}" y="${(p.y + 5).toFixed(1)}" font-family="Inter, system-ui, sans-serif" font-size="13" font-weight="800" text-anchor="middle" fill="var(--hc-acc)">${nd.n}</text>
      <text x="${p.x.toFixed(1)}" y="${(p.y + 36).toFixed(1)}" font-family="Inter, system-ui, sans-serif" font-size="8.6" font-weight="600" text-anchor="middle" fill="var(--hc-ink-soft)">${nd.cap}</text>
    </g>`;
  }).join("");
  // Directional arrowheads on the ring between the nodes.
  const arrow = (aDeg) => {
    const p = pos(aDeg);
    const rot = aDeg + 90; // tangent direction of travel (clockwise)
    return `<path d="M-5,-4.5 L5,0 L-5,4.5 Z" fill="var(--hc-acc-2)" transform="translate(${p.x.toFixed(1)},${p.y.toFixed(1)}) rotate(${rot})"/>`;
  };

  return `<svg viewBox="0 0 460 320" role="img" aria-label="Left: the AI tutor answering a question. Right: the accounting cycle from transactions to final accounts">
    ${hcGlow(120, 170, 130, 120, "var(--hc-acc)", 0.09)}
    ${hcGlow(344, 158, 128, 128, "var(--hc-acc-2)", 0.07)}
    ${hcStar(232, 44, 9, "var(--hc-acc-2)", 0.7)}

    <!-- chat card -->
    <g>
      <rect x="18" y="34" width="200" height="252" rx="16" fill="var(--hc-card)" stroke="var(--hc-stroke)" stroke-width="1.8"/>
      <circle cx="40" cy="58" r="6" fill="var(--hc-acc)"/>
      <text x="54" y="62" font-family="Inter, system-ui, sans-serif" font-size="10.5" font-weight="800" letter-spacing="1.2" fill="var(--hc-acc)">AI TUTOR</text>
      <line x1="18" y1="76" x2="218" y2="76" stroke="var(--hc-stroke)" stroke-width="1.4"/>

      <!-- student bubble -->
      <rect x="72" y="88" width="130" height="46" rx="12" fill="var(--hc-card-2)" stroke="var(--hc-stroke)" stroke-width="1.3"/>
      <text x="84" y="106" font-family="Inter, system-ui, sans-serif" font-size="9.4" fill="var(--hc-ink-soft)">Why is Capital</text>
      <text x="84" y="120" font-family="Inter, system-ui, sans-serif" font-size="9.4" fill="var(--hc-ink-soft)">credited?</text>

      <!-- tutor bubble -->
      <rect x="28" y="144" width="166" height="94" rx="12" fill="var(--hc-card-2)" stroke="var(--hc-acc)" stroke-width="1.5"/>
      <text x="40" y="163" font-family="Inter, system-ui, sans-serif" font-size="9.4" fill="var(--hc-ink)">Capital is the owner's claim —</text>
      <text x="40" y="177" font-family="Inter, system-ui, sans-serif" font-size="9.4" fill="var(--hc-ink)">the business owes it back, so</text>
      <text x="40" y="191" font-family="Inter, system-ui, sans-serif" font-size="9.4" fill="var(--hc-ink)">it's a <tspan font-weight="800" fill="var(--hc-acc)">liability → credited</tspan>.</text>
      <rect x="40" y="200" width="142" height="26" rx="7" fill="rgba(0,0,0,0.22)"/>
      <text x="50" y="212" font-family="'JetBrains Mono', monospace" font-size="8.2" fill="var(--hc-acc-2)">Cash A/c Dr ₹70,000</text>
      <text x="50" y="222" font-family="'JetBrains Mono', monospace" font-size="8.2" fill="var(--hc-acc-2)">To Capital ₹70,000</text>

      <!-- input pill -->
      <rect x="28" y="250" width="166" height="24" rx="12" fill="rgba(0,0,0,0.22)" stroke="var(--hc-stroke)" stroke-width="1.2"/>
      <text x="40" y="266" font-family="Inter, system-ui, sans-serif" font-size="8.8" fill="var(--hc-ink-faint)">Ask any accounting question…</text>
      <circle cx="182" cy="262" r="8.5" fill="var(--hc-acc)"/>
      <path d="M179,262 L185,262 M182.5,258.8 L185.5,262 L182.5,265.2" stroke="#0E1512" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>
    </g>

    <!-- cycle ring -->
    <circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="var(--hc-stroke)" stroke-width="2" stroke-dasharray="5 7"/>
    ${arrow(-54)}${arrow(90)}${arrow(162)}
    ${nodeSvg}
    <text x="${cx}" y="${cy - 4}" font-family="'Source Serif 4', Georgia, serif" font-size="12.5" font-weight="700" text-anchor="middle" fill="var(--hc-ink)">Accounting</text>
    <text x="${cx}" y="${cy + 12}" font-family="'Source Serif 4', Georgia, serif" font-size="12.5" font-weight="700" text-anchor="middle" fill="var(--hc-ink)">Cycle</text>
  </svg>`;
}

