    { x: 318, y: 182, label: isC12 ? "Activity Labs" : "Detectives", icon: "M11,4.4 a6.6,6.6 0 1 0 0,13.2 a6.6,6.6 0 0 0 0,-13.2 z M20.4,20.4 l-4.2,-4.2", extra: "" }
