/* ---- Bookmarks page — resolves every bookmark key format used
   across the site (chapter practice banks, DC balance-sheet
   questions, Ledger exam questions, Important Questions) back
   to its original question. ---- */
function resolveBookmark(key) {
  const CH_LABEL = { intro: "Ch.1 · Introduction to Accounting", terms: "Ch.2 · Basic Accounting Terms", tbase: "Ch.3 · Theory Base of Accounting", basis: "Ch.4 · Bases of Accounting", eq: "Ch.5 · Accounting Equation", dc: "Ch.6 · Debit & Credit", "dc-bs": "Ch.6 · Balance Sheet Qs", jr: "Ch.7 · Journal", lg: "Ch.8 · Ledger", cb: "Ch.9 · Cash Book", sp2: "Ch.10 · Special Purpose Books 2", brs: "Ch.11 · Bank Reconciliation Statement", gst: "Ch.12 · Accounting of GST", tb: "Ch.13 · Trial Balance", dep: "Ch.14 · Depreciation", pres: "Ch.15 · Provisions and Reserves", roe: "Ch.16 · Rectification of Errors", fs: "Ch.17 · Financial Statements of Sole Proprietorship", adj: "Ch.18 · Adjustment in Preparation of Financial Statements" };
  if (key.startsWith("iq-")) {
    const parts = key.slice(3).split("-");
    const chapter = parts[0], idx = parseInt(parts[1], 10);
    const q = (APP_DATA.importantQuestions[chapter] || [])[idx];
    if (q) return { title: q.q, sub: `${CH_LABEL[chapter] || chapter} · Important Question`, route: "important-questions", body: q.answer };
  }
  if (key.startsWith("lg-exam-")) {
    const m = key.match(/^lg-exam-(easy|medium|hard)-(\d+)$/);
    if (m) {
      const q = (APP_DATA.ledger.examQuestions[m[1]] || [])[parseInt(m[2], 10)];
      if (q) return { title: q.q, sub: "Ch.8 · Exam Question", route: "ch-lg", body: q.a };
    }
  }
  if (key.startsWith("dc-bs-")) {
    const id = parseInt(key.slice(6), 10);
    const q = (APP_DATA.debitCredit.balanceSheetQuestions || []).find(x => x.id === id);
    if (q) return { title: q.transaction || `Balance sheet question ${id}`, sub: CH_LABEL["dc-bs"], route: "ch-dc", body: q.explanation || "" };
  }
  if (key.startsWith("eq-")) {
    const q = APP_DATA.equation.numericals.find(x => x.id === parseInt(key.slice(3), 10));
    if (q) return { title: q.transaction, sub: CH_LABEL.eq, route: "ch-eq", body: q.explanation || "" };
  }
  if (key.startsWith("dc-")) {
    const q = APP_DATA.debitCredit.numericals.find(x => x.id === parseInt(key.slice(3), 10));
    if (q) return { title: q.transaction, sub: CH_LABEL.dc, route: "ch-dc", body: q.explanation || "" };
  }
  if (key.startsWith("jr-")) {
    const q = APP_DATA.journal.numericals.find(x => x.id === parseInt(key.slice(3), 10));
    if (q) return { title: q.transaction, sub: CH_LABEL.jr, route: "ch-jr", body: q.explanation || "" };
  }
  if (key.startsWith("lg-")) {
    const q = getLedgerPracticePool().find(x => x.id === parseInt(key.slice(3), 10));
    if (q) return { title: q.transaction, sub: CH_LABEL.lg, route: "ch-lg", body: q.explanation || "" };
  }
  if (key.startsWith("cb-")) {
    const q = APP_DATA.cashBook.numericals.find(x => x.id === parseInt(key.slice(3), 10));
    if (q) return { title: q.transaction, sub: CH_LABEL.cb, route: "ch-cb", body: q.explanation || "" };
  }
  if (key.startsWith("sp2-")) {
    const q = APP_DATA.specialBooks2.numericals.find(x => x.id === parseInt(key.slice(4), 10));
    if (q) return { title: q.transaction, sub: CH_LABEL.sp2, route: "ch-sp2", body: q.explanation || "" };
  }
  if (key.startsWith("brsdet-")) {
    const c = APP_DATA.brs.detective.find(x => x.id === parseInt(key.slice(7), 10));
    if (c) return { title: c.situation, sub: `${CH_LABEL.brs} · BRS Detective`, route: "ch-brs", body: "" };
  }
  if (key.startsWith("brs-")) {
    const q = APP_DATA.brs.numericals.find(x => x.id === parseInt(key.slice(4), 10));
    if (q) return { title: q.transaction, sub: CH_LABEL.brs, route: "ch-brs", body: q.explanation || "" };
  }
  if (key.startsWith("gstdet-")) {
    const c = APP_DATA.gst.detective.find(x => x.id === parseInt(key.slice(7), 10));
    if (c) return { title: `Goods ${c.billText.goods}, discount ${c.billText.discount}, GST ${c.billText.gstRate}`, sub: `${CH_LABEL.gst} · GST Bill Detective`, route: "ch-gst", body: (c.steps || []).join(" ") };
  }
  if (key.startsWith("gst-")) {
    const q = APP_DATA.gst.numericals.find(x => x.id === parseInt(key.slice(4), 10));
    if (q) return { title: q.question, sub: CH_LABEL.gst, route: "ch-gst", body: q.explanation || "" };
  }
  if (key.startsWith("tbcheck-")) {
    const c = APP_DATA.tb.checkpoint.find(x => x.id === parseInt(key.slice(8), 10));
    if (c) return { title: c.prompt, sub: `${CH_LABEL.tb} · Trial Balance Checkpoint`, route: "ch-tb", body: c.reasoning || "" };
  }
  if (key.startsWith("tb-")) {
    const q = APP_DATA.tb.numericals.find(x => x.id === parseInt(key.slice(3), 10));
    if (q) return { title: q.question, sub: CH_LABEL.tb, route: "ch-tb", body: q.explanation || "" };
  }
  if (key.startsWith("dep-")) {
    const q = APP_DATA.dep.numericals.find(x => x.id === parseInt(key.slice(4), 10));
    if (q) return { title: q.question, sub: CH_LABEL.dep, route: "ch-dep", body: q.explanation || "" };
  }
  if (key.startsWith("pres-lab-")) {
    const c = APP_DATA.pres.decisionLab.find(x => x.id === parseInt(key.slice(9), 10));
    if (c) return { title: c.title, sub: `${CH_LABEL.pres} · Decision Lab`, route: "ch-pres", body: c.situation };
  }
  if (key.startsWith("roe-det-")) {
    const c = APP_DATA.roe.auditCases.find(x => x.id === parseInt(key.slice(8), 10));
    if (c) return { title: c.title, sub: `${CH_LABEL.roe} · Error Detective`, route: "ch-roe", body: c.errorDescription };
  }
  if (key.startsWith("adj-studio-")) {
    const c = APP_DATA.adj.adjustmentCases.find(x => x.id === parseInt(key.slice(11), 10));
    if (c) return { title: c.concept, sub: `${CH_LABEL.adj} · Adjustment Studio`, route: "ch-adj", body: c.adjustment };
  }
  if (key.startsWith("fsbuild-")) {
    const c = APP_DATA.fs.builderCases.find(x => x.id === parseInt(key.slice(8), 10));
    if (c) return { title: c.title, sub: `${CH_LABEL.fs} · Statement Builder`, route: "ch-fs", body: c.adjustments.join(" ") };
  }
  if (key.startsWith("pres-")) {
    const q = APP_DATA.pres.numericals.find(x => x.id === parseInt(key.slice(5), 10));
    if (q) return { title: q.question, sub: CH_LABEL.pres, route: "ch-pres", body: q.explanation || "" };
  }
  if (key.startsWith("roe-")) {
    const q = APP_DATA.roe.numericals.find(x => x.id === parseInt(key.slice(4), 10));
    if (q) return { title: q.question, sub: CH_LABEL.roe, route: "ch-roe", body: q.explanation || "" };
  }
  if (key.startsWith("fs-")) {
    const q = APP_DATA.fs.numericals.find(x => x.id === parseInt(key.slice(3), 10));
    if (q) return { title: q.question, sub: CH_LABEL.fs, route: "ch-fs", body: q.explanation || "" };
  }
  if (key.startsWith("adj-")) {
    const q = APP_DATA.adj.numericals.find(x => x.id === parseInt(key.slice(4), 10));
    if (q) return { title: q.question, sub: CH_LABEL.adj, route: "ch-adj", body: q.explanation || "" };
  }
  if (key.startsWith("intro-")) {
    const q = APP_DATA.intro.numericals.find(x => x.id === parseInt(key.slice(6), 10));
    if (q) return { title: q.question, sub: CH_LABEL.intro, route: "ch-intro", body: q.explanation || "" };
  }
  if (key.startsWith("terms-")) {
    const q = APP_DATA.terms.numericals.find(x => x.id === parseInt(key.slice(6), 10));
    if (q) return { title: q.question, sub: CH_LABEL.terms, route: "ch-terms", body: q.explanation || "" };
  }
  if (key.startsWith("tbase-")) {
    const q = APP_DATA.tbase.numericals.find(x => x.id === parseInt(key.slice(6), 10));
    if (q) return { title: q.question, sub: CH_LABEL.tbase, route: "ch-tbase", body: q.explanation || "" };
  }
  if (key.startsWith("basis-")) {
    const q = APP_DATA.basis.numericals.find(x => x.id === parseInt(key.slice(6), 10));
    if (q) return { title: q.question, sub: CH_LABEL.basis, route: "ch-basis", body: q.explanation || "" };
  }
  return null;
}

function renderBookmarks(root) {
  root.appendChild(sectionTitle("Bookmarks"));
  const hint = el("p", "", "Everything you've tapped the bookmark icon on, across every chapter and question bank.");
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px;";
  root.appendChild(hint);

  if (!STATE.bookmarks.length) {
    const empty = el("div", "card-solid", "");
    empty.style.cssText = "padding:32px; text-align:center; color:var(--ink-faint);";
    empty.innerHTML = `<i data-lucide="bookmark" style="width:32px; height:32px; margin-bottom:10px;"></i><p style="font-size:0.9rem;">No bookmarks yet. Look for the bookmark icon on any question card.</p>`;
    root.appendChild(empty);
    icons();
    return;
  }

  STATE.bookmarks.slice().reverse().forEach(key => {
    const resolved = resolveBookmark(key);
    const card = el("div", "card q-card", "");
    if (!resolved) {
      card.innerHTML = `<div class="q-body" style="color:var(--ink-faint); font-size:0.85rem;">A saved bookmark from an older version of this question bank (${key}).</div>`;
    } else {
      card.innerHTML = `
        <div class="q-meta">
          <span class="diff-badge" style="background:var(--gold-soft); color:var(--gold);">${resolved.sub}</span>
          <button class="icon-btn sm" data-act="unbookmark" style="margin-left:auto;" title="Remove bookmark"><i data-lucide="bookmark-check"></i></button>
        </div>
        <div class="q-body">${resolved.title}</div>
        ${resolved.body ? `<div class="reveal-block" style="margin-top:12px;"><p style="font-size:0.85rem; line-height:1.55;">${resolved.body}</p></div>` : ""}
        <div class="q-actions" style="margin-top:14px;">
          <button class="btn-ghost sm ripple-surface" data-act="goto"><i data-lucide="arrow-right"></i> Open chapter</button>
          ${aiAskCustomBtn({ text: resolved.title, section: resolved.sub, chapterId: null, explanation: resolved.body })}
        </div>
      `;
      card.addEventListener("click", (e) => {
        const btn = e.target.closest("button[data-act]");
        if (!btn) return;
        if (btn.dataset.act === "goto") navigate(resolved.route);
        if (btn.dataset.act === "unbookmark") {
          toggleBookmark(key);   // removes it (and repaints any matching question-card icon)
          card.remove();
          if (!STATE.bookmarks.length) { root.innerHTML = ""; renderBookmarks(root); }
        }
      });
    }
    root.appendChild(card);
  });
  attachRipple(root);
  icons();
}

/* ---------------------------------------------------------
   5z. CHAPTER 1 — INTRODUCTION TO ACCOUNTING
   Follows the same tab structure as every other chapter, plus
   one unique section: "Accounting in Action" — a scripted
   business-scenario walkthrough (Business activity → Transaction
   → Information created → Recorded/classified → Used → Decision)
   with two checkpoint questions per scenario.
   --------------------------------------------------------- */
let introFilterDifficulty = "All";

function renderIntroChapter(root) {
  const data = APP_DATA.intro;
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Chapter 1</span>
    <h1>Introduction to Accounting</h1>
    <p>${APP_DATA.chapters[0].tagline} Meaning, objectives, advantages and limitations, types of information, users and their needs, and the qualitative characteristics that make accounting information worth trusting.</p>
  `));

  const tabs = ["Introduction", "Theory", "Mind Map", "Practice Bank", "Accounting in Action", "Quick Revision"];
  const tabBar = el("div", "", "");
  tabBar.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; margin-bottom:22px;";
  tabs.forEach((t, i) => {
    const chip = el("button", `chip ${i===0?'active':''}`, t);
    chip.dataset.tab = t;
    tabBar.appendChild(chip);
  });
  const journeyEl = renderJourneyStepper(root, "intro");
  root.appendChild(tabBar);
  const panel = el("div", "");
  root.appendChild(panel);

  function showTab(name) {
    $all(".chip", tabBar).forEach(c => c.classList.toggle("active", c.dataset.tab === name));
    panel.innerHTML = "";
    updateJourneyStepper(journeyEl, "intro", name);
    if (name === "Introduction") renderIntroIntro(panel, data);
    if (name === "Theory") renderIntroTheory(panel, data);
    if (name === "Mind Map") renderMindMap(panel, "intro");
    if (name === "Practice Bank") renderIntroPracticeBank(panel, data);
    if (name === "Quick Revision") renderIntroQuickRevision(panel, data);
    if (name === "Accounting in Action") renderIntroActionLab(panel, data);
    icons();
  }
  tabBar.addEventListener("click", e => {
    const chip = e.target.closest(".chip");
    if (chip) showTab(chip.dataset.tab);
  });
  showTab("Introduction");
}

function renderIntroIntro(panel, data) {
  panel.appendChild(sectionTitle("Meaning, purpose & objectives"));
  renderCashBookTheoryBlocks(panel, data.theory.simple, "var(--c-intro)", "var(--c-intro-soft)");
  panel.appendChild(sectionTitle("Key concepts"));
  const grid = el("div", "grid-3");
  data.concepts.forEach(c => {
    const card = el("div", "card liftable", "");
    card.style.padding = "22px";
    card.innerHTML = `<h4 style="font-size:1rem; margin-bottom:8px; color:var(--c-intro);">${c.title}</h4><p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${c.body}</p>`;
    grid.appendChild(card);
  });
  panel.appendChild(grid);
}

function renderIntroTheory(panel, data) {
  panel.appendChild(sectionTitle("Advantages, limitations, information, users & characteristics"));
  renderCashBookTheoryBlocks(panel, data.theory.advanced, "var(--c-intro)", "var(--c-intro-soft)");
}

function renderIntroPracticeBank(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Introduction to Accounting practice bank"));
  const hint = el("p", "", `${data.numericals.length} questions — meaning, objectives, advantages, limitations, users, and qualitative characteristics. Pick the correct option, then check your answer for a full explanation.`);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const filterBar = el("div", "", "");
  filterBar.style.cssText = "display:flex; gap:8px; margin-bottom:18px; flex-wrap:wrap;";
  ["All", "Easy", "Medium", "Hard"].forEach(d => {
    const chip = el("button", `chip ${d === introFilterDifficulty ? "active" : ""}`, d);
    chip.addEventListener("click", () => { introFilterDifficulty = d; renderIntroPracticeBank(panel, data); });
    filterBar.appendChild(chip);
  });
  panel.appendChild(filterBar);

  const list = data.numericals.filter(q => introFilterDifficulty === "All" || q.difficulty === introFilterDifficulty);
  const countLabel = el("p", "", `Showing ${list.length} of ${data.numericals.length} questions`);
  countLabel.style.cssText = "font-size:0.83rem; color:var(--ink-faint); margin-bottom:16px;";
  panel.appendChild(countLabel);

  list.forEach(q => {
    const solvedKey = `intro-${q.id}`;
    const alreadySolved = STATE.solved[solvedKey];
    let picked = null;
    const shuffledOrder = fisherYatesShuffle(q.options.map((_, i) => i));

    const card = el("div", "card q-card", "");
    card.innerHTML = `
      <div class="q-meta">
        <span class="diff-badge ${q.difficulty}">${q.difficulty}</span>
        <span class="q-id">Q${q.id}</span>
        ${alreadySolved ? `<span style="margin-left:auto; color:var(--c-intro); font-size:0.78rem; display:flex; align-items:center; gap:4px;"><i data-lucide="check-circle" style="width:13px;height:13px;"></i> Solved</span>` : ""}
        ${bookmarkButtonHTML(solvedKey, alreadySolved ? "" : "margin-left:auto;")}
      </div>
      <div class="q-body">${q.question}</div>
      <div style="margin-top:14px;">
        <div class="opt-group" data-role="answer" style="display:flex; flex-wrap:wrap; gap:8px;">
          ${shuffledOrder.map(i => `<button class="chip" data-val="${i}">${q.options[i]}</button>`).join("")}
        </div>
      </div>
      <div class="q-actions" style="margin-top:14px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Answer</button>
        ${aiAskBtn("intro.numericals", q)}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);

    card.addEventListener("click", (e) => {
      const optBtn = e.target.closest(".opt-group button[data-val]");
      if (optBtn) {
        const group = optBtn.closest(".opt-group");
        $all("button", group).forEach(b => b.classList.remove("active"));
        optBtn.classList.add("active");
        picked = parseInt(optBtn.dataset.val, 10);
        return;
      }
      const bookmarkBtn = e.target.closest("button[data-act='bookmark']");
      if (bookmarkBtn) {
        toggleBookmark(solvedKey, bookmarkBtn);
        return;
      }
      const checkBtn = e.target.closest("button[data-act='check']");
      if (checkBtn) {
        if (picked === null) {
          revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Pick an option first.</p></div>`;
          return;
        }
        const correct = picked === q.answerIndex;
        if (correct) {
          revealArea.innerHTML = `
            <div class="reveal-block">
              <h4>Correct!</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${q.explanation}</p>
            </div>`;
          playSuccessSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: true, attempts: 1 };
            saveState(); addXP(4, `Introduction to Accounting Q${q.id} solved`); logActivity({ type: "practice", text: `Introduction to Accounting Q${q.id} solved (${q.difficulty})`, route: "ch-intro", tab: "Practice Bank", qid: q.id, difficulty: q.difficulty, status: "solved" }); refreshProgress();
          }
          mistakeBookRecordCorrect(solvedKey);
        } else {
          revealArea.innerHTML = `
            <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
              <h4>Not quite</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${q.options[q.answerIndex]}</b>.<br>${q.explanation}</p>
            </div>`;
          playErrorSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: false, attempts: 1 };
            if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
            saveState(); addXP(-XP_WRONG_PENALTY, `Q${q.id} incorrect`); refreshProgress();
          }
          mistakeBookRecord({
            key: solvedKey, question: q.question, chapter: "intro", chapterLabel: "Introduction to Accounting",
            topic: "Introduction to Accounting", type: "Introduction to Accounting Practice",
            studentAnswer: q.options[picked],
            correctAnswer: q.options[q.answerIndex],
            explanation: q.explanation
          });
        }
        icons();
      }
    });
    panel.appendChild(card);
  });
  applyMobilePager(panel);
  icons();
}

/* ---- Quick Revision — ONE shared renderer for every chapter ----
   Reads whatever blocks the chapter's data.quickRevision provides and
   simply skips what it does not, so all 18 chapters get an identical
   structure while keeping their own wording (block titles come from
   the data: rulesTitle / stepsTitle). Blocks render in this order:
     definition              — the one-line definition
     keyPoints               — "Key points"
     rules                   — rulesTitle (e.g. ledger's four posting rules)
     calculationSteps | balancingSteps | postingRules | addLessLogic
                             — stepsTitle, or the key's default title
     formulas                — [{ label, expr }] the formulas that apply
     formats                 — [{ title?, rows: [line | [label, value]] }]
     distinctions            — [{ title?, head?: [L,R], rows: [[a,b]] }]
     examPoints              — what examiners actually ask for
     commonMistakes          — the traps (flag coloured)
     mnemonic                — the memory line
   --------------------------------------------------------- */
const QR_METHOD_KEYS = [
  ["calculationSteps", "Calculation steps"],
  ["balancingSteps", "Balancing steps"],
  ["postingRules", "Posting rules"],
  ["addLessLogic", "Add/Less logic"]
];
function renderQuickRevision(panel, data, opts) {
  opts = opts || {};
  const qr = (data && data.quickRevision) || {};
  panel.appendChild(sectionTitle("Quick revision"));
  const accent = opts.accent || "var(--ink)";
  const soft = opts.soft || "var(--surface-sunken)";
  const blocks = [];
  const head = (title, color) => `<div class="ledger-rule"${blocks.length ? ` style="margin-top:18px;"` : ""}><h4 style="font-size:0.95rem; margin-bottom:8px;${color ? ` color:${color};` : ""}">${title}</h4>`;
  const addList = (title, arr, tag, color) => {
    if (!Array.isArray(arr) || !arr.length) return;
    const body = `<${tag} style="padding-left:20px;">${arr.map(r => `<li style="margin-bottom:6px; font-size:0.87rem; color:var(--ink-soft);">${r}</li>`).join("")}</${tag}>`;
    blocks.push(head(title, color) + body + `</div>`);
  };

  if (typeof qr.definition === "string" && qr.definition.trim()) {
    blocks.push(`<div class="ledger-rule"><h4 style="font-size:0.95rem; margin-bottom:8px;">Definition</h4><p style="font-size:0.89rem; line-height:1.6; color:var(--ink-soft);">${qr.definition}</p></div>`);
  }
  addList("Key points", qr.keyPoints, "ol");
  addList(qr.rulesTitle || "Rules", qr.rules, "ol");
  for (let i = 0; i < QR_METHOD_KEYS.length; i++) {
    const key = QR_METHOD_KEYS[i][0];
    if (Array.isArray(qr[key]) && qr[key].length) { addList(qr.stepsTitle || QR_METHOD_KEYS[i][1], qr[key], "ol"); break; }
  }
  if (Array.isArray(qr.formulas) && qr.formulas.length) {
    blocks.push(head("Key formulas") + qr.formulas.map(f => {
      const label = typeof f === "string" ? "" : f.label || "";
      const expr = typeof f === "string" ? f : (f.expr || "");
      return `<p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft); margin-bottom:6px;">${label ? `<strong>${label}</strong> — ` : ""}<span class="tnum">${expr}</span></p>`;
    }).join("") + `</div>`);
  }
  if (Array.isArray(qr.formats) && qr.formats.length) {
    blocks.push(head("Formats & structures") + qr.formats.map(fmt => {
      const title = fmt && fmt.title ? `<p style="font-size:0.85rem; font-weight:600; margin:0; padding:8px 10px; background:var(--surface-sunken);">${fmt.title}</p>` : "";
      const rows = ((fmt && fmt.rows) || []).map(row => Array.isArray(row)
        ? `<div style="display:flex; justify-content:space-between; gap:12px; padding:6px 10px; border-top:1px dashed var(--line);"><span>${row[0]}</span><span class="tnum" style="text-align:right;">${row[1] == null ? "" : row[1]}</span></div>`
        : `<div style="padding:6px 10px; border-top:1px dashed var(--line);">${row}</div>`).join("");
      return `<div style="border:1px solid var(--line); border-radius:10px; overflow:hidden; margin-bottom:12px; background:var(--paper-raised); font-size:0.85rem;">${title}${rows}</div>`;
    }).join("") + `</div>`);
  }
  if (Array.isArray(qr.distinctions) && qr.distinctions.length) {
    /* Rendered by column count, so one table shape serves both
       classes: the original Class 11 tables label two columns of
       cells (row width == head length), while Class 12 adds a
       leading aspect column and carries one cell more than the
       head — the extra header cell stays empty. A Class 11 table
       takes the same path and comes out exactly as it always did. */
    const TH = "text-align:left; font-size:0.74rem; text-transform:uppercase; letter-spacing:0.04em; color:var(--ink-faint); padding:6px 10px; border-bottom:1px solid var(--line);";
    const TD0 = "padding:7px 10px; border-bottom:1px solid var(--line); font-weight:600; color:var(--ink); vertical-align:top; width:40%;";
    const TDN = "padding:7px 10px; border-bottom:1px solid var(--line); color:var(--ink-soft); vertical-align:top;";
    blocks.push(head("Key distinctions") + qr.distinctions.map(d => {
      const cap = d && d.title ? `<p style="font-size:0.85rem; font-weight:600; margin:0 0 6px;">${d.title}</p>` : "";
      const srcRows = (d && Array.isArray(d.rows)) ? d.rows : [];
      const rowWidth = srcRows.reduce((m, r) => Math.max(m, Array.isArray(r) ? r.length : 0), 0);
      const headCells = (d && Array.isArray(d.head)) ? d.head.slice() : [];
      if (headCells.length && rowWidth > headCells.length) headCells.unshift("");
      if (headCells.length && rowWidth) headCells.length = Math.min(headCells.length, rowWidth);
      const hr = headCells.length ? `<tr>${headCells.map(h => `<th style="${TH}">${h == null ? "" : h}</th>`).join("")}</tr>` : "";
      const rows = srcRows.map(r => {
        const cells = Array.isArray(r) ? r : [r];
        return `<tr>${cells.map((c, ci) => `<td style="${ci === 0 ? TD0 : TDN}">${c == null ? "" : c}</td>`).join("")}</tr>`;
      }).join("");
      return cap + `<div style="overflow-x:auto; margin-bottom:12px;"><table style="width:100%; border-collapse:collapse; font-size:0.85rem;">${hr}${rows}</table></div>`;
    }).join("") + `</div>`);
  }
  addList("Exam points", qr.examPoints, "ul");
  addList("Common mistakes", qr.commonMistakes, "ul", "var(--flag)");
  if (qr.mnemonic) {
    blocks.push(`<div class="tnum" style="text-align:center; font-size:0.92rem; font-weight:600; color:${accent}; background:${soft}; padding:14px; border-radius:10px; margin-top:18px;">💡 Mnemonic: ${qr.mnemonic}</div>`);
  }
  if (!blocks.length) return;
  const card = el("div", "card-solid", "");
  card.style.padding = "28px";
  card.innerHTML = blocks.join("\n");
  panel.appendChild(card);
}

function renderIntroQuickRevision(panel, data) {
  renderQuickRevision(panel, data, { accent: "var(--c-intro)", soft: "var(--c-intro-soft)" });
}

/* ---- "Accounting in Action" — the chapter's unique interactive
   section. Walks the student through five real-life business
   scenarios along one fixed flow: Business activity → Transaction
   → Information created → Recorded/classified → Information used
   → Decision made. Two checkpoint MCQs per scenario gate the final
   reveal, each wired into XP, the Mistake Book, and sound feedback
   exactly like every other practice question on the site — but
   filed under a separate "introaction-" key so it never distorts
   the chapter's main Practice Bank progress percentage. ---- */
const ACTION_FLOW_STAGES = ["Business Activity", "Transaction", "Information Created", "Recorded / Classified", "Information Used", "Decision Made"];
let introActionIndex = 0;
let introActionState = {}; // { [scenarioId]: { c0: bool|null, c1: bool|null, revealed: bool } }

function renderIntroActionLab(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Accounting in Action 🔎"));
  const hint = el("p", "", `${data.actionLab.length} real business situations. Read what happens, answer the two checkpoints, then see who ends up using this information — and what they decide because of it.`);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const scenarios = data.actionLab;
  if (introActionIndex >= scenarios.length) introActionIndex = 0;
  const sc = scenarios[introActionIndex];
  if (!introActionState[sc.id]) introActionState[sc.id] = { c0: null, c1: null, revealed: false };
  const st = introActionState[sc.id];

  // How far the student has gotten, for the flow strip highlight.
  let reachedStage = 1; // activity + transaction text are shown immediately
  if (st.c0 !== null) reachedStage = 2;
  if (st.c1 !== null) reachedStage = 4;
  if (st.revealed) reachedStage = 5;

  const nav = el("div", "");
  nav.style.cssText = "display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:16px;";
  nav.innerHTML = `
    <button class="icon-btn" data-act="prev" title="Previous scenario"><i data-lucide="chevron-left"></i></button>
    <span style="font-size:0.83rem; font-weight:600; color:var(--ink-soft);">Scenario ${introActionIndex + 1} of ${scenarios.length}</span>
    <button class="icon-btn" data-act="next" title="Next scenario"><i data-lucide="chevron-right"></i></button>
  `;
  panel.appendChild(nav);

  const flowStrip = el("div", "");
  flowStrip.style.cssText = "display:flex; flex-wrap:wrap; gap:6px; margin-bottom:20px;";
  flowStrip.innerHTML = ACTION_FLOW_STAGES.map((s, i) => `
    <span style="flex:1; min-width:100px; text-align:center; font-size:0.72rem; font-weight:600; padding:8px 6px; border-radius:8px;
      background:${i < reachedStage ? "var(--c-intro)" : "var(--c-intro-soft)"}; color:${i < reachedStage ? "#fff" : "var(--c-intro)"};
      opacity:${i < reachedStage ? "1" : "0.7"};">
      ${i + 1}. ${s}
    </span>
  `).join("");
  panel.appendChild(flowStrip);

  const card = el("div", "card-solid", "");
  card.style.padding = "26px";

  const checkpointHtml = (cp, idx) => {
    const answered = st[`c${idx}`] !== null;
    const shuffledOrder = fisherYatesShuffle(cp.options.map((_, i) => i));
    return `
    <div class="ledger-rule" data-checkpoint="${idx}" style="margin-top:18px;">
      <h4 style="font-size:0.9rem; margin-bottom:10px;">Checkpoint ${idx + 1}: ${cp.q}</h4>
      <div class="opt-group" data-role="answer-${idx}" style="display:flex; flex-wrap:wrap; gap:8px; ${answered ? "pointer-events:none; opacity:0.6;" : ""}">
        ${shuffledOrder.map(i => `<button class="chip" data-cpidx="${idx}" data-val="${i}">${cp.options[i]}</button>`).join("")}
      </div>
      <div class="q-actions" style="margin-top:10px;">${aiAskBtn("intro.actionLab", cp)}</div>
      <div class="reveal-area" data-reveal="${idx}" style="margin-top:10px;"></div>
    </div>`;
  };

  card.innerHTML = `
    <div style="display:flex; align-items:center; gap:10px; margin-bottom:14px;">
      <span style="font-size:1.4rem;">🏪</span>
      <h4 style="font-size:1.02rem; margin:0;">${sc.business}</h4>
    </div>
    <div class="ledger-rule">
      <h4 style="font-size:0.85rem; margin-bottom:6px; color:var(--c-intro);">The activity</h4>
      <p style="font-size:0.89rem; line-height:1.6; color:var(--ink-soft);">${sc.activity}</p>
    </div>
    <div class="ledger-rule" style="margin-top:14px;">
      <h4 style="font-size:0.85rem; margin-bottom:6px; color:var(--c-intro);">Why this is a transaction</h4>
      <p style="font-size:0.89rem; line-height:1.6; color:var(--ink-soft);">${sc.transaction}</p>
    </div>
    ${checkpointHtml(sc.checkpoints[0], 0)}
    ${st.c0 !== null ? checkpointHtml(sc.checkpoints[1], 1) : `<p style="font-size:0.82rem; color:var(--ink-faint); margin-top:14px;">Answer Checkpoint 1 to unlock Checkpoint 2.</p>`}
    <div data-decision-area style="margin-top:18px;"></div>
  `;
  panel.appendChild(card);

  // Re-render just the reveal state for an already-answered checkpoint
  // (e.g. after navigating away and back within the same session).
  [0, 1].forEach(idx => {
    if (st[`c${idx}`] !== null && sc.checkpoints[idx]) {
      const revealArea = $(`[data-reveal="${idx}"]`, card);
      if (revealArea) {
        const cp = sc.checkpoints[idx];
        revealArea.innerHTML = st[`c${idx}`]
          ? `<div class="reveal-block"><h4>Correct!</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">${cp.explanation}</p></div>`
          : `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not quite</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${cp.options[cp.answerIndex]}</b>.<br>${cp.explanation}</p></div>`;
      }
    }
  });

  function renderDecisionArea() {
    const area = $("[data-decision-area]", card);
    if (!area) return;
    if (st.c0 === null || st.c1 === null) {
      area.innerHTML = "";
      return;
    }
    if (!st.revealed) {
      area.innerHTML = `<button class="btn-primary ripple-surface" data-act="reveal-decision"><i data-lucide="sparkles"></i> See what happens next</button>`;
      return;
    }
    area.innerHTML = `
      <div class="ledger-rule" style="border-left-color:var(--gold);">
        <h4 style="font-size:0.85rem; margin-bottom:6px;">Recorded &amp; classified</h4>
        <p style="font-size:0.89rem; line-height:1.6; color:var(--ink-soft);">${sc.recorded}</p>
      </div>
      <div class="tnum" style="margin-top:14px; font-size:0.9rem; font-weight:600; color:var(--c-intro); background:var(--c-intro-soft); padding:14px; border-radius:10px;">
        🎯 Decision made: ${sc.decision}
      </div>`;
  }
  renderDecisionArea();

  function answerCheckpoint(idx, picked) {
    const cp = sc.checkpoints[idx];
    const correct = picked === cp.answerIndex;
    const solvedKey = `introaction-${sc.id}-${idx}`;
    st[`c${idx}`] = correct;
    const revealArea = $(`[data-reveal="${idx}"]`, card);
    const group = $(`[data-role="answer-${idx}"]`, card);
    if (group) { group.style.pointerEvents = "none"; group.style.opacity = "0.6"; }
    if (correct) {
      if (revealArea) revealArea.innerHTML = `<div class="reveal-block"><h4>Correct!</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">${cp.explanation}</p></div>`;
      playSuccessSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: true, attempts: 1 };
        saveState(); addXP(3, `Accounting in Action — scenario ${sc.id} checkpoint ${idx + 1}`);
      }
      mistakeBookRecordCorrect(solvedKey);
    } else {
      if (revealArea) revealArea.innerHTML = `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not quite</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${cp.options[cp.answerIndex]}</b>.<br>${cp.explanation}</p></div>`;
      playErrorSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: false, attempts: 1 };
        if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
        saveState();
      }
      mistakeBookRecord({
        key: solvedKey, question: cp.q, chapter: "intro", chapterLabel: "Introduction to Accounting",
        topic: "Accounting in Action", type: "Accounting in Action Scenario",
        studentAnswer: cp.options[picked],
        correctAnswer: cp.options[cp.answerIndex],
        explanation: cp.explanation
      });
    }
    icons();
  }

  card.addEventListener("click", (e) => {
    const optBtn = e.target.closest("button[data-cpidx]");
    if (optBtn) {
      const idx = parseInt(optBtn.dataset.cpidx, 10);
      if (st[`c${idx}`] !== null) return; // already answered
      const picked = parseInt(optBtn.dataset.val, 10);
      answerCheckpoint(idx, picked);
      if (idx === 0) { renderIntroActionLab(panel, data); return; } // re-render to unlock checkpoint 2
      renderDecisionArea();
      icons();
      return;
    }
    const revealBtn = e.target.closest("button[data-act='reveal-decision']");
    if (revealBtn) {
      st.revealed = true;
      /* Once per scenario, ever — re-opening the lab can't re-pay. */
      if (awardXPOnce("aia|" + sc.id, 2, `Accounting in Action — scenario ${sc.id} completed`)) {
        logActivity({
          type: "scenario", key: "aia|" + sc.id,
          text: `Worked through "${sc.business}" in Accounting in Action`,
          route: "ch-intro", tab: "Accounting in Action", status: "completed"
        });
      }
      renderDecisionArea();
      icons();
    }
  });

  nav.addEventListener("click", (e) => {
    const btn = e.target.closest("button[data-act]");
    if (!btn) return;
    if (btn.dataset.act === "prev") introActionIndex = (introActionIndex - 1 + scenarios.length) % scenarios.length;
    if (btn.dataset.act === "next") introActionIndex = (introActionIndex + 1) % scenarios.length;
    renderIntroActionLab(panel, data);
  });

  icons();
}

/* ---------------------------------------------------------
   5y. CHAPTER 2 — BASIC ACCOUNTING TERMS
   Same tab structure as every other chapter, plus one unique
   section: "Term Detective" — a mixed-format case file (situation
   → term, term → meaning, business scenario → term) followed by
   a click-to-match mini-game pairing terms with their meanings.
   --------------------------------------------------------- */
let termsFilterDifficulty = "All";

function renderTermsChapter(root) {
  const data = APP_DATA.terms;
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Chapter 2</span>
    <h1>Basic Accounting Terms</h1>
    <p>${APP_DATA.chapters[1].tagline}. Business, Capital, Drawings, Assets, Liabilities, Debtor, Creditor, Revenue, Expense, Profit, Loss, Trade &amp; Cash Discount, Solvent, Insolvent, and more — all at Class 11 level.</p>
  `));

  const tabs = ["Introduction", "Theory", "Mind Map", "Practice Bank", "Term Detective", "Quick Revision"];
  const tabBar = el("div", "", "");
  tabBar.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; margin-bottom:22px;";
  tabs.forEach((t, i) => {
    const chip = el("button", `chip ${i===0?'active':''}`, t);
    chip.dataset.tab = t;
    tabBar.appendChild(chip);
  });
  const journeyEl = renderJourneyStepper(root, "terms");
  root.appendChild(tabBar);
  const panel = el("div", "");
  root.appendChild(panel);

  function showTab(name) {
    $all(".chip", tabBar).forEach(c => c.classList.toggle("active", c.dataset.tab === name));
    panel.innerHTML = "";
    updateJourneyStepper(journeyEl, "terms", name);
    if (name === "Introduction") renderTermsIntro(panel, data);
    if (name === "Theory") renderTermsTheory(panel, data);
    if (name === "Mind Map") renderMindMap(panel, "terms");
    if (name === "Practice Bank") renderTermsPracticeBank(panel, data);
    if (name === "Quick Revision") renderTermsQuickRevision(panel, data);
    if (name === "Term Detective") renderTermDetective(panel, data);
    icons();
  }
  tabBar.addEventListener("click", e => {
    const chip = e.target.closest(".chip");
    if (chip) showTab(chip.dataset.tab);
  });
  showTab("Introduction");
}

function renderTermsIntro(panel, data) {
  panel.appendChild(sectionTitle("The business, its owner, transactions & records"));
  renderCashBookTheoryBlocks(panel, data.theory.simple, "var(--c-terms)", "var(--c-terms-soft)");
  panel.appendChild(sectionTitle("Key terms at a glance"));
  const grid = el("div", "grid-3");
  data.concepts.forEach(c => {
    const card = el("div", "card liftable", "");
    card.style.padding = "22px";
    card.innerHTML = `<h4 style="font-size:1rem; margin-bottom:8px; color:var(--c-terms);">${c.title}</h4><p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${c.body}</p>`;
    grid.appendChild(card);
  });
  panel.appendChild(grid);
}

function renderTermsTheory(panel, data) {
  panel.appendChild(sectionTitle("Money, goods, people & discounts"));
  renderCashBookTheoryBlocks(panel, data.theory.advanced, "var(--c-terms)", "var(--c-terms-soft)");
}

function renderTermsPracticeBank(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Basic Accounting Terms practice bank"));
  const hint = el("p", "", `${data.numericals.length} questions across all 24 terms. Pick the correct option, then check your answer for a full explanation.`);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const filterBar = el("div", "", "");
  filterBar.style.cssText = "display:flex; gap:8px; margin-bottom:18px; flex-wrap:wrap;";
  ["All", "Easy", "Medium", "Hard"].forEach(d => {
    const chip = el("button", `chip ${d === termsFilterDifficulty ? "active" : ""}`, d);
    chip.addEventListener("click", () => { termsFilterDifficulty = d; renderTermsPracticeBank(panel, data); });
    filterBar.appendChild(chip);
  });
  panel.appendChild(filterBar);

  const list = data.numericals.filter(q => termsFilterDifficulty === "All" || q.difficulty === termsFilterDifficulty);
  const countLabel = el("p", "", `Showing ${list.length} of ${data.numericals.length} questions`);
  countLabel.style.cssText = "font-size:0.83rem; color:var(--ink-faint); margin-bottom:16px;";
  panel.appendChild(countLabel);

  list.forEach(q => {
    const solvedKey = `terms-${q.id}`;
    const alreadySolved = STATE.solved[solvedKey];
    let picked = null;
    const shuffledOrder = fisherYatesShuffle(q.options.map((_, i) => i));

    const card = el("div", "card q-card", "");
    card.innerHTML = `
      <div class="q-meta">
        <span class="diff-badge ${q.difficulty}">${q.difficulty}</span>
        <span class="q-id">Q${q.id}</span>
        ${alreadySolved ? `<span style="margin-left:auto; color:var(--c-terms); font-size:0.78rem; display:flex; align-items:center; gap:4px;"><i data-lucide="check-circle" style="width:13px;height:13px;"></i> Solved</span>` : ""}
        ${bookmarkButtonHTML(solvedKey, alreadySolved ? "" : "margin-left:auto;")}
      </div>
      <div class="q-body">${q.question}</div>
      <div style="margin-top:14px;">
        <div class="opt-group" data-role="answer" style="display:flex; flex-wrap:wrap; gap:8px;">
          ${shuffledOrder.map(i => `<button class="chip" data-val="${i}">${q.options[i]}</button>`).join("")}
        </div>
      </div>
      <div class="q-actions" style="margin-top:14px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Answer</button>
        ${aiAskBtn("terms.numericals", q)}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);

    card.addEventListener("click", (e) => {
      const optBtn = e.target.closest(".opt-group button[data-val]");
      if (optBtn) {
        const group = optBtn.closest(".opt-group");
        $all("button", group).forEach(b => b.classList.remove("active"));
        optBtn.classList.add("active");
        picked = parseInt(optBtn.dataset.val, 10);
        return;
      }
      const bookmarkBtn = e.target.closest("button[data-act='bookmark']");
      if (bookmarkBtn) {
        toggleBookmark(solvedKey, bookmarkBtn);
        return;
      }
      const checkBtn = e.target.closest("button[data-act='check']");
      if (checkBtn) {
        if (picked === null) {
          revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Pick an option first.</p></div>`;
          return;
        }
        const correct = picked === q.answerIndex;
        if (correct) {
          revealArea.innerHTML = `
            <div class="reveal-block">
              <h4>Correct!</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${q.explanation}</p>
            </div>`;
          playSuccessSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: true, attempts: 1 };
            saveState(); addXP(4, `Basic Accounting Terms Q${q.id} solved`); logActivity({ type: "practice", text: `Basic Accounting Terms Q${q.id} solved (${q.difficulty})`, route: "ch-terms", tab: "Practice Bank", qid: q.id, difficulty: q.difficulty, status: "solved" }); refreshProgress();
          }
          mistakeBookRecordCorrect(solvedKey);
        } else {
          revealArea.innerHTML = `
            <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
              <h4>Not quite</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${q.options[q.answerIndex]}</b>.<br>${q.explanation}</p>
            </div>`;
          playErrorSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: false, attempts: 1 };
            if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
            saveState(); addXP(-XP_WRONG_PENALTY, `Q${q.id} incorrect`); refreshProgress();
          }
          mistakeBookRecord({
            key: solvedKey, question: q.question, chapter: "terms", chapterLabel: "Basic Accounting Terms",
            topic: "Basic Accounting Terms", type: "Basic Accounting Terms Practice",
            studentAnswer: q.options[picked],
            correctAnswer: q.options[q.answerIndex],
            explanation: q.explanation
          });
        }
        icons();
      }
    });
    panel.appendChild(card);
  });
  applyMobilePager(panel);
  icons();
}

function renderTermsQuickRevision(panel, data) {
  renderQuickRevision(panel, data, { accent: "var(--c-terms)", soft: "var(--c-terms-soft)" });
}

/* ---- "Term Detective" — the chapter's unique interactive
   section. A shuffled case file mixing three question formats
   (situation → term, term → meaning, business scenario → term),
   followed by a separate click-to-match mini-game. Answers use a
   "termdetective-" key so they never distort the chapter's main
   Practice Bank progress percentage. ---- */
let termDetectiveMode = "cases";
let termDetectiveIndex = 0;
let termDetectiveAnswered = {}; // { [caseIndex]: boolean }
let termMatchState = null; // { termOrder, meaningOrder, selectedTerm, matched:Set, wrongPulse }

function renderTermDetective(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Term Detective 🕵️"));
  const hint = el("p", "", "Crack each case by picking the right accounting term, then test yourself with the matching round.");
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const modeBar = el("div", "");
  modeBar.style.cssText = "display:flex; gap:8px; margin-bottom:20px;";
  modeBar.innerHTML = `
    <button class="chip ${termDetectiveMode === "cases" ? "active" : ""}" data-mode="cases">Case Files</button>
    <button class="chip ${termDetectiveMode === "match" ? "active" : ""}" data-mode="match">Match the Terms</button>
  `;
  modeBar.addEventListener("click", e => {
    const btn = e.target.closest("button[data-mode]");
    if (!btn) return;
    termDetectiveMode = btn.dataset.mode;
    renderTermDetective(panel, data);
  });
  panel.appendChild(modeBar);

  if (termDetectiveMode === "cases") renderTermDetectiveCases(panel, data);
  else renderTermDetectiveMatch(panel, data);
  icons();
}

function renderTermDetectiveCases(panel, data) {
  const cases = data.termDetective.cases;
  if (termDetectiveIndex >= cases.length) termDetectiveIndex = 0;
  const c = cases[termDetectiveIndex];
  const answered = termDetectiveAnswered[termDetectiveIndex];

  const formatLabel = { situation: "Identify the Term", meaning: "Choose the Meaning", case: "Business Scenario" }[c.format] || "Case";

  const nav = el("div", "");
  nav.style.cssText = "display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:16px;";
  nav.innerHTML = `
    <button class="icon-btn" data-act="prev" title="Previous case"><i data-lucide="chevron-left"></i></button>
    <span style="font-size:0.83rem; font-weight:600; color:var(--ink-soft);">Case ${termDetectiveIndex + 1} of ${cases.length}</span>
    <button class="icon-btn" data-act="next" title="Next case"><i data-lucide="chevron-right"></i></button>
  `;
  panel.appendChild(nav);

  const shuffledOrder = fisherYatesShuffle(c.options.map((_, i) => i));
  const card = el("div", "card-solid", "");
  card.style.padding = "26px";
  card.innerHTML = `
    <span class="diff-badge" style="background:var(--c-terms-soft); color:var(--c-terms);">${formatLabel}</span>
    <h4 style="font-size:1rem; margin:12px 0 16px;">${c.prompt}</h4>
    <div class="opt-group" data-role="answer" style="display:flex; flex-wrap:wrap; gap:8px; ${answered ? "pointer-events:none; opacity:0.7;" : ""}">
      ${shuffledOrder.map(i => `<button class="chip" data-val="${i}">${c.options[i]}</button>`).join("")}
    </div>
    <div class="q-actions" style="margin-top:12px;">${aiAskBtn("terms.termDetective", c)}</div>
    <div class="reveal-area" style="margin-top:14px;"></div>
  `;
  panel.appendChild(card);
  const revealArea = $(".reveal-area", card);

  if (answered) {
    revealArea.innerHTML = answered.correct
      ? `<div class="reveal-block"><h4>Case cracked!</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">${c.explanation}</p></div>`
      : `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not quite</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${c.options[c.answerIndex]}</b>.<br>${c.explanation}</p></div>`;
  }

  card.addEventListener("click", e => {
    const optBtn = e.target.closest("button[data-val]");
    if (!optBtn || termDetectiveAnswered[termDetectiveIndex]) return;
    const picked = parseInt(optBtn.dataset.val, 10);
    const correct = picked === c.answerIndex;
    const solvedKey = `termdetective-${termDetectiveIndex}`;
    termDetectiveAnswered[termDetectiveIndex] = { correct };
    $all("button[data-val]", card).forEach(b => b.style.pointerEvents = "none");
    if (correct) {
      revealArea.innerHTML = `<div class="reveal-block"><h4>Case cracked!</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">${c.explanation}</p></div>`;
      playSuccessSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: true, attempts: 1 }; saveState(); addXP(3, "Term Detective — case cracked");
        logActivity({ type: "case", key: "termdet|" + termDetectiveIndex, text: `Term Detective case ${termDetectiveIndex + 1} cracked`, route: "ch-terms", tab: "Term Detective", status: "solved" });
      }
      mistakeBookRecordCorrect(solvedKey);
    } else {
      revealArea.innerHTML = `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not quite</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${c.options[c.answerIndex]}</b>.<br>${c.explanation}</p></div>`;
      playErrorSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: false, attempts: 1 };
        if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
        saveState();
      }
      mistakeBookRecord({
        key: solvedKey, question: c.prompt, chapter: "terms", chapterLabel: "Basic Accounting Terms",
        topic: "Term Detective", type: "Term Detective Case",
        studentAnswer: c.options[picked], correctAnswer: c.options[c.answerIndex], explanation: c.explanation
      });
    }
    icons();
  });

  nav.addEventListener("click", e => {
    const btn = e.target.closest("button[data-act]");
    if (!btn) return;
    if (btn.dataset.act === "prev") termDetectiveIndex = (termDetectiveIndex - 1 + cases.length) % cases.length;
    if (btn.dataset.act === "next") termDetectiveIndex = (termDetectiveIndex + 1) % cases.length;
    renderTermDetective(panel, data);
  });
}

function renderTermDetectiveMatch(panel, data) {
  const pairs = data.termDetective.matchPairs;
  if (!termMatchState || termMatchState.pairs !== pairs) {
    termMatchState = {
      pairs,
      termOrder: fisherYatesShuffle(pairs.map((_, i) => i)),
      meaningOrder: fisherYatesShuffle(pairs.map((_, i) => i)),
      selectedTerm: null,
      matched: new Set()
    };
  }
  const st = termMatchState;

  const progress = el("p", "", `Matched ${st.matched.size} of ${pairs.length} — click a term, then its matching meaning.`);
  progress.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin-bottom:16px;";
  panel.appendChild(progress);

  const grid = el("div", "");
  grid.style.cssText = "display:grid; grid-template-columns:1fr 1fr; gap:24px;";
  const termCol = el("div", "");
  termCol.style.cssText = "display:flex; flex-direction:column; gap:8px;";
  const meaningCol = el("div", "");
  meaningCol.style.cssText = "display:flex; flex-direction:column; gap:8px;";

  st.termOrder.forEach(i => {
    const isMatched = st.matched.has(i);
    const isSelected = st.selectedTerm === i;
    const btn = el("button", "chip", pairs[i].term);
    btn.dataset.term = i;
    btn.style.cssText = `text-align:left; ${isMatched ? "background:var(--c-terms); color:#fff; pointer-events:none;" : ""} ${isSelected ? "outline:2px solid var(--c-terms);" : ""}`;
    termCol.appendChild(btn);
  });
  st.meaningOrder.forEach(i => {
    const isMatched = st.matched.has(i);
    const btn = el("button", "chip", pairs[i].meaning);
    btn.dataset.meaning = i;
    btn.style.cssText = `text-align:left; ${isMatched ? "background:var(--c-terms); color:#fff; pointer-events:none;" : ""}`;
    meaningCol.appendChild(btn);
  });
  grid.appendChild(termCol);
  grid.appendChild(meaningCol);
  panel.appendChild(grid);

  if (st.matched.size === pairs.length) {
    const done = el("div", "reveal-block", "");
    done.style.marginTop = "20px";
    done.innerHTML = `<h4>All matched! 🎉</h4><p style="font-size:0.87rem; color:var(--ink-soft);">You've correctly paired every term with its meaning.</p>`;
    panel.appendChild(done);
  }

  grid.addEventListener("click", e => {
    const termBtn = e.target.closest("button[data-term]");
    const meaningBtn = e.target.closest("button[data-meaning]");
    if (termBtn) {
      st.selectedTerm = parseInt(termBtn.dataset.term, 10);
      renderTermDetective(panel, data);
      return;
    }
    if (meaningBtn && st.selectedTerm !== null) {
      const meaningIdx = parseInt(meaningBtn.dataset.meaning, 10);
      if (meaningIdx === st.selectedTerm) {
        st.matched.add(meaningIdx);
        st.selectedTerm = null;
        playSuccessSound();
        if (st.matched.size === pairs.length) {
          /* Round completion pays once per chapter, ever — replaying
             the round is free practice (anti-farm gate). */
          if (awardXPOnce("round|terms", 6, "Term Detective — matching round completed")) {
            logActivity({
              type: "round", key: "round|terms",
              text: "Completed the Term Detective matching round",
              route: "ch-terms", tab: "Term Detective", status: "completed"
            });
          }
        }
      } else {
        playErrorSound();
        meaningBtn.style.background = "var(--flag-soft)";
        setTimeout(() => { meaningBtn.style.background = ""; }, 350);
        st.selectedTerm = null;
      }
      renderTermDetective(panel, data);
    }
  });
}

/* ---------------------------------------------------------
   5x. CHAPTER 3 — THEORY BASE OF ACCOUNTING, ACCOUNTING
   STANDARDS & INDIAN ACCOUNTING STANDARDS
   Same tab structure as every other chapter, plus one unique
   section: "Concept Detective" — mixed-format cases (situation →
   concept, concept → meaning, AS vs. Ind AS) plus a click-to-match
   mini-game pairing concepts with their meanings.
   --------------------------------------------------------- */
let tbaseFilterDifficulty = "All";

function renderTbaseChapter(root) {
  const data = APP_DATA.tbase;
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Chapter 3</span>
    <h1>Theory Base of Accounting, Accounting Standards &amp; Indian Accounting Standards</h1>
    <p>${APP_DATA.chapters[2].tagline}. GAAP, the three Fundamental Accounting Assumptions, Business Entity, Money Measurement, Cost, Dual Aspect, Revenue Recognition, Matching, Full Disclosure, Consistency, Conservatism, Materiality, Objectivity, Cash vs. Accrual Basis, and AS / Ind AS — all at Class 11 level.</p>
  `));

  const tabs = ["Introduction", "Theory", "Mind Map", "Practice Bank", "Concept Detective", "Quick Revision"];
  const tabBar = el("div", "", "");
  tabBar.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; margin-bottom:22px;";
  tabs.forEach((t, i) => {
    const chip = el("button", `chip ${i===0?'active':''}`, t);
    chip.dataset.tab = t;
    tabBar.appendChild(chip);
  });
  const journeyEl = renderJourneyStepper(root, "tbase");
  root.appendChild(tabBar);
  const panel = el("div", "");
  root.appendChild(panel);

  function showTab(name) {
    $all(".chip", tabBar).forEach(c => c.classList.toggle("active", c.dataset.tab === name));
    panel.innerHTML = "";
    updateJourneyStepper(journeyEl, "tbase", name);
    if (name === "Introduction") renderTbaseIntro(panel, data);
    if (name === "Theory") renderTbaseTheory(panel, data);
    if (name === "Mind Map") renderMindMap(panel, "tbase");
    if (name === "Practice Bank") renderTbasePracticeBank(panel, data);
    if (name === "Quick Revision") renderTbaseQuickRevision(panel, data);
    if (name === "Concept Detective") renderConceptDetective(panel, data);
    icons();
  }
  tabBar.addEventListener("click", e => {
    const chip = e.target.closest(".chip");
    if (chip) showTab(chip.dataset.tab);
  });
  showTab("Introduction");
}

function renderTbaseIntro(panel, data) {
  panel.appendChild(sectionTitle("GAAP, the fundamental assumptions & the basics"));
  renderCashBookTheoryBlocks(panel, data.theory.simple, "var(--c-tbase)", "var(--c-tbase-soft)");
  panel.appendChild(sectionTitle("Key concepts at a glance"));
  const grid = el("div", "grid-3");
  data.concepts.forEach(c => {
    const card = el("div", "card liftable", "");
    card.style.padding = "22px";
    card.innerHTML = `<h4 style="font-size:1rem; margin-bottom:8px; color:var(--c-tbase);">${c.title}</h4><p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${c.body}</p>`;
    grid.appendChild(card);
  });
  panel.appendChild(grid);
}

function renderTbaseTheory(panel, data) {
  panel.appendChild(sectionTitle("Recording principles, honesty & standards"));
  renderCashBookTheoryBlocks(panel, data.theory.advanced, "var(--c-tbase)", "var(--c-tbase-soft)");
}

function renderTbasePracticeBank(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Theory Base practice bank"));
  const hint = el("p", "", `${data.numericals.length} questions across all the assumptions, concepts, and standards. Pick the correct option, then check your answer for a full explanation.`);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const filterBar = el("div", "", "");
  filterBar.style.cssText = "display:flex; gap:8px; margin-bottom:18px; flex-wrap:wrap;";
  ["All", "Easy", "Medium", "Hard"].forEach(d => {
    const chip = el("button", `chip ${d === tbaseFilterDifficulty ? "active" : ""}`, d);
    chip.addEventListener("click", () => { tbaseFilterDifficulty = d; renderTbasePracticeBank(panel, data); });
    filterBar.appendChild(chip);
  });
  panel.appendChild(filterBar);

  const list = data.numericals.filter(q => tbaseFilterDifficulty === "All" || q.difficulty === tbaseFilterDifficulty);
  const countLabel = el("p", "", `Showing ${list.length} of ${data.numericals.length} questions`);
  countLabel.style.cssText = "font-size:0.83rem; color:var(--ink-faint); margin-bottom:16px;";
  panel.appendChild(countLabel);

  list.forEach(q => {
    const solvedKey = `tbase-${q.id}`;
    const alreadySolved = STATE.solved[solvedKey];
    let picked = null;
    const shuffledOrder = fisherYatesShuffle(q.options.map((_, i) => i));

    const card = el("div", "card q-card", "");
    card.innerHTML = `
      <div class="q-meta">
        <span class="diff-badge ${q.difficulty}">${q.difficulty}</span>
        <span class="q-id">Q${q.id}</span>
        ${alreadySolved ? `<span style="margin-left:auto; color:var(--c-tbase); font-size:0.78rem; display:flex; align-items:center; gap:4px;"><i data-lucide="check-circle" style="width:13px;height:13px;"></i> Solved</span>` : ""}
        ${bookmarkButtonHTML(solvedKey, alreadySolved ? "" : "margin-left:auto;")}
      </div>
      <div class="q-body">${q.question}</div>
      <div style="margin-top:14px;">
        <div class="opt-group" data-role="answer" style="display:flex; flex-wrap:wrap; gap:8px;">
          ${shuffledOrder.map(i => `<button class="chip" data-val="${i}">${q.options[i]}</button>`).join("")}
        </div>
      </div>
      <div class="q-actions" style="margin-top:14px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Answer</button>
        ${aiAskBtn("tbase.numericals", q)}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);

    card.addEventListener("click", (e) => {
      const optBtn = e.target.closest(".opt-group button[data-val]");
      if (optBtn) {
        const group = optBtn.closest(".opt-group");
        $all("button", group).forEach(b => b.classList.remove("active"));
        optBtn.classList.add("active");
        picked = parseInt(optBtn.dataset.val, 10);
        return;
      }
      const bookmarkBtn = e.target.closest("button[data-act='bookmark']");
      if (bookmarkBtn) {
        toggleBookmark(solvedKey, bookmarkBtn);
        return;
      }
      const checkBtn = e.target.closest("button[data-act='check']");
      if (checkBtn) {
        if (picked === null) {
          revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Pick an option first.</p></div>`;
          return;
        }
        const correct = picked === q.answerIndex;
        if (correct) {
          revealArea.innerHTML = `
            <div class="reveal-block">
              <h4>Correct!</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${q.explanation}</p>
            </div>`;
          playSuccessSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: true, attempts: 1 };
            saveState(); addXP(4, `Theory Base Q${q.id} solved`); logActivity({ type: "practice", text: `Theory Base Q${q.id} solved (${q.difficulty})`, route: "ch-tbase", tab: "Practice Bank", qid: q.id, difficulty: q.difficulty, status: "solved" }); refreshProgress();
          }
          mistakeBookRecordCorrect(solvedKey);
        } else {
          revealArea.innerHTML = `
            <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
              <h4>Not quite</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${q.options[q.answerIndex]}</b>.<br>${q.explanation}</p>
            </div>`;
          playErrorSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: false, attempts: 1 };
            if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
            saveState(); addXP(-XP_WRONG_PENALTY, `Q${q.id} incorrect`); refreshProgress();
          }
          mistakeBookRecord({
            key: solvedKey, question: q.question, chapter: "tbase", chapterLabel: "Theory Base of Accounting",
            topic: "Theory Base of Accounting", type: "Theory Base Practice",
            studentAnswer: q.options[picked],
            correctAnswer: q.options[q.answerIndex],
            explanation: q.explanation
          });
        }
        icons();
      }
    });
    panel.appendChild(card);
  });
  applyMobilePager(panel);
  icons();
}

function renderTbaseQuickRevision(panel, data) {
  renderQuickRevision(panel, data, { accent: "var(--c-tbase)", soft: "var(--c-tbase-soft)" });
}

/* ---- "Concept Detective" — the chapter's unique interactive
   section. Mixed-format cases (situation → concept, concept →
   meaning, AS vs. Ind AS distinctions, business scenario →
   concept) plus a separate click-to-match mini-game. Answers use
   a "conceptdetective-" key so they never distort the chapter's
   main Practice Bank progress percentage. ---- */
let conceptDetectiveMode = "cases";
let conceptDetectiveIndex = 0;
let conceptDetectiveAnswered = {}; // { [caseIndex]: { correct } }
let conceptMatchState = null; // { pairs, termOrder, meaningOrder, selectedTerm, matched:Set }

function renderConceptDetective(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Concept Detective 🕵️‍♀️"));
  const hint = el("p", "", "Crack each case by identifying the right assumption, concept, basis, or standard, then test yourself with the matching round.");
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const modeBar = el("div", "");
  modeBar.style.cssText = "display:flex; gap:8px; margin-bottom:20px;";
  modeBar.innerHTML = `
    <button class="chip ${conceptDetectiveMode === "cases" ? "active" : ""}" data-mode="cases">Case Files</button>
    <button class="chip ${conceptDetectiveMode === "match" ? "active" : ""}" data-mode="match">Match the Concepts</button>
  `;
  modeBar.addEventListener("click", e => {
    const btn = e.target.closest("button[data-mode]");
    if (!btn) return;
    conceptDetectiveMode = btn.dataset.mode;
    renderConceptDetective(panel, data);
  });
  panel.appendChild(modeBar);

  if (conceptDetectiveMode === "cases") renderConceptDetectiveCases(panel, data);
  else renderConceptDetectiveMatch(panel, data);
  icons();
}

function renderConceptDetectiveCases(panel, data) {
  const cases = data.conceptDetective.cases;
  if (conceptDetectiveIndex >= cases.length) conceptDetectiveIndex = 0;
  const c = cases[conceptDetectiveIndex];
  const answered = conceptDetectiveAnswered[conceptDetectiveIndex];

  const formatLabel = { situation: "Identify the Concept", meaning: "Choose the Meaning", as: "AS vs. Ind AS", case: "Business Scenario" }[c.format] || "Case";

  const nav = el("div", "");
  nav.style.cssText = "display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:16px;";
  nav.innerHTML = `
    <button class="icon-btn" data-act="prev" title="Previous case"><i data-lucide="chevron-left"></i></button>
    <span style="font-size:0.83rem; font-weight:600; color:var(--ink-soft);">Case ${conceptDetectiveIndex + 1} of ${cases.length}</span>
    <button class="icon-btn" data-act="next" title="Next case"><i data-lucide="chevron-right"></i></button>
  `;
  panel.appendChild(nav);

  const shuffledOrder = fisherYatesShuffle(c.options.map((_, i) => i));
  const card = el("div", "card-solid", "");
  card.style.padding = "26px";
  card.innerHTML = `
    <span class="diff-badge" style="background:var(--c-tbase-soft); color:var(--c-tbase);">${formatLabel}</span>
    <h4 style="font-size:1rem; margin:12px 0 16px;">${c.prompt}</h4>
    <div class="opt-group" data-role="answer" style="display:flex; flex-wrap:wrap; gap:8px; ${answered ? "pointer-events:none; opacity:0.7;" : ""}">
      ${shuffledOrder.map(i => `<button class="chip" data-val="${i}">${c.options[i]}</button>`).join("")}
    </div>
    <div class="q-actions" style="margin-top:12px;">${aiAskBtn("tbase.conceptDetective", c)}</div>
    <div class="reveal-area" style="margin-top:14px;"></div>
  `;
  panel.appendChild(card);
  const revealArea = $(".reveal-area", card);

  if (answered) {
    revealArea.innerHTML = answered.correct
      ? `<div class="reveal-block"><h4>Case cracked!</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">${c.explanation}</p></div>`
      : `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not quite</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${c.options[c.answerIndex]}</b>.<br>${c.explanation}</p></div>`;
  }

  card.addEventListener("click", e => {
    const optBtn = e.target.closest("button[data-val]");
    if (!optBtn || conceptDetectiveAnswered[conceptDetectiveIndex]) return;
    const picked = parseInt(optBtn.dataset.val, 10);
    const correct = picked === c.answerIndex;
    const solvedKey = `conceptdetective-${conceptDetectiveIndex}`;
    conceptDetectiveAnswered[conceptDetectiveIndex] = { correct };
    $all("button[data-val]", card).forEach(b => b.style.pointerEvents = "none");
    if (correct) {
      revealArea.innerHTML = `<div class="reveal-block"><h4>Case cracked!</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">${c.explanation}</p></div>`;
      playSuccessSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: true, attempts: 1 }; saveState(); addXP(3, "Concept Detective — case cracked");
        logActivity({ type: "case", key: "conceptdet|" + conceptDetectiveIndex, text: `Concept Detective case ${conceptDetectiveIndex + 1} cracked`, route: "ch-tbase", tab: "Concept Detective", status: "solved" });
      }
      mistakeBookRecordCorrect(solvedKey);
    } else {
      revealArea.innerHTML = `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not quite</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${c.options[c.answerIndex]}</b>.<br>${c.explanation}</p></div>`;
      playErrorSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: false, attempts: 1 };
        if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
        saveState();
      }
      mistakeBookRecord({
        key: solvedKey, question: c.prompt, chapter: "tbase", chapterLabel: "Theory Base of Accounting",
        topic: "Concept Detective", type: "Concept Detective Case",
        studentAnswer: c.options[picked], correctAnswer: c.options[c.answerIndex], explanation: c.explanation
      });
    }
    icons();
  });

  nav.addEventListener("click", e => {
    const btn = e.target.closest("button[data-act]");
    if (!btn) return;
    if (btn.dataset.act === "prev") conceptDetectiveIndex = (conceptDetectiveIndex - 1 + cases.length) % cases.length;
    if (btn.dataset.act === "next") conceptDetectiveIndex = (conceptDetectiveIndex + 1) % cases.length;
    renderConceptDetective(panel, data);
  });
}

function renderConceptDetectiveMatch(panel, data) {
  const pairs = data.conceptDetective.matchPairs;
  if (!conceptMatchState || conceptMatchState.pairs !== pairs) {
    conceptMatchState = {
      pairs,
      termOrder: fisherYatesShuffle(pairs.map((_, i) => i)),
      meaningOrder: fisherYatesShuffle(pairs.map((_, i) => i)),
      selectedTerm: null,
      matched: new Set()
    };
  }
  const st = conceptMatchState;

  const progress = el("p", "", `Matched ${st.matched.size} of ${pairs.length} — click a concept, then its matching meaning.`);
  progress.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin-bottom:16px;";
  panel.appendChild(progress);

  const grid = el("div", "");
  grid.style.cssText = "display:grid; grid-template-columns:1fr 1fr; gap:24px;";
  const termCol = el("div", "");
  termCol.style.cssText = "display:flex; flex-direction:column; gap:8px;";
  const meaningCol = el("div", "");
  meaningCol.style.cssText = "display:flex; flex-direction:column; gap:8px;";

  st.termOrder.forEach(i => {
    const isMatched = st.matched.has(i);
    const isSelected = st.selectedTerm === i;
    const btn = el("button", "chip", pairs[i].term);
    btn.dataset.term = i;
    btn.style.cssText = `text-align:left; ${isMatched ? "background:var(--c-tbase); color:#fff; pointer-events:none;" : ""} ${isSelected ? "outline:2px solid var(--c-tbase);" : ""}`;
    termCol.appendChild(btn);
  });
  st.meaningOrder.forEach(i => {
    const isMatched = st.matched.has(i);
    const btn = el("button", "chip", pairs[i].meaning);
    btn.dataset.meaning = i;
    btn.style.cssText = `text-align:left; ${isMatched ? "background:var(--c-tbase); color:#fff; pointer-events:none;" : ""}`;
    meaningCol.appendChild(btn);
  });
  grid.appendChild(termCol);
  grid.appendChild(meaningCol);
  panel.appendChild(grid);

  if (st.matched.size === pairs.length) {
    const done = el("div", "reveal-block", "");
    done.style.marginTop = "20px";
    done.innerHTML = `<h4>All matched! 🎉</h4><p style="font-size:0.87rem; color:var(--ink-soft);">You've correctly paired every concept with its meaning.</p>`;
    panel.appendChild(done);
  }

  grid.addEventListener("click", e => {
    const termBtn = e.target.closest("button[data-term]");
    const meaningBtn = e.target.closest("button[data-meaning]");
    if (termBtn) {
      st.selectedTerm = parseInt(termBtn.dataset.term, 10);
      renderConceptDetective(panel, data);
      return;
    }
    if (meaningBtn && st.selectedTerm !== null) {
      const meaningIdx = parseInt(meaningBtn.dataset.meaning, 10);
      if (meaningIdx === st.selectedTerm) {
        st.matched.add(meaningIdx);
        st.selectedTerm = null;
        playSuccessSound();
        if (st.matched.size === pairs.length) {
          if (awardXPOnce("round|tbase", 6, "Concept Detective — matching round completed")) {
            logActivity({
              type: "round", key: "round|tbase",
              text: "Completed the Concept Detective matching round",
              route: "ch-tbase", tab: "Concept Detective", status: "completed"
            });
          }
        }
      } else {
        playErrorSound();
        meaningBtn.style.background = "var(--flag-soft)";
        setTimeout(() => { meaningBtn.style.background = ""; }, 350);
        st.selectedTerm = null;
      }
      renderConceptDetective(panel, data);
    }
  });
}

/* ---------------------------------------------------------
   5w. CHAPTER 4 — BASES OF ACCOUNTING
   Same tab structure as every other chapter, plus one unique
   section: "Basis Switch" — flip between Cash Basis and Accrual
   Basis to see the SAME situation treated differently, a side-by-
   side compare view, and checkpoint questions on the switching
   logic itself.
   --------------------------------------------------------- */
let basisFilterDifficulty = "All";

function renderBasisChapter(root) {
  const data = APP_DATA.basis;
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Chapter 4</span>
    <h1>Bases of Accounting</h1>
    <p>${APP_DATA.chapters[3].tagline}. Cash Basis, Accrual Basis, their features, advantages and limitations, and how outstanding expenses, prepaid expenses, accrued income, and income received in advance are treated under each — all at Class 11 level.</p>
  `));

  const tabs = ["Introduction", "Theory", "Mind Map", "Practice Bank", "Basis Switch", "Quick Revision"];
  const tabBar = el("div", "", "");
  tabBar.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; margin-bottom:22px;";
  tabs.forEach((t, i) => {
    const chip = el("button", `chip ${i===0?'active':''}`, t);
    chip.dataset.tab = t;
    tabBar.appendChild(chip);
  });
  const journeyEl = renderJourneyStepper(root, "basis");
  root.appendChild(tabBar);
  const panel = el("div", "");
  root.appendChild(panel);

  function showTab(name) {
    $all(".chip", tabBar).forEach(c => c.classList.toggle("active", c.dataset.tab === name));
    panel.innerHTML = "";
    updateJourneyStepper(journeyEl, "basis", name);
    if (name === "Introduction") renderBasisIntro(panel, data);
    if (name === "Theory") renderBasisTheory(panel, data);
    if (name === "Mind Map") renderMindMap(panel, "basis");
    if (name === "Practice Bank") renderBasisPracticeBank(panel, data);
    if (name === "Quick Revision") renderBasisQuickRevision(panel, data);
    if (name === "Basis Switch") renderBasisSwitch(panel, data);
    icons();
  }
  tabBar.addEventListener("click", e => {
    const chip = e.target.closest(".chip");
    if (chip) showTab(chip.dataset.tab);
  });
  showTab("Introduction");
}

function renderBasisIntro(panel, data) {
  panel.appendChild(sectionTitle("Meaning, Cash Basis & its limitations"));
  renderCashBookTheoryBlocks(panel, data.theory.simple, "var(--c-basis)", "var(--c-basis-soft)");
  panel.appendChild(sectionTitle("Key concepts at a glance"));
  const grid = el("div", "grid-3");
  data.concepts.forEach(c => {
    const card = el("div", "card liftable", "");
    card.style.padding = "22px";
    card.innerHTML = `<h4 style="font-size:1rem; margin-bottom:8px; color:var(--c-basis);">${c.title}</h4><p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${c.body}</p>`;
    grid.appendChild(card);
  });
  panel.appendChild(grid);
}

function renderBasisTheory(panel, data) {
  panel.appendChild(sectionTitle("Accrual Basis, key differences & the four adjustments"));
  renderCashBookTheoryBlocks(panel, data.theory.advanced, "var(--c-basis)", "var(--c-basis-soft)");
}

function renderBasisPracticeBank(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Bases of Accounting practice bank"));
  const hint = el("p", "", `${data.numericals.length} questions on Cash Basis, Accrual Basis, and the four key adjustments. Pick the correct option, then check your answer for a full explanation.`);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const filterBar = el("div", "", "");
  filterBar.style.cssText = "display:flex; gap:8px; margin-bottom:18px; flex-wrap:wrap;";
  ["All", "Easy", "Medium", "Hard"].forEach(d => {
    const chip = el("button", `chip ${d === basisFilterDifficulty ? "active" : ""}`, d);
    chip.addEventListener("click", () => { basisFilterDifficulty = d; renderBasisPracticeBank(panel, data); });
    filterBar.appendChild(chip);
  });
  panel.appendChild(filterBar);

  const list = data.numericals.filter(q => basisFilterDifficulty === "All" || q.difficulty === basisFilterDifficulty);
  const countLabel = el("p", "", `Showing ${list.length} of ${data.numericals.length} questions`);
  countLabel.style.cssText = "font-size:0.83rem; color:var(--ink-faint); margin-bottom:16px;";
  panel.appendChild(countLabel);

  list.forEach(q => {
    const solvedKey = `basis-${q.id}`;
    const alreadySolved = STATE.solved[solvedKey];
    let picked = null;
    const shuffledOrder = fisherYatesShuffle(q.options.map((_, i) => i));

    const card = el("div", "card q-card", "");
    card.innerHTML = `
      <div class="q-meta">
        <span class="diff-badge ${q.difficulty}">${q.difficulty}</span>
        <span class="q-id">Q${q.id}</span>
        ${alreadySolved ? `<span style="margin-left:auto; color:var(--c-basis); font-size:0.78rem; display:flex; align-items:center; gap:4px;"><i data-lucide="check-circle" style="width:13px;height:13px;"></i> Solved</span>` : ""}
        ${bookmarkButtonHTML(solvedKey, alreadySolved ? "" : "margin-left:auto;")}
      </div>
      <div class="q-body">${q.question}</div>
      <div style="margin-top:14px;">
        <div class="opt-group" data-role="answer" style="display:flex; flex-wrap:wrap; gap:8px;">
          ${shuffledOrder.map(i => `<button class="chip" data-val="${i}">${q.options[i]}</button>`).join("")}
        </div>
      </div>
      <div class="q-actions" style="margin-top:14px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Answer</button>
        ${aiAskBtn("basis.numericals", q)}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);

    card.addEventListener("click", (e) => {
      const optBtn = e.target.closest(".opt-group button[data-val]");
      if (optBtn) {
        const group = optBtn.closest(".opt-group");
        $all("button", group).forEach(b => b.classList.remove("active"));
        optBtn.classList.add("active");
        picked = parseInt(optBtn.dataset.val, 10);
        return;
      }
      const bookmarkBtn = e.target.closest("button[data-act='bookmark']");
      if (bookmarkBtn) {
        toggleBookmark(solvedKey, bookmarkBtn);
        return;
      }
      const checkBtn = e.target.closest("button[data-act='check']");
      if (checkBtn) {
        if (picked === null) {
          revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Pick an option first.</p></div>`;
          return;
        }
        const correct = picked === q.answerIndex;
        if (correct) {
          revealArea.innerHTML = `
            <div class="reveal-block">
              <h4>Correct!</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${q.explanation}</p>
            </div>`;
          playSuccessSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: true, attempts: 1 };
            saveState(); addXP(4, `Bases of Accounting Q${q.id} solved`); logActivity({ type: "practice", text: `Bases of Accounting Q${q.id} solved (${q.difficulty})`, route: "ch-basis", tab: "Practice Bank", qid: q.id, difficulty: q.difficulty, status: "solved" }); refreshProgress();
          }
          mistakeBookRecordCorrect(solvedKey);
        } else {
          revealArea.innerHTML = `
            <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
              <h4>Not quite</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${q.options[q.answerIndex]}</b>.<br>${q.explanation}</p>
            </div>`;
          playErrorSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: false, attempts: 1 };
            if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
            saveState(); addXP(-XP_WRONG_PENALTY, `Q${q.id} incorrect`); refreshProgress();
          }
          mistakeBookRecord({
            key: solvedKey, question: q.question, chapter: "basis", chapterLabel: "Bases of Accounting",
            topic: "Bases of Accounting", type: "Bases of Accounting Practice",
            studentAnswer: q.options[picked],
            correctAnswer: q.options[q.answerIndex],
            explanation: q.explanation
          });
        }
        icons();
      }
    });
    panel.appendChild(card);
  });
  applyMobilePager(panel);
  icons();
}

function renderBasisQuickRevision(panel, data) {
  renderQuickRevision(panel, data, { accent: "var(--c-basis)", soft: "var(--c-basis-soft)" });
}

/* ---- "Basis Switch" — the chapter's unique interactive section.
   A toggle flips every situation between Cash Basis and Accrual
   Basis treatment (Switch view), or shows both side by side at
   once (Compare view), followed by checkpoint questions on the
   switching logic. Answers use a "basisswitch-" key so they never
   distort the chapter's main Practice Bank progress percentage. ---- */
let basisSwitchMode = "switch"; // "switch" | "compare"
let basisSwitchBasis = "cash"; // "cash" | "accrual"
let basisSwitchAnswered = {}; // { [checkpointIndex]: { correct } }

function renderBasisSwitch(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Basis Switch 🔀"));
  const hint = el("p", "", `Flip the switch to see the SAME ${data.basisSwitch.items.length} situations treated differently under Cash Basis and Accrual Basis — then test the logic with the checkpoints below.`);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const modeBar = el("div", "");
  modeBar.style.cssText = "display:flex; gap:8px; margin-bottom:16px; flex-wrap:wrap;";
  modeBar.innerHTML = `
    <button class="chip ${basisSwitchMode === "switch" ? "active" : ""}" data-mode="switch">Switch View</button>
    <button class="chip ${basisSwitchMode === "compare" ? "active" : ""}" data-mode="compare">Compare View</button>
  `;
  modeBar.addEventListener("click", e => {
    const btn = e.target.closest("button[data-mode]");
    if (!btn) return;
    basisSwitchMode = btn.dataset.mode;
    renderBasisSwitch(panel, data);
  });
  panel.appendChild(modeBar);

  if (basisSwitchMode === "switch") renderBasisSwitchToggleView(panel, data);
  else renderBasisSwitchCompareView(panel, data);

  panel.appendChild(sectionTitle("Checkpoints"));
  renderBasisSwitchCheckpoints(panel, data);
  icons();
}

function renderBasisSwitchToggleView(panel, data) {
  const toggleBar = el("div", "");
  toggleBar.style.cssText = "display:flex; gap:0; margin-bottom:20px; border:1px solid var(--line); border-radius:999px; padding:4px; width:fit-content;";
  toggleBar.innerHTML = `
    <button class="chip" data-basis="cash" style="border:none; ${basisSwitchBasis === "cash" ? "background:var(--c-basis); color:#fff;" : "background:transparent;"}">Cash Basis</button>
    <button class="chip" data-basis="accrual" style="border:none; ${basisSwitchBasis === "accrual" ? "background:var(--c-basis); color:#fff;" : "background:transparent;"}">Accrual Basis</button>
  `;
  toggleBar.addEventListener("click", e => {
    const btn = e.target.closest("button[data-basis]");
    if (!btn) return;
    basisSwitchBasis = btn.dataset.basis;
    renderBasisSwitch(panel, data);
  });
  panel.appendChild(toggleBar);

  data.basisSwitch.items.forEach(item => {
    const t = basisSwitchBasis === "cash" ? item.cash : item.accrual;
    const card = el("div", "card-solid", "");
    card.style.padding = "22px";
    card.style.marginBottom = "14px";
    card.innerHTML = `
      <h4 style="font-size:0.98rem; margin-bottom:8px;">${item.title}</h4>
      <p style="font-size:0.87rem; color:var(--ink-soft); margin-bottom:14px;">${item.situation}</p>
      <div class="ledger-rule" style="border-left-color:var(--c-basis);">
        <div style="display:flex; justify-content:space-between; flex-wrap:wrap; gap:8px; margin-bottom:6px;">
          <span style="font-size:0.8rem; font-weight:600; color:var(--c-basis); text-transform:uppercase; letter-spacing:.03em;">${basisSwitchBasis === "cash" ? "Cash Basis" : "Accrual Basis"} treatment</span>
        </div>
        <p style="font-size:0.87rem; color:var(--ink-soft); margin-bottom:4px;"><b>When recognised:</b> ${t.recognized}</p>
        <p style="font-size:0.87rem; color:var(--ink-soft); margin-bottom:4px;"><b>Amount:</b> ${t.amount}</p>
        <p style="font-size:0.85rem; color:var(--ink-faint); margin-top:8px;">${t.note}</p>
      </div>
      <div class="q-actions" style="margin-top:12px;">${aiAskBtn("basis.basisSwitch", item)}</div>
    `;
    panel.appendChild(card);
  });
}

function renderBasisSwitchCompareView(panel, data) {
  data.basisSwitch.items.forEach(item => {
    const card = el("div", "card-solid", "");
    card.style.padding = "22px";
    card.style.marginBottom = "14px";
    card.innerHTML = `
      <h4 style="font-size:0.98rem; margin-bottom:8px;">${item.title}</h4>
      <p style="font-size:0.87rem; color:var(--ink-soft); margin-bottom:14px;">${item.situation}</p>
      <div style="display:grid; grid-template-columns:1fr 1fr; gap:14px;">
        <div class="ledger-rule">
          <span style="font-size:0.78rem; font-weight:600; color:var(--ink-faint); text-transform:uppercase; letter-spacing:.03em;">Cash Basis</span>
          <p style="font-size:0.85rem; color:var(--ink-soft); margin:6px 0 2px;"><b>When:</b> ${item.cash.recognized}</p>
          <p style="font-size:0.85rem; color:var(--ink-soft);"><b>Amount:</b> ${item.cash.amount}</p>
        </div>
        <div class="ledger-rule" style="border-left-color:var(--c-basis);">
          <span style="font-size:0.78rem; font-weight:600; color:var(--c-basis); text-transform:uppercase; letter-spacing:.03em;">Accrual Basis</span>
          <p style="font-size:0.85rem; color:var(--ink-soft); margin:6px 0 2px;"><b>When:</b> ${item.accrual.recognized}</p>
          <p style="font-size:0.85rem; color:var(--ink-soft);"><b>Amount:</b> ${item.accrual.amount}</p>
        </div>
      </div>
      <div class="q-actions" style="margin-top:12px;">${aiAskBtn("basis.basisSwitch", item)}</div>
    `;
    panel.appendChild(card);
  });
}

function renderBasisSwitchCheckpoints(panel, data) {
  const checkpoints = data.basisSwitch.checkpoints;
  checkpoints.forEach((c, idx) => {
    const solvedKey = `basisswitch-${idx}`;
    const answered = basisSwitchAnswered[idx];
    const shuffledOrder = fisherYatesShuffle(c.options.map((_, i) => i));

    const card = el("div", "card q-card", "");
    card.innerHTML = `
      <div class="q-body">${c.q}</div>
      <div style="margin-top:14px;">
        <div class="opt-group" style="display:flex; flex-wrap:wrap; gap:8px; ${answered ? "pointer-events:none; opacity:0.7;" : ""}">
          ${shuffledOrder.map(i => `<button class="chip" data-val="${i}">${c.options[i]}</button>`).join("")}
        </div>
      </div>
      <div class="q-actions" style="margin-top:12px;">${aiAskBtn("basis.basisSwitch.checkpoints", c)}</div>
      <div class="reveal-area" style="margin-top:12px;"></div>
    `;
    const revealArea = $(".reveal-area", card);

    if (answered) {
      revealArea.innerHTML = answered.correct
        ? `<div class="reveal-block"><h4>Correct!</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">${c.explanation}</p></div>`
        : `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not quite</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${c.options[c.answerIndex]}</b>.<br>${c.explanation}</p></div>`;
    }

    card.addEventListener("click", e => {
      const optBtn = e.target.closest("button[data-val]");
      if (!optBtn || basisSwitchAnswered[idx]) return;
      const picked = parseInt(optBtn.dataset.val, 10);
      const correct = picked === c.answerIndex;
      basisSwitchAnswered[idx] = { correct };
      $all("button[data-val]", card).forEach(b => b.style.pointerEvents = "none");
      if (correct) {
        revealArea.innerHTML = `<div class="reveal-block"><h4>Correct!</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">${c.explanation}</p></div>`;
        playSuccessSound();
        if (!STATE.solved[solvedKey]) { STATE.solved[solvedKey] = { correct: true, attempts: 1 }; saveState(); addXP(3, "Basis Switch — checkpoint correct"); }
        mistakeBookRecordCorrect(solvedKey);
      } else {
        revealArea.innerHTML = `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not quite</h4><p style="font-size:0.86rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${c.options[c.answerIndex]}</b>.<br>${c.explanation}</p></div>`;
        playErrorSound();
        if (!STATE.solved[solvedKey]) {
          STATE.solved[solvedKey] = { correct: false, attempts: 1 };
          if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
          saveState();
        }
        mistakeBookRecord({
          key: solvedKey, question: c.q, chapter: "basis", chapterLabel: "Bases of Accounting",
          topic: "Basis Switch", type: "Basis Switch Checkpoint",
          studentAnswer: c.options[picked], correctAnswer: c.options[c.answerIndex], explanation: c.explanation
        });
      }
      icons();
    });
    panel.appendChild(card);
  });
}

