/* ---- 4. JOURNAL → LEDGER PRACTICE (interactive quiz) ----
   Pulls simple two-line transactions from the Journal chapter's
   own numericals bank (plus a couple of goods-return examples
   unique to this chapter), and asks the student to identify the
   debited and credited account for each — instant feedback + XP. */
function getLedgerPracticePool() {
  const fromJournal = APP_DATA.journal.numericals
    .filter(q => q.entries.length === 2)
    .map(q => ({
      id: q.id,
      difficulty: q.difficulty,
      transaction: q.transaction,
      debitAccount: q.entries[0].particulars.trim(),
      creditAccount: q.entries[1].particulars.replace(/^\s*To\s+/, "").trim(),
      explanation: q.explanation
    }));
  const extra = (APP_DATA.ledger.extraPracticeTransactions || []).map(q => ({
    id: 1000 + q.id,
    difficulty: q.difficulty,
    transaction: q.transaction,
    debitAccount: q.entries[0].particulars.trim(),
    creditAccount: q.entries[1].particulars.replace(/^\s*To\s+/, "").trim(),
    explanation: q.explanation
  }));
  return [...fromJournal, ...extra];
}

let lgFilterDifficulty = "All";

function renderLedgerPracticeWidget(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Journal → Ledger practice"));
  const hint = el("p", "", `${getLedgerPracticePool().length} built-in transactions. For each one, pick which account gets debited and which gets credited when it's posted from the Journal into the Ledger.`);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px;";
  panel.appendChild(hint);

  const filterBar = el("div", "", "");
  filterBar.style.cssText = "display:flex; gap:8px; margin-bottom:18px; flex-wrap:wrap;";
  ["All", "Easy", "Medium", "Hard"].forEach(d => {
    const chip = el("button", `chip ${d === lgFilterDifficulty ? "active" : ""}`, d);
    chip.addEventListener("click", () => { lgFilterDifficulty = d; renderLedgerPracticeWidget(panel, data); });
    filterBar.appendChild(chip);
  });
  panel.appendChild(filterBar);

  const pool = getLedgerPracticePool();
  const accountPool = [...new Set(pool.flatMap(p => [p.debitAccount, p.creditAccount]))];
  const list = pool.filter(q => lgFilterDifficulty === "All" || q.difficulty === lgFilterDifficulty);
  const countLabel = el("p", "", `Showing ${list.length} of ${pool.length} transactions`);
  countLabel.style.cssText = "font-size:0.83rem; color:var(--ink-faint); margin-bottom:16px;";
  panel.appendChild(countLabel);

  function shuffledOptions(correct) {
    const distractors = accountPool.filter(a => a !== correct);
    for (let i = distractors.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [distractors[i], distractors[j]] = [distractors[j], distractors[i]];
    }
    const opts = [correct, ...distractors.slice(0, 3)];
    for (let i = opts.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [opts[i], opts[j]] = [opts[j], opts[i]];
    }
    return opts;
  }

  list.forEach(q => {
    const solvedKey = `lg-${q.id}`;
    const alreadySolved = STATE.solved[solvedKey];
    const debitOptions = shuffledOptions(q.debitAccount);
    const creditOptions = shuffledOptions(q.creditAccount);
    let picked = { debit: null, credit: null };

    const card = el("div", "card q-card", "");
    card.innerHTML = `
      <div class="q-meta">
        <span class="diff-badge ${q.difficulty}">${q.difficulty}</span>
        <span class="q-id">Q${q.id}</span>
        ${alreadySolved ? `<span style="margin-left:auto; color:var(--c-lg); font-size:0.78rem; display:flex; align-items:center; gap:4px;"><i data-lucide="check-circle" style="width:13px;height:13px;"></i> Solved</span>` : ""}
        ${bookmarkButtonHTML(solvedKey, alreadySolved ? "" : "margin-left:auto;")}
      </div>
      <div class="q-body">${q.transaction}</div>
      <div style="margin-top:14px;">
        <p style="font-size:0.78rem; text-transform:uppercase; letter-spacing:0.04em; color:var(--ink-faint); margin-bottom:8px;">Which account is debited?</p>
        <div class="opt-group" data-role="debit" style="display:flex; flex-wrap:wrap; gap:8px;">
          ${debitOptions.map(o => `<button class="chip" data-val="${o}">${o}</button>`).join("")}
        </div>
      </div>
      <div style="margin-top:14px;">
        <p style="font-size:0.78rem; text-transform:uppercase; letter-spacing:0.04em; color:var(--ink-faint); margin-bottom:8px;">Which account is credited?</p>
        <div class="opt-group" data-role="credit" style="display:flex; flex-wrap:wrap; gap:8px;">
          ${creditOptions.map(o => `<button class="chip" data-val="${o}">${o}</button>`).join("")}
        </div>
      </div>
      <div class="q-actions" style="margin-top:14px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Answer</button>
        ${aiAskBtn("ledger.practice", q, { chapterId: "lg" })}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);

    card.addEventListener("click", (e) => {
      const optBtn = e.target.closest(".opt-group button[data-val]");
      if (optBtn) {
        const group = optBtn.closest(".opt-group");
        $all("button", group).forEach(b => b.classList.remove("active"));
        optBtn.classList.add("active");
        picked[group.dataset.role] = optBtn.dataset.val;
        return;
      }
      const bookmarkBtn = e.target.closest("button[data-act='bookmark']");
      if (bookmarkBtn) {
        toggleBookmark(solvedKey, bookmarkBtn);
        return;
      }
      const checkBtn = e.target.closest("button[data-act='check']");
      if (checkBtn) {
        if (!picked.debit || !picked.credit) {
          revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Pick one account for each side first.</p></div>`;
          return;
        }
        const correct = picked.debit === q.debitAccount && picked.credit === q.creditAccount;
        if (correct) {
          revealArea.innerHTML = `
            <div class="reveal-block">
              <h4>Correct!</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${q.debitAccount} is debited (posted 'To ${q.creditAccount}'); ${q.creditAccount} is credited (posted 'By ${q.debitAccount}'). ${q.explanation}</p>
            </div>`;
          playSuccessSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: true, attempts: 1 };
            saveState(); addXP(4, `Posted ledger Q${q.id}`); logActivity({ type: "practice", text: `Ledger posting Q${q.id} solved (${q.difficulty})`, route: "ch-lg", tab: "Journal → Ledger Practice", qid: q.id, difficulty: q.difficulty, status: "solved" }); refreshProgress();
          }
          mistakeBookRecordCorrect(solvedKey);
        } else {
          revealArea.innerHTML = `
            <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
              <h4>Not quite</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">The correct posting is: <b>${q.debitAccount}</b> debited (To ${q.creditAccount}), <b>${q.creditAccount}</b> credited (By ${q.debitAccount}). ${q.explanation}</p>
            </div>`;
          playErrorSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: false, attempts: 1 };
            if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
            saveState(); addXP(-XP_WRONG_PENALTY, `Q${q.id} incorrect`); refreshProgress();
          }
          mistakeBookRecord({
            key: solvedKey, question: q.transaction, chapter: "lg", chapterLabel: "Ledger",
            topic: "Journal → Ledger Posting", type: "Ledger Posting",
            studentAnswer: `Debit: ${picked.debit} · Credit: ${picked.credit}`,
            correctAnswer: `Debit: ${q.debitAccount} · Credit: ${q.creditAccount}`,
            explanation: q.explanation
          });
        }
        icons();
      }
    });
    panel.appendChild(card);
  });
  applyMobilePager(panel);
  icons();
}

/* ---- 5. BALANCING ACCOUNTS ---- */
function renderLedgerBalancing(panel, data) {
  panel.appendChild(sectionTitle("Balancing accounts"));
  const stepsCard = el("div", "card-solid", "");
  stepsCard.style.padding = "26px";
  let stepsHtml = `<h3 style="margin-bottom:14px;"><i data-lucide="list-ordered" style="width:18px;height:18px;vertical-align:-3px;color:var(--c-lg);"></i> Steps to balance any ledger account</h3><ol style="padding-left:20px;">`;
  data.balancing.steps.forEach(s => stepsHtml += `<li style="margin-bottom:10px; font-size:0.89rem; line-height:1.6; color:var(--ink-soft);">${s}</li>`);
  stepsHtml += `</ol>`;
  stepsCard.innerHTML = stepsHtml;
  panel.appendChild(stepsCard);

  panel.appendChild(sectionTitle("Solved example"));
  const ex = data.balancing.example;
  const exCard = el("div", "card-solid", "");
  exCard.style.padding = "22px";
  const scroll = el("div", "table-scroll");
  const cellsFor = (r) => r
    ? `<td style="border:1px solid var(--line); padding:8px; font-family:var(--font-mono); font-size:0.8rem;">${r.date}</td><td style="border:1px solid var(--line); padding:8px; font-size:0.82rem;">${r.particulars}</td><td style="border:1px solid var(--line); padding:8px; text-align:center; font-family:var(--font-mono); font-size:0.8rem;">${r.jf}</td><td style="border:1px solid var(--line); padding:8px; text-align:right; font-family:var(--font-mono); font-size:0.8rem;">${r.amount.toLocaleString("en-IN")}</td>`
    : `<td style="border:1px solid var(--line); padding:8px;"></td><td style="border:1px solid var(--line); padding:8px;"></td><td style="border:1px solid var(--line); padding:8px;"></td><td style="border:1px solid var(--line); padding:8px;"></td>`;
  const rowCount = Math.max(ex.debitRows.length, ex.creditRows.length);
  let bodyRowsHtml = "";
  for (let i = 0; i < rowCount; i++) {
    bodyRowsHtml += `<tr>${cellsFor(ex.debitRows[i])}${cellsFor(ex.creditRows[i])}</tr>`;
  }
  scroll.innerHTML = `
    <div style="text-align:center; font-weight:700; font-family:var(--font-mono); margin-bottom:10px;">${ex.accountName} — ${ex.period}</div>
    <table class="t-account-grid" style="width:100%; border-collapse:collapse; min-width:560px;">
      <tr>
        <th colspan="4" style="text-align:center; border:1.5px solid var(--line-strong); background:var(--c-lg-soft); color:var(--c-lg); padding:8px;">Dr.</th>
        <th colspan="4" style="text-align:center; border:1.5px solid var(--line-strong); background:var(--c-lg-soft); color:var(--c-lg); padding:8px;">Cr.</th>
      </tr>
      <tr>
        <th style="border:1px solid var(--line-strong); padding:6px; font-size:0.74rem;">Date</th><th style="border:1px solid var(--line-strong); padding:6px; font-size:0.74rem;">Particulars</th><th style="border:1px solid var(--line-strong); padding:6px; font-size:0.74rem;">J.F.</th><th style="border:1px solid var(--line-strong); padding:6px; font-size:0.74rem;">₹</th>
        <th style="border:1px solid var(--line-strong); padding:6px; font-size:0.74rem;">Date</th><th style="border:1px solid var(--line-strong); padding:6px; font-size:0.74rem;">Particulars</th><th style="border:1px solid var(--line-strong); padding:6px; font-size:0.74rem;">J.F.</th><th style="border:1px solid var(--line-strong); padding:6px; font-size:0.74rem;">₹</th>
      </tr>
      ${bodyRowsHtml}
      <tr>
        <td colspan="4" style="border:1px solid var(--line);"></td>
        <td style="border:1px solid var(--line); padding:8px; font-family:var(--font-mono); font-size:0.8rem;">Apr 30</td>
        <td style="border:1px solid var(--line); padding:8px; font-size:0.82rem; color:var(--c-lg); font-weight:600;">By Balance c/d</td>
        <td style="border:1px solid var(--line); padding:8px;"></td>
        <td style="border:1px solid var(--line); padding:8px; text-align:right; font-family:var(--font-mono); font-size:0.8rem; color:var(--c-lg); font-weight:600;">${ex.balanceCD.toLocaleString("en-IN")}</td>
      </tr>
      <tr style="font-weight:700;">
        <td colspan="3" style="border-top:2px solid var(--line-strong); padding:8px; text-align:right;">Total</td>
        <td style="border-top:2px solid var(--line-strong); padding:8px; text-align:right; font-family:var(--font-mono);">${ex.totalDebit.toLocaleString("en-IN")}</td>
        <td colspan="3" style="border-top:2px solid var(--line-strong); padding:8px; text-align:right;">Total</td>
        <td style="border-top:2px solid var(--line-strong); padding:8px; text-align:right; font-family:var(--font-mono);">${ex.totalDebit.toLocaleString("en-IN")}</td>
      </tr>
      <tr>
        <td style="padding:8px; font-family:var(--font-mono); font-size:0.8rem;">May 1</td>
        <td style="padding:8px; font-size:0.82rem; color:var(--c-lg); font-weight:600;">To Balance b/d</td>
        <td style="padding:8px;"></td>
        <td style="padding:8px; text-align:right; font-family:var(--font-mono); font-size:0.8rem; color:var(--c-lg); font-weight:600;">${ex.balanceCD.toLocaleString("en-IN")}</td>
        <td colspan="4" style="padding:8px;"></td>
      </tr>
    </table>
  `;
  exCard.appendChild(scroll);
  const working = el("div", "reveal-block");
  working.style.marginTop = "16px";
  working.innerHTML = `<h4>Working</h4><p style="font-size:0.87rem; line-height:1.65;">${ex.workingExplanation}</p><p style="font-size:0.85rem; margin-top:8px;">Result: <b>${ex.balanceCDNature} balance of ₹${ex.balanceCD.toLocaleString("en-IN")}</b>, brought down on 1 May.</p>`;
  exCard.appendChild(working);
  panel.appendChild(exCard);
}

/* ---- 6. EXAM-ORIENTED QUESTIONS ---- */
let lgExamTab = "easy";
function renderLedgerExamQuestions(panel, data) {
  panel.innerHTML = "";
  panel.appendChild(sectionTitle("Exam-oriented questions"));
  const tabRow = el("div", "", "");
  tabRow.style.cssText = "display:flex; gap:8px; margin-bottom:18px; flex-wrap:wrap;";
  [["easy", `Easy (${data.examQuestions.easy.length})`], ["medium", `Medium (${data.examQuestions.medium.length})`], ["hard", `Hard (${data.examQuestions.hard.length})`]].forEach(([id, label]) => {
    const chip = el("button", `chip ${lgExamTab === id ? "active" : ""}`, label);
    chip.addEventListener("click", () => { lgExamTab = id; renderLedgerExamQuestions(panel, data); });
    tabRow.appendChild(chip);
  });
  panel.appendChild(tabRow);

  const list = data.examQuestions[lgExamTab];
  list.forEach((q, i) => {
    const key = `lg-exam-${lgExamTab}-${i}`;
    const card = el("div", "card q-card", "");
    card.innerHTML = `
      <div class="q-meta">
        <span class="diff-badge ${lgExamTab === "easy" ? "Easy" : lgExamTab === "medium" ? "Medium" : "Hard"}">${lgExamTab[0].toUpperCase() + lgExamTab.slice(1)}</span>
        <span class="q-id">Q${i + 1}</span>
        ${bookmarkButtonHTML(key, "margin-left:auto;")}
      </div>
      <div class="q-body">${q.q}</div>
      <div class="q-actions">
        <button class="btn-primary sm ripple-surface" data-act="answer"><i data-lucide="eye"></i> Show Answer</button>
        ${aiAskBtn("ledger.examQuestions", q)}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);
    card.addEventListener("click", (e) => {
      const btn = e.target.closest("button[data-act]");
      if (!btn) return;
      if (btn.dataset.act === "answer") {
        revealArea.innerHTML = `<div class="reveal-block"><h4>Answer</h4><p style="font-size:0.87rem; line-height:1.65;">${q.a}</p></div>`;
        if (!STATE.solved[key]) {
          STATE.solved[key] = { correct: true, attempts: 1 };
          saveState(); addXP(3, `Reviewed a ledger exam question`); logActivity({ type: "practice", text: `Reviewed a ${lgExamTab} Ledger question`, route: "ch-lg", tab: "Exam Questions", difficulty: lgExamTab, status: "reviewed" }); refreshProgress();
        }
      }
      if (btn.dataset.act === "bookmark") {
        toggleBookmark(key, btn);
      }
      icons();
    });
    panel.appendChild(card);
  });
  applyMobilePager(panel);
  icons();
}

/* ---- 7. QUICK REVISION ---- */
function renderLedgerQuickRevision(panel, data) {
  renderQuickRevision(panel, data, { accent: "var(--c-lg)", soft: "var(--c-lg-soft)" });
}

/* ---------------------------------------------------------
   6d-2. CHAPTER 9 — SPECIAL PURPOSE BOOKS 1: CASH BOOK
   Content sourced entirely from the provided chapter PDF
   (APP_DATA.cashBook). Uses a lighter tab set than Ledger's —
   Notes/Illustrations/Quick Revision — since this chapter's
   integration is about Notes, Quiz, Flashcards, Important
   Questions, Revision, Formula Sheet, and Exam Mode, not a
   bespoke interactive simulator.
   --------------------------------------------------------- */
function renderCashBookChapter(root) {
  const data = APP_DATA.cashBook;
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Chapter 9</span>
    <h1>Special Purpose Books 1 - Cash Book</h1>
    <p>${APP_DATA.chapters[8].tagline} Cash Book, Two-Column Cash Book, contra entries, cheques-in-hand, post-dated cheques, bank overdraft, and Petty Cash Book — all from your textbook chapter.</p>
  `));

  const tabs = ["Introduction", "Mind Map", "Format & Rules", "Cash Book Challenge", "Practice Bank", "Quick Revision"];
  const tabBar = el("div", "", "");
  tabBar.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; margin-bottom:22px;";
  tabs.forEach((t, i) => {
    const chip = el("button", `chip ${i===0?'active':''}`, t);
    chip.dataset.tab = t;
    tabBar.appendChild(chip);
  });
  const journeyEl = renderJourneyStepper(root, "cb");
  root.appendChild(tabBar);
  const panel = el("div", "");
  root.appendChild(panel);

  function showTab(name) {
    $all(".chip", tabBar).forEach(c => c.classList.toggle("active", c.dataset.tab === name));
    panel.innerHTML = "";
    updateJourneyStepper(journeyEl, "cb", name);
    if (name === "Introduction") renderCashBookIntro(panel, data);
    if (name === "Mind Map") renderMindMap(panel, "cb");
    if (name === "Format & Rules") renderCashBookFormatRules(panel, data);
    if (name === "Cash Book Challenge") renderCashBookChallenge(panel, data);
    if (name === "Practice Bank") renderCashBookPracticeBank(panel, data);
    if (name === "Quick Revision") renderCashBookQuickRevision(panel, data);
    icons();
  }
  tabBar.addEventListener("click", e => {
    const chip = e.target.closest(".chip");
    if (chip) showTab(chip.dataset.tab);
  });
  showTab("Introduction");
}

/* ------------------------------------------------------------
   CASH BOOK CHALLENGE — interactive single/double/triple column
   Students record a day's transactions into a real cash book,
   choose the correct side (receipt/payment), fill the right
   columns, mark contra entries, then balance the book. Guided
   mode shows hints; Challenge mode scores without hints.
   ------------------------------------------------------------ */
function renderCashBookChallenge(panel, data) {
  const cfg = data.challenge;
  panel.appendChild(sectionTitle("Cash Book Challenge 🧾"));
  const hint = el("p", "", cfg.intro);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  /* Persisted run-state so switching tabs doesn't lose progress. */
  const st = window.__cbcState || (window.__cbcState = {
    mode: "guided", si: 0, ti: 0, entries: [], score: 0, attempted: 0, hintsUsed: 0, mistakes: 0, done: false, balanced: false
  });

  const wrap = el("div", "card-solid");
  wrap.style.cssText = "padding:26px;";
  panel.appendChild(wrap);

  function scenario() { return cfg.scenarios[st.si]; }
  function txn() { return scenario().transactions[st.ti]; }

  function resetRun(keepMode) {
    const m = keepMode ? st.mode : st.mode;
    window.__cbcState = { mode: m, si: st.si, ti: 0, entries: [], score: 0, attempted: 0, hintsUsed: 0, mistakes: 0, done: false, balanced: false };
    Object.assign(st, window.__cbcState);
    draw();
  }

  /* ---- top bar: mode + scenario picker + progress ---- */
  function drawTopBar() {
    const bar = el("div", "", "");
    bar.style.cssText = "display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:16px;";
    const modeBtn = st.mode === "guided"
      ? `<button class="chip active" data-act="mode" data-val="guided"><i data-lucide="compass"></i> Guided</button><button class="chip" data-act="mode" data-val="challenge"><i data-lucide="trophy"></i> Challenge</button>`
      : `<button class="chip" data-act="mode" data-val="guided"><i data-lucide="compass"></i> Guided</button><button class="chip active" data-act="mode" data-val="challenge"><i data-lucide="trophy"></i> Challenge</button>`;
    const scenChips = cfg.scenarios.map((s, i) => `<button class="chip ${i===st.si?'active':''}" data-act="scen" data-val="${i}">${s.title.replace(' Cash Book','')}</button>`).join("");
    bar.innerHTML = `
      <div style="display:flex; gap:6px; flex-wrap:wrap;">${modeBtn}</div>
      <div style="display:flex; gap:6px; flex-wrap:wrap;">${scenChips}</div>`;
    return bar;
  }

  function drawProgress() {
    const s = scenario();
    const p = el("div", "", "");
    p.style.cssText = "display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:14px; font-size:0.83rem;";
    const scoreTxt = st.mode === "challenge" ? `<span style="color:var(--c-cb); font-weight:600;">Score: ${st.score}/${st.attempted}</span>` : `<span style="color:var(--ink-faint);">Entries correct: ${st.entries.length}/${s.transactions.length}</span>`;
    p.innerHTML = `<p style="margin:0; color:var(--ink-faint);">${s.title} — ${s.subtitle}</p>${scoreTxt}`;
    return p;
  }

  /* ---- the running cash book table ---- */
  function cashBookTable(highlightLast) {
    const s = scenario();
    const hasBank = s.cols.includes("Bank");
    const hasDisc = s.cols.includes("Discount");
    const receipts = st.entries.filter(e => e.side === "receipt");
    const payments = st.entries.filter(e => e.side === "payment");

    function sideRows(list, side) {
      if (!list.length) return `<tr><td colspan="${2+s.cols.length}" style="color:var(--ink-faint); font-style:italic; padding:8px;">— no entries yet —</td></tr>`;
      return list.map((e, idx) => {
        const globalIdx = st.entries.indexOf(e);
        const hl = highlightLast && globalIdx === st.entries.length-1 ? ' style="background:var(--c-cb-soft);"' : '';
        const cells = s.cols.map(c => `<td class="tnum" style="text-align:right; padding:6px 8px;">${e[c] ? fmtINR(e[c]) : ''}</td>`).join("");
        const lf = e.contra ? 'C' : '';
        return `<tr${hl}><td style="padding:6px 8px; white-space:nowrap;">${e.date}</td><td style="padding:6px 8px;">${e.particulars}${e._new?' <span style="color:var(--c-cb); font-weight:700;">✓</span>':''}</td><td style="padding:6px 8px; text-align:center; color:var(--c-cb); font-weight:700;">${lf}</td>${cells}</tr>`;
      }).join("");
    }

    const colHead = s.cols.map(c => `<th style="text-align:right; padding:6px 8px;">${c}${c==='Discount'?' <span style="font-weight:400; opacity:0.7;">(Alw/Rec)</span>':''}</th>`).join("");
    const totalReceipts = s.cols.map(c => receipts.reduce((sum,e)=>sum+(e[c]||0),0));
    const totalPayments = s.cols.map(c => payments.reduce((sum,e)=>sum+(e[c]||0),0));
    const totalCells = (arr) => arr.map(t => `<td class="tnum" style="text-align:right; padding:6px 8px; font-weight:700;">${t?fmtINR(t):''}</td>`).join("");

    const receiptTotalRow = st.entries.length ? `<tr style="border-top:2px solid var(--line-strong); font-weight:600;"><td colspan="${2+s.cols.length-s.cols.length}" style="padding:6px 8px;"></td>${totalCells(totalReceipts)}</tr>` : '';
    const paymentTotalRow = st.entries.length ? `<tr style="border-top:2px solid var(--line-strong); font-weight:600;"><td colspan="2" style="padding:6px 8px; text-align:right;">Total</td>${totalCells(totalPayments)}</tr>` : '';

    const openReceipt = `<tr style="background:var(--paper);"><td style="padding:6px 8px;">${scenario().opening.side==='Dr'?'—':''}</td><td style="padding:6px 8px; font-style:italic;">To Balance b/d <span style="color:var(--ink-faint);">(${s.opening.note})</span></td><td style="padding:6px 8px;"></td><td class="tnum" style="text-align:right; padding:6px 8px;">${fmtINR(s.opening.amount)}</td>${hasBank?`<td class="tnum" style="text-align:right; padding:6px 8px;">${s.opening.bankOpening?fmtINR(s.opening.bankOpening):''}</td>`:''}${hasDisc?'<td></td>':''}</tr>`;

    return `<div style="overflow-x:auto;">
      <table class="ledger-table" style="width:100%; border-collapse:collapse; font-size:0.82rem; min-width:520px;">
        <thead>
          <tr style="border-bottom:2px solid var(--line-strong);">
            <th colspan="${3+s.cols.length}" style="text-align:left; padding:8px; color:var(--c-cb);">Dr. — RECEIPTS</th>
          </tr>
          <tr style="border-bottom:1px solid var(--line);">
            <th style="text-align:left; padding:6px 8px;">Date</th><th style="text-align:left; padding:6px 8px;">Particulars</th><th style="text-align:center; padding:6px 8px;">L.F.</th>${colHead}
          </tr>
        </thead>
        <tbody>${openReceipt}${sideRows(receipts,'receipt')}${receiptTotalRow}</tbody>
      </table>
      <table class="ledger-table" style="width:100%; border-collapse:collapse; font-size:0.82rem; min-width:520px; margin-top:18px;">
        <thead>
          <tr style="border-bottom:2px solid var(--line-strong);">
            <th colspan="${3+s.cols.length}" style="text-align:left; padding:8px; color:var(--c-cb);">Cr. — PAYMENTS</th>
          </tr>
          <tr style="border-bottom:1px solid var(--line);">
            <th style="text-align:left; padding:6px 8px;">Date</th><th style="text-align:left; padding:6px 8px;">Particulars</th><th style="text-align:center; padding:6px 8px;">L.F.</th>${colHead}
          </tr>
        </thead>
        <tbody>${sideRows(payments,'payment')}${paymentTotalRow}</tbody>
      </table>
    </div>`;
  }

  /* ---- entry form for the current transaction ---- */
  function drawEntryForm() {
    const s = scenario();
    const t = txn();
    const hasBank = s.cols.includes("Bank");
    const hasDisc = s.cols.includes("Discount");
    const guided = st.mode === "guided";

    const card = el("div", "");
    card.style.cssText = "margin-top:20px; padding:20px; border:1px solid var(--line-strong); border-radius:12px; background:var(--paper);";
    const colInputs = s.cols.map(c => `
      <div class="field-group" style="margin-bottom:0;">
        <label>${c === 'Discount' ? 'Discount (₹)' : c + ' (₹)'}</label>
        <input type="number" class="field-input cbc-amt" data-col="${c}" placeholder="0" min="0" step="1">
      </div>`).join("");

    card.innerHTML = `
      <p style="font-size:0.74rem; text-transform:uppercase; letter-spacing:0.04em; color:var(--ink-faint); margin-bottom:6px;">Transaction ${st.ti+1} of ${s.transactions.length}</p>
      <p style="font-size:0.8rem; color:var(--ink-faint); margin-bottom:2px;">${t.date}</p>
      <p style="font-size:0.98rem; font-weight:600; margin-bottom:16px; line-height:1.5;">${t.particulars}</p>
      <p style="font-size:0.8rem; font-weight:600; margin-bottom:8px;">1. Which side of the cash book?</p>
      <div class="opt-group" data-role="side" style="display:flex; gap:8px; margin-bottom:16px; flex-wrap:wrap;">
        <button class="chip" data-side="receipt"><i data-lucide="arrow-down-left"></i> Receipt (Dr)</button>
        <button class="chip" data-side="payment"><i data-lucide="arrow-up-right"></i> Payment (Cr)</button>
      </div>
      ${hasBank ? `<label style="display:flex; align-items:center; gap:8px; font-size:0.85rem; margin-bottom:16px; cursor:pointer;"><input type="checkbox" class="cbc-contra"> Contra entry (cash ⇄ bank — mark 'C' in L.F.)</label>` : ''}
      <p style="font-size:0.8rem; font-weight:600; margin-bottom:8px;">2. Enter the amount in each column:</p>
      <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(130px,1fr)); gap:12px; margin-bottom:16px;">${colInputs}</div>
      ${guided ? `<button class="btn-ghost sm ripple-surface" data-act="hint" style="margin-bottom:12px;"><i data-lucide="lightbulb"></i> Show hint</button>` : ''}
      <div id="cbcHint" style="margin-bottom:12px;"></div>
      <div style="display:flex; gap:10px; flex-wrap:wrap;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Record entry</button>
        <button class="btn-ghost sm ripple-surface" data-act="reveal"><i data-lucide="eye"></i> Show answer</button>
        ${st.ti>0?`<button class="btn-ghost sm ripple-surface" data-act="prev"><i data-lucide="arrow-left"></i> Back</button>`:''}
      </div>
      <div id="cbcFeedback" style="margin-top:14px;"></div>`;
    return card;
  }

  function drawBalancing() {
    const s = scenario();
    const hasBank = s.cols.includes("Bank");
    const receipts = st.entries.filter(e=>e.side==="receipt");
    const payments = st.entries.filter(e=>e.side==="payment");
    const sum = (list,c)=>list.reduce((a,e)=>a+(e[c]||0),0);
    const openCash = s.opening.amount, openBank = s.opening.bankOpening||0;
    const cashDr = openCash + sum(receipts,"Cash");
    const cashCr = sum(payments,"Cash");
    const cashBal = cashDr - cashCr;
    const bankDr = openBank + sum(receipts,"Bank");
    const bankCr = sum(payments,"Bank");
    const bankBal = bankDr - bankCr;

    const card = el("div", "");
    card.style.cssText = "margin-top:20px; padding:22px; border:1px solid var(--c-cb); border-radius:12px; background:var(--c-cb-soft);";
    card.innerHTML = `
      <h4 style="font-size:1rem; margin-bottom:8px; color:var(--c-cb);"><i data-lucide="scale"></i> Balance the cash book</h4>
      <p style="font-size:0.85rem; color:var(--ink-soft); margin-bottom:14px; line-height:1.6;">All ${st.entries.length} transactions recorded. Now total both sides and carry down the closing balance to the lighter side. Enter the closing Cash balance${hasBank?' and Bank balance':''} below.</p>
      <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:14px; margin-bottom:14px;">
        <div class="field-group" style="margin-bottom:0;"><label>Closing Cash balance (₹)</label><input type="number" id="cbcBalCash" class="field-input" placeholder="0"></div>
        ${hasBank?`<div class="field-group" style="margin-bottom:0;"><label>Closing Bank balance (₹)</label><input type="number" id="cbcBalBank" class="field-input" placeholder="0"></div>`:''}
      </div>
      <div id="cbcBalFb" style="margin-bottom:12px;"></div>
      <button class="btn-primary sm ripple-surface" data-act="balance"><i data-lucide="check-circle"></i> Check balance</button>`;
    card._expected = { cashBal, bankBal };
    return card;
  }

  function drawSummary() {
    const s = scenario();
    const acc = st.mode==="challenge" ? `Score ${st.score}/${st.attempted} · ${st.attempted?Math.round(st.score/st.attempted*100):0}%` : `${st.entries.length} entries recorded`;
    const card = el("div", "");
    card.style.cssText = "margin-top:20px; padding:24px; border:1px solid var(--line-strong); border-radius:12px; text-align:center; background:var(--paper);";
    card.innerHTML = `
      <div style="font-size:2rem; margin-bottom:6px;">🎉</div>
      <h4 style="font-size:1.1rem; margin-bottom:6px;">${s.title} complete!</h4>
      <p style="font-size:0.9rem; color:var(--ink-soft); margin-bottom:6px;">${acc}${st.mode==='challenge'?` · Hints used: ${st.hintsUsed} · Mistakes: ${st.mistakes}`:''}</p>
      <p style="font-size:0.83rem; color:var(--ink-faint); margin-bottom:18px;">Closing Cash balance ${fmtINR(card_bal_cash())}${s.cols.includes('Bank')?` · Closing Bank balance ${fmtINR(card_bal_bank())}`:''}</p>
      <div style="display:flex; gap:10px; justify-content:center; flex-wrap:wrap;">
        ${st.si < cfg.scenarios.length-1 ? `<button class="btn-primary sm ripple-surface" data-act="nextscen"><i data-lucide="arrow-right"></i> Next: ${cfg.scenarios[st.si+1].title.replace(' Cash Book','')}</button>`:''}
        <button class="btn-ghost sm ripple-surface" data-act="retry"><i data-lucide="rotate-ccw"></i> Retry this format</button>
      </div>`;
    return card;
  }
  function card_bal_cash(){const s=scenario();const r=st.entries.filter(e=>e.side==="receipt"),p=st.entries.filter(e=>e.side==="payment");return s.opening.amount+r.reduce((a,e)=>a+(e.Cash||0),0)-p.reduce((a,e)=>a+(e.Cash||0),0);}
  function card_bal_bank(){const s=scenario();const r=st.entries.filter(e=>e.side==="receipt"),p=st.entries.filter(e=>e.side==="payment");return (s.opening.bankOpening||0)+r.reduce((a,e)=>a+(e.Bank||0),0)-p.reduce((a,e)=>a+(e.Bank||0),0);}

  function draw() {
    wrap.innerHTML = "";
    wrap.appendChild(drawTopBar());
    wrap.appendChild(drawProgress());
    wrap.appendChild(el("div", "", cashBookTable(true)));
    if (st.done) {
      wrap.appendChild(drawSummary());
    } else if (st.ti >= scenario().transactions.length) {
      wrap.appendChild(drawBalancing());
    } else {
      wrap.appendChild(drawEntryForm());
    }
    icons();
  }

  /* ---- validation ---- */
  function readForm() {
    const sideBtn = $(".opt-group[data-role='side'] .chip.active", wrap);
    const side = sideBtn ? sideBtn.dataset.side : null;
    const amounts = {};
    $all(".cbc-amt", wrap).forEach(inp => { amounts[inp.dataset.col] = parseFloat(inp.value) || 0; });
    const contraCb = $(".cbc-contra", wrap);
    const contra = contraCb ? contraCb.checked : false;
    return { side, amounts, contra };
  }

  function checkEntry() {
    const s = scenario();
    const t = txn();
    const { side, amounts, contra } = readForm();
    const fb = $("#cbcFeedback", wrap);
    if (!side) { fb.innerHTML = `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><p style="font-size:0.86rem;">Choose the Receipt or Payment side first.</p></div>`; return; }
    const exp = t.entry;
    const expSide = exp.side;
    const cols = s.cols;
    let sideOk = side === expSide;
    let colOk = true; const wrongCols = [];
    cols.forEach(c => {
      const got = amounts[c] || 0;
      const want = exp[c] || 0;
      if (got !== want) { colOk = false; wrongCols.push(c); }
    });
    const expContra = !!exp.contra;
    const contraOk = !s.cols.includes("Bank") ? true : (contra === expContra);
    const allOk = sideOk && colOk && contraOk;

    st.attempted++;
    /* One entry = one first attempt that decides its XP for good, ever
       (keyed by date + particulars) — replaying a completed cash book
       run can never re-harvest entry XP. */
    const cbEntryKey = "cb-entry|" + (t.date || "") + "|" + String(t.particulars || "").slice(0, 60);
    if (allOk) {
      st.score++;
      const entry = { date: t.date, particulars: t.particulars, side: expSide, contra: expContra, _new: true };
      cols.forEach(c => entry[c] = exp[c] || 0);
      if (exp.discountType) entry.discountType = exp.discountType;
      st.entries.push(entry);
      awardXPOnce(cbEntryKey, 4, "Cash book entry recorded");
      const nextT = st.ti + 1;
      const doneAll = nextT >= s.transactions.length;
      fb.innerHTML = `<div class="reveal-block"><h4>Correct ✓</h4><p style="font-size:0.86rem;">${t.why}</p></div>`;
      setTimeout(() => { st.ti = nextT; draw(); }, doneAll ? 1400 : 1100);
    } else {
      st.mistakes++;
      awardXPOnce(cbEntryKey, -XP_WRONG_PENALTY, "Cash book entry incorrect");
      const probs = [];
      if (!sideOk) probs.push(`It belongs on the <b>${expSide}</b> side, not ${side}.`);
      if (!colOk) probs.push(`Check the amount in: <b>${wrongCols.join(', ')}</b>.`);
      if (!contraOk) probs.push(expContra ? `This is a <b>contra</b> entry — tick the contra box.` : `This is <b>not</b> a contra entry — untick the box.`);
      fb.innerHTML = `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not quite</h4><ul style="margin:6px 0 8px 18px; font-size:0.86rem;">${probs.map(p=>`<li>${p}</li>`).join('')}</ul><p style="font-size:0.84rem; color:var(--ink-faint);">${t.why}</p></div>`;
    }
  }

  function showHint() {
    const t = txn();
    const box = $("#cbcHint", wrap);
    st.hintsUsed++;
    const exp = t.entry;
    const colsTxt = scenario().cols.map(c => exp[c] ? `${c} ${fmtINR(exp[c])}` : null).filter(Boolean).join(", ");
    box.innerHTML = `<div class="reveal-block" style="background:var(--paper-raised); border-left-color:var(--gold);"><p style="font-size:0.84rem;"><b>Hint:</b> Record on the <b>${exp.side}</b> side${exp.contra?' — it\'s a contra entry':''}. Columns: ${colsTxt}.</p></div>`;
    icons();
  }

  function revealAnswer() {
    const s = scenario(); const t = txn(); const exp = t.entry;
    const fb = $("#cbcFeedback", wrap);
    st.mistakes++;
    const entry = { date: t.date, particulars: t.particulars, side: exp.side, contra: !!exp.contra, _new: true };
    s.cols.forEach(c => entry[c] = exp[c] || 0);
    if (exp.discountType) entry.discountType = exp.discountType;
    st.entries.push(entry);
    fb.innerHTML = `<div class="reveal-block"><h4>Answer shown</h4><p style="font-size:0.86rem;">${t.why}</p></div>`;
    const nextT = st.ti + 1;
    setTimeout(() => { st.ti = nextT; draw(); }, 1600);
  }

  function checkBalance() {
    const s = scenario();
    const balCard = Array.from(wrap.children).find(c => c._expected);
    const exp = balCard._expected;
    const gotCash = parseFloat($("#cbcBalCash", wrap).value);
    const bankInput = $("#cbcBalBank", wrap);
    const gotBank = bankInput ? parseFloat(bankInput.value) : undefined;
    const fb = $("#cbcBalFb", wrap);
    const cashOk = gotCash === exp.cashBal;
    const bankOk = bankInput ? (gotBank === exp.bankBal) : true;
    if (cashOk && bankOk) {
      st.done = true;
      /* Balanced once per scenario, ever — switching scenarios and
         replaying cannot re-award the completion bonus. */
      awardXPOnce("cb-balanced|" + (s.id != null ? s.id : (s.title || "default")), 6, "Cash book balanced");
      fb.innerHTML = `<div class="reveal-block"><h4>Balanced correctly ✓</h4><p style="font-size:0.86rem;">Closing Cash balance ${fmtINR(exp.cashBal)}${s.cols.includes('Bank')?` and Bank balance ${fmtINR(exp.bankBal)}`:''} carried down to the lighter side.</p></div>`;
      setTimeout(draw, 1500);
    } else {
      st.mistakes++;
      const probs=[];
      if(!cashOk) probs.push(`Cash balance should be <b>${fmtINR(exp.cashBal)}</b> (Dr side total − Cr side total).`);
      if(!bankOk) probs.push(`Bank balance should be <b>${fmtINR(exp.bankBal)}</b>.`);
      fb.innerHTML = `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Recheck</h4><ul style="margin:6px 0 0 18px; font-size:0.86rem;">${probs.map(p=>`<li>${p}</li>`).join('')}</ul></div>`;
    }
    icons();
  }

  wrap.addEventListener("click", (e) => {
    const sideChip = e.target.closest(".opt-group[data-role='side'] .chip");
    if (sideChip) { $all(".opt-group[data-role='side'] .chip", wrap).forEach(c=>c.classList.remove("active")); sideChip.classList.add("active"); return; }
    const btn = e.target.closest("button[data-act]");
    if (!btn) return;
    const act = btn.dataset.act;
    if (act === "mode") { st.mode = btn.dataset.val; resetRun(true); }
    else if (act === "scen") { st.si = parseInt(btn.dataset.val,10); resetRun(true); }
    else if (act === "hint") showHint();
    else if (act === "check") checkEntry();
    else if (act === "reveal") revealAnswer();
    else if (act === "prev") { if (st.ti>0) { st.ti--; if (st.entries.length) st.entries.pop(); draw(); } }
    else if (act === "balance") checkBalance();
    else if (act === "retry") { st.ti = 0; st.entries = []; st.done=false; st.balanced=false; st.score=0; st.attempted=0; st.mistakes=0; st.hintsUsed=0; draw(); }
    else if (act === "nextscen") { st.si = Math.min(cfg.scenarios.length-1, st.si+1); st.ti=0; st.entries=[]; st.done=false; st.score=0; st.attempted=0; st.mistakes=0; draw(); }
  });

  draw();
}

/* ------------------------------------------------------------
   v92 Part 2 — the ONE theory renderer for every chapter.
   Renders the structured block schema
     { h, p, p2, formula, list:[{term,def}],
       example, note, simple, real, tip, mistakes:[..],
       confusion:{a,aText,b,bText,diff} }
   with the shared reading design (styles.css .th-* classes), and
   injects the chapter-level learning chrome (introduction,
   objectives, common mistakes, recap, check-your-understanding)
   exactly once per tab through the theory-upgrade context map.
   The signature is unchanged — every existing call site keeps
   working, and chapters without upgrade data render as before.
   ------------------------------------------------------------ */
function thBoxHtml(kind, label, icon, bodyHtml) {
  return `<div class="th-box th-box--${kind}"><span class="th-box-label"><i data-lucide="${icon}"></i> ${label}</span>${bodyHtml}</div>`;
}
function renderCashBookTheoryBlocks(panel, blocks, accent, soft) {
  if (!Array.isArray(blocks) || !blocks.length) return;
  const ctx = (typeof window !== "undefined" && window.THEORY_CTX_MAP) ? window.THEORY_CTX_MAP.get(blocks) : null;
  /* Chrome presence is detected on the DOM itself, not on a cached
     flag: the chapter panels persist across tab switches (only their
     innerHTML is cleared), so a stale flag would wrongly suppress the
     chrome on every re-render of the same tab. */
  const hasChrome = (k) => !!panel.querySelector('.th-view--chrome[data-th-kind="' + k + '"]');
  /* the "simple" chrome (introduction + objectives) opens the surface… */
  if (ctx && ctx.kind === "simple" && !hasChrome("simple")) {
    theoryChrome(panel, ctx.data, "simple", accent);
  }
  const wrap = el("div", "th-view");
  wrap.style.setProperty("--th-accent", accent || "var(--ink)");
  wrap.style.setProperty("--th-soft", soft || "transparent");
  blocks.forEach(block => {
    const b = el("div", "th-block ledger-rule");
    let html = `<h4 class="th-h">${block.h}</h4>`;
    if (block.p) html += `<p class="th-p">${block.p}</p>`;
    if (block.formula) html += `<div class="th-formula tnum">${block.formula}</div>`;
    if (block.p2) html += `<p class="th-p">${block.p2}</p>`;
    if (block.list && block.list.length) {
      html += `<ul class="th-list">`;
      block.list.forEach(item => html += `<li><b>${item.term}:</b> ${item.def}</li>`);
      html += `</ul>`;
    }
    if (block.simple) html += thBoxHtml("simple", "In Simple Words", "message-circle", `<p class="th-p">${block.simple}</p>`);
    if (block.real) html += thBoxHtml("real", "Real-Life Connection", "store", `<p class="th-p">${block.real}</p>`);
    if (block.example) html += thBoxHtml("example", "Worked Example", "calculator", `<p class="th-p th-pre">${block.example}</p>`);
    if (block.note) html += thBoxHtml("note", "Remember This", "lightbulb", `<p class="th-p">${block.note}</p>`);
    if (block.tip) html += thBoxHtml("tip", "Exam Tip", "graduation-cap", `<p class="th-p">${block.tip}</p>`);
    if (Array.isArray(block.mistakes) && block.mistakes.length) {
      html += thBoxHtml("mistake", "Common Mistakes", "triangle-alert",
        `<ul class="th-list">` + block.mistakes.map(m => `<li>${m}</li>`).join("") + `</ul>`);
    }
    if (block.confusion && block.confusion.a) {
      const c = block.confusion;
      html += thBoxHtml("confusion", "Common Confusion", "git-compare",
        `<div class="th-confusion"><div class="th-confusion-col"><b>${c.a}</b><p class="th-p">${c.aText || ""}</p></div>` +
        `<div class="th-confusion-col"><b>${c.b}</b><p class="th-p">${c.bText || ""}</p></div></div>` +
        (c.diff ? `<p class="th-p th-confusion-diff"><b>The difference:</b> ${c.diff}</p>` : ""));
    }
    b.innerHTML = html;
    wrap.appendChild(b);
    /* v94 — a purposeful diagram, anchored to this exact heading
       (guided-learning.js holds the specs; the anchor must match the
       block heading, so a diagram can never float free of its text). */
    if (ctx && ctx.data && ctx.data.guide && window.GuidedLearn) {
      const spec = window.GuidedLearn.diagramAfter(ctx.data.guide, block.h);
      if (spec) {
        const fig = window.GuidedLearn.buildDiagram(spec);
        if (fig) {
          const slot = el("div", "gl-diag-slot");
          slot.innerHTML = fig;
          wrap.appendChild(slot);
        }
      }
    }
  });
  panel.appendChild(wrap);
  /* …and the "advanced" chrome (mistakes, recap, check) closes it,
     after every block has been read. */
  if (ctx && ctx.kind === "advanced" && !hasChrome("advanced")) {
    theoryChrome(panel, ctx.data, "advanced", accent);
  }
}

/* Chapter-level learning chrome (v94 guided journey). Runs once per
   tab. The "simple" surface opens the LEARN stage — the hook (why
   you should care), why the chapter exists, what you will be able
   to do, where it connects in the syllabus, a low-stakes readiness
   check and one clear next step. The "advanced" surface closes the
   UNDERSTAND stage — common mistakes, the quick recap, a checkpoint
   drawn from this chapter's own practice bank, an attempt-first
   recall set and a revision strip. Fields come from data.guide
   (guided-learning.js) and data.upgrade (theory-upgrade.js). */
function theoryChrome(panel, data, kind, accent) {
  const up = data && data.upgrade;
  const guide = data && data.guide;
  if (!up && !guide) return;
  const routeId = glChapterKeyOf(data);
  const wrap = el("div", "th-view th-view--chrome");
  wrap.setAttribute("data-th-kind", kind);
  wrap.style.setProperty("--th-accent", accent || "var(--ink)");

  if (kind === "simple") {
    /* 1 — the hook: why should I care about this chapter? */
    if (guide && guide.hook) {
      const hook = el("div", "gl-hook");
      hook.innerHTML = `<i data-lucide="compass"></i><p>${guide.hook}</p>`;
      wrap.appendChild(hook);
    }
    /* 2 — purpose: what this chapter actually does for you. */
    if (up && Array.isArray(up.intro) && up.intro.length) {
      const lead = el("div", "th-lead");
      lead.innerHTML = `<h4 class="th-h th-h--lead"><i data-lucide="compass"></i> Why this chapter exists</h4>` +
        up.intro.map(p => `<p class="th-p th-lead-p">${p}</p>`).join("");
      wrap.appendChild(lead);
    }
    /* 3 — objectives, in plain student language. */
    if (up && Array.isArray(up.objectives) && up.objectives.length) {
      const obj = el("div", "th-box th-box--obj");
      obj.innerHTML = `<span class="th-box-label"><i data-lucide="target"></i> By the end of this chapter you can</span>` +
        `<ul class="th-list">` + up.objectives.map(o => `<li>${o}</li>`).join("") + `</ul>`;
      wrap.appendChild(obj);
    }
    /* 4 — where this chapter sits in the syllabus. */
    glAppendConnects(wrap, guide);
    /* 5 — a low-stakes readiness check (never blocks the lesson). */
    glAppendReadiness(wrap, routeId, guide);
    /* 6 — one clear next step. */
    glAppendIntroAction(wrap, routeId);
  } else {
    /* Common mistakes to avoid */
    if (up && Array.isArray(up.mistakes) && up.mistakes.length) {
      const m = el("div", "th-box th-box--mistake");
      m.innerHTML = `<span class="th-box-label"><i data-lucide="triangle-alert"></i> Common mistakes to avoid</span>` +
        `<ul class="th-list">` + up.mistakes.map(x => `<li>${x}</li>`).join("") + `</ul>`;
      wrap.appendChild(m);
    }
    /* The recap students actually reread before an exam */
    if (up && Array.isArray(up.summary) && up.summary.length) {
      const s = el("div", "th-box th-box--summary");
      s.innerHTML = `<span class="th-box-label"><i data-lucide="list-checks"></i> Quick recap</span>` +
        `<ul class="th-list">` + up.summary.map(x => `<li>${x}</li>`).join("") + `</ul>`;
      wrap.appendChild(s);
    }
    /* A checkpoint built from this chapter's own questions */
    glAppendCheckpoint(wrap, routeId, guide);
    /* Attempt-first recall set */
    glAppendRecall(wrap, routeId, guide);
    /* Revision strip */
    glAppendReviseStrip(wrap, routeId);
  }
  if (wrap.children.length) panel.appendChild(wrap);
  icons();
}

/* ---------------------------------------------------------
   v94 guided-journey widgets (DOM side of guided-learning.js).
   Every stage marker here comes from a real student action on
   this page — nothing is pre-ticked, nothing is decorative.
   --------------------------------------------------------- */

/* APP_DATA section object -> route id (data keys differ from route
   ids for six Class 11 chapters). Identity lookup, not name
   matching, so a Class 12 section resolves exactly too. */
function glChapterKeyOf(data) {
  if (!data || typeof APP_DATA === "undefined" || !GL) return null;
  const keys = Object.keys(APP_DATA);
  for (let i = 0; i < keys.length; i++) {
    if (APP_DATA[keys[i]] === data) return GL.dataKeyToRoute(keys[i]);
  }
  return null;
}

/* Stage completion helpers — one-time markers + honest feedback. */
function glLearnDone(routeId) {
  if (!routeId) return;
  if (markGuideStage(routeId, "learnAt")) {
    toast(`Learn stage started — ${chapterTitleOf(routeId)}`, "success", "compass");
    refreshRoadmap();
  }
}
function glUnderstandDone(routeId) {
  if (!routeId) return;
  if (markGuideStage(routeId, "understandAt")) {
    toast(`Understand stage complete — ${chapterTitleOf(routeId)}`, "success", "badge-check");
    refreshRoadmap();
  }
}
function glRememberDone(routeId) {
  if (!routeId) return;
  awardXPOnce("guide-rcl|" + routeId, 6, `${chapterTitleOf(routeId)} recall complete`);
  if (markGuideStage(routeId, "rememberAt")) {
    toast(`Remember stage complete — ${chapterTitleOf(routeId)}`, "success", "rotate-ccw");
    refreshRoadmap();
  }
}

/* 4 — "Where this fits": genuine syllabus links from the guide
   data. Both sides are optional; a chapter with no real link
   simply shows the side that exists. */
function glAppendConnects(wrap, guide) {
  if (!guide || !guide.connects) return;
  const c = guide.connects;
  if (!c.before && !c.after) return;
  const box = el("div", "gl-connect");
  let html = `<span class="gl-box-label"><i data-lucide="link-2"></i> Where this fits</span><ul class="gl-connect-list">`;
  if (c.before) html += `<li><b>Builds on:</b> ${c.before}</li>`;
  if (c.after) html += `<li><b>Leads to:</b> ${c.after}</li>`;
  box.innerHTML = html + `</ul>`;
  wrap.appendChild(box);
}

/* 5 — Readiness check: one scenario question answered BEFORE the
   lesson, so the student knows what they do not yet know. Submitting
   it (right or wrong) opens the Learn stage; a wrong answer is never
   penalised — they have not been taught yet. */
function glAppendReadiness(wrap, routeId, guide) {
  if (!guide || !guide.readiness) return;
  const r = guide.readiness;
  const box = el("div", "gl-readiness");
  box.innerHTML = `
    <span class="gl-box-label"><i data-lucide="sparkles"></i> Before we start — what do you already sense?</span>
    <p class="gl-rd-q">${r.q}</p>
    <div class="opt-group gl-rd-opts" data-role="answer"></div>
    <div class="q-actions gl-rd-actions">
      <button class="btn-primary sm ripple-surface" type="button" data-act="rd-check"><i data-lucide="check"></i> Check my guess</button>
    </div>
    <div class="reveal-area"></div>`;
  const group = $(".gl-rd-opts", box);
  const reveal = $(".reveal-area", box);
  r.options.forEach((opt, i) => {
    const b = el("button", "chip", escapeHtml(opt));
    b.type = "button";
    b.dataset.val = String(i);
    group.appendChild(b);
  });
  let picked = null;
  box.addEventListener("click", (e) => {
    const chip = e.target.closest(".opt-group button[data-val]");
    if (chip) {
      $all("button", group).forEach(b => b.classList.remove("active"));
      chip.classList.add("active");
      picked = parseInt(chip.dataset.val, 10);
      return;
    }
    if (e.target.closest("[data-act='rd-check']")) {
      if (picked === null) {
        reveal.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Pick the option that feels closest — there is no penalty here.</p></div>`;
        return;
      }
      const correct = picked === r.answer;
      reveal.innerHTML = correct
        ? `<div class="reveal-block"><h4>Yes — that is the idea.</h4><p style="font-size:0.88rem; line-height:1.6; color:var(--ink-soft);">${r.explain}</p></div>`
        : `<div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);"><h4>Not there yet — that is exactly why this chapter exists.</h4><p style="font-size:0.88rem; line-height:1.6; color:var(--ink-soft);">${r.explain}</p></div>`;
      if (correct) playSuccessSound(); else playErrorSound();
      awardXPOnce("guide-rd|" + routeId, 4, `${chapterTitleOf(routeId)} readiness check`);
      logActivity({
        type: "practice",
        text: `${chapterTitleOf(routeId)} — readiness check ${correct ? "answered correctly" : "attempted"}`,
        route: "ch-" + routeId, tab: glActiveTab() || "Introduction", status: "started"
      });
      glLearnDone(routeId);
      icons();
    }
  });
  wrap.appendChild(box);
}

/* 6 — One clear CTA out of the introduction: the first real tab of
   the Understand stage (or Practise, for chapters without one). */
function glAppendIntroAction(wrap, routeId) {
  const tabs = glTabChips().map(c => c.dataset.tab);
  const target = (routeId && GL.firstStageTab(routeId, "understand", tabs)) ||
    (routeId && GL.firstStageTab(routeId, "practise", tabs));
  if (!target) return;
  const started = !!(guideRec(routeId || "").learnAt);
  const box = el("div", "gl-cta");
  box.innerHTML = `<p class="gl-cta-note">${started
    ? "You have the context. Pick the lesson back up where you left it."
    : "You have the context. Next comes the lesson itself — the concepts worked through, then checked."}</p>`;
  const btn = el("button", "btn-primary ripple-surface gl-cta-btn",
    `<i data-lucide="book-open"></i> ${started ? "Continue learning" : "Start learning"} — ${escapeHtml(target)}`);
  btn.type = "button";
  btn.addEventListener("click", () => glClickTab(target));
  box.appendChild(btn);
  wrap.appendChild(box);
}

/* UNDERSTAND checkpoint — real questions from this chapter's own
   practice bank, placed at the end of the lesson. Same questions,
   same solved keys, same XP rules as the bank: solving one here
   marks it solved there (and vice versa), so the checkpoint can
   never inflate progress or mint duplicate XP. */
function glAppendCheckpoint(wrap, routeId, guide) {
  if (!guide || !Array.isArray(guide.checkpoint) || !guide.checkpoint.length) return;
  const seen = {};
  const list = el("div", "gl-cp-list", "");
  guide.checkpoint.forEach((qid) => {
    if (typeof qid !== "number" || seen[qid]) return;
    seen[qid] = 1;
    const card = glCheckpointCard(routeId, qid);
    if (card) list.appendChild(card);
  });
  if (!list.children.length) return;
  const box = el("div", "gl-checkpoint");
  box.innerHTML = `<span class="gl-box-label"><i data-lucide="badge-check"></i> Checkpoint — prove you understood it</span>` +
    `<p class="gl-cp-sub">Real questions from this chapter's own question bank. Getting one wrong is useful: it lands in your Mistake Book with the explanation attached.</p>`;
  box.appendChild(list);
  wrap.appendChild(box);
  icons();
}

function glCheckpointCard(routeId, qid) {
  if (!routeId) return null;
  const bankOf = () => (CHAPTER_BANK[routeId] ? CHAPTER_BANK[routeId]() : null);
  const find = () => {
    const bank = bankOf();
    return bank ? bank.find(x => x.id === qid) || null : null;
  };
  /* Chapters whose bank questions carry their own full card
     renderer host it verbatim — one solved key, one XP path. */
  if (routeId === "eq" || routeId === "dc" || routeId === "jr") {
    const q = find();
    if (!q) return null;
    const holder = el("div", "gl-cp-host", "");
    const card = routeId === "eq" ? renderQuestionCard(q, "eq")
      : routeId === "dc" ? renderDCQuestionCard(q)
      : renderJRQuestionCard(q);
    const solvedKey = `${routeId}-${q.id}`;
    /* The hosted card updates STATE.solved itself; this listener
       (attached after the card's own, so it runs afterwards) only
       notices a correct answer to close the Understand stage. */
    card.addEventListener("click", () => {
      const s = STATE.solved[solvedKey];
      if (s && s.correct) glUnderstandDone(routeId);
    });
    holder.appendChild(card);
    return holder;
  }
  if (routeId === "lg") return glDualChoiceCard(find());
  if (routeId === "cb" || routeId === "sp2" || routeId === "brs") {
    const opts = routeId === "cb" ? CB_PRACTICE_OPTIONS
      : routeId === "sp2" ? SP2_PRACTICE_OPTIONS : BRS_PRACTICE_OPTIONS;
    return glChoiceCard(find(), routeId, opts);
  }
  /* Every remaining chapter (Class 11 MCQ banks + all Class 12) */
  const q = find();
  if (!q || !Array.isArray(q.options) || typeof q.answerIndex !== "number") return null;
  return glMcqCard(q, routeId);
}

/* Compact MCQ checkpoint — mirrors the practice-bank flow exactly
   (shuffle, check, sound, XP, mistake book) with the shared solved
   key `<routeId>-<id>`. */
function glMcqCard(q, routeId) {
  const title = chapterTitleOf(routeId);
  const solvedKey = `${routeId}-${q.id}`;
  const alreadySolved = STATE.solved[solvedKey];
  const questionText = q.question || q.q;
  let picked = null;
  const shuffledOrder = fisherYatesShuffle(q.options.map((_, i) => i));

  const card = el("div", "card q-card gl-cp-q", "");
  card.innerHTML = `
    <div class="q-meta">
      <span class="diff-badge ${q.difficulty}">${q.difficulty}</span>
      <span class="q-id">Q${q.id}</span>
      ${alreadySolved ? `<span style="margin-left:auto; color:var(--th-accent, var(--ink)); font-size:0.78rem; display:flex; align-items:center; gap:4px;"><i data-lucide="check-circle" style="width:13px;height:13px;"></i> Solved</span>` : ""}
    </div>
    <div class="q-body">${questionText}</div>
    <div class="gl-cp-opts opt-group" data-role="answer">
      ${shuffledOrder.map(i => `<button class="chip" data-val="${i}">${q.options[i]}</button>`).join("")}
    </div>
    <div class="q-actions">
      <button class="btn-primary sm ripple-surface" type="button" data-act="check"><i data-lucide="check"></i> Check Answer</button>
      ${aiAskBtn(`${routeId}.numericals`, q)}
    </div>
    <div class="reveal-area"></div>`;
  const revealArea = $(".reveal-area", card);

  card.addEventListener("click", (e) => {
    const optBtn = e.target.closest(".opt-group button[data-val]");
    if (optBtn) {
      const group = optBtn.closest(".opt-group");
      $all("button", group).forEach(b => b.classList.remove("active"));
      optBtn.classList.add("active");
      picked = parseInt(optBtn.dataset.val, 10);
      return;
    }
    if (!e.target.closest("button[data-act='check']")) return;
    if (picked === null) {
      revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Pick an option first.</p></div>`;
      return;
    }
    const correct = picked === q.answerIndex;
    if (correct) {
      revealArea.innerHTML = `
        <div class="reveal-block">
          <h4>Correct!</h4>
          <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${q.explanation}</p>
        </div>`;
      playSuccessSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: true, attempts: 1 };
        saveState(); addXP(4, `${title} Q${q.id} solved`);
        logActivity({ type: "practice", text: `${title} Q${q.id} solved (${q.difficulty})`, route: "ch-" + routeId, tab: "Understanding Checkpoint", qid: q.id, difficulty: q.difficulty, status: "solved" });
        refreshProgress();
      }
      mistakeBookRecordCorrect(solvedKey);
      glUnderstandDone(routeId);
    } else {
      revealArea.innerHTML = `
        <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
          <h4>Not quite</h4>
          <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${q.options[q.answerIndex]}</b>.<br>${q.explanation}</p>
        </div>`;
      playErrorSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: false, attempts: 1 };
        if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
        saveState(); addXP(-XP_WRONG_PENALTY, `Q${q.id} incorrect`); refreshProgress();
      }
      mistakeBookRecord({
        key: solvedKey, question: questionText, chapter: routeId, chapterLabel: title, topic: title,
        type: "Understanding Checkpoint", studentAnswer: q.options[picked],
        correctAnswer: q.options[q.answerIndex], explanation: q.explanation
      });
    }
    icons();
  });
  return card;
}

/* Ledger checkpoint — which account is posted to each side, using
   the same pool and solved keys as the Journal → Ledger Practice tab. */
function glDualChoiceCard(q) {
  if (!q) return null;
  const routeId = "lg";
  const solvedKey = `lg-${q.id}`;
  const alreadySolved = STATE.solved[solvedKey];
  const pool = getLedgerPracticePool();
  const accountPool = [...new Set(pool.flatMap(p => [p.debitAccount, p.creditAccount]))];
  function shuffledOptions(correct) {
    const distractors = accountPool.filter(a => a !== correct);
    for (let i = distractors.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [distractors[i], distractors[j]] = [distractors[j], distractors[i]];
    }
    const opts = [correct, ...distractors.slice(0, 3)];
    for (let i = opts.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [opts[i], opts[j]] = [opts[j], opts[i]];
    }
    return opts;
  }
  let picked = { debit: null, credit: null };
  const card = el("div", "card q-card gl-cp-q", "");
  card.innerHTML = `
    <div class="q-meta">
      <span class="diff-badge ${q.difficulty}">${q.difficulty}</span>
      <span class="q-id">Q${q.id}</span>
      ${alreadySolved ? `<span style="margin-left:auto; color:var(--c-lg); font-size:0.78rem; display:flex; align-items:center; gap:4px;"><i data-lucide="check-circle" style="width:13px;height:13px;"></i> Solved</span>` : ""}
    </div>
    <div class="q-body">${q.transaction}</div>
    <div style="margin-top:12px;">
      <p class="gl-cp-prompt">Which account is debited?</p>
      <div class="opt-group" data-role="debit" style="display:flex; flex-wrap:wrap; gap:8px;">
        ${shuffledOptions(q.debitAccount).map(o => `<button class="chip" data-val="${o}">${o}</button>`).join("")}
      </div>
    </div>
    <div style="margin-top:12px;">
      <p class="gl-cp-prompt">Which account is credited?</p>
      <div class="opt-group" data-role="credit" style="display:flex; flex-wrap:wrap; gap:8px;">
        ${shuffledOptions(q.creditAccount).map(o => `<button class="chip" data-val="${o}">${o}</button>`).join("")}
      </div>
    </div>
    <div class="q-actions">
      <button class="btn-primary sm ripple-surface" type="button" data-act="check"><i data-lucide="check"></i> Check Answer</button>
      ${aiAskBtn("ledger.practice", q, { chapterId: "lg" })}
    </div>
    <div class="reveal-area"></div>`;
  const revealArea = $(".reveal-area", card);

  card.addEventListener("click", (e) => {
    const optBtn = e.target.closest(".opt-group button[data-val]");
    if (optBtn) {
      const group = optBtn.closest(".opt-group");
      $all("button", group).forEach(b => b.classList.remove("active"));
      optBtn.classList.add("active");
      picked[group.dataset.role] = optBtn.dataset.val;
      return;
    }
    if (!e.target.closest("button[data-act='check']")) return;
    if (!picked.debit || !picked.credit) {
      revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Pick one account for each side first.</p></div>`;
      return;
    }
    const correct = picked.debit === q.debitAccount && picked.credit === q.creditAccount;
    if (correct) {
      revealArea.innerHTML = `
        <div class="reveal-block">
          <h4>Correct!</h4>
          <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${q.debitAccount} is debited (posted 'To ${q.creditAccount}'); ${q.creditAccount} is credited (posted 'By ${q.debitAccount}'). ${q.explanation}</p>
        </div>`;
      playSuccessSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: true, attempts: 1 };
        saveState(); addXP(4, `Posted ledger Q${q.id}`);
        logActivity({ type: "practice", text: `Ledger posting Q${q.id} solved (${q.difficulty})`, route: "ch-lg", tab: "Understanding Checkpoint", qid: q.id, difficulty: q.difficulty, status: "solved" });
        refreshProgress();
      }
      mistakeBookRecordCorrect(solvedKey);
      glUnderstandDone(routeId);
    } else {
      revealArea.innerHTML = `
        <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
          <h4>Not quite</h4>
          <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">The correct posting is: <b>${q.debitAccount}</b> debited (To ${q.creditAccount}), <b>${q.creditAccount}</b> credited (By ${q.debitAccount}). ${q.explanation}</p>
        </div>`;
      playErrorSound();
      if (!STATE.solved[solvedKey]) {
        STATE.solved[solvedKey] = { correct: false, attempts: 1 };
        if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
        saveState(); addXP(-XP_WRONG_PENALTY, `Q${q.id} incorrect`); refreshProgress();
      }
      mistakeBookRecord({
        key: solvedKey, question: q.transaction, chapter: "lg", chapterLabel: "Ledger",
        topic: "Ledger posting", type: "Understanding Checkpoint",
        studentAnswer: `${picked.debit} debited / ${picked.credit} credited`,
        correctAnswer: `${q.debitAccount} debited / ${q.creditAccount} credited`,
        explanation: q.explanation
      });
    }
    icons();
  });
  return card;
}

