/* ---------------------------------------------------------
   6d-6. CHAPTERS 15-18 — Provisions & Reserves, Rectification
   of Errors, Financial Statements of Sole Proprietorship, and
   Adjustment in Preparation of Financial Statements.

   All four share one shell (hero + tab bar + journey stepper),
   one practice-bank engine, one step-case engine and one
   quick-revision panel. Each chapter contributes its own
   interactive tab:
     Ch.15 Decision Lab      — classify provision vs reserve
     Ch.16 Error Detective   — find the error, pass the entry
     Ch.17 Statement Builder — place every head, reveal the statements
     Ch.18 Adjustment Studio — two effects of every adjustment
   --------------------------------------------------------- */
const CH_NEW_META = {
  pres: { num: 15, idx: 14, name: "Provisions and Reserves", accent: "var(--c-pres)", soft: "var(--c-pres-soft)", blurb: "Provisions vs reserves, capital and revenue profits, secret reserves, and when each one is (and is not) allowed — plus the Decision Lab." },
  roe: { num: 16, idx: 15, name: "Rectification of Errors", accent: "var(--c-roe)", soft: "var(--c-roe-soft)", blurb: "Errors of omission, commission, principle, casting and compensating errors, the Suspense A/c, and the Error Detective." },
  fs: { num: 17, idx: 16, name: "Financial Statements of Sole Proprietorship", accent: "var(--c-fs)", soft: "var(--c-fs-soft)", blurb: "Trading A/c, P&L A/c and Balance Sheet from a Trial Balance, direct vs indirect items, and the Statement Builder." },
  adj: { num: 18, idx: 17, name: "Adjustment in Preparation of Financial Statements", accent: "var(--c-adj)", soft: "var(--c-adj-soft)", blurb: "Closing stock, outstanding and prepaid items, accruals, depreciation, bad debts — every adjustment with both its effects, in the Adjustment Studio." }
};

function renderNewChapterShell(root, chId, tabs, renderPanel) {
  const m = CH_NEW_META[chId];
  const data = APP_DATA[chId];
  if (!data) { root.appendChild(el("p", "", "Chapter data is still loading.")); return; }
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Chapter ${m.num}</span>
    <h1>${m.name}</h1>
    <p>${APP_DATA.chapters[m.idx].tagline} ${m.blurb}</p>
  `));

  const tabBar = el("div", "", "");
  tabBar.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; margin-bottom:22px;";
  tabs.forEach((t, i) => {
    const chip = el("button", `chip ${i === 0 ? "active" : ""}`, t);
    chip.dataset.tab = t;
    tabBar.appendChild(chip);
  });
  const journeyEl = renderJourneyStepper(root, chId);
  root.appendChild(tabBar);
  const panel = el("div", "");
  root.appendChild(panel);

  function showTab(name) {
    $all(".chip", tabBar).forEach(c => c.classList.toggle("active", c.dataset.tab === name));
    panel.innerHTML = "";
    updateJourneyStepper(journeyEl, chId, name);
    renderPanel(name, panel, data, m);
    icons();
  }
  tabBar.addEventListener("click", e => {
    const chip = e.target.closest(".chip");
    if (chip) showTab(chip.dataset.tab);
  });
  showTab(tabs[0]);
}

