/* ---------------------------------------------------------
   Step-case engine — drives the Decision Lab (Ch.15),
   the Error Detective (Ch.16) and the Adjustment Studio
   (Ch.18). Each case is a short context plus 3-4 MCQ steps;
   every step reveals its hint if wrong and its reasoning when
   checked. The deck shuffles once per visit, tracks a score,
   feeds the Mistake Book and the XP/progress system.
   --------------------------------------------------------- */
const CH_CASE_STATE = {};

function renderChCaseActivity(panel, cfg) {
  panel.appendChild(sectionTitle(cfg.title));
  const hint = el("p", "", cfg.hint);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const cases = cfg.cases;
  let st = CH_CASE_STATE[cfg.key];
  if (!st || st.len !== cases.length) {
    st = CH_CASE_STATE[cfg.key] = {
      order: fisherYatesShuffle(cases.map((_, i) => i)),
      index: 0, score: { correct: 0, attempted: 0 }, picks: {}, len: cases.length
    };
  }
  if (st.index >= st.order.length) st.index = 0;
  if (st.index < 0) st.index = st.order.length - 1;

  const topBar = el("div", "", "");
  topBar.style.cssText = "display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:14px;";
  topBar.innerHTML = `
    <p style="font-size:0.83rem; color:var(--ink-faint); margin:0;">${cfg.caseNoun} ${st.index + 1} of ${cases.length}</p>
    <p style="font-size:0.83rem; color:${cfg.accent}; margin:0; font-weight:600;">Score: ${st.score.correct}/${st.score.attempted}</p>
  `;
  panel.appendChild(topBar);

  const c = cases[st.order[st.index]];
  const qs = cfg.questionsOf(c);
  const pickKey = `${cfg.key}-${c.id}`;
  if (!st.picks[pickKey]) st.picks[pickKey] = {};
  const picks = st.picks[pickKey];

  const card = el("div", "card-solid q-card", "");
  card.style.cssText = "padding:26px;";
  card.innerHTML = `
    <div class="q-meta">
      <span class="diff-badge ${c.difficulty}">${c.difficulty}</span>
      <span class="q-id">${cfg.caseNoun} ${c.id}</span>
      <span style="margin-left:auto; font-size:0.74rem; color:var(--ink-faint); text-transform:uppercase; letter-spacing:0.03em;">${cfg.subtitleOf(c)}</span>
      ${bookmarkButtonHTML(pickKey)}
    </div>
    ${cfg.contextOf(c)}
    ${qs.map((q, i) => `
      <div class="stepq" data-i="${i}" style="margin-top:16px; padding-top:14px; border-top:1px solid var(--line);">
        <p style="font-size:0.9rem; line-height:1.65; font-weight:600; margin-bottom:10px;">${i + 1}. ${cfg.promptOf(q)}</p>
        <div class="opt-group" data-role="answer" data-i="${i}" style="display:flex; flex-wrap:wrap; gap:8px;">
          ${q.options.map((o, oi) => `<button class="chip" data-val="${oi}">${o}</button>`).join("")}
        </div>
        <div class="stepq-reveal" data-i="${i}"></div>
      </div>`).join("")}
    <div class="q-actions" style="margin-top:18px; display:flex; gap:10px; flex-wrap:wrap;">
      <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Answers</button>
      ${aiAskBtn(cfg.srcKey, c, { getPicks: () => qs.map((q, i) => picks[i] !== undefined ? { index: picks[i], label: q.options[picks[i]] } : null) })}
      <button class="btn-ghost sm ripple-surface" data-act="prev"><i data-lucide="arrow-left"></i> Previous</button>
      <button class="btn-ghost sm ripple-surface" data-act="next"><i data-lucide="arrow-right"></i> Next</button>
    </div>
    <div class="reveal-area"></div>
  `;
  const revealArea = $(".reveal-area", card);

  card.addEventListener("click", (e) => {
    const optBtn = e.target.closest(".opt-group button[data-val]");
    if (optBtn) {
      const group = optBtn.closest(".opt-group");
      $all("button", group).forEach(b => b.classList.remove("active"));
      optBtn.classList.add("active");
      picks[group.dataset.i] = parseInt(optBtn.dataset.val, 10);
      return;
    }
    const bookmarkBtn = e.target.closest("button[data-act='bookmark']");
    if (bookmarkBtn) { toggleBookmark(pickKey, bookmarkBtn); return; }
    const prevBtn = e.target.closest("button[data-act='prev']");
    if (prevBtn) {
      st.index = (st.index - 1 + st.order.length) % st.order.length;
      panel.innerHTML = "";
      renderChCaseActivity(panel, cfg);
      return;
    }
    const nextBtn = e.target.closest("button[data-act='next']");
    if (nextBtn) {
      st.index = (st.index + 1) % st.order.length;
      panel.innerHTML = "";
      renderChCaseActivity(panel, cfg);
      return;
    }
    const checkBtn = e.target.closest("button[data-act='check']");
    if (checkBtn) {
      const unanswered = qs.some((_, i) => picks[i] === undefined);
      if (unanswered) {
        revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Answer every step first.</p></div>`;
        return;
      }
      let correctCount = 0;
      qs.forEach((q, i) => {
        const ok = picks[i] === q.answerIndex;
        if (ok) correctCount++;
        const target = $(`.stepq-reveal[data-i="${i}"]`, card);
        target.innerHTML = ok
          ? `<div class="reveal-block" style="margin-top:10px;"><h4 style="font-size:0.88rem;">Correct</h4><p style="font-size:0.85rem; line-height:1.6; color:var(--ink-soft);">${q.reasoning}</p></div>`
          : `<div class="reveal-block" style="margin-top:10px; background:var(--flag-soft); border-left-color:var(--flag);"><h4 style="font-size:0.88rem;">Not quite</h4><p style="font-size:0.85rem; line-height:1.6; color:var(--ink-soft);"><b>Hint:</b> ${q.hint}<br><b>Answer:</b> ${q.options[q.answerIndex]}<br>${q.reasoning}</p></div>`;
      });
      const allCorrect = correctCount === qs.length;
      revealArea.innerHTML = `
        <div class="reveal-block" style="${allCorrect ? "" : "background:var(--flag-soft); border-left-color:var(--flag);"} margin-top:16px;">
          <h4>${allCorrect ? "All steps correct!" : `${correctCount} of ${qs.length} steps correct`}</h4>
          <p style="font-size:0.86rem; line-height:1.65; color:var(--ink-soft);">${cfg.wrapUpOf(c)}</p>
        </div>`;
      if (allCorrect) playSuccessSound(); else playErrorSound();
      st.score.attempted++;
      if (allCorrect) st.score.correct++;
      const scoreEl = topBar.querySelectorAll("p")[1];
      if (scoreEl) scoreEl.textContent = `Score: ${st.score.correct}/${st.score.attempted}`;

      if (!STATE.solved[pickKey]) {
        STATE.solved[pickKey] = { correct: allCorrect, attempts: 1 };
        saveState();
        if (allCorrect) {
          addXP(5, `${cfg.activityName} ${c.id} solved`);
          logActivity({ type: "case", text: `${cfg.activityName} ${c.id} solved (${c.difficulty})`, route: "ch-" + cfg.chId, tab: cfg.activityName, qid: c.id, qidNoun: cfg.caseNoun, difficulty: c.difficulty, status: "solved" });
          mistakeBookRecordCorrect(pickKey);
        } else {
          if (!STATE.mistakes.includes(pickKey)) STATE.mistakes.push(pickKey);
          addXP(-XP_WRONG_PENALTY, `${cfg.activityName} ${c.id} incorrect`);
          mistakeBookRecord({
            key: pickKey, question: cfg.questionOf(c), chapter: cfg.chId, chapterLabel: cfg.chapterLabel,
            topic: cfg.activityName, type: cfg.activityName,
            studentAnswer: qs.map((q, i) => `${cfg.promptOf(q)} → ${q.options[picks[i]]}`).join(" | "),
            correctAnswer: qs.map(q => `${cfg.promptOf(q)} → ${q.options[q.answerIndex]}`).join(" | "),
            explanation: qs.map(q => q.reasoning).join(" ")
          });
        }
        refreshProgress();
      }
      icons();
    }
  });
  panel.appendChild(card);
  icons();
}

/* ---- Ch.15 — Decision Lab ---- */
function renderDecisionLab(panel, data, m) {
  renderChCaseActivity(panel, {
    key: "pres-lab", chId: "pres", chapterLabel: m.name, accent: m.accent,
    title: "Decision Lab ⚖️",
    hint: `${data.decisionLab.length} year-end scenarios. For each one decide what the amount really is — a provision, a revenue reserve, a capital reserve, or something else entirely — then see the reasoning the moment you check it.`,
    cases: data.decisionLab, caseNoun: "Scenario", activityName: "Decision Lab", srcKey: "pres.decisionLab",
    questionsOf: c => c.steps,
    promptOf: q => q.q,
    subtitleOf: c => "Classify the amount",
    contextOf: c => `
      <div class="tnum" style="font-size:0.92rem; font-weight:600; color:${m.accent}; background:${m.soft}; padding:12px; border-radius:10px; margin:14px 0 10px;">${c.title}</div>
      <p style="font-size:0.92rem; line-height:1.7; color:var(--ink-soft); margin-bottom:6px;"><b>Situation:</b> ${c.situation}</p>`,
    questionOf: c => `${c.title} — ${c.situation}`,
    wrapUpOf: c => `${c.title} — the deciding test is always the same: is this an expected liability (provision), or a division of profit already earned (reserve), and is that profit capital or revenue in nature?`
  });
}

/* ---- Ch.16 — Error Detective ---- */
function renderErrorDetective(panel, data, m) {
  renderChCaseActivity(panel, {
    key: "roe-det", chId: "roe", chapterLabel: m.name, accent: m.accent,
    title: "Error Detective 🕵️",
    hint: `${data.auditCases.length} cases straight off a bookkeeper's desk. Read the records, work out what went wrong, then answer each step — the type of error, whether the Trial Balance agrees, and the correcting entry.`,
    cases: data.auditCases, caseNoun: "Case", activityName: "Error Detective", srcKey: "roe.auditCases",
    questionsOf: c => c.questions,
    promptOf: q => q.q,
    subtitleOf: c => "Rectification",
    contextOf: c => `
      <div class="tnum" style="font-size:0.92rem; font-weight:600; color:${m.accent}; background:${m.soft}; padding:12px; border-radius:10px; margin:14px 0 10px;">${c.title}</div>
      <ul style="padding-left:20px; margin-bottom:10px;">${c.records.map(r => `<li style="font-size:0.88rem; line-height:1.65; color:var(--ink-soft); margin-bottom:5px;">${r}</li>`).join("")}</ul>
      <p style="font-size:0.78rem; text-transform:uppercase; letter-spacing:0.04em; color:var(--ink-faint); margin-bottom:4px;">What the books show</p>`,
    questionOf: c => `${c.title}: ${c.errorDescription}`,
    wrapUpOf: c => c.errorDescription
  });
}

/* ---- Ch.18 — Adjustment Studio ---- */
function renderAdjustmentStudio(panel, data, m) {
  renderChCaseActivity(panel, {
    key: "adj-studio", chId: "adj", chapterLabel: m.name, accent: m.accent,
    title: "Adjustment Studio 🛠️",
    hint: `${data.adjustmentCases.length} adjustments — the full list a Class 11 paper can throw at you. For each one, work out what it means, which accounts it touches, and its effect on profit and on the Balance Sheet. Remember: two effects, every single time.`,
    cases: data.adjustmentCases, caseNoun: "Adjustment", activityName: "Adjustment Studio", srcKey: "adj.adjustmentCases",
    questionsOf: c => c.questions,
    promptOf: q => q.q,
    subtitleOf: c => c.concept,
    contextOf: c => `
      <div class="tnum" style="font-size:0.92rem; font-weight:600; color:${m.accent}; background:${m.soft}; padding:12px; border-radius:10px; margin:14px 0 8px;">${c.concept}</div>
      <p style="font-size:0.92rem; line-height:1.7; color:var(--ink-soft); margin-bottom:6px;"><b>The adjustment:</b> ${c.adjustment}</p>`,
    questionOf: c => `${c.concept}: ${c.adjustment}`,
    wrapUpOf: c => `${c.concept} — one effect in the Trading/P&L A/c, one in the Balance Sheet. Miss either side and the Balance Sheet refuses to tally.`
  });
}

/* ---------------------------------------------------------
   Ch.17 — Statement Builder: place every Trial Balance head
   (and every adjustment's effect) in the right statement,
   then reveal the full Trading A/c, P&L A/c and Balance Sheet
   and check that they tally.
   --------------------------------------------------------- */
const BUILDER_PLACEMENT_OPTS = [
  ["T-Dr", "Trading A/c — Dr"],
  ["T-Cr", "Trading A/c — Cr"],
  ["P-Dr", "P&L A/c — Dr"],
  ["BS-A", "Balance Sheet — Asset"],
  ["BS-L", "Balance Sheet — Liability"]
];
const BUILDER_STATE = { index: 0, picks: {}, score: { correct: 0, attempted: 0 }, showSolution: {} };

function builderStatementHTML(c) {
  const s = c.solution;
  const rows = pairs => pairs.map(p => `<tr style="border-bottom:1px solid var(--line);"><td style="padding:6px 4px;">${p[0]}</td><td class="tnum" style="text-align:right; padding:6px 4px;">${fmtINR(p[1])}</td></tr>`).join("");
  const sum = pairs => pairs.reduce((a, p) => a + p[1], 0);
  const tbl = (title, pairs) => `
    <div>
      <h4 style="font-size:0.9rem; margin-bottom:8px; color:var(--c-fs);">${title}</h4>
      <table style="width:100%; border-collapse:collapse; font-size:0.8rem;">
        <tbody>${rows(pairs)}</tbody>
        <tfoot><tr style="border-top:2px solid var(--line); font-weight:700;"><td style="padding:7px 4px;">Total</td><td class="tnum" style="text-align:right; padding:7px 4px;">${fmtINR(sum(pairs))}</td></tr></tfoot>
      </table>
    </div>`;
  const tDr = sum(s.trading.dr), tCr = sum(s.trading.cr);
  const pDr = sum(s.pnl.dr), pCr = sum(s.pnl.cr);
  const liab = sum(s.balanceSheet.liabilities), assets = sum(s.balanceSheet.assets);
  return `
    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(230px,1fr)); gap:18px; margin-top:6px;">
      ${tbl("Trading A/c — Dr", s.trading.dr)}
      ${tbl("Trading A/c — Cr", s.trading.cr)}
      ${tbl("Profit & Loss A/c — Dr", s.pnl.dr)}
      ${tbl("Profit & Loss A/c — Cr", s.pnl.cr)}
      ${tbl("Balance Sheet — Liabilities", s.balanceSheet.liabilities)}
      ${tbl("Balance Sheet — Assets", s.balanceSheet.assets)}
    </div>
    <div style="display:flex; gap:12px; flex-wrap:wrap; margin-top:16px;">
      <div class="tnum" style="flex:1; min-width:150px; text-align:center; background:var(--c-fs-soft); color:var(--c-fs); padding:12px; border-radius:10px; font-weight:700;">Gross Profit<br><span style="font-size:1rem;">${fmtINR(s.grossProfit)}</span><br><span style="font-size:0.72rem; font-weight:500;">${tCr - tDr === s.grossProfit ? "✓ Cr − Dr agrees" : "✗ mismatch"}</span></div>
      <div class="tnum" style="flex:1; min-width:150px; text-align:center; background:var(--c-fs-soft); color:var(--c-fs); padding:12px; border-radius:10px; font-weight:700;">Net Profit<br><span style="font-size:1rem;">${fmtINR(s.netProfit)}</span><br><span style="font-size:0.72rem; font-weight:500;">${pCr - pDr === s.netProfit ? "✓ Cr − Dr agrees" : "✗ mismatch"}</span></div>
      <div class="tnum" style="flex:1; min-width:150px; text-align:center; background:var(--c-fs-soft); color:var(--c-fs); padding:12px; border-radius:10px; font-weight:700;">Balance Sheet<br><span style="font-size:1rem;">${fmtINR(s.balanceTotal)}</span><br><span style="font-size:0.72rem; font-weight:500;">${liab === assets ? "✓ Liabilities = Assets" : "✗ does not tally"}</span></div>
    </div>
    <p style="font-size:0.83rem; line-height:1.7; color:var(--ink-soft); margin-top:14px;">Gross profit flows from the Trading A/c into the P&L A/c, net profit flows into the Balance Sheet, and every adjustment has been given both its effects — which is why the two sides agree at ${fmtINR(s.balanceTotal)}.</p>`;
}

function renderStatementBuilder(panel, data, m) {
  panel.appendChild(sectionTitle("Statement Builder 🏗️"));
  const hint = el("p", "", `${data.builderCases.length} complete questions. First place every Trial Balance head — and every adjustment's effect — in the statement it belongs to. Then reveal the full Trading A/c, P&L A/c and Balance Sheet built from the same figures and check that they tally.`);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const cases = data.builderCases;
  if (BUILDER_STATE.index >= cases.length) BUILDER_STATE.index = 0;
  const c = cases[BUILDER_STATE.index];
  const stateKey = `fsbuild-${c.id}`;
  if (!BUILDER_STATE.picks[stateKey]) BUILDER_STATE.picks[stateKey] = {};
  const picks = BUILDER_STATE.picks[stateKey];
  const drTotal = c.trialBalance.filter(t => t.side === "Dr").reduce((a, t) => a + t.amount, 0);
  const crTotal = c.trialBalance.filter(t => t.side === "Cr").reduce((a, t) => a + t.amount, 0);

  const topBar = el("div", "", "");
  topBar.style.cssText = "display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:14px;";
  topBar.innerHTML = `
    <p style="font-size:0.83rem; color:var(--ink-faint); margin:0;">Question ${BUILDER_STATE.index + 1} of ${cases.length}</p>
    <p style="font-size:0.83rem; color:var(--c-fs); margin:0; font-weight:600;">Score: ${BUILDER_STATE.score.correct}/${BUILDER_STATE.score.attempted}</p>
  `;
  panel.appendChild(topBar);

  const card = el("div", "card-solid q-card", "");
  card.style.cssText = "padding:26px;";
  card.innerHTML = `
    <div class="q-meta">
      <span class="diff-badge ${c.difficulty}">${c.difficulty}</span>
      <span class="q-id">Question ${c.id}</span>
      <span style="margin-left:auto; font-size:0.74rem; color:var(--ink-faint); text-transform:uppercase; letter-spacing:0.03em;">as on ${c.asOn}</span>
      ${bookmarkButtonHTML(stateKey)}
    </div>
    <div class="tnum" style="font-size:0.92rem; font-weight:600; color:var(--c-fs); background:var(--c-fs-soft); padding:12px; border-radius:10px; margin:14px 0;">${c.title}</div>

    <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(250px,1fr)); gap:18px; margin-bottom:16px;">
      <div>
        <h4 style="font-size:0.9rem; margin-bottom:8px; color:var(--c-fs);">Trial Balance</h4>
        <table style="width:100%; border-collapse:collapse; font-size:0.8rem;">
          <thead><tr style="border-bottom:1px solid var(--line);"><th style="text-align:left; padding:5px 4px;">Head</th><th style="text-align:right; padding:5px 4px;">Dr (₹)</th><th style="text-align:right; padding:5px 4px;">Cr (₹)</th></tr></thead>
          <tbody>
            ${c.trialBalance.map(t => `<tr style="border-bottom:1px solid var(--line);"><td style="padding:5px 4px;">${t.head}</td><td class="tnum" style="text-align:right; padding:5px 4px;">${t.side === "Dr" ? fmtINR(t.amount) : ""}</td><td class="tnum" style="text-align:right; padding:5px 4px;">${t.side === "Cr" ? fmtINR(t.amount) : ""}</td></tr>`).join("")}
          </tbody>
          <tfoot><tr style="border-top:2px solid var(--line); font-weight:700;"><td style="padding:7px 4px;">Total</td><td class="tnum" style="text-align:right; padding:7px 4px;">${fmtINR(drTotal)}</td><td class="tnum" style="text-align:right; padding:7px 4px;">${fmtINR(crTotal)}</td></tr></tfoot>
        </table>
        <p style="font-size:0.78rem; color:${drTotal === crTotal ? "var(--success)" : "var(--flag)"}; margin-top:6px;">${drTotal === crTotal ? "✓ The Trial Balance agrees" : "✗ Difference of " + fmtINR(Math.abs(drTotal - crTotal))}</p>
      </div>
      <div>
        <h4 style="font-size:0.9rem; margin-bottom:8px; color:var(--c-fs);">Additional Information</h4>
        <ol style="padding-left:18px;">${c.adjustments.map(a => `<li style="font-size:0.85rem; line-height:1.6; color:var(--ink-soft); margin-bottom:7px;">${a}</li>`).join("")}</ol>
        <p style="font-size:0.8rem; line-height:1.6; color:var(--ink-faint); margin-top:12px;">Each of these has TWO effects — one in the final accounts, one in the Balance Sheet. They appear as rows below.</p>
      </div>
    </div>

    <h4 style="font-size:0.9rem; margin:18px 0 10px; color:var(--c-fs);">Where does each item go?</h4>
    ${c.placements.map((p, i) => `
      <div class="builder-row" data-i="${i}" style="display:flex; align-items:flex-start; gap:12px; flex-wrap:wrap; padding:9px 0; border-bottom:1px solid var(--line);">
        <p style="flex:1 1 240px; font-size:0.86rem; line-height:1.55; margin:0;">${p.label}</p>
        <div class="opt-group" data-role="answer" data-i="${i}" style="display:flex; flex-wrap:wrap; gap:6px;">
          ${BUILDER_PLACEMENT_OPTS.map(o => `<button class="chip" data-val="${o[0]}" style="font-size:0.76rem;">${o[1]}</button>`).join("")}
        </div>
        <div class="builder-reveal" data-i="${i}" style="flex:1 1 100%;"></div>
      </div>`).join("")}

    <div class="q-actions" style="margin-top:18px; display:flex; gap:10px; flex-wrap:wrap;">
      <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Placements</button>
      <button class="btn-ghost sm ripple-surface" data-act="solution"><i data-lucide="table-2"></i> ${BUILDER_STATE.showSolution[stateKey] ? "Hide" : "Reveal"} Full Statements</button>
      ${aiAskBtn("fs.builderCases", c, { getPicks: () => c.placements.map((p, i) => picks[i] !== undefined ? { code: picks[i], label: (BUILDER_PLACEMENT_OPTS.find(o => o[0] === picks[i]) || ["", picks[i]])[1] } : null) })}
      <button class="btn-ghost sm ripple-surface" data-act="prev"><i data-lucide="arrow-left"></i> Previous</button>
      <button class="btn-ghost sm ripple-surface" data-act="next"><i data-lucide="arrow-right"></i> Next</button>
    </div>
    <div class="reveal-area"></div>
    <div class="solution-area"></div>
  `;
  const revealArea = $(".reveal-area", card);
  const solutionArea = $(".solution-area", card);

  const paintSolution = () => {
    solutionArea.innerHTML = BUILDER_STATE.showSolution[stateKey]
      ? `<div class="reveal-block" style="margin-top:16px;">${builderStatementHTML(c)}</div>`
      : "";
    icons();
  };
  paintSolution();

  card.addEventListener("click", (e) => {
    const optBtn = e.target.closest(".opt-group button[data-val]");
    if (optBtn) {
      const group = optBtn.closest(".opt-group");
      $all("button", group).forEach(b => b.classList.remove("active"));
      optBtn.classList.add("active");
      picks[group.dataset.i] = optBtn.dataset.val;
      return;
    }
    const bookmarkBtn = e.target.closest("button[data-act='bookmark']");
    if (bookmarkBtn) { toggleBookmark(stateKey, bookmarkBtn); return; }
    const prevBtn = e.target.closest("button[data-act='prev']");
    if (prevBtn) {
      BUILDER_STATE.index = (BUILDER_STATE.index - 1 + cases.length) % cases.length;
      panel.innerHTML = "";
      renderStatementBuilder(panel, data, m);
      return;
    }
    const nextBtn = e.target.closest("button[data-act='next']");
    if (nextBtn) {
      BUILDER_STATE.index = (BUILDER_STATE.index + 1) % cases.length;
      panel.innerHTML = "";
      renderStatementBuilder(panel, data, m);
      return;
    }
    const solBtn = e.target.closest("button[data-act='solution']");
    if (solBtn) {
      BUILDER_STATE.showSolution[stateKey] = !BUILDER_STATE.showSolution[stateKey];
      paintSolution();
      return;
    }
    const checkBtn = e.target.closest("button[data-act='check']");
    if (checkBtn) {
      if (c.placements.some((_, i) => picks[i] === undefined)) {
        revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Choose a statement for every item first.</p></div>`;
        return;
      }
      let correctCount = 0;
      c.placements.forEach((p, i) => {
        const ok = picks[i] === p.answer;
        if (ok) correctCount++;
        const target = $(`.builder-reveal[data-i="${i}"]`, card);
        const rightLabel = (BUILDER_PLACEMENT_OPTS.find(o => o[0] === p.answer) || ["", p.answer])[1];
        target.innerHTML = ok
          ? `<p style="font-size:0.8rem; line-height:1.6; color:var(--success); margin-top:5px;">✓ ${p.note}</p>`
          : `<p style="font-size:0.8rem; line-height:1.6; color:var(--flag); margin-top:5px;">✗ Goes to <b>${rightLabel}</b> — ${p.note}</p>`;
      });
      const allCorrect = correctCount === c.placements.length;
      revealArea.innerHTML = `
        <div class="reveal-block" style="${allCorrect ? "" : "background:var(--flag-soft); border-left-color:var(--flag);"} margin-top:16px;">
          <h4>${allCorrect ? "Every item placed correctly!" : `${correctCount} of ${c.placements.length} items placed correctly`}</h4>
          <p style="font-size:0.86rem; line-height:1.65; color:var(--ink-soft);">Gross Profit ${fmtINR(c.solution.grossProfit)} · Net Profit ${fmtINR(c.solution.netProfit)} · Balance Sheet ${fmtINR(c.solution.balanceTotal)} — reveal the full statements to see all three built up from these placements.</p>
        </div>`;
      if (allCorrect) playSuccessSound(); else playErrorSound();
      BUILDER_STATE.score.attempted++;
      if (allCorrect) BUILDER_STATE.score.correct++;
      const scoreEl = topBar.querySelectorAll("p")[1];
      if (scoreEl) scoreEl.textContent = `Score: ${BUILDER_STATE.score.correct}/${BUILDER_STATE.score.attempted}`;

      if (!STATE.solved[stateKey]) {
        STATE.solved[stateKey] = { correct: allCorrect, attempts: 1 };
        saveState();
        if (allCorrect) {
          addXP(6, `Statement Builder question ${c.id} solved`);
          logActivity({ type: "case", text: `Statement Builder question ${c.id} solved (${c.difficulty})`, route: "ch-fs", tab: "Statement Builder", qid: c.id, qidNoun: "Question", difficulty: c.difficulty, status: "solved" });
          mistakeBookRecordCorrect(stateKey);
        } else {
          if (!STATE.mistakes.includes(stateKey)) STATE.mistakes.push(stateKey);
          addXP(-XP_WRONG_PENALTY, `Statement Builder question ${c.id} incorrect`);
          mistakeBookRecord({
            key: stateKey,
            question: `Place every item of "${c.title}" (as on ${c.asOn}) in the statement it belongs to.`,
            chapter: "fs", chapterLabel: m.name, topic: "Statement Builder", type: "Statement Builder",
            studentAnswer: c.placements.map((p, i) => `${p.label} → ${p.answer}`).join(" | "),
            correctAnswer: c.placements.map(p => `${p.label} → ${p.answer}`).join(" | "),
            explanation: c.placements.map(p => p.note).join(" ")
          });
        }
        refreshProgress();
      }
      if (allCorrect && !BUILDER_STATE.showSolution[stateKey]) {
        BUILDER_STATE.showSolution[stateKey] = true;
        paintSolution();
      }
      icons();
    }
  });
  panel.appendChild(card);
  icons();
}

/* ---- the four chapter routes ---- */
function renderPresChapter(root) {
  renderNewChapterShell(root, "pres",
    ["Introduction", "Mind Map", "Format & Rules", "Decision Lab", "Practice Bank", "Quick Revision"],
    (name, panel, data, m) => {
      if (name === "Introduction") renderChNewIntro(panel, data, m);
      else if (name === "Mind Map") renderMindMap(panel, "pres");
      else if (name === "Format & Rules") renderChNewAdvanced(panel, data, m, "Provisions, reserves & how each is treated");
      else if (name === "Decision Lab") renderDecisionLab(panel, data, m);
      else if (name === "Practice Bank") renderChNewPracticeBank(panel, data, m, "pres");
      else if (name === "Quick Revision") renderChNewQuickRevision(panel, data, m);
    });
}

function renderRoeChapter(root) {
  renderNewChapterShell(root, "roe",
    ["Introduction", "Mind Map", "Format & Rules", "Error Detective", "Practice Bank", "Quick Revision"],
    (name, panel, data, m) => {
      if (name === "Introduction") renderChNewIntro(panel, data, m);
      else if (name === "Mind Map") renderMindMap(panel, "roe");
      else if (name === "Format & Rules") renderChNewAdvanced(panel, data, m, "Suspense A/c, rectification & staged correction");
      else if (name === "Error Detective") renderErrorDetective(panel, data, m);
      else if (name === "Practice Bank") renderChNewPracticeBank(panel, data, m, "roe");
      else if (name === "Quick Revision") renderChNewQuickRevision(panel, data, m);
    });
}

function renderFsChapter(root) {
  renderNewChapterShell(root, "fs",
    ["Introduction", "Mind Map", "Format & Rules", "Statement Builder", "Practice Bank", "Quick Revision"],
    (name, panel, data, m) => {
      if (name === "Introduction") renderChNewIntro(panel, data, m);
      else if (name === "Mind Map") renderMindMap(panel, "fs");
      else if (name === "Format & Rules") renderChNewAdvanced(panel, data, m, "Formats, classification & closing entries");
      else if (name === "Statement Builder") renderStatementBuilder(panel, data, m);
      else if (name === "Practice Bank") renderChNewPracticeBank(panel, data, m, "fs");
      else if (name === "Quick Revision") renderChNewQuickRevision(panel, data, m);
    });
}

function renderAdjChapter(root) {
  renderNewChapterShell(root, "adj",
    ["Introduction", "Mind Map", "Format & Rules", "Adjustment Studio", "Practice Bank", "Quick Revision"],
    (name, panel, data, m) => {
      if (name === "Introduction") renderChNewIntro(panel, data, m);
      else if (name === "Mind Map") renderMindMap(panel, "adj");
      else if (name === "Format & Rules") renderChNewAdvanced(panel, data, m, "Every adjustment, both effects");
      else if (name === "Adjustment Studio") renderAdjustmentStudio(panel, data, m);
      else if (name === "Practice Bank") renderChNewPracticeBank(panel, data, m, "adj");
      else if (name === "Quick Revision") renderChNewQuickRevision(panel, data, m);
    });
}

/* ---------------------------------------------------------
   6e. SHARED THEORY / CONCEPTS RENDERER (used by Ch.2 & Ch.3)
   --------------------------------------------------------- */
function renderGenericTheory(panel, data, chId) {
  /* v92 Part 2 — delegates to the ONE shared theory renderer (reading
     design + chapter chrome); the old duplicated grid-2 loop is gone. */
  const accent = chId === "dc" ? "var(--c-dc)" : "var(--c-jr)";
  const soft = chId === "dc" ? "var(--c-dc-soft)" : "var(--c-jr-soft)";
  panel.appendChild(sectionTitle("Simple explanation"));
  renderCashBookTheoryBlocks(panel, data.theory.simple, accent, soft);
  panel.appendChild(sectionTitle("Detailed explanation"));
  renderCashBookTheoryBlocks(panel, data.theory.advanced, accent, soft);
}

function renderGenericConcepts(panel, data, chId) {
  const accent = chId === "dc" ? "var(--c-dc)" : "var(--c-jr)";
  panel.appendChild(sectionTitle("Key concepts"));
  const grid = el("div", "grid-3");
  data.concepts.forEach(c => {
    const card = el("div", "card liftable", "");
    card.style.padding = "22px";
    card.innerHTML = `<h4 style="font-size:1rem; margin-bottom:8px; color:${accent};">${c.title}</h4><p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${c.body}</p>`;
    grid.appendChild(card);
  });
  panel.appendChild(grid);
}

/* ---------------------------------------------------------
   6e. FLASHCARDS — flip cards across all three chapters
   --------------------------------------------------------- */
let flashState = { chapter: "all", deck: [], index: 0, flipped: false, knownCount: 0, activityLogged: false };

/* Chapter filter list — also the source for the deep-link labels
   (?ch=intro from a Recent Activity row) and activity titles. */
/* Chapter labels for the Flashcards / Important Questions pickers.
   v83: derived from the ACTIVE class — Class 11 keeps its exact
   original labels, Class 12 builds "Ch.n <short>" from the registry. */
const FLASH_CHAPTERS_C11 = [["all","All Chapters"],["intro","Ch.1 Introduction"],["terms","Ch.2 Basic Terms"],["tbase","Ch.3 Theory Base"],["basis","Ch.4 Bases"],["eq","Ch.5 Equation"],["dc","Ch.6 Debit & Credit"],["jr","Ch.7 Journal"],["lg","Ch.8 Ledger"],["cb","Ch.9 Cash Book"],["sp2","Ch.10 Other Books"],["brs","Ch.11 BRS"],["gst","Ch.12 GST"],["tb","Ch.13 Trial Balance"],["dep","Ch.14 Depreciation"],["pres","Ch.15 Provisions & Reserves"],["roe","Ch.16 Rectification"],["fs","Ch.17 Financial Statements"],["adj","Ch.18 Adjustments"]];
function flashChapterRows() {
  if (activeClass() === ClassRegistry.CLASS_12) {
    return [["all", "All Chapters"]].concat(
      ClassRegistry.chaptersOf("12").map(c => [c.id, "Ch." + c.num + " " + (c.short || c.name)])
    );
  }
  return FLASH_CHAPTERS_C11;
}
let FLASH_CHAPTERS = FLASH_CHAPTERS_C11;
let FLASH_CH_LABEL = Object.fromEntries(FLASH_CHAPTERS);
function refreshFlashChapterLabels() {
  FLASH_CHAPTERS = flashChapterRows();
  FLASH_CH_LABEL = Object.fromEntries(FLASH_CHAPTERS);
}
refreshFlashChapterLabels();

function renderFlashcards(root) {
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Practice</span>
    <h1>Flashcards</h1>
    <p>Tap the card — or press Enter / Space — to flip it, then mark whether you knew it. Filter by chapter to focus your drilling.</p>
  `));

  /* Deep link: #flashcards?ch=jr (from a Recent Activity row) preselects
     the chapter; unknown values fall back to All Chapters. */
  try {
    const q = new URLSearchParams(routeQueryString || "");
    const chParam = q.get("ch");
    if (chParam && FLASH_CH_LABEL[chParam]) flashState.chapter = chParam;
  } catch (e) { /* no query or unparsable — keep current filter */ }

  /* ---- Chapter dropdown (v86) — replaces the old chip scroller.
     19 chips pushed the card off-screen and made the deck's own
     controls unreachable, so the filter is now a native <select>
     reusing the Important Questions picker (same markup, same
     styles, same UIF.buildIQChapterOptions option builder). The
     chapter labels and the "All Chapters" total come from the same
     FLASH_CHAPTERS rows the site has always used, so the menu can
     never drift from the content. ---- */
  const fcRows = flashChapterRows().filter(row => row[0] !== "all");
  const fcCounts = {};
  fcRows.forEach(([id]) => {
    fcCounts[id] = APP_DATA.flashcards.filter(c => c.chapter === id).length;
  });
  const fcOptions = UIF.buildIQChapterOptions(
    fcRows.map(([id, label]) => ({ id: id, name: label })),
    fcCounts,
    c => c.name
  );
  const picker = el("div", "iq-picker", "");
  picker.innerHTML = `
    <label class="iq-picker-label" for="flashChapterSelect">Choose a chapter</label>
    <div class="iq-select-wrap">
      <select id="flashChapterSelect" class="iq-select" aria-describedby="flashPickerHint">
        ${fcOptions.map(o =>
          `<option value="${o.value}"${o.value === flashState.chapter ? " selected" : ""}>${o.label}${o.count ? ` (${o.count})` : " — no cards yet"}</option>`).join("")}
      </select>
      <i data-lucide="chevron-down" class="iq-select-chevron" aria-hidden="true"></i>
    </div>
    <p class="iq-picker-hint" id="flashPickerHint"></p>`;
  root.appendChild(picker);

  const area = el("div", "");
  root.appendChild(area);

  const fcSelect = $("#flashChapterSelect", picker);
  const fcHint = $("#flashPickerHint", picker);
  const syncFlashHint = () => {
    const opt = fcSelect.options[fcSelect.selectedIndex];
    const selectedLabel = opt ? opt.textContent.replace(/\s*\(.*\)$/, "").replace(/\s*—.*$/, "") : "All Chapters";
    fcHint.textContent = flashState.chapter === "all"
      ? `Drilling cards from all ${fcRows.length} chapters (${fcOptions[0].count} in total).`
      : `Drilling the ${selectedLabel} deck.`;
  };
  fcSelect.addEventListener("change", () => {
    flashState.chapter = fcSelect.value;   // selection and deck always in step
    syncFlashHint();
    startFlashDeck();
    renderFlashArea(area);
  });
  syncFlashHint();

  startFlashDeck();
  renderFlashArea(area);
}

function startFlashDeck() {
  const activeIds = activeChapterIds();
  const pool = APP_DATA.flashcards.filter(c => activeIds.indexOf(c.chapter) !== -1 &&
    (flashState.chapter === "all" || c.chapter === flashState.chapter));
  flashState.deck = fisherYatesShuffle(pool);
  flashState.index = 0;
  flashState.flipped = false;
  flashState.knownCount = 0;
  flashState.xpAwarded = false;
  flashState.activityLogged = false;
  flashState.history = [];   // stack of "known" | "learning" per completed card, so Back can undo correctly
}

function renderFlashArea(area) {
  const deck = flashState.deck;
  if (!deck.length) {
    flashDom = null;
    area.innerHTML = `<p style="color:var(--ink-faint);">No cards in this set.</p>`;
    return;
  }
  if (flashState.index >= deck.length) {
    /* ---- Deck completion: one activity row per run, and the XP bonus
       claimed through the daily gate — replaying a deck never re-pays
       (today), and a closed gate shows no reward toast at all. ---- */
    flashDom = null;
    let xpNote = "";
    if (!flashState.xpAwarded) {
      flashState.xpAwarded = true;
      const gateKey = "flash-deck|" + flashState.chapter;
      if (flashState.knownCount > 0) {
        const got = awardXPDaily(gateKey, Math.min(20, flashState.knownCount), "Flashcard deck completed");
        if (!got) xpNote = "Today's flashcard bonus for this set is already earned — replaying is still good practice.";
      }
    }
    if (!flashState.activityLogged) {
      flashState.activityLogged = true;
      const setLabel = flashState.chapter === "all" ? "All-chapters" : FLASH_CH_LABEL[flashState.chapter];
      logActivity({
        type: "flashcards", key: "flash-deck|" + flashState.chapter,
        text: `${setLabel} flashcard deck completed — ${flashState.knownCount} of ${deck.length} known`,
        route: "flashcards", status: "completed",
        chapterId: flashState.chapter === "all" ? null : flashState.chapter
      });
    }
    area.innerHTML = `
      <div class="card-solid" style="padding:40px; text-align:center;">
        <i data-lucide="party-popper" style="width:32px;height:32px;color:var(--gold);"></i>
        <h3 style="margin:12px 0 6px;">Deck complete</h3>
        <p style="color:var(--ink-soft); font-size:0.9rem; margin-bottom:${xpNote ? "8px" : "18px"};">You marked ${flashState.knownCount} of ${deck.length} as known.</p>
        ${xpNote ? `<p class="xp-note" style="color:var(--ink-faint); font-size:0.82rem; margin-bottom:16px;">${xpNote}</p>` : ""}
        <button class="btn-primary ripple-surface" id="flashRestart"><i data-lucide="rotate-ccw"></i> Restart deck</button>
      </div>`;
    icons();
    $("#flashRestart").addEventListener("click", () => { startFlashDeck(); renderFlashArea(area); });
    return;
  }

  /* ---- v86: the deck's DOM is built ONCE per visit and then only
     patched. The old version rebuilt `area.innerHTML` for every card,
     which re-created (and re-parsed) the whole card, re-ran lucide
     and re-bound the handlers on each Next/Previous — slow on long
     decks and the reason the card could not be scrolled to once its
     text grew. Now the card element persists and only its text, the
     counters and the flip class change. The flip itself is untouched:
     flip() still toggles `is-flipped` on the SAME element, so the CSS
     rotateY transition plays exactly as before. ---- */
  if (!flashDom || flashDom.area !== area || !area.contains(flashDom.cardEl)) {
    buildFlashDeckDom(area);
  }
  paintFlashCard(deck[flashState.index]);
}

/* The persistent card scaffold: created once, patched per card. */
let flashDom = null;

function buildFlashDeckDom(area) {
  area.innerHTML = `
    <div class="flash-meta" style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; font-size:0.83rem; color:var(--ink-faint);">
      <span id="flashCounter"></span>
      <span id="flashChLabel" style="font-weight:600;"></span>
    </div>
    <div class="flashcard-wrap">
      <div class="flashcard" id="flashCardEl"
           role="button" tabindex="0" aria-pressed="false" aria-label="">
        <div class="flashcard-face flashcard-front" aria-hidden="false"><p class="flash-text"></p><span class="flash-hint">Tap or press Enter to flip</span></div>
        <div class="flashcard-face flashcard-back" aria-hidden="true"><p class="flash-text"></p><span class="flash-hint">Tap to flip back</span></div>
      </div>
    </div>
    <div class="flash-controls" style="display:flex; gap:10px; justify-content:center; margin-top:20px; flex-wrap:wrap;">
      <button class="btn-ghost ripple-surface" id="flashBackBtn"><i data-lucide="arrow-left"></i> Previous</button>
      <button class="btn-ghost ripple-surface" id="flashDontKnow"><i data-lucide="rotate-ccw"></i> Still learning</button>
      <button class="btn-primary ripple-surface" id="flashKnow"><i data-lucide="check"></i> I knew this</button>
    </div>`;
  icons();

  const cardEl = $("#flashCardEl", area);
  const front = cardEl.querySelector(".flashcard-front");
  const back = cardEl.querySelector(".flashcard-back");
  const backBtn = $("#flashBackBtn", area);
  const knowBtn = $("#flashKnow", area);
  const dontBtn = $("#flashDontKnow", area);

  /* FLIP: toggle the is-flipped class on the EXISTING element — the
     card is never re-rendered on flip, so the CSS 3D transition
     actually plays (front face rotates away, back face rotates in,
     both with backface-visibility hidden so nothing shows through).
     Mouse click, touch tap and keyboard (Enter/Space) all go through
     the same flip(), and aria-pressed/aria-label/aria-hidden stay in
     step with the visible face. Handlers are bound once and live as
     long as the element does. */
  const flip = () => {
    flashState.flipped = !flashState.flipped;
    cardEl.classList.toggle("is-flipped", flashState.flipped);
    cardEl.setAttribute("aria-pressed", flashState.flipped ? "true" : "false");
    cardEl.setAttribute("aria-label", flashAriaLabel());
    front.setAttribute("aria-hidden", flashState.flipped ? "true" : "false");
    back.setAttribute("aria-hidden", flashState.flipped ? "false" : "true");
  };
  cardEl.addEventListener("click", flip);
  cardEl.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") { e.preventDefault(); flip(); }
  });
  knowBtn.addEventListener("click", (e) => {
    e.stopPropagation(); playSuccessSound();
    flashState.knownCount++; flashState.history.push("known");
    flashState.index++; flashState.flipped = false; renderFlashArea(area);
  });
  dontBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    flashState.history.push("learning");
    flashState.index++; flashState.flipped = false; renderFlashArea(area);
  });
  backBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    if (flashState.index === 0) return;
    const last = flashState.history.pop();
    if (last === "known") flashState.knownCount = Math.max(0, flashState.knownCount - 1);
    flashState.index--; flashState.flipped = false; renderFlashArea(area);
  });

  flashDom = {
    area: area, cardEl: cardEl, front: front, back: back,
    counter: $("#flashCounter", area), chLabel: $("#flashChLabel", area),
    backBtn: backBtn
  };
}

function flashAriaLabel() {
  const deck = flashState.deck;
  return `Flashcard ${flashState.index + 1} of ${deck.length}. ${flashState.flipped ? "Answer side" : "Question side"} showing. Press Enter or Space to flip.`;
}

/* Chapter badge for the card — Class 12 chapters resolve through the
   registry, the original Class 11 table stays byte-identical. */
const FLASH_CH_BADGE_C11 = { intro: "Ch.1 Introduction", terms: "Ch.2 Basic Terms", tbase: "Ch.3 Theory Base", basis: "Ch.4 Bases", eq: "Ch.5 Equation", dc: "Ch.6 Debit & Credit", jr: "Ch.7 Journal", lg: "Ch.8 Ledger", cb: "Ch.9 Cash Book", sp2: "Ch.10 Other Books", brs: "Ch.11 BRS", gst: "Ch.12 GST", tb: "Ch.13 Trial Balance", dep: "Ch.14 Depreciation", pres: "Ch.15 Provisions & Reserves", roe: "Ch.16 Rectification", fs: "Ch.17 Financial Statements", adj: "Ch.18 Adjustments" };
function flashChapterBadge(chId) {
  if (FLASH_CH_BADGE_C11[chId]) return { label: FLASH_CH_BADGE_C11[chId], color: "var(--c-" + chId + ")" };
  const reg = ClassRegistry.chaptersOf("12").filter(c => c.id === chId)[0];
  if (reg) return { label: "Ch." + reg.num + " " + (reg.short || reg.name), color: reg.color };
  return { label: chId, color: "var(--ink-faint)" };
}

function paintFlashCard(card) {
  const deck = flashState.deck;
  const badge = flashChapterBadge(card.chapter);
  flashDom.counter.textContent = `Card ${flashState.index + 1} of ${deck.length}`;
  flashDom.chLabel.textContent = badge.label;
  flashDom.chLabel.style.color = badge.color;
  flashDom.front.querySelector(".flash-text").innerHTML = card.front;
  flashDom.back.querySelector(".flash-text").innerHTML = card.back;
  flashDom.backBtn.disabled = flashState.index === 0;

  /* Apply the flip state WITHOUT a transition: the face has just been
     rewritten, so an animated swing here would look like the new card
     arrived already turning. flip() — the user-driven path — keeps the
     transition untouched. */
  const cardEl = flashDom.cardEl;
  cardEl.style.transition = "none";
  cardEl.classList.toggle("is-flipped", flashState.flipped);
  void cardEl.offsetWidth;               // force the no-transition frame
  cardEl.style.transition = "";
  cardEl.setAttribute("aria-pressed", flashState.flipped ? "true" : "false");
  cardEl.setAttribute("aria-label", flashAriaLabel());
  flashDom.front.setAttribute("aria-hidden", flashState.flipped ? "true" : "false");
  flashDom.back.setAttribute("aria-hidden", flashState.flipped ? "false" : "true");
}

/* ---------------------------------------------------------
   6f. QUIZ — MCQ engine across all three chapters
   --------------------------------------------------------- */
let quizState = { chapters: ["all"], difficulty: "all", pool: [], index: 0, score: 0, answered: false, selected: null, answers: [] };
/* v83 — quiz chapter picker rows follow the ACTIVE class (Class 11
   keeps its exact original labels). */
const QUIZ_CHAPTER_LIST_C11 = [["intro","Introduction"],["terms","Basic Terms"],["tbase","Theory Base"],["basis","Bases of Accounting"],["eq","Accounting Equation"],["dc","Debit & Credit"],["jr","Journal"],["lg","Ledger"],["cb","Cash Book"],["sp2","Other Books"],["brs","BRS"],["gst","GST"],["tb","Trial Balance"],["dep","Depreciation"],["pres","Provisions & Reserves"],["roe","Rectification of Errors"],["fs","Financial Statements"],["adj","Adjustments"]];
let QUIZ_CHAPTER_LIST = QUIZ_CHAPTER_LIST_C11;
let QUIZ_CHAPTER_LABEL = Object.fromEntries(QUIZ_CHAPTER_LIST.map(([id, label]) => [id, label]));
function refreshQuizChapterLabels() {
  if (activeClass() === ClassRegistry.CLASS_12) {
    QUIZ_CHAPTER_LIST = ClassRegistry.chaptersOf("12").map(c => [c.id, c.short || c.name]);
  } else {
    QUIZ_CHAPTER_LIST = QUIZ_CHAPTER_LIST_C11;
  }
  QUIZ_CHAPTER_LABEL = Object.fromEntries(QUIZ_CHAPTER_LIST.map(([id, label]) => [id, label]));
}
refreshQuizChapterLabels();
const QUIZ_DIFFICULTIES = ["All", "Easy", "Medium", "Hard"];

/* Genuine Fisher–Yates shuffle — unlike Array.sort(() => Math.random()-0.5),
   this gives every permutation equal probability. Used for both question
   order and (below) each question's own option order, so the correct
   answer is never biased toward any one position. */
function fisherYatesShuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/* BUG FIX: quiz/exam options used to be shown in the exact order stored
   in data.js, where the correct answer happened to sit at index 1
   ("B") far more often than any other position — so the visible
   pattern looked hard-coded even though it wasn't intentional. This
   independently reshuffles ONE question's options (and remaps
   answerIndex to match) every time it's called, so the correct
   option lands in a genuinely random position on every attempt,
   without ever changing which option text is actually correct. */
function shuffleQuizOptions(q) {
  const order = fisherYatesShuffle(q.options.map((_, i) => i));
  return {
    ...q,
    options: order.map(i => q.options[i]),
    answerIndex: order.indexOf(q.answerIndex)
  };
}

function renderQuiz(root) {
  /* v83 — the chapter-count word follows the ACTIVE class (18 → "eighteen",
     13 → "thirteen"); Class 11 output stays byte-identical to v82. */
  const quizScope = { 18: "eighteen", 13: "thirteen" }[activeChapters().length] || String(activeChapters().length);
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Practice</span>
    <h1>Quiz</h1>
    <p>Multiple-choice questions drawing on all ${quizScope} chapters, with instant feedback and a running score.</p>
  `));

  root.appendChild(buildQuizFilterBar());

  const area = el("div", "");
  root.appendChild(area);
  startQuiz();
  renderQuizArea(area);
}

/* Custom chapter multi-select + difficulty filter for the Quiz. Deliberately not a native    <select> — a button opens a checkbox panel (search box included since 18 chapters is enough
   to want one), selected chapters render as removable chips, and a chip row handles difficulty.
   Both filters share one small piece of state (quizState.chapters / quizState.difficulty) and
   restart the quiz through the existing startQuiz()/renderQuizArea() pipeline — no second
   question store, no separate scoring path. */
function buildQuizFilterBar() {
  const wrap = el("div", "quiz-filters", "");
  wrap.innerHTML = `
    <div class="quiz-filter-row">
      <div class="qc-picker" id="qcPicker">
        <button type="button" class="qc-picker-btn" id="qcPickerBtn" aria-haspopup="true" aria-expanded="false">
          <i data-lucide="book-open" style="width:15px;height:15px;"></i>
          <span id="qcPickerLabel">All Chapters</span>
          <i data-lucide="chevron-down" class="qc-caret" style="width:15px;height:15px;"></i>
        </button>
        <div class="qc-panel" id="qcPanel" role="listbox" aria-multiselectable="true" hidden>
          <div class="qc-panel-search">
            <i data-lucide="search" style="width:14px;height:14px;"></i>
            <input type="text" id="qcSearch" placeholder="Search chapters…" autocomplete="off">
          </div>
          <div class="qc-panel-list" id="qcPanelList"></div>
          <div class="qc-panel-footer">
            <button type="button" class="qc-clear" id="qcClear">Clear selection</button>
            <button type="button" class="qc-done" id="qcDone">Done</button>
          </div>
        </div>
      </div>
      <div class="qc-chips" id="qcChips"></div>
    </div>
    <div class="quiz-filter-row">
      <span class="quiz-filter-label">Difficulty</span>
      <div class="qd-chips" id="qdChips">
        ${QUIZ_DIFFICULTIES.map(d => `<button type="button" class="chip qd-chip ${(/^all$/i.test(d) ? "all" : d) === quizState.difficulty ? "active" : ""}" data-diff="${d === "All" ? "all" : d}">${d}</button>`).join("")}
      </div>
    </div>
  `;

  const btn = $("#qcPickerBtn", wrap), panel = $("#qcPanel", wrap), list = $("#qcPanelList", wrap), search = $("#qcSearch", wrap), chipsBox = $("#qcChips", wrap), label = $("#qcPickerLabel", wrap);

  function renderPanelList(filterText) {
    const q = (filterText || "").trim().toLowerCase();
    const rows = QUIZ_CHAPTER_LIST.filter(([, lbl]) => !q || lbl.toLowerCase().includes(q));
    const allRow = `<label class="qc-row qc-row-all"><input type="checkbox" data-ch="all" ${quizState.chapters.includes("all") ? "checked" : ""}><span>All Chapters</span></label>`;
    const chRows = rows.map(([id, lbl]) => `<label class="qc-row"><input type="checkbox" data-ch="${id}" ${quizState.chapters.includes(id) ? "checked" : ""}><span>${lbl}</span></label>`).join("");
    list.innerHTML = (q ? "" : allRow) + (chRows || `<p class="qc-empty">No chapters match "${escapeHtml(filterText)}".</p>`);
  }
  function syncLabelAndChips() {
    const n = quizState.chapters.includes("all") ? 0 : quizState.chapters.length;
    label.textContent = n === 0 ? "All Chapters" : n === 1 ? QUIZ_CHAPTER_LABEL[quizState.chapters[0]] : `${n} chapters selected`;
    chipsBox.innerHTML = quizState.chapters.includes("all") ? "" : quizState.chapters.map(id => `<span class="qc-tag" data-ch="${id}">${QUIZ_CHAPTER_LABEL[id]} <i data-lucide="x" style="width:11px;height:11px;"></i></span>`).join("");
    icons();
  }
  // The question area is always the sibling immediately after the filter bar in renderQuiz's DOM.
  function restart() { const area = wrap.nextElementSibling; startQuiz(); if (area) renderQuizArea(area); }

  function toggleChapter(id, checked) {
    if (id === "all") { quizState.chapters = ["all"]; }
    else {
      quizState.chapters = quizState.chapters.filter(x => x !== "all");
      if (checked) { if (!quizState.chapters.includes(id)) quizState.chapters.push(id); }
      else quizState.chapters = quizState.chapters.filter(x => x !== id);
      if (!quizState.chapters.length) quizState.chapters = ["all"];
    }
    syncLabelAndChips();
    renderPanelList(search.value);
    restart();
  }

  function openPanel() {
    panel.hidden = false; btn.setAttribute("aria-expanded", "true"); wrap.querySelector(".qc-picker").classList.add("open");
    renderPanelList(""); search.value = ""; icons();
    requestAnimationFrame(() => search.focus());
    document.addEventListener("mousedown", onOutside, true);
    document.addEventListener("keydown", onEscape, true);
  }
  function closePanel() {
    panel.hidden = true; btn.setAttribute("aria-expanded", "false"); wrap.querySelector(".qc-picker").classList.remove("open");
    document.removeEventListener("mousedown", onOutside, true);
    document.removeEventListener("keydown", onEscape, true);
  }
  function onOutside(e) { if (!wrap.contains(e.target)) closePanel(); }
  function onEscape(e) { if (e.key === "Escape") { closePanel(); btn.focus(); } }

  btn.addEventListener("click", () => { panel.hidden ? openPanel() : closePanel(); });
  $("#qcDone", wrap).addEventListener("click", closePanel);
  $("#qcClear", wrap).addEventListener("click", () => { quizState.chapters = ["all"]; syncLabelAndChips(); renderPanelList(search.value); restart(); });
  search.addEventListener("input", () => renderPanelList(search.value));
  list.addEventListener("change", (e) => { const cb = e.target.closest("input[type=checkbox]"); if (cb) toggleChapter(cb.dataset.ch, cb.checked); });
  chipsBox.addEventListener("click", (e) => { const tag = e.target.closest(".qc-tag"); if (tag) toggleChapter(tag.dataset.ch, false); });
  $("#qdChips", wrap).addEventListener("click", (e) => {
    const chip = e.target.closest("[data-diff]"); if (!chip) return;
    quizState.difficulty = chip.dataset.diff;
    $all("[data-diff]", wrap).forEach(b => b.classList.toggle("active", b === chip));
    restart();
  });

  syncLabelAndChips();
  return wrap;
}

function quizQuestionMatchesFilters(q) {
  /* v83 — the merged quiz bank holds both classes; the chapter id on
     every question says which class it belongs to, so "All Chapters"
     means all chapters of the ACTIVE class only. */
  const classOk = ClassRegistry.classOfChapterId(q.chapter) === activeClass();
  const chOk = quizState.chapters.includes("all") || quizState.chapters.includes(q.chapter);
  const diffOk = quizState.difficulty === "all" || (q.difficulty || "Medium") === quizState.difficulty;
  return classOk && chOk && diffOk;
}

function startQuiz() {
  const pool = APP_DATA.quiz.filter(quizQuestionMatchesFilters);
  quizState.pool = fisherYatesShuffle(pool).map(shuffleQuizOptions);
  quizState.index = 0; quizState.score = 0; quizState.answered = false; quizState.selected = null;
  quizState.answers = new Array(quizState.pool.length).fill(null); // each slot: null (unanswered) or the selected option index
  quizState.xpAwarded = false;
  quizState.completionSoundPlayed = false;
}

/* Recompute score from the answers array — the single source of truth,
   so navigating back and forth (and possibly changing an answer's
   underlying question via re-filter) never double-counts or drifts. */
function recomputeQuizScore() {
  quizState.score = quizState.pool.reduce((sum, q, i) => {
    return sum + (quizState.answers[i] !== null && quizState.answers[i] === q.answerIndex ? 1 : 0);
  }, 0);
}

function renderQuizArea(area) {
  const pool = quizState.pool;
  if (!pool.length) {
    area.innerHTML = `<div class="card-solid" style="padding:32px; text-align:center;">
      <i data-lucide="search-x" style="width:26px;height:26px;color:var(--ink-faint);"></i>
      <p style="margin:12px 0 0; color:var(--ink-soft); font-size:0.92rem;">No questions available for this chapter/difficulty combination.</p>
      <p style="margin:6px 0 0; color:var(--ink-faint); font-size:0.82rem;">Try a different chapter selection or difficulty.</p>
    </div>`;
    icons();
    return;
  }
  if (quizState.index >= pool.length) {
    const pct = Math.round((quizState.score / pool.length) * 100);
    /* Completion reward: score × 2, claimed through the DAILY gate for
       this quiz configuration — re-running the same set today (or
       farming it across a session) never pays twice. A 0-score run
       claims nothing, and when the gate is closed the card says so
       instead of pretending a reward happened. */
    let quizNote = "";
    if (!quizState.xpAwarded) {
      quizState.xpAwarded = true;
      const cfgKey = UIF.quizConfigKey(quizState.chapters, quizState.difficulty);
      if (quizState.score > 0) {
        const got = awardXPDaily("quiz|" + cfgKey, quizState.score * 2, "Quiz answers correct");
        if (!got) quizNote = "Today's bonus for this quiz is already earned — replays are still good practice.";
      }
      logActivity({
        type: "quiz", key: "quiz|" + cfgKey,
        text: `Completed a quiz — ${quizState.score} of ${pool.length} correct (${pct}%)`,
        route: "quiz", status: pct >= 70 ? "passed" : "completed"
      });
    }
    area.innerHTML = `
      <div class="card-solid" style="padding:40px; text-align:center;">
        <i data-lucide="trophy" style="width:32px;height:32px;color:var(--gold);"></i>
        <h3 style="margin:12px 0 6px;">Quiz complete</h3>
        <p style="color:var(--ink-soft); font-size:0.9rem; margin-bottom:${quizNote ? "8px" : "18px"};">You scored ${quizState.score} out of ${pool.length} (${pct}%).</p>
        ${quizNote ? `<p class="xp-note" style="color:var(--ink-faint); font-size:0.82rem; margin-bottom:16px;">${quizNote}</p>` : ""}
        <div style="display:flex; gap:10px; justify-content:center; flex-wrap:wrap;">
          <button class="btn-ghost ripple-surface" id="quizReview"><i data-lucide="arrow-left"></i> Review answers</button>
          <button class="btn-primary ripple-surface" id="quizRestart"><i data-lucide="rotate-ccw"></i> Try again</button>
        </div>
      </div>`;
    icons();
    $("#quizRestart").addEventListener("click", () => { startQuiz(); renderQuizArea(area); });
    $("#quizReview").addEventListener("click", () => { quizState.index = pool.length - 1; renderQuizArea(area); });
    if (!quizState.completionSoundPlayed) {
      quizState.completionSoundPlayed = true;
      if (pct >= 70) launchConfetti();
      playCompletionSound();
    }
    STATE.bestScores.quiz = Math.max(STATE.bestScores.quiz || 0, pct);
    saveState();
    return;
  }
  const q = pool[quizState.index];
  const priorAnswer = quizState.answers[quizState.index];   // null if not yet answered, else the chosen option index
  const chColor = { intro: "var(--c-intro)", terms: "var(--c-terms)", tbase: "var(--c-tbase)", basis: "var(--c-basis)", eq: "var(--c-eq)", dc: "var(--c-dc)", jr: "var(--c-jr)", lg: "var(--c-lg)", cb: "var(--c-cb)", sp2: "var(--c-sp2)", brs: "var(--c-brs)", gst: "var(--c-gst)", tb: "var(--c-tb)", dep: "var(--c-dep)", pres: "var(--c-pres)", roe: "var(--c-roe)", fs: "var(--c-fs)", adj: "var(--c-adj)" }[q.chapter];
  area.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; font-size:0.83rem; color:var(--ink-faint);">
      <span>Question ${quizState.index + 1} of ${pool.length}</span>
      <span class="tnum">Score: <b>${quizState.score}</b></span>
    </div>
    <div class="card-solid" style="padding:26px;">
      <span class="diff-badge ${q.difficulty}" style="margin-bottom:10px; display:inline-block;">${q.difficulty}</span>
      <span style="float:right;">${aiAskBtn("quiz", q)}</span>
      <h3 style="font-size:1.02rem; margin-bottom:18px; line-height:1.5;">${q.q}</h3>
      <div id="quizOptions"></div>
      <div id="quizFeedback" style="margin-top:14px;"></div>
      <div style="display:flex; justify-content:space-between; margin-top:16px; gap:10px;">
        <button class="btn-ghost ripple-surface" id="quizPrevBtn" ${quizState.index === 0 ? "disabled" : ""}><i data-lucide="arrow-left"></i> Previous</button>
        <button class="btn-primary ripple-surface" id="quizNextBtn" ${priorAnswer === null ? "hidden" : ""}>${quizState.index === pool.length - 1 ? "Finish" : "Next question"} <i data-lucide="arrow-right"></i></button>
      </div>
    </div>
  `;
  const optWrap = $("#quizOptions");

  function showFeedbackFor(selectedIndex) {
    const correct = selectedIndex === q.answerIndex;
    $all("#quizOptions .chip").forEach((el2, idx) => {
      el2.disabled = true;
      if (idx === q.answerIndex) {
        el2.classList.add("is-correct");
        if (idx === selectedIndex && !STATE.reduceMotion) el2.classList.add("fb-correct");
      }
      else if (idx === selectedIndex) {
        el2.classList.add("is-wrong");
        if (!STATE.reduceMotion) el2.classList.add("fb-wrong");
      }
    });
    $("#quizFeedback").innerHTML = `<div class="reveal-block" style="${correct ? "" : "background:var(--flag-soft); border-left-color:var(--flag);"}"><h4>${correct ? "Correct" : "Not quite"}</h4><p style="font-size:0.87rem;">${q.explanation}</p></div>`;
    $("#quizNextBtn").hidden = false;
  }

  q.options.forEach((opt, i) => {
    const b = el("button", "chip ripple-surface", opt);
    b.style.cssText = "display:block; width:100%; text-align:left; margin-bottom:8px; padding:12px 14px; border-radius:12px;";
    b.addEventListener("click", () => {
      if (quizState.answers[quizState.index] !== null) return; // already answered this question — locked
      quizState.answers[quizState.index] = i;
      const correct = i === q.answerIndex;
      /* First attempt on this question decides its XP for good, ever —
         the same rule as chapter practice (and mirrored in the penalty
         path below). Replays and retries after the claim are free: no
         reward, no penalty, no toast. */
      const qKey = "quizq|" + q.id;
      if (correct) {
        awardXPOnce(qKey, 2, "Quiz question correct"); playSuccessSound();
        mistakeBookRecordCorrect(`quiz-${q.id}`);
      } else {
        awardXPOnce(qKey, -XP_WRONG_PENALTY, "Quiz question incorrect"); playErrorSound();
        mistakeBookRecord({
          key: `quiz-${q.id}`, question: q.q, chapter: q.chapter, chapterLabel: CH_FULL_NAME[q.chapter] || q.chapter,
          topic: CH_FULL_NAME[q.chapter] || q.chapter, type: "Quiz MCQ",
          studentAnswer: q.options[i], correctAnswer: q.options[q.answerIndex], explanation: q.explanation
        });
      }
      recomputeQuizScore();
      showFeedbackFor(i);
      icons();
    });
    optWrap.appendChild(b);
  });

  // If this question was already answered earlier (navigated back to it), restore that state immediately.
  if (priorAnswer !== null) {
    showFeedbackFor(priorAnswer);
  }

  icons();
  $("#quizNextBtn").addEventListener("click", () => {
    quizState.index++; renderQuizArea(area);
  });
  $("#quizPrevBtn").addEventListener("click", () => {
    if (quizState.index === 0) return;
    quizState.index--; renderQuizArea(area);
  });
}

/* ---------------------------------------------------------
   8. FORMULA SHEET (built now — genuinely quick to ship well)
   --------------------------------------------------------- */
function renderFormulaSheet(root) {
  if (activeClass() === ClassRegistry.CLASS_12) {
    /* v83 — Class 12 formula sheet is generated from the chapter
       registry: every chapter's formulas plus its key distinctions,
       so a data change is instantly reflected here. */
    root.appendChild(el("div", "hero", `
      <span class="hero-eyebrow">Revision</span>
      <h1>Formula Sheet</h1>
      <p>Core relationships and rules across all ${activeChapterIds().length} Class 12 chapters, ready to scan or print.</p>
      <button class="btn-primary ripple-surface" id="printBtn" style="margin-top:10px;"><i data-lucide="printer"></i> Print / Save as PDF</button>
    `));
    const card = el("div", "card-solid", "");
    card.style.padding = "26px";
    let html = "";
    activeChapters().forEach(ch => {
      const content = APP_DATA[ch.id] || {};
      const qr = content.quickRevision || {};
      const formulas = qr.formulas || [];
      html += `<h3 style="margin:28px 0 12px; color:${ch.color || "var(--ink)"};">Chapter ${ch.num} — ${ch.name}</h3>`;
      if (formulas.length) {
        html += `<table class="ledger-table">
          <thead><tr><th>Item</th><th>Formula</th></tr></thead>
          <tbody>${formulas.map(f => `<tr><td>${f.label}</td><td class="tnum">${f.expr}</td></tr>`).join("")}</tbody>
        </table>`;
      }
      (qr.distinctions || []).forEach(d => {
        html += `<h4 style="margin:18px 0 8px; font-size:0.95rem;">${d.title}</h4>
        <table class="ledger-table">
          <thead><tr><th></th>${(d.head || []).map(h => `<th>${h}</th>`).join("")}</tr></thead>
          <tbody>${(d.rows || []).map(r => `<tr><td style="font-weight:600;">${r[0]}</td>${r.slice(1).map(c => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody>
        </table>`;
      });
    });
    if (!html) html = `<p style="color:var(--ink-faint);">Chapter formulas appear here once the chapter content is available.</p>`;
    card.innerHTML = html;
    root.appendChild(card);
    attachRipple(root);
    $("#printBtn").addEventListener("click", () => window.print());
    return;
  }
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Revision</span>
    <h1>Formula Sheet</h1>
    <p>Core relationships and rules across all eighteen chapters, ready to scan or print.</p>
    <button class="btn-primary ripple-surface" id="printBtn" style="margin-top:10px;"><i data-lucide="printer"></i> Print / Save as PDF</button>
  `));
  const card = el("div", "card-solid", "");
  card.style.padding = "26px";
  card.innerHTML = `
    <h3 style="margin-bottom:12px; color:var(--c-intro);">Chapter 1 — Introduction to Accounting</h3>
    <p style="font-size:0.82rem; color:var(--ink-faint); margin:-4px 0 10px;">This chapter has no formulas — here are its key terms and characteristics to remember instead.</p>
    <table class="ledger-table">
      <thead><tr><th>Term</th><th>What it means</th></tr></thead>
      <tbody>
        <tr><td>Accounting</td><td>Identifying, recording, classifying, summarising, analysing, interpreting, and communicating financial transactions</td></tr>
        <tr><td>Book-keeping</td><td>Only the recording/posting part — the routine base that Accounting is built on</td></tr>
        <tr><td>5 Objectives</td><td>Systematic records · Ascertain profit/loss · Ascertain financial position · Provide information to users · Protect assets</td></tr>
        <tr><td>3 Types of Information</td><td>Profit or loss · Financial position · Cash flows</td></tr>
        <tr><td>Internal Users</td><td>Owners · Management · Employees</td></tr>
        <tr><td>External Users</td><td>Banks · Investors · Creditors · Government · Researchers · Public</td></tr>
        <tr><td>4 Qualitative Characteristics</td><td>Reliability · Relevance · Understandability · Comparability</td></tr>
        <tr><td>Key Limitation</td><td>Records only transactions measurable in money, at historical cost, with some figures resting on judgement</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-terms);">Chapter 2 — Basic Accounting Terms</h3>
    <p style="font-size:0.82rem; color:var(--ink-faint); margin:-4px 0 10px;">No formulas here either — just the core vocabulary and the pairs students mix up most.</p>
    <table class="ledger-table">
      <thead><tr><th>Term</th><th>What it means</th></tr></thead>
      <tbody>
        <tr><td>Capital</td><td>Owner's investment in the business — a liability of the business towards the owner</td></tr>
        <tr><td>Drawings</td><td>Cash/goods withdrawn by the owner for personal use — reduces Capital</td></tr>
        <tr><td>Assets vs. Liabilities</td><td>Assets = what the business owns; Liabilities = what it owes to outsiders</td></tr>
        <tr><td>Debtor vs. Creditor</td><td>Debtor owes money TO the business; Creditor is owed money BY the business</td></tr>
        <tr><td>Revenue, Expense, Income</td><td>Revenue = earned; Expense = cost incurred; Income = Revenue − Expense</td></tr>
        <tr><td>Purchases vs. Sales</td><td>Purchases = goods bought for resale/production; Sales = goods sold that were bought/made for resale</td></tr>
        <tr><td>Profit vs. Loss</td><td>Profit = Revenue &gt; Expense for the period; Loss = Expense &gt; Revenue</td></tr>
        <tr><td>Trade Discount vs. Cash Discount</td><td>Trade discount is never recorded separately; cash discount IS recorded (reward for prompt payment)</td></tr>
        <tr><td>Solvent vs. Insolvent</td><td>Solvent = assets &gt; liabilities (can pay debts); Insolvent = liabilities &gt; assets (cannot)</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-tbase);">Chapter 3 — Theory Base of Accounting, Accounting Standards &amp; Ind AS</h3>
    <p style="font-size:0.82rem; color:var(--ink-faint); margin:-4px 0 10px;">No formulas — just the assumptions, concepts, and standards every later chapter relies on.</p>
    <table class="ledger-table">
      <thead><tr><th>Term</th><th>What it means</th></tr></thead>
      <tbody>
        <tr><td>3 Fundamental Assumptions</td><td>Going Concern · Consistency · Accrual</td></tr>
        <tr><td>Business Entity</td><td>Owner and business are treated as separate</td></tr>
        <tr><td>Money Measurement</td><td>Only transactions expressible in money are recorded</td></tr>
        <tr><td>Cost Concept</td><td>Assets recorded at price actually paid, not current market value</td></tr>
        <tr><td>Dual Aspect</td><td>Every transaction has a giving and a receiving side — basis of Assets = Capital + Liabilities</td></tr>
        <tr><td>Revenue Recognition vs. Matching</td><td>Revenue recorded when earned; that period's expenses matched against that period's revenue</td></tr>
        <tr><td>Full Disclosure, Consistency, Conservatism, Materiality, Objectivity</td><td>Together keep accounting honest, comparable, and verifiable</td></tr>
        <tr><td>Cash Basis vs. Accrual Basis</td><td>Cash basis = actual cash movement only; Accrual basis = recorded as earned/incurred</td></tr>
        <tr><td>AS vs. Ind AS</td><td>AS issued by ICAI for broad use; Ind AS converged with IFRS, mainly for larger companies</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-basis);">Chapter 4 — Bases of Accounting</h3>
    <p style="font-size:0.82rem; color:var(--ink-faint); margin:-4px 0 10px;">No formulas — just the two bases and how each treats outstanding/prepaid/accrued items.</p>
    <table class="ledger-table">
      <thead><tr><th>Term</th><th>What it means</th></tr></thead>
      <tbody>
        <tr><td>Cash Basis</td><td>Revenue/expense recorded only when cash is actually received/paid</td></tr>
        <tr><td>Accrual Basis</td><td>Revenue/expense recorded when earned/incurred, regardless of cash timing</td></tr>
        <tr><td>Outstanding Expense</td><td>Incurred, unpaid — Accrual Basis only, shown as a liability</td></tr>
        <tr><td>Prepaid Expense</td><td>Paid in advance for a future period — Accrual Basis only, shown as an asset</td></tr>
        <tr><td>Accrued Income</td><td>Earned, not yet received — Accrual Basis only, shown as an asset</td></tr>
        <tr><td>Income Received in Advance</td><td>Received for a future period — Accrual Basis only, shown as a liability</td></tr>
        <tr><td>Legal Requirement</td><td>Companies Act requires Accrual Basis; Cash Basis only for very small non-corporate entities</td></tr>
        <tr><td>OPAI Mnemonic</td><td>Outstanding expense · Prepaid expense · Accrued income · Income received in advance</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-eq);">Chapter 5 — Accounting Equation</h3>
    <table class="ledger-table">
      <thead><tr><th>To find</th><th>Formula</th></tr></thead>
      <tbody>
        <tr><td>Assets</td><td class="tnum">Capital + Liabilities</td></tr>
        <tr><td>Capital</td><td class="tnum">Assets − Liabilities</td></tr>
        <tr><td>Liabilities</td><td class="tnum">Assets − Capital</td></tr>
        <tr><td>Effective Capital</td><td class="tnum">Opening Capital + Profit + Additional Capital − Drawings − Loss</td></tr>
        <tr><td>Profit on a transaction</td><td class="tnum">Selling Price − Cost</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-dc);">Chapter 6 — Rules of Debit &amp; Credit</h3>
    <table class="ledger-table">
      <thead><tr><th>Account type</th><th>Rule</th></tr></thead>
      <tbody>
        <tr><td>Personal (Golden Rule)</td><td>Debit the Receiver, Credit the Giver</td></tr>
        <tr><td>Real (Golden Rule)</td><td>Debit what comes in, Credit what goes out</td></tr>
        <tr><td>Nominal (Golden Rule)</td><td>Debit all expenses/losses, Credit all incomes/gains</td></tr>
        <tr><td>Assets / Expenses (Modern Rule)</td><td>Increase = Debit, Decrease = Credit</td></tr>
        <tr><td>Liabilities / Capital / Revenue (Modern Rule)</td><td>Increase = Credit, Decrease = Debit</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-jr);">Chapter 7 — Journal</h3>
    <table class="ledger-table">
      <thead><tr><th>Element</th><th>Detail</th></tr></thead>
      <tbody>
        <tr><td>Journal columns</td><td>Date · Particulars · L.F. · Debit ₹ · Credit ₹</td></tr>
        <tr><td>Format</td><td>Debit account first (with "Dr."), credit account indented below (with "To")</td></tr>
        <tr><td>Narration</td><td>Written in brackets below every entry, starting with "Being…"</td></tr>
        <tr><td>Compound entry rule</td><td>Total Debits = Total Credits, even across multiple lines</td></tr>
        <tr><td>Trade discount</td><td>Never recorded — only the net billed value is journalised</td></tr>
        <tr><td>Cash discount</td><td>Recorded via Discount Allowed A/c (expense) or Discount Received A/c (income)</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-lg);">Chapter 8 — Ledger</h3>
    <table class="ledger-table">
      <thead><tr><th>Element</th><th>Detail</th></tr></thead>
      <tbody>
        <tr><td>Definition</td><td>Principal book of accounts where all Journal transactions are posted, classified by account</td></tr>
        <tr><td>Format</td><td>T-shaped account — Debit (Dr.) on the left, Credit (Cr.) on the right, with Date · Particulars · J.F. · Amount on each side</td></tr>
        <tr><td>J.F. column</td><td>Journal Folio — the page number of the Journal the entry was posted from</td></tr>
        <tr><td>Posting rule — debit</td><td>Journal debit → Ledger debit (same account, same amount)</td></tr>
        <tr><td>Posting rule — credit</td><td>Journal credit → Ledger credit (same account, same amount)</td></tr>
        <tr><td>Debit side wording</td><td>Prefix with "To" — e.g. "To Sales A/c"</td></tr>
        <tr><td>Credit side wording</td><td>Prefix with "By" — e.g. "By Cash A/c"</td></tr>
        <tr><td>Balancing — Step 1</td><td>Total (foot) both sides separately</td></tr>
        <tr><td>Balancing — Step 2</td><td>Write the difference as "Balance c/d" on the smaller side, so both sides tally</td></tr>
        <tr><td>Balancing — Step 3</td><td>Bring the same figure down as "Balance b/d" on the opposite side, next period</td></tr>
        <tr><td>Debit balance</td><td>Balance b/d appears on the debit side — typical of Assets and Expenses</td></tr>
        <tr><td>Credit balance</td><td>Balance b/d appears on the credit side — typical of Liabilities, Capital, and Income</td></tr>
        <tr><td>Nil balance</td><td>Both sides total exactly the same — common for Nominal accounts closed to Profit &amp; Loss A/c</td></tr>
        <tr><td>Mnemonic</td><td>"Debit — To; Credit — By" — say it as one phrase to recall instantly</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-cb);">Chapter 9 — Special Purpose Books 1: Cash Book</h3>
    <table class="ledger-table">
      <thead><tr><th>Element</th><th>Detail</th></tr></thead>
      <tbody>
        <tr><td>Cash Book</td><td>Records only cash and bank transactions, in chronological order — receipts on debit (left), payments on credit (right)</td></tr>
        <tr><td>Dual nature</td><td>Both a Subsidiary Book (original entry) AND a Principal Book (it IS the Cash/Bank Account — balances go straight to the Trial Balance)</td></tr>
        <tr><td>Simple Cash Book</td><td>One amount column each side — cash transactions only; never shows a credit balance</td></tr>
        <tr><td>Two-Column Cash Book</td><td>Cash column + Bank column each side — represents Cash A/c and Bank A/c together</td></tr>
        <tr><td>Contra Entry</td><td>Cash ↔ Bank transfer — marked 'C' in the L.F. column on both sides; never posted to any Ledger account</td></tr>
        <tr><td>Cash Discount</td><td>Never entered in the Cash Book — always via Journal Proper: Discount Allowed A/c Dr./To Party (allowed); Party Dr./To Discount Received A/c (received)</td></tr>
        <tr><td>Cheques-in-Hand A/c</td><td>Used only when a cheque received is NOT deposited the same day — Dr. on receipt, credited on deposit</td></tr>
        <tr><td>Post-dated cheque</td><td>Entered on the date actually deposited/issued, never on the future date printed on the cheque</td></tr>
        <tr><td>Discounting charges</td><td class="tnum">Amount × Rate% p.a. × Remaining period / 12</td></tr>
        <tr><td>Bank Overdraft</td><td>Amount withdrawn in excess of balance — a liability; shows as a credit balance in the bank column</td></tr>
        <tr><td>Petty Cash Book</td><td>Records small/petty payments only, kept by the Petty Cashier, usually under the Imprest System</td></tr>
        <tr><td>Imprest System</td><td>Fixed estimated amount given at period start; exact amount spent is reimbursed at period end</td></tr>
        <tr><td>Posting Petty Cash</td><td>Advance: Petty Cash A/c Dr./To Cash A/c. Submission: each Expense A/c Dr./To Petty Cash A/c</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-sp2);">Chapter 10 — Special Purpose Books 2: Other Books</h3>
    <table class="ledger-table">
      <thead><tr><th>Element</th><th>Detail</th></tr></thead>
      <tbody>
        <tr><td>Purchases Book</td><td>Records only CREDIT purchases of goods dealt in or used for manufacturing — net of trade discount</td></tr>
        <tr><td>Sales Book</td><td>Records only CREDIT sales of goods dealt in — net of trade discount</td></tr>
        <tr><td>Purchases Return Book</td><td>Records return of goods purchased on credit — basis: Debit Note (prepared by the purchaser)</td></tr>
        <tr><td>Sales Return Book</td><td>Records return of goods sold on credit — basis: Credit Note (prepared by the seller)</td></tr>
        <tr><td>Journal Proper</td><td>Records everything that fits none of the other five books — Opening, Closing, Rectification, Transfer, Adjustment, and Miscellaneous entries</td></tr>
        <tr><td>Trade Discount treatment</td><td class="tnum">Net amount recorded = List Price − Trade Discount (never entered as its own figure)</td></tr>
        <tr><td>Freight/Packing on Purchases</td><td class="tnum">Cost column → Purchases A/c (Dr.); Freight/Packing column → own account (Dr.); Total → Seller's A/c (Cr.)</td></tr>
        <tr><td>Freight/Packing on Sales</td><td class="tnum">Sale Value column → Sales A/c (Cr.); Packing column → Packing Charges A/c (Cr.); Total → Buyer's A/c (Dr.)</td></tr>
        <tr><td>Purchases Book posting</td><td>Each supplier credited individually; periodic total debited to Purchases A/c</td></tr>
        <tr><td>Sales Book posting</td><td>Each customer debited individually; periodic total credited to Sales A/c</td></tr>
        <tr><td>Debit Note vs Credit Note</td><td>Debit Note — by purchaser, for Purchases Return Book. Credit Note — by seller, for Sales Return Book</td></tr>
        <tr><td>Return Books' ruling</td><td>Identical to Purchases/Sales Book, except "Invoice No." is replaced by "Debit/Credit Note No."</td></tr>
        <tr><td>Opening Entry pattern</td><td>Sundry Assets A/c Dr.; To Sundry Liabilities A/c; To Capital A/c</td></tr>
        <tr><td>Rule of thumb</td><td>What matters is what the RECORDING firm deals in — not what the counterparty intends to do with the goods</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-brs);">Chapter 11 — Bank Reconciliation Statement (BRS)</h3>
    <table class="ledger-table">
      <thead><tr><th>Element</th><th>Detail</th></tr></thead>
      <tbody>
        <tr><td>BRS</td><td>A statement explaining, item by item, the difference between Balance as per Cash Book and Balance as per Pass Book, proving they agree once adjusted</td></tr>
        <tr><td>The one Add/Less rule</td><td class="tnum">Starting balance SHORT of target → Add. Starting balance AHEAD of target → Less.</td></tr>
        <tr><td>Format (from Cash Book)</td><td class="tnum">Balance as per Cash Book ± Items = Balance as per Pass Book</td></tr>
        <tr><td>Format (from Pass Book)</td><td class="tnum">Balance as per Pass Book ± Items = Balance as per Cash Book</td></tr>
        <tr><td>Opposite-direction rule</td><td>Every item's Add/Less treatment reverses when the starting balance is switched</td></tr>
        <tr><td>Cheque issued, not presented</td><td>Add (from Cash Book) / Less (from Pass Book)</td></tr>
        <tr><td>Cheque deposited, not collected</td><td>Less (from Cash Book) / Add (from Pass Book)</td></tr>
        <tr><td>Bank charges, not in Cash Book</td><td>Less (from Cash Book) / Add (from Pass Book)</td></tr>
        <tr><td>Interest allowed, not in Cash Book</td><td>Add (from Cash Book) / Less (from Pass Book)</td></tr>
        <tr><td>Direct collection by bank</td><td>Add (from Cash Book) / Less (from Pass Book)</td></tr>
        <tr><td>Direct payment by bank</td><td>Less (from Cash Book) / Add (from Pass Book)</td></tr>
        <tr><td>Dishonoured cheque, not in Cash Book</td><td>Less (from Cash Book) / Add (from Pass Book)</td></tr>
        <tr><td>Direct deposit by customer</td><td>Add (from Cash Book) / Less (from Pass Book)</td></tr>
        <tr><td>Receipts side undercast (Cash Book)</td><td>Add the shortfall (balance was understated)</td></tr>
        <tr><td>Payments side overcast (Cash Book)</td><td>Add the excess (balance was understated)</td></tr>
        <tr><td>Balance as per Pass Book, sign convention</td><td>Written from the bank's point of view — a favourable firm balance is a CREDIT there, the reverse of the Cash Book</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-gst);">Chapter 12 — Accounting of GST</h3>
    <table class="ledger-table">
      <thead><tr><th>Element</th><th>Detail</th></tr></thead>
      <tbody>
        <tr><td>GST</td><td>Goods and Services Tax — a single, comprehensive, indirect, multi-stage, destination-based tax on the supply of goods and services</td></tr>
        <tr><td>GST Amount</td><td class="tnum">Taxable Value × GST Rate / 100</td></tr>
        <tr><td>Invoice Value</td><td class="tnum">Taxable Value + GST Amount</td></tr>
        <tr><td>Taxable Value (with trade discount)</td><td class="tnum">List Price − Trade Discount</td></tr>
        <tr><td>Trade discount rule</td><td>Always deducted from the list price BEFORE calculating GST — never calculate GST on the gross list price</td></tr>
        <tr><td>Freight — GST applicable</td><td>Add freight to the taxable value FIRST, then calculate GST on goods + freight together</td></tr>
        <tr><td>Freight — GST not applicable</td><td>Calculate GST on goods only; add freight to the invoice value afterwards</td></tr>
        <tr><td>Intra-state sale (same state)</td><td>CGST + SGST, split equally (e.g. 18% total = 9% CGST + 9% SGST)</td></tr>
        <tr><td>Inter-state sale (different states)</td><td>IGST — the full GST rate as a single tax, no CGST/SGST split</td></tr>
        <tr><td>Input GST</td><td>GST paid on purchases — claimable as credit</td></tr>
        <tr><td>Output GST</td><td>GST collected on sales — payable to the government</td></tr>
        <tr><td>Net GST Payable</td><td class="tnum">Output GST − Input GST</td></tr>
        <tr><td>Purchase entry (simple)</td><td class="tnum">Purchases A/c Dr., Input GST A/c Dr. → To Cash/Creditor's A/c</td></tr>
        <tr><td>Sale entry (simple)</td><td class="tnum">Cash/Debtor's A/c Dr. → To Sales A/c, To Output GST A/c</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-tb);">Chapter 13 — Trial Balance</h3>
    <table class="ledger-table">
      <thead><tr><th>Element</th><th>Detail</th></tr></thead>
      <tbody>
        <tr><td>Trial Balance</td><td>A statement listing the balance of every ledger account as on a particular date, to check arithmetical accuracy</td></tr>
        <tr><td>Core rule</td><td class="tnum">Total Debit Balances = Total Credit Balances</td></tr>
        <tr><td>Balance Method — steps</td><td>Balance every ledger account → list each account's balance in the correct column → total both columns → compare</td></tr>
        <tr><td>Normally Debit balances</td><td>Assets, Expenses/Losses, Drawings (e.g. Cash, Machinery, Purchases, Wages, Bad Debts)</td></tr>
        <tr><td>Normally Credit balances</td><td>Liabilities, Capital, Incomes/Gains (e.g. Creditors, Capital, Sales, Commission Received)</td></tr>
        <tr><td>Errors NOT affecting agreement</td><td>Errors of omission, errors of principle, compensating errors, and certain errors of commission</td></tr>
        <tr><td>Errors that DO affect agreement</td><td>One-sided errors — wrong side posting, casting (totalling) errors, wrong balance carried forward</td></tr>
        <tr><td>Trial Balance agrees ≠</td><td>Conclusive proof of error-free books — it only confirms arithmetical accuracy, not complete correctness</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-dep);">Chapter 14 — Depreciation</h3>
    <table class="ledger-table">
      <thead><tr><th>To find</th><th>Formula / Rule</th></tr></thead>
      <tbody>
        <tr><td>Depreciation (SLM)</td><td class="tnum">(Cost − Residual Value) ÷ Useful Life  —  or  —  (Cost − Residual Value) × Rate ÷ 100</td></tr>
        <tr><td>Depreciation (WDV) — for a year</td><td class="tnum">Opening Book Value × Rate ÷ 100</td></tr>
        <tr><td>Closing Book Value (WDV)</td><td class="tnum">Opening Book Value − Depreciation for the year</td></tr>
        <tr><td>Part-year depreciation</td><td class="tnum">Full-year Depreciation × (Months Used ÷ 12)</td></tr>
        <tr><td>Book Value (either method)</td><td class="tnum">Original Cost − Accumulated Depreciation to date</td></tr>
        <tr><td>Rate of Depreciation (from amount)</td><td class="tnum">(Annual Depreciation ÷ Cost or Opening Book Value) × 100</td></tr>
        <tr><td>Profit on Sale of Asset</td><td class="tnum">Sale Proceeds − Book Value  (when Sale Proceeds &gt; Book Value)</td></tr>
        <tr><td>Loss on Sale of Asset</td><td class="tnum">Book Value − Sale Proceeds  (when Book Value &gt; Sale Proceeds)</td></tr>
        <tr><td>Direct method — year-end entry</td><td class="tnum">Depreciation A/c Dr. → To Asset A/c</td></tr>
        <tr><td>Provision method — year-end entry</td><td class="tnum">Depreciation A/c Dr. → To Provision for Depreciation A/c</td></tr>
        <tr><td>Closing Depreciation A/c</td><td class="tnum">Profit &amp; Loss A/c Dr. → To Depreciation A/c</td></tr>
        <tr><td>Disposal — step 1 (transfer cost out)</td><td class="tnum">Asset Disposal A/c Dr. → To Asset A/c [Original Cost]</td></tr>
        <tr><td>Disposal — step 2 (transfer acc. depreciation out)</td><td class="tnum">Provision for Depreciation A/c Dr. → To Asset Disposal A/c [Accumulated Depreciation]</td></tr>
        <tr><td>Disposal — step 3 (record sale proceeds)</td><td class="tnum">Bank/Cash A/c Dr. → To Asset Disposal A/c [Sale Proceeds]</td></tr>
        <tr><td>Disposal — step 4 (profit)</td><td class="tnum">Asset Disposal A/c Dr. → To Profit on Sale of Asset A/c [Profit]</td></tr>
        <tr><td>Disposal — step 4 (loss)</td><td class="tnum">Loss on Sale of Asset A/c Dr. → To Asset Disposal A/c [Loss]</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-pres);">Chapter 15 — Provisions and Reserves</h3>
    <table class="ledger-table">
      <thead><tr><th>To find / to decide</th><th>Formula / Rule</th></tr></thead>
      <tbody>
        <tr><td>Create a Provision</td><td class="tnum">Profit &amp; Loss A/c Dr. → To Provision A/c  (a charge against profit — made even in a loss year)</td></tr>
        <tr><td>Create a Reserve</td><td class="tnum">Profit &amp; Loss A/c Dr. → To Reserve A/c  (an appropriation — only out of profit)</td></tr>
        <tr><td>Provision vs Reserve</td><td class="tnum">Provision = liability of uncertain amount/timing, deducted BEFORE net profit · Reserve = division of profit already earned</td></tr>
        <tr><td>Distributable profit</td><td class="tnum">Net Profit − Provisions charged − Transfers to Reserves</td></tr>
        <tr><td>Capital Reserve</td><td class="tnum">Made from capital profits — premium on issue, profit on sale of a fixed asset, revaluation profit. Not available for dividend.</td></tr>
        <tr><td>Revenue Reserve</td><td class="tnum">Made from revenue profits — General Reserve, Contingency Reserve, Dividend Equalisation Reserve. Free for any purpose, including dividend.</td></tr>
        <tr><td>Debtors after the new provision</td><td class="tnum">Debtors − Bad Debts − New Provision for Doubtful Debts</td></tr>
        <tr><td>Provision charged to the P&amp;L A/c</td><td class="tnum">Bad Debts + New Provision − Old Provision</td></tr>
        <tr><td>Secret Reserve</td><td class="tnum">Created by understating profit (excess depreciation, undervalued stock, excessive provisions) — hidden, so never shown in the Balance Sheet</td></tr>
        <tr><td>Where reserves appear</td><td class="tnum">Liabilities side, under Reserves &amp; Surplus (they belong to the proprietor)</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-roe);">Chapter 16 — Rectification of Errors</h3>
    <p style="font-size:0.82rem; color:var(--ink-faint); margin:-4px 0 10px;">No formulas to memorise — this chapter runs on a method. Find what SHOULD have been recorded, find what WAS recorded, and pass an entry that turns the second into the first.</p>
    <table class="ledger-table">
      <thead><tr><th>Error / situation</th><th>How it shows up and how to fix it</th></tr></thead>
      <tbody>
        <tr><td>Error of omission</td><td>Left out entirely (both sides — TB agrees) or partially (one side — TB disagrees)</td></tr>
        <tr><td>Error of commission</td><td>Right type of entry, wrong account of the same class or wrong amount → reverse the wrong posting, post the correct one</td></tr>
        <tr><td>Error of principle</td><td>Wrong class of account (asset treated as expense) → move the amount from the revenue account to the asset account</td></tr>
        <tr><td>Error of original entry</td><td>Same wrong figure on both sides → correct the side that carries the wrong amount; TB still agreed</td></tr>
        <tr><td>Error of casting</td><td>Footing mistake on one side → correct the total, the difference sits in the Suspense A/c</td></tr>
        <tr><td>Compensating error</td><td>Two equal one-sided errors offset each other — TB agrees, accounts stay wrong</td></tr>
        <tr><td>Suspense A/c</td><td class="tnum">Opened only when the TB disagrees · Parked difference = Debit total − Credit total · Closed to nil once every one-sided error is found</td></tr>
        <tr><td>Rectified before the TB</td><td>One correcting journal entry — no Suspense A/c needed</td></tr>
        <tr><td>Rectified after the TB, before final accounts</td><td>Correcting entry, using the Suspense A/c for any effect on an already-closed account</td></tr>
        <tr><td>Rectified after final accounts</td><td>Prior-period correction — adjusted in the current year's financial statements, not hidden in this year's profit</td></tr>
        <tr><td>Posting the wrong account</td><td class="tnum">Debit the account wrongly credited · Credit the account wrongly debited</td></tr>
        <tr><td>Wrong amount, both sides</td><td class="tnum">Post the difference (wrong figure − correct figure) to the side that carries the excess</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-fs);">Chapter 17 — Financial Statements of Sole Proprietorship</h3>
    <table class="ledger-table">
      <thead><tr><th>To find</th><th>Formula</th></tr></thead>
      <tbody>
        <tr><td>Cost of Goods Sold</td><td class="tnum">Opening Stock + Purchases + Direct Expenses − Closing Stock</td></tr>
        <tr><td>Gross Profit</td><td class="tnum">Net Sales − Cost of Goods Sold</td></tr>
        <tr><td>Net Profit</td><td class="tnum">Gross Profit + Other Incomes − All Indirect Expenses</td></tr>
        <tr><td>Closing Capital</td><td class="tnum">Opening Capital + Net Profit − Drawings + Additional Capital Introduced</td></tr>
        <tr><td>Balance Sheet equation</td><td class="tnum">Assets = Liabilities + Capital</td></tr>
        <tr><td>Gross Profit % on Sales</td><td class="tnum">(Gross Profit ÷ Net Sales) × 100</td></tr>
        <tr><td>Gross Profit % on Cost</td><td class="tnum">(Gross Profit ÷ Cost of Goods Sold) × 100</td></tr>
        <tr><td>Sales from Cost (GP % on cost)</td><td class="tnum">Cost × (100 + GP%) ÷ 100</td></tr>
        <tr><td>Closing Stock valuation</td><td class="tnum">Cost or Net Realisable Value, whichever is LOWER</td></tr>
        <tr><td>Direct vs Indirect</td><td class="tnum">Direct (Trading A/c): wages, carriage inwards, freight, factory rent/power · Indirect (P&amp;L A/c): office &amp; selling and financial expenses</td></tr>
        <tr><td>Order of preparation</td><td class="tnum">Trading A/c → Profit &amp; Loss A/c → Balance Sheet (gross profit feeds the P&amp;L, net profit feeds the Balance Sheet)</td></tr>
      </tbody>
    </table>

    <h3 style="margin:28px 0 12px; color:var(--c-adj);">Chapter 18 — Adjustment in Preparation of Financial Statements</h3>
    <p style="font-size:0.82rem; color:var(--ink-faint); margin:-4px 0 10px;">The one rule every adjustment obeys: <b>two effects</b> — one in the final accounts, one in the Balance Sheet.</p>
    <table class="ledger-table">
      <thead><tr><th>Adjustment</th><th>Effect 1 — Trading / P&amp;L A/c</th><th>Effect 2 — Balance Sheet</th></tr></thead>
      <tbody>
        <tr><td>Closing Stock</td><td>Credit to the Trading A/c (lowers cost of goods sold)</td><td>Current asset</td></tr>
        <tr><td>Outstanding expense</td><td>ADD to the expense</td><td>Current liability</td></tr>
        <tr><td>Prepaid expense</td><td>DEDUCT from the expense</td><td>Current asset</td></tr>
        <tr><td>Accrued income</td><td>ADD to the income</td><td>Current asset</td></tr>
        <tr><td>Income received in advance</td><td>DEDUCT from the income</td><td>Current liability</td></tr>
        <tr><td>Depreciation</td><td>Debit as an expense</td><td>Asset shown at its reduced value</td></tr>
        <tr><td>Interest on capital</td><td>Debit as an expense</td><td>Added to Capital</td></tr>
        <tr><td>Interest on drawings</td><td>Credit as income</td><td>Deducted from Capital</td></tr>
        <tr><td>Goods withdrawn / free samples / charity</td><td>Deduct from Closing Stock; charge advertisement (samples) or charity where applicable</td><td>Stock reduced; Capital reduced (drawings)</td></tr>
        <tr><td>Bad debts &amp; new provision</td><td class="tnum">Charge = Bad Debts + New Provision − Old Provision</td><td class="tnum">Debtors = Debtors − Bad Debts − New Provision</td></tr>
        <tr><td>Discount allowed to debtors</td><td>Debit as an expense</td><td>Deducted from Debtors</td></tr>
        <tr><td>Adjusted net profit</td><td class="tnum">Profit before adjustments + Closing Stock − Outstanding items − Prepaid items − Depreciation ± other effects</td><td>—</td></tr>
        <tr><td>Final check</td><td colspan="2">Tick each adjustment off on both statements — if one effect is missing, the Balance Sheet will not tally.</td></tr>
      </tbody>
    </table>
  `;
  root.appendChild(card);
  attachRipple(root);
  $("#printBtn").addEventListener("click", () => window.print());
}

/* ---------------------------------------------------------
   9. PERFORMANCE DASHBOARD
   --------------------------------------------------------- */
function renderPerformance(root) {
  const solved = Object.values(STATE.solved);
  const total = solved.length;
  const correct = solved.filter(s => s.correct).length;
  const accuracy = total ? Math.round((correct/total)*100) : 0;

  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">You</span>
    <h1>Performance Dashboard</h1>
    <p>A running picture of how your practice is going, stored locally on this device.</p>
  `));

  const grid = el("div", "grid-4");
  grid.appendChild(statCard("check-circle", "Questions Solved", total, "All chapters"));
  grid.appendChild(statCard("percent", "Accuracy", accuracy + "%", "Correct on reveal"));
  grid.appendChild(statCard("flame", "Streak", STATE.streak + " days", "Consecutive"));
  grid.appendChild(statCard("sparkles", "Total XP", STATE.xp, "Current balance"));
  root.appendChild(grid);

  const xpGrid = el("div", "grid-3");
  xpGrid.style.marginTop = "14px";
  xpGrid.appendChild(statCard("trending-up", "XP Gained", STATE.xpGained || 0, "Lifetime, from correct answers"));
  xpGrid.appendChild(statCard("trending-down", "XP Deducted", STATE.xpDeducted || 0, "Lifetime, from incorrect answers"));
  xpGrid.appendChild(statCard("target", "Best Exam Score", (STATE.bestScores.exam || 0) + "%", "Exam Mode"));
  root.appendChild(xpGrid);

  root.appendChild(sectionTitle("Chapter progress"));
  const chCard = el("div", "card-solid", "");
  chCard.style.padding = "22px";
  activeChapters().forEach(ch => {
    const pct = STATE.chapterProgress[ch.id] || 0;
    const row = el("div", "");
    row.style.cssText = "margin-bottom:16px;";
    row.innerHTML = `<div style="display:flex; justify-content:space-between; font-size:0.87rem; margin-bottom:6px;"><span>${ch.name}</span><span class="tnum">${pct}%</span></div><div class="progress-track"><div class="progress-fill" data-target="${pct}" style="width:0%"></div></div>`;
    chCard.appendChild(row);
  });
  root.appendChild(chCard);

  root.appendChild(sectionTitle("Achievements"));
  const earnedCount = (typeof Achievements !== "undefined") ? Achievements.ACHIEVEMENTS.filter(a => STATE.badges.includes(a.id)).length : 0;
  const earnedNote = el("p", "", `${earnedCount} of ${typeof Achievements !== "undefined" ? Achievements.ACHIEVEMENTS.length : 0} unlocked — each one is earned from something you actually did, and stays earned.`);
  earnedNote.style.cssText = "font-size:0.83rem; color:var(--ink-soft); margin:0 0 14px;";
  root.appendChild(earnedNote);
  const badgeGrid = el("div", "grid-4");
  if (typeof Achievements !== "undefined") {
    Achievements.ACHIEVEMENTS.forEach(a => {
      const earned = STATE.badges.includes(a.id);
      const b = el("div", "card achievement-card", "");
      b.style.cssText = `padding:18px; text-align:center; opacity:${earned ? 1 : 0.42};`;
      b.innerHTML = `
        <i data-lucide="${earned ? "award" : "lock"}" style="width:24px;height:24px; color:${earned ? "var(--gold)" : "var(--ink-faint)"};"></i>
        <p style="font-size:0.84rem; margin-top:8px; font-weight:600;">${escapeHtml(a.name)}</p>
        <p style="font-size:0.74rem; color:var(--ink-faint); margin:6px 0 0; line-height:1.5;">${escapeHtml(a.criteria)}</p>
        <p style="font-size:0.7rem; margin:8px 0 0; font-weight:700; letter-spacing:0.04em; text-transform:uppercase; color:${earned ? "var(--c-eq)" : "var(--ink-faint)"};">${earned ? "Unlocked" : "Locked"}</p>
      `;
      badgeGrid.appendChild(b);
    });
  }
  root.appendChild(badgeGrid);

  renderMyCertificatesSection(root);
}

/* ---------------------------------------------------------
   10. SETTINGS
   --------------------------------------------------------- */
function renderNotifSettingsHTML() {
  /* v87 — the full notification card (honest status, 10 categories,
     schedule, quiet hours, pause/unsubscribe, real server test) is
     rendered by push-manager.js so its state and the subscription
     logic can never drift apart. */
  if (window.ABAPush) return ABAPush.renderSettingsHTML();
  return `
    <label>Notifications</label>
    <p style="font-size:0.82rem; color:var(--ink-faint); margin:6px 0 0;">The notification interface didn't load — reload the page and try again.</p>
  `;
}

function renderSettings(root) {
  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">You</span>
    <h1>Settings</h1>
    <p>Control theme, accessibility, sound, and your saved progress.</p>
  `));

  const card = el("div", "card-solid", "");
  card.style.padding = "26px";
  card.innerHTML = `
    <div class="field-group">
      <label>Profile</label>
      <div class="profile-name-row">
        <input type="text" id="profileNameInput" maxlength="40" placeholder="Your name" value="${STATE.userName ? escapeHtml(STATE.userName) : ''}">
        <button class="btn-primary sm ripple-surface" id="saveNameBtn"><i data-lucide="check"></i> Save</button>
        <button class="btn-ghost sm ripple-surface" id="clearNameBtn"><i data-lucide="user-x"></i> Clear profile</button>
      </div>
      <p style="font-size:0.78rem; color:var(--ink-faint); margin:8px 0 0;">Your name only personalizes greetings — it never leaves this device. Changing or clearing it does not touch your XP, streak, or progress.</p>
    </div>
    <div class="field-group">
      <label>Class</label>
      <div id="settingsClassHost"></div>
    </div>
    <div class="field-group" id="notifFieldGroup">
      ${renderNotifSettingsHTML()}
    </div>
    <div class="field-group">
      <label>Theme</label>
      <div style="display:flex; gap:8px;">
        <button class="chip ${STATE.theme==='light'?'active':''}" data-set="theme-light">Light</button>
        <button class="chip ${STATE.theme==='dark'?'active':''}" data-set="theme-dark">Dark</button>
      </div>
    </div>
    <div class="field-group">
      <label>Color theme</label>
      <div class="theme-swatch-row" id="themeSwatchRow">
        ${["classic","ocean","forest","sunset","slate","rose"].map(ct => `
          <button class="theme-swatch swatch-${ct} ${STATE.colorTheme===ct?'active':''}" data-ctheme="${ct}" title="${ct.charAt(0).toUpperCase()+ct.slice(1)}"></button>
        `).join("")}
      </div>
    </div>
    <div class="field-group">
      <label>Font size</label>
      <div style="display:flex; gap:8px;">
        <button class="chip ${STATE.fontScale===0.9?'active':''}" data-set="font-0.9">Small</button>
        <button class="chip ${STATE.fontScale===1?'active':''}" data-set="font-1">Default</button>
        <button class="chip ${STATE.fontScale===1.15?'active':''}" data-set="font-1.15">Large</button>
      </div>
    </div>
    <div class="field-group">
      <label>Accessibility</label>
      <div style="display:flex; gap:8px; flex-wrap:wrap;">
        <button class="chip ${STATE.highContrast?'active':''}" data-set="contrast">High contrast</button>
        <button class="chip ${STATE.colorblind?'active':''}" data-set="colorblind">Color-blind mode</button>
        <button class="chip ${STATE.reduceMotion?'active':''}" data-set="motion">Reduce motion</button>
      </div>
    </div>
    <div class="field-group">
      <label>Sound</label>
      <div style="display:flex; gap:8px; align-items:center;">
        <button class="chip ${STATE.soundOn?'active':''}" data-set="sound">${STATE.soundOn?'On':'Off'}</button>
        <button class="btn-ghost sm" id="testSoundBtn" type="button"><i data-lucide="volume-2"></i> Test sound</button>
      </div>
      <p style="font-size:0.78rem; color:var(--ink-faint); margin:6px 0 0;">Plays a short click on every button and chip, plus a chime when the app opens. Off by default the first time this device visits the site.</p>
    </div>
    <div class="ledger-rule" style="margin-top:20px;">
      <label style="font-size:0.82rem; font-weight:600; color:var(--ink-soft); display:block; margin-bottom:10px;">Progress data</label>
      <div style="display:flex; gap:10px; flex-wrap:wrap;">
        <button class="btn-ghost sm" id="exportBtn"><i data-lucide="download"></i> Export progress</button>
        <button class="btn-ghost sm" id="importBtn"><i data-lucide="upload"></i> Import progress</button>
        <button class="btn-danger sm" id="resetProgressBtn"><i data-lucide="trash-2"></i> Reset progress</button>
      </div>
      <p style="font-size:0.78rem; color:var(--ink-faint); margin:8px 0 0;">Clears XP, streak, chapter progress, quiz/exam history, bookmarks, and AI Tutor chats — but keeps your name, theme, font size, and accessibility settings.</p>
      <input type="file" id="importFile" hidden accept="application/json">
    </div>
    <div class="ledger-rule" style="margin-top:16px;">
      <label style="font-size:0.82rem; font-weight:600; color:var(--ink-soft); display:block; margin-bottom:10px;">Preferences</label>
      <div style="display:flex; gap:10px; flex-wrap:wrap;">
        <button class="btn-danger sm" id="resetSettingsBtn"><i data-lucide="rotate-ccw"></i> Reset settings to default</button>
      </div>
      <p style="font-size:0.78rem; color:var(--ink-faint); margin:8px 0 0;">Restores theme, color theme, font size, accessibility, and sound to their defaults — your name, XP, progress, and AI chats are untouched.</p>
    </div>
    <div class="ledger-rule" style="margin-top:16px;">
      <label style="font-size:0.82rem; font-weight:600; color:var(--flag); display:block; margin-bottom:10px;">Danger zone</label>
      <div style="display:flex; gap:10px; flex-wrap:wrap;">
        <button class="btn-danger sm" id="resetAllBtn"><i data-lucide="alert-triangle"></i> Reset all data</button>
      </div>
      <p style="font-size:0.78rem; color:var(--ink-faint); margin:8px 0 0;">Deletes everything this site has stored on this device — your name, progress, and settings — and shows the welcome screen again next visit.</p>
    </div>
  `;
  root.appendChild(card);

  /* v83 — the same compact class switcher as the sidebar, mirrored
     here so the class can be changed from Settings too. */
  const settingsClassHost = $("#settingsClassHost", card);
  if (settingsClassHost) buildClassSwitchBar(settingsClassHost);

  $("#saveNameBtn").addEventListener("click", () => {
    const val = $("#profileNameInput").value.trim();
    STATE.userName = val ? val.slice(0, 40) : null;
    if (!STATE.onboardedAt) STATE.onboardedAt = Date.now();
    saveState();
    toast(val ? `Saved — hi, ${firstName()}!` : "Name cleared", "success", "user-check");
  });
  $("#clearNameBtn").addEventListener("click", async () => {
    if (!(await uiConfirm("Your progress will not be affected.", { title: "Clear your saved name?", confirmLabel: "Clear name" }))) return;
    STATE.userName = null;
    saveState();
    $("#profileNameInput").value = "";
    toast("Profile name cleared", "success", "user-x");
  });

  function refreshNotifUI() {
    $("#notifFieldGroup").innerHTML = renderNotifSettingsHTML();
    icons();
    wireNotifUI();
  }
  function wireNotifUI() {
    /* v87 — all notification controls (enable/disable, pause, test,
       categories, schedule, quiet hours, restore) are wired by
       push-manager.js against the same live subscription state. */
    if (window.ABAPush) ABAPush.wireSettings(refreshNotifUI);
  }
  wireNotifUI();

  card.addEventListener("click", e => {
    const swatch = e.target.closest("button[data-ctheme]");
    if (swatch) {
      STATE.colorTheme = swatch.dataset.ctheme;
      saveState(); applyTheme();
      $all(".theme-swatch", $("#themeSwatchRow")).forEach(s => s.classList.toggle("active", s.dataset.ctheme === STATE.colorTheme));
      toast(`Theme set to ${STATE.colorTheme}`, "success", "palette");
      return;
    }
    const btn = e.target.closest("button[data-set]");
    if (!btn) return;
    const [key, val] = btn.dataset.set.split("-");
    if (key === "theme") STATE.theme = val;
    if (key === "font") STATE.fontScale = parseFloat(val);
    if (btn.dataset.set === "contrast") STATE.highContrast = !STATE.highContrast;
    if (btn.dataset.set === "colorblind") STATE.colorblind = !STATE.colorblind;
    if (btn.dataset.set === "motion") STATE.reduceMotion = !STATE.reduceMotion;
    if (btn.dataset.set === "sound") STATE.soundOn = !STATE.soundOn;
    saveState(); applyTheme(); renderSettings(root.parentElement ? root : root);
    renderRoute();
  });

  $("#testSoundBtn").addEventListener("click", () => {
    if (!STATE.soundOn) { toast("Turn sound on first", "error", "volume-x"); return; }
    playSuccessSound();
  });

  $("#exportBtn").addEventListener("click", () => {
    const blob = new Blob([JSON.stringify(STATE, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = "accountancy-progress.json"; a.click();
    URL.revokeObjectURL(url);
    toast("Progress exported", "success", "download");
  });
  $("#importBtn").addEventListener("click", () => $("#importFile").click());
  $("#importFile").addEventListener("change", e => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const parsed = JSON.parse(reader.result);
        STATE = Object.assign(structuredClone(defaultState), parsed);
        saveState(); applyTheme(); renderRoute();
        toast("Progress imported", "success", "upload");
      } catch (err) { toast("Invalid file", "error", "alert-triangle"); }
    };
    reader.readAsText(file);
  });
  $("#resetProgressBtn").addEventListener("click", async () => {
    if (!(await uiConfirm("This clears XP, streak, chapter progress, quiz/exam history, bookmarks, and AI Tutor chats. This cannot be undone.", { title: "Reset all progress?", confirmLabel: "Reset progress" }))) return;
    const keepSettings = {
      theme: STATE.theme, colorTheme: STATE.colorTheme, fontScale: STATE.fontScale,
      colorblind: STATE.colorblind, highContrast: STATE.highContrast, reduceMotion: STATE.reduceMotion, soundOn: STATE.soundOn,
      userName: STATE.userName, onboardedAt: STATE.onboardedAt,
      notificationsEnabled: STATE.notificationsEnabled, notifyHour: STATE.notifyHour, notificationsPromptDismissed: STATE.notificationsPromptDismissed
    };
    STATE = Object.assign(structuredClone(defaultState), keepSettings);
    saveState(); applyTheme(); renderRoute();
    toast("Progress reset", "success", "trash-2");
  });

  $("#resetAllBtn").addEventListener("click", async () => {
    if (!(await uiConfirm("This deletes your name, progress, and settings, and cannot be undone.", { title: "Reset all data on this device?", confirmLabel: "Reset everything" }))) return;
    /* v87 — full reset also drops the anonymous push device id, prefs
       and weekly counters, so this device leaves the push list. */
    if (window.ABAPush) await ABAPush.forgetEverything();
    else await unsubscribeFromPush();
    STATE = structuredClone(defaultState);
    saveState(); applyTheme(); renderRoute();
    toast("All data reset", "success", "alert-triangle");
    showWelcomeModal();
  });

  $("#resetSettingsBtn").addEventListener("click", async () => {
    if (!(await uiConfirm("Theme, font size, accessibility, and sound go back to defaults. Your progress and AI chats will not be affected.", { title: "Reset settings?", confirmLabel: "Reset settings", tone: "neutral" }))) return;
    STATE.theme = defaultState.theme;
    STATE.colorTheme = defaultState.colorTheme;
    STATE.fontScale = defaultState.fontScale;
    STATE.colorblind = defaultState.colorblind;
    STATE.highContrast = defaultState.highContrast;
    STATE.reduceMotion = defaultState.reduceMotion;
    STATE.soundOn = defaultState.soundOn;
    saveState(); applyTheme(); renderRoute();
    toast("Settings reset to default", "success", "rotate-ccw");
  });
}

