/* ---- Tiny markdown-lite formatter for AI messages ---- */
function mdLite(text) {
  const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const lines = String(text == null ? "" : text).split("\n");
  let html = "", inList = false, inOList = false, tbl = null;
  const closeLists = () => { if (inList) { html += "</ul>"; inList = false; } if (inOList) { html += "</ol>"; inOList = false; } };
  const flushTable = () => { if (tbl) { html += mdTable(tbl, esc); tbl = null; } };
  lines.forEach(line => {
    const trimmed = line.trim();
    if (/^\|.*\|$/.test(trimmed)) { closeLists(); (tbl = tbl || []).push(trimmed); return; }
    flushTable();
    const bullet = /^[-•]\s+(.*)/.exec(trimmed);
    const numbered = /^\d+[.)]\s+(.*)/.exec(trimmed);
    if (/^(-{3,}|\*{3,}|_{3,})$/.test(trimmed)) { closeLists(); html += "<hr>"; return; }
    if (bullet) {
      if (inOList) { html += "</ol>"; inOList = false; }
      if (!inList) { html += "<ul>"; inList = true; }
      html += `<li>${inlineMd(esc(bullet[1]))}</li>`;
      return;
    }
    if (numbered) {
      if (inList) { html += "</ul>"; inList = false; }
      if (!inOList) { html += "<ol>"; inOList = true; }
      html += `<li>${inlineMd(esc(numbered[1]))}</li>`;
      return;
    }
    closeLists();
    if (!trimmed) { html += "<br>"; return; }
    if (/^#{1,4}\s+/.test(trimmed)) { html += `<h4>${inlineMd(esc(trimmed.replace(/^#{1,4}\s+/, "")))}</h4>`; return; }
    html += `<p>${inlineMd(esc(trimmed))}</p>`;
  });
  flushTable();
  closeLists();
  return html;
}
function mdTable(rows, esc) {
  const cells = r => r.replace(/^\|/, "").replace(/\|$/, "").split("|").map(c => c.trim());
  const isSep = r => /^[\s|:-]+$/.test(r) && /-/.test(r);
  const hasHead = rows.length > 1 && isSep(rows[1]);
  const aligns = hasHead ? cells(rows[1]).map(c => /^:-*:$/.test(c) ? "center" : /-:$/.test(c) ? "right" : "left") : [];
  const body = rows.slice(hasHead ? 2 : 0).filter(r => !isSep(r));
  const td = (tag, c, i) => `<${tag}${aligns[i] && aligns[i] !== "left" ? ` style="text-align:${aligns[i]}"` : ""}>${inlineMd(esc(c))}</${tag}>`;
  return `<div class="ai-table-wrap"><table class="ai-table">${hasHead ? `<thead><tr>${cells(rows[0]).map((c, i) => td("th", c, i)).join("")}</tr></thead>` : ""}<tbody>${body.map(r => `<tr>${cells(r).map((c, i) => td("td", c, i)).join("")}</tr>`).join("")}</tbody></table></div>`;
}
function inlineMd(s) {
  return s.replace(/\*\*(.+?)\*\*/g, "<b>$1</b>").replace(/(^|[^*\w])\*(?!\s)([^*]+?)\*(?![*\w])/g, "$1<i>$2</i>").replace(/`(.+?)`/g, "<code>$1</code>");
}

