  if (!words.length) return null;
  const CH_NAME = { intro: "Introduction to Accounting", terms: "Basic Accounting Terms", tbase: "Theory Base of Accounting", basis: "Bases of Accounting", eq: "Accounting Equation", dc: "Rules of Debit & Credit", jr: "Journal", lg: "Ledger", cb: "Special Purpose Books 1 - Cash Book", sp2: "Special Purpose Books 2 - Other Books", brs: "Bank Reconciliation Statement (BRS)", gst: "Accounting of GST", tb: "Trial Balance", dep: "Depreciation", pres: "Provisions and Reserves", roe: "Rectification of Errors", fs: "Financial Statements of Sole Proprietorship", adj: "Adjustment in Preparation of Financial Statements" };
  const CH_DATA_KEY = { intro: "intro", terms: "terms", tbase: "tbase", basis: "basis", eq: "equation", dc: "debitCredit", jr: "journal", lg: "ledger", cb: "cashBook", sp2: "specialBooks2", brs: "brs", gst: "gst", tb: "tb", dep: "dep", pres: "pres", roe: "roe", fs: "fs", adj: "adj" };
  /* v83 — the local theory match follows the ACTIVE class: Class 12 scans
     C12 chapter content, Class 11 keeps the original chapter list. */
  let srcCh;
  if (activeClass() === ClassRegistry.CLASS_12) {
    srcCh = (typeof C12_DATA !== "undefined" && C12_DATA.content) ? ClassRegistry.chaptersOf(ClassRegistry.CLASS_12).map(c => ({ id: c.id, name: c.name, data: C12_DATA.content[c.id] })) : [];
  } else {
    srcCh = ["intro", "terms", "tbase", "basis", "eq", "dc", "jr", "lg", "cb", "sp2", "brs", "gst", "tb", "dep", "pres", "roe", "fs", "adj"].map(ch => ({ id: ch, name: CH_NAME[ch], data: APP_DATA[CH_DATA_KEY[ch]] }));
  }
  let best = null, bestScore = 0;
  srcCh.forEach(item => {
    const data = item.data;
    if (!data || !data.theory) return;
    [...(data.theory.simple || []), ...(data.theory.advanced || [])].forEach(block => {
      const hay = (block.h + " " + (block.p || "") + " " + (block.p2 || "")).toLowerCase();
      const score = words.filter(w => hay.includes(w)).length;
      if (score > bestScore) { bestScore = score; best = { block, ch: item.name, route: "ch-" + item.id }; }
    });
    (data.concepts || []).forEach(c => {
      const hay = (c.title + " " + c.body).toLowerCase();
      const score = words.filter(w => hay.includes(w)).length;
      if (score > bestScore) { bestScore = score; best = { block: { h: c.title, p: c.body }, ch: item.name, route: "ch-" + item.id }; }
    });
  });
