function aiLocalBrain(text, chat, opts) {
  const lower = text.toLowerCase().trim();

  if (/^why\??$/.test(lower) || (lower.includes("why") && lower.length < 20 && chat.lastPattern)) {
    return { text: aiExplainWhy(chat.lastPattern), quick: ["explain-simply", "practice"] };
  }
  if (lower.includes("explain simply") || lower.includes("explain simpler") || lower.includes("simple words") && lower.length < 30) {
    const lastBot = [...chat.messages].reverse().find(m => m.role === "assistant");
    return { text: aiSimplify(lastBot ? lastBot.text : "that concept"), quick: ["why", "practice"] };
  }
  if (lower.includes("hint")) {
    if (chat.pendingPractice) {
      return { text: `💡 **Hint:** ${chat.pendingPractice.hint || "Think about which accounts are affected and whether each one increases or decreases."}`, quick: ["show-solution"] };
    }
    return { text: "Ask me for a practice question first (\"give me a practice question\"), and I'll give you hints on that one before showing the full solution.", quick: ["practice"] };
  }
  if (lower.includes("show") && lower.includes("solution") && chat.pendingPractice) {
    const q = chat.pendingPractice;
    const answer = q.explanation || q.answer || q.narration || "Check the matching chapter's Practice Bank for the full worked solution.";
    chat.pendingPractice = null;
    return { text: `✅ **Full solution:**\n\n${answer}`, quick: ["practice", "another-example"] };
  }
  if (lower.includes("practice question") || lower.includes("give me a question") || /^give me a .+ question$/i.test(lower.trim()) || lower.includes("test me") || (lower.includes("practice") && lower.length < 25)) {
    const ch = aiDetectChapter(text) || chat.chapterContext || (activeClass() === ClassRegistry.CLASS_12 ? "pf" : "eq");
    const diff = lower.includes("hard") ? "hard" : lower.includes("easy") ? "easy" : lower.includes("medium") ? "medium" : null;
    const q = aiRandomPractice(ch, diff);
    if (!q) return { text: "I couldn't find a practice question for that right now — try asking for a different chapter.", quick: [] };
    chat.pendingPractice = q;
    const qText = q.transaction || q.q || q.question || "Practice question";
    const qOpts = Array.isArray(q.options) && q.options.length ? "\n\n" + q.options.map((o, i) => String.fromCharCode(65 + i) + ") " + o).join("\n") : "";
    return { text: `Here's one for you (${(q.difficulty || "").toLowerCase() || "medium"} difficulty):\n\n**${qText}**${qOpts}\n\nTry working it out, then ask me for a **hint** or say **"show solution"**.`, quick: ["hint", "show-solution"] };
  }
  if ((lower.includes(" dr.") || lower.includes(" dr ") || /\bto\s+\w+\s*a\/c/i.test(text)) && chat.lastPattern) {
    const check = aiCheckStudentAnswer(text, chat.lastPattern);
    if (check) return { text: check, quick: ["why", "practice"] };
  }

  const pattern = matchJournalPattern(text);
  if (pattern) {
    chat.lastPattern = pattern;
    const debit = (pattern.debitTemplate || pattern.debit || "").replace("{name}", extractName(text)).trim();
    const credit = (pattern.creditTemplate || pattern.credit || "").replace("{name}", extractName(text)).trim();
    let reply = `Let's work through this one:\n\n**Accounts involved:** ${debit.replace(/A\/c.*/i,"A/c")} and ${credit.replace(/^To\s+/i,"").replace(/A\/c.*/i,"A/c")}\n\n${pattern.narration}.\n\n**Journal entry:**\n${aiFormatPatternEntry({ ...pattern, debitTemplate: debit, creditTemplate: credit })}`;
    if (pattern.compound) reply = `This is a **compound entry** — more than two accounts are involved.\n\n${pattern.narration}.\n\n${aiFormatPatternEntry(pattern)}\n\nMake sure you mention every amount in order when asking me to fill one of these in.`;
    return { text: reply, quick: ["why", "explain-simply", "practice"] };
  }

  // The site-wide search (AIKnowledge) is smarter than this word-overlap theory match,
  // so the caller can ask this function to stop here and try that first.
  if (opts && opts.skipTheory) return null;

  const theoryMatch = aiFindTheoryMatch(text);
  if (theoryMatch) {
    const b = theoryMatch.block;
    let reply = `**${b.h}**\n\n${b.p || ""}`;
    if (b.formula) reply += `\n\n${b.formula}`;
    if (b.p2) reply += `\n\n${b.p2}`;
    reply += `\n\n*(From ${theoryMatch.ch} — open that chapter's Theory tab for the full picture.)*`;
    return { text: reply, quick: ["explain-simply", "practice"], route: theoryMatch.route };
  }

  return {
    text: `I couldn't confidently match that to something in the ${ClassRegistry.CLASS_META[activeClass() || "11"].shortLabel} syllabus covered here. I'm best with:\n\n- Specific transactions — try *"Paid rent ₹5,000 in cash"* or *"Sold goods on credit to Meera ₹20,000"*\n- Concept questions — try *"What is a Real Account?"* or *"Explain the Accounting Equation"*\n- **"Give me a practice question"** for a random problem\n\nWant to try rephrasing, or pick one of the suggestions below?`,
    quick: ["practice", "why"]
  };
}

const AI_QUICK_ACTION_LABELS = {
  "explain-simply": { icon: "baby", label: "Explain Simply", text: "Explain that more simply" },
  "why": { icon: "help-circle", label: "Why?", text: "Why?" },
  "hint": { icon: "lightbulb", label: "Give me a Hint", text: "Give me a hint" },
  "show-solution": { icon: "eye", label: "Show Full Solution", text: "Show solution" },
  "practice": { icon: "target", label: "Give Me Practice", text: "Give me a practice question" },
  "another-example": { icon: "refresh-cw", label: "Another Example", text: "Give me another example" },
  "example": { icon: "file-text", label: "Give an Example", text: "Give me an example" },
  "try-yourself": { icon: "pencil", label: "Try It Myself", text: "I'll try it myself" },
  "check-answer": { icon: "check-circle", label: "Check My Answer", text: "check my answer" }
};

/* ---- Backend hook: tries a real AI function first, falls back to
   the local engine above if it's not deployed/configured/reachable. ---- */
// Commands that the older local brain already handles with its own chat state
// (hint / show solution / practice / explain simply / why).
function aiIsLocalCommand(text) {
  const l = String(text || "").toLowerCase().trim();
  return /^why\??$/.test(l) || /^(show|give).{0,12}(solution|answer)\b/.test(l) || /^(give me )?(a )?hint\b/.test(l) || /explain (that )?(more )?simpl/.test(l) || /practice question|give me a question|test me/.test(l);
}

// The tutor's brain, used whether or not the AI service is available.
//   AICore  = intent + conversation memory + role-aware retrieval of this site's own content + answer composition
//   AISolver = deterministic, self-validating numerical solutions
// The journal engine (tutor-engine.js, built on the Accounting Cycle logic) keeps handling plain
// transactions ("paid rent 5000 in cash"), mode switches and its own practice problems.
function aiCoreReady() { return aiEnsureKB() && typeof AICore !== "undefined" && typeof AISolver !== "undefined"; }
function aiCoreState(chat) { chat.cstate = AICore.cleanState(chat.cstate); chat.cstate.mode = chat.answerMode || null; return chat.cstate; }
function aiRememberReply(chat, text, reply, q, extra) {
  // Replies that came from another engine (journal engine / AI service) still become conversation memory,
  // so "explain that more simply" or "give another example" work on them too.
  if (!aiCoreReady()) return;
  try { chat.cstate = AICore.observe(AIKnowledge.getKB(), aiCoreState(chat), text, reply.text, Object.assign({ question: q || null, sources: reply.sources || [] }, extra || {})); } catch (e) { /* memory is best-effort */ }
}
function aiHasPendingJournalProblem(chat) { return !!(chat && chat.pendingProblem); }

function aiOfflineRespond(text, chat) {
  const ready = aiCoreReady();
  const q = ready && chat.attachedQuestion ? AIKnowledge.fromWire(chat.attachedQuestion) : null;
  // A practice problem the journal engine set (Try it myself / Check my answer) keeps priority while it is pending.
  if (typeof TutorEngine !== "undefined" && aiHasPendingJournalProblem(chat)) {
    try { const er = TutorEngine.respond(text, chat); if (er) { aiRememberReply(chat, text, er, q, { kind: "question", parts: { explanation: er.text } }); return er; } } catch (e) { /* fall through */ }
  }
  if (ready) {
    const res = AICore.respond(AIKnowledge.getKB(), text, aiCoreState(chat), { question: q, mode: chat.answerMode || "steps", hasCycle: typeof acParseTransaction === "function", chapterScope: activeChapters().map(c => c.id), classLabel: ClassRegistry.CLASS_META[activeClass() || "11"].label });
    if (res.answer) {
      chat.cstate = res.state;
      const a = res.answer;
      // practice questions set by the core are checked by the core; clear the journal engine's pending problem
      if (a.practiceId) chat.pendingProblem = null;
      return { text: a.text, quick: a.quick && a.quick.length ? a.quick : ["explain-simply", "practice"], sources: a.sources || [] };
    }
    chat.cstate = res.state;
  }
  // Plain transactions, mode switches and anything the core leaves alone -> the journal engine
  if (typeof TutorEngine !== "undefined") {
    try { const er = TutorEngine.respond(text, chat); if (er) { aiRememberReply(chat, text, er, q, { kind: "question", parts: { explanation: er.text } }); return er; } } catch (e) { /* fall through */ }
  }
  if (aiIsLocalCommand(text)) return aiLocalBrain(text, chat);
  const pat = aiLocalBrain(text, chat, { skipTheory: true });
  if (pat) { aiRememberReply(chat, text, pat, q, { kind: "question", parts: { explanation: pat.text } }); return pat; }
  return aiLocalBrain(text, chat);
}

/* ---- Local tutor: the reply is built entirely from this site's own
   content + validated calculations (AIKnowledge, AICore, TutorEngine,
   aiLocalBrain). No remote AI service is contacted — there is no
   fetch, no endpoint and no key anywhere in this path. ---- */
async function aiRespond(text, chat, image) {
  if (image) {
    // Honest: reading a photo needs a vision service, and there is no
    // service anymore. The text tutor is fully local.
    return { text: "I can't read photos at the moment. Could you type the question out (with its figures)? Then I'll solve it step by step.", quick: ["practice"] };
  }
  return aiOfflineRespond(text, chat);
}

function aiSourcesHTML(msg) {
  const srcs = (msg.sources || []).filter(x => x && x.label).slice(0, 2);
  if (!srcs.length) return "";
  return `<div class="ai-sources">${srcs.map(x => {
    const safe = String(x.label).replace(/</g, "&lt;");
    return x.route ? `<button type="button" class="ai-source-chip" data-ai-route="${String(x.route).replace(/"/g, "")}" title="Open this chapter"><i data-lucide="book-open"></i>${safe}</button>` : `<span class="ai-source-chip"><i data-lucide="book-open"></i>${safe}</span>`;
  }).join("")}</div>`;
}

function renderAITutor(root) {
  root.classList.add("ai-route-root");
  const shell = el("div", "ai-tutor-shell");
  shell.innerHTML = `
    <div class="ai-tutor-header">
      <button id="aiHistoryToggle" class="icon-btn sm" title="Chat history"><i data-lucide="panel-left"></i></button>
      <div class="ai-header-title">
        <span><i data-lucide="bot" style="width:16px;height:16px;vertical-align:-3px;"></i> AI Tutor</span>
        <span class="ai-context-badge" id="aiContextBadge" hidden></span>
      </div>
      <button id="aiClearBtn" class="btn-ghost sm ripple-surface" title="Clear this conversation"><i data-lucide="eraser"></i><span class="ai-btn-label"> Clear</span></button>
      <button id="aiNewChatBtn" class="btn-ghost sm ripple-surface"><i data-lucide="plus"></i> New Chat</button>
    </div>
    <div class="ai-tutor-body">
      <div class="ai-history-overlay" id="aiHistoryOverlay" hidden></div>
      <aside class="ai-history-drawer" id="aiHistoryDrawer">
        <div class="ai-history-head">
          <span>Chats</span>
          <button class="icon-btn sm" id="aiHistoryClose" aria-label="Close chat history" title="Close chat history"><i data-lucide="x"></i></button>
        </div>
        <div class="ai-history-list" id="aiHistoryList"></div>
      </aside>
      <div class="ai-chat-main">
        <div class="ai-messages" id="aiMessages" aria-label="Conversation with the AI Tutor"></div>
        <div class="sr-only" id="aiStatus" role="status" aria-live="polite" aria-atomic="true"></div>
        <div class="ai-input-bar">
          <div class="ai-image-preview" id="aiImagePreview" hidden>
            <img id="aiImagePreviewImg" alt="Attached question">
            <button id="aiImageRemove" class="icon-btn sm" title="Remove image"><i data-lucide="x"></i></button>
          </div>
          <div class="ai-input-row">
            <button id="aiImageBtn" class="icon-btn sm" title="Upload a photo of your question" aria-label="Upload a photo of your question"><i data-lucide="image-plus"></i></button>
            <textarea id="aiInput" placeholder="${window.innerWidth <= 640 ? "Ask a question…" : `Ask about any ${ClassRegistry.CLASS_META[activeClass() || "11"].label} topic…`}" aria-label="Ask the AI Tutor a question" rows="1" maxlength="4000"></textarea>
            <button id="aiSendBtn" class="btn-primary sm ripple-surface" title="Send" aria-label="Send message" aria-keyshortcuts="Enter"><i data-lucide="send"></i></button>
          </div>
          <input type="file" id="aiImageInput" accept="image/*" hidden>
          <p class="ai-disclaimer">Answers follow your ${ClassRegistry.CLASS_META[activeClass() || "11"].shortLabel} chapters. For anything important, double-check with your textbook or teacher.</p>
        </div>
      </div>
    </div>
  `;
  root.appendChild(shell);
  icons();

  let pendingImage = null;
  let aiSending = false;   // one reply at a time — blocks double-Enter / double-click

  function setSending(on) {
    aiSending = on;
    const b = $("#aiSendBtn");
    if (b) { b.disabled = on; b.setAttribute("aria-busy", on ? "true" : "false"); }
  }
  // Short, non-noisy announcements for screen readers (the log itself is
  // rebuilt on every reply, so it must not be a live region).
  function announceStatus(msg) { const s = $("#aiStatus"); if (s) s.textContent = msg; }

  function scrollToBottom() {
    const m = $("#aiMessages");
    m.scrollTop = m.scrollHeight;
  }

  function renderHistoryList() {
    const list = $("#aiHistoryList");
    const chats = aiGetChats();
    if (!chats.length) { list.innerHTML = `<p style="font-size:0.82rem; color:var(--ink-faint); padding:14px;">No chats yet — start one below.</p>`; return; }
    list.innerHTML = chats.map(c => `
      <div class="ai-history-item ${c.id === STATE.aiActiveChatId ? "active" : ""}" data-chat="${c.id}">
        <i data-lucide="message-square" style="width:14px;height:14px; flex-shrink:0;"></i>
        <span class="ai-history-item-title">${c.title}</span>
        <button class="ai-history-delete" data-delete="${c.id}" title="Delete chat"><i data-lucide="trash-2"></i></button>
      </div>
    `).join("");
    icons();
    $all(".ai-history-item", list).forEach(item => {
      item.addEventListener("click", (e) => {
        if (e.target.closest("[data-delete]")) return;
        STATE.aiActiveChatId = item.dataset.chat;
        saveState();
        renderAll();
        closeHistoryDrawer();
      });
    });
    $all("[data-delete]", list).forEach(btn => {
      btn.addEventListener("click", async (e) => {
        e.stopPropagation();
        if (!(await uiConfirm("This chat will be removed. This can't be undone.", { title: "Delete this chat?", confirmLabel: "Delete chat" }))) return;
        aiDeleteChat(btn.dataset.delete);
        renderAll();
      });
    });
  }

  function renderContextBadge() {
    const chat = aiGetActiveChat();
    const badge = $("#aiContextBadge");
    if (chat && chat.chapterContext) {
      const CH_NAME = { eq: "Accounting Equation", dc: "Debit & Credit", jr: "Journal", lg: "Ledger", cb: "Special Purpose Books 1 - Cash Book", sp2: "Special Purpose Books 2 - Other Books", brs: "Bank Reconciliation Statement (BRS)", gst: "Accounting of GST" };
      badge.hidden = false;
      badge.textContent = `Studying: ${CH_NAME[chat.chapterContext] || chat.chapterContext}`;
    } else {
      badge.hidden = true;
    }
  }

  function messageBubble(msg, msgIndex) {
    const bubble = el("div", `ai-msg ai-msg-${msg.role}`);
    let inner = "";
    if (msg.role === "user") {
      inner = `<div class="ai-msg-bubble">${msg.image ? `<img src="${msg.image}" class="ai-msg-image" alt="Uploaded question">` : ""}${msg.text ? `<p>${msg.text.replace(/</g,"&lt;")}</p>` : ""}</div>`;
      bubble.innerHTML = inner;
      return bubble;
    }
    inner = `<div class="ai-msg-avatar"><i data-lucide="bot"></i></div><div class="ai-msg-col"><div class="ai-msg-bubble">${mdLite(msg.text)}${msg.journalHTML || ""}${msg.sectionsHTML || ""}</div>${aiSourcesHTML(msg)}<div class="ai-msg-actions">
      <button class="ai-msg-action" data-act="copy" title="Copy"><i data-lucide="copy"></i></button>
      <button class="ai-msg-action" data-act="regenerate" title="Regenerate"><i data-lucide="refresh-cw"></i></button>
      <button class="ai-msg-action ${msg.feedback === 'up' ? 'active-good' : ''}" data-act="up" title="Helpful"><i data-lucide="thumbs-up"></i></button>
      <button class="ai-msg-action ${msg.feedback === 'down' ? 'active-bad' : ''}" data-act="down" title="Not helpful"><i data-lucide="thumbs-down"></i></button>
    </div></div>`;
    bubble.innerHTML = inner;

    $all("[data-ai-route]", bubble).forEach(chip => chip.addEventListener("click", () => navigate(chip.dataset.aiRoute)));
    const act = (name) => $(`[data-act="${name}"]`, bubble);
    act("copy").addEventListener("click", () => {
      const plain = msg.text.replace(/\*\*(.+?)\*\*/g, "$1").replace(/`(.+?)`/g, "$1");
      navigator.clipboard.writeText(plain).then(() => toast("Copied to clipboard", "success", "copy")).catch(() => toast("Couldn't copy", "error", "alert-circle"));
    });
    act("regenerate").addEventListener("click", async () => {
      const chat = aiGetActiveChat();
      if (!chat || aiSending) return;
      // Find the user message that immediately precedes this assistant reply.
      let userMsg = null;
      for (let i = msgIndex - 1; i >= 0; i--) {
        if (chat.messages[i].role === "user") { userMsg = chat.messages[i]; break; }
      }
      if (!userMsg) { toast("Nothing to regenerate from", "error", "alert-circle"); return; }
      const removed = chat.messages.splice(msgIndex, 1)[0];
      saveState();
      renderMessages();
      setSending(true);
      announceStatus("AI Tutor is thinking…");
      const typingEl = showTyping();
      let replyObj = null, failed = false;
      try { replyObj = await aiRespond(userMsg.text, chat, userMsg.image || null); }
      catch (err) { failed = true; }
      typingEl.remove();
      setSending(false);
      if (failed) {
        chat.messages.splice(msgIndex, 0, removed);   // keep the previous answer — never lose a reply
        saveState(); renderMessages();
        announceStatus("Regeneration failed; your previous answer was kept.");
        toast("Couldn't regenerate — kept your previous answer", "error", "alert-circle");
        return;
      }
      chat.messages.push({ role: "assistant", text: replyObj.text, quick: replyObj.quick, journalHTML: replyObj.journalHTML, sectionsHTML: replyObj.sectionsHTML, sources: replyObj.sources, engine: replyObj.engine, ts: Date.now() });
      chat.updatedAt = Date.now();
      saveState();
      renderMessages();
      renderHistoryList();
      renderContextBadge();
      announceStatus("AI Tutor replied.");
    });
    act("up").addEventListener("click", () => {
      const chat = aiGetActiveChat();
      if (!chat) return;
      msg.feedback = msg.feedback === "up" ? null : "up";
      saveState(); renderMessages();
      if (msg.feedback === "up") toast("Thanks for the feedback!", "success", "thumbs-up");
    });
    act("down").addEventListener("click", () => {
      const chat = aiGetActiveChat();
      if (!chat) return;
      msg.feedback = msg.feedback === "down" ? null : "down";
      saveState(); renderMessages();
      if (msg.feedback === "down") toast("Thanks — noted for improvement", "success", "thumbs-down");
    });
    return bubble;
  }

  function renderQuickActions(container, keys) {
    if (!keys || !keys.length) return;
    const bar = el("div", "ai-quick-actions");
    keys.forEach(k => {
      const meta = AI_QUICK_ACTION_LABELS[k];
      if (!meta) return;
      const b = el("button", "chip ripple-surface ai-quick-chip", `<i data-lucide="${meta.icon}"></i> ${meta.label}`);
      b.addEventListener("click", () => sendMessage(meta.text));
      bar.appendChild(b);
    });
    container.appendChild(bar);
    icons();
  }

  function renderQuestionContext(wrap, chat) {
    const q = chat && chat.attachedQuestion;
    if (!q) return;
    const card = el("div", "ai-qcontext");
    const safe = s => String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    const preview = q.text.length > 260 ? q.text.slice(0, 259).trimEnd() + "…" : q.text;
    card.innerHTML = `
      <div class="ai-qcontext-head">
        <span class="ai-qcontext-label"><i data-lucide="sparkles"></i> Question from: ${safe(q.section || "Practice")}</span>
        <button type="button" class="icon-btn sm" data-act="detach" title="Stop attaching this question" aria-label="Detach question"><i data-lucide="x"></i></button>
      </div>
      <blockquote>${safe(preview)}</blockquote>
      ${q.options && q.options.length ? `<ul class="ai-qcontext-opts">${q.options.slice(0, 6).map((o, i) => `<li>${String.fromCharCode(65 + i)}. ${safe(String(o).length > 90 ? String(o).slice(0, 89) + "…" : o)}</li>`).join("")}</ul>` : ""}
      <p class="ai-qcontext-foot">Ask the tutor about this question — your follow-up messages are about it too.</p>`;
    $("[data-act='detach']", card).addEventListener("click", () => { chat.attachedQuestion = null; if (chat.cstate) chat.cstate.stepIdx = 0; saveState(); renderMessages(); });
    wrap.appendChild(card);
  }

  function renderMessages() {
    const wrap = $("#aiMessages");
    wrap.innerHTML = "";
    const chat = aiGetActiveChat();
    renderQuestionContext(wrap, chat);
    if (!chat || !chat.messages.length) {
      const welcome = el("div", "ai-welcome");
      welcome.innerHTML = `
        <div class="ai-welcome-icon"><i data-lucide="bot"></i></div>
        <h2>Hi! I'm your Accountancy AI Tutor 👋</h2>
        <p class="ai-welcome-sub">Ask me anything about ${ClassRegistry.CLASS_META[activeClass() || "11"].label}.</p>
        <p class="ai-welcome-desc">I can explain concepts, solve numerical problems, check your answers, give hints, and help you prepare for exams.</p>
        <div class="ai-prompt-grid" id="aiPromptGrid"></div>
      `;
      wrap.appendChild(welcome);
      const grid = $("#aiPromptGrid");
      const aiClsLabel = ClassRegistry.CLASS_META[activeClass() || "11"].label;
      AI_WELCOME_PROMPTS.forEach(p => {
        let pText = p.text.replace("Class 11 Accountancy", aiClsLabel);
        if (activeClass() === ClassRegistry.CLASS_12) pText = pText.replace("Accounting Equation", "Change in Profit-Sharing Ratio");
        const card = el("button", "ai-prompt-card ripple-surface", `<i data-lucide="${p.icon}"></i><span class="ai-prompt-label">${p.label}</span><span class="ai-prompt-text">"${pText}"</span>`);
        card.addEventListener("click", () => sendMessage(pText));
        grid.appendChild(card);
      });
      icons();
      return;
    }
    chat.messages.forEach((msg, i) => wrap.appendChild(messageBubble(msg, i)));
    const lastMsg = chat.messages[chat.messages.length - 1];
    if (lastMsg && lastMsg.role === "assistant" && lastMsg.quick) renderQuickActions(wrap, lastMsg.quick);
    icons();
    scrollToBottom();
  }

  function showTyping() {
    const wrap = $("#aiMessages");
    const t = el("div", "ai-msg ai-msg-assistant ai-typing-msg");
    t.setAttribute("role", "status");
    t.innerHTML = `<div class="ai-msg-avatar"><i data-lucide="bot"></i></div><div class="ai-msg-bubble ai-typing"><span>AI Tutor is thinking</span><span class="ai-typing-dots"><i></i><i></i><i></i></span></div>`;
    wrap.appendChild(t);
    icons();
    scrollToBottom();
    return t;
  }

  // Shown when the local engine fails. The question is never lost — the
  // student can retry the exact same message with one tap.
  function showSendError(onRetry) {
    const wrap = $("#aiMessages");
    const box = el("div", "ai-msg-err");
    box.setAttribute("role", "alert");
    box.innerHTML = `<p><strong>Something went wrong</strong> while preparing that answer. Your message is still here.</p><button type="button" class="btn-ghost sm ripple-surface" data-retry><i data-lucide="refresh-cw"></i> Try again</button>`;
    wrap.appendChild(box);
    icons();
    $("[data-retry]", box).addEventListener("click", () => { box.remove(); onRetry(); });
    scrollToBottom();
  }

  /* One reply pipeline for every entry point (first send, quick chip,
     welcome prompt, auto-send from Ask-Tutor, Try again): same loading
     state, same error handling, same re-entry guard. */
  async function answerLastUserMessage(chat, opts) {
    opts = opts || {};
    let lastUser = null;
    for (let i = chat.messages.length - 1; i >= 0; i--) {
      if (chat.messages[i].role === "user") { lastUser = chat.messages[i]; break; }
    }
    if (!lastUser) return;
    setSending(true);
    announceStatus("AI Tutor is thinking…");
    const typingEl = showTyping();
    let replyObj = null, failed = false;
    try { replyObj = await aiRespond(lastUser.text, chat, lastUser.image || null); }
    catch (err) { failed = true; }
    typingEl.remove();
    setSending(false);
    if (failed) {
      announceStatus("The AI Tutor could not prepare an answer.");
      showSendError(() => answerLastUserMessage(chat, opts));
      return;
    }
    chat.messages.push({ role: "assistant", text: replyObj.text, quick: replyObj.quick, journalHTML: replyObj.journalHTML, sectionsHTML: replyObj.sectionsHTML, sources: replyObj.sources, engine: replyObj.engine, ts: Date.now() });
    chat.updatedAt = Date.now();
    saveState();
    renderMessages();
    renderHistoryList();
    renderContextBadge();
    announceStatus("AI Tutor replied.");
    // Launching from an "Ask AI" button must not move XP (the student only clicked a help button);
    // XP is still given for messages the student types themselves, as before.
    /* XP for typed questions is capped at 5 per calendar day — asking
       is always free, but re-asking can't farm XP. The cap message
       fires once per day, and a capped message grants nothing (so no
       reward toast appears). */
    if (!opts.noXP) {
      if (xpBumpDaily("ai-tutor", 5)) {
        addXP(1, "Asked the AI Tutor");
      } else if (UIF.awardDaily(STATE.xpOnce, "ai-tutor-cap-hint", Date.now())) {
        saveState();
        toast("Today's tutor XP is used up (5 questions) — keep asking, the tutor still answers.", "info", "sparkles");
      }
      playSuccessSound();
    }
  }

  async function sendMessage(textArg, sendOpts) {
    sendOpts = sendOpts || {};
    const input = $("#aiInput");
    const text = (textArg !== undefined ? textArg : input.value).trim();
    if (!text && !pendingImage) {
      // Input validation: an empty send gives gentle feedback instead of
      // silently doing nothing.
      if (textArg === undefined) { toast("Type your question first", "info", "message-square"); input.focus(); }
      return;
    }
    if (aiSending) return;   // one reply at a time
    let chat = aiGetActiveChat();
    if (!chat) chat = aiNewChat(aiDetectChapter(text));
    if (!chat.chapterContext) chat.chapterContext = aiDetectChapter(text);

    chat.messages.push({ role: "user", text, image: pendingImage, ts: Date.now() });
    if (chat.messages.length === 1) chat.title = chat.attachedQuestion ? aiTitleFromText(`${chat.attachedQuestion.section}: ${chat.attachedQuestion.text}`) : aiTitleFromText(text || "Image question");
    chat.updatedAt = Date.now();
    saveState();
    input.value = ""; input.style.height = "auto";
    pendingImage = null;
    $("#aiImagePreview").hidden = true;
    renderMessages();
    renderHistoryList();
    renderContextBadge();

    await answerLastUserMessage(chat, sendOpts);
  }

  function renderAll() {
    renderContextBadge();
    renderHistoryList();
    renderMessages();
  }

  function openHistoryDrawer() { $("#aiHistoryDrawer").classList.add("open"); $("#aiHistoryOverlay").hidden = false; }
  function closeHistoryDrawer() { $("#aiHistoryDrawer").classList.remove("open"); $("#aiHistoryOverlay").hidden = true; }
  $("#aiHistoryToggle").addEventListener("click", openHistoryDrawer);
  $("#aiHistoryClose").addEventListener("click", closeHistoryDrawer);
  $("#aiHistoryOverlay").addEventListener("click", closeHistoryDrawer);

  $("#aiNewChatBtn").addEventListener("click", () => {
    aiNewChat(aiDetectChapter(window.location.hash.replace("#", "")));
    renderAll();
    closeHistoryDrawer();
  });

  $("#aiClearBtn").addEventListener("click", async () => {
    const chat = aiGetActiveChat();
    if (!chat || (!chat.messages.length && !chat.attachedQuestion)) { toast("Nothing to clear", "info", "info"); return; }
    if (!(await uiConfirm("This empties the current conversation (and detaches any attached question).", { title: "Clear this conversation?", confirmLabel: "Clear" }))) return;
    chat.messages = []; chat.attachedQuestion = null; chat.cstate = null; chat.lastPattern = null; chat.pendingPractice = null; chat.pendingProblem = null; chat.lastComputed = null;
    chat.answerMode = null;
    chat.title = "New chat"; chat.updatedAt = Date.now();
    saveState(); renderAll();
  });

  const input = $("#aiInput");
  input.addEventListener("input", () => { input.style.height = "auto"; input.style.height = Math.min(input.scrollHeight, 140) + "px"; });
  input.addEventListener("keydown", (e) => {
    // Don't send while an IME (Japanese / Chinese / Korean) candidate
    // window is open — Enter confirms the composition there.
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); }
  });
  $("#aiSendBtn").addEventListener("click", () => sendMessage());

  $("#aiImageBtn").addEventListener("click", () => $("#aiImageInput").click());
  $("#aiImageInput").addEventListener("change", (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 8 * 1024 * 1024) { toast("Image is too large — please use one under 8MB", "error", "alert-circle"); return; }
    const reader = new FileReader();
    reader.onload = () => {
      pendingImage = reader.result;
      $("#aiImagePreviewImg").src = pendingImage;
      $("#aiImagePreview").hidden = false;
    };
    reader.readAsDataURL(file);
  });
  $("#aiImageRemove").addEventListener("click", () => { pendingImage = null; $("#aiImagePreview").hidden = true; $("#aiImageInput").value = ""; });

  // Auto-detect chapter context from wherever the user came from (e.g. a
  // chapter page), so a brand-new chat can greet them appropriately.
  if (!aiGetActiveChat()) {
    const lastChapter = STATE.lastChapterViewed;
    if (aiGetChats().length === 0 && lastChapter) {
      // Don't auto-create a chat — just remember context for the next one sent.
    }
  }

  renderAll();

  // If the student arrived here via an "Ask AI about this" contextual
  // button (from a question card, a mistake, etc.), send that prompt
  // automatically so the AI Tutor feels like part of the page they came
  // from, not a separate cold-start chatbot.
  if (PENDING_AI_QUESTION) {
    // Launched from a question's "Ask AI" button: the question is already attached to this chat
    // (context card above), so just ask — no copy/paste needed, and no XP is awarded for the click.
    PENDING_AI_QUESTION = null;
    const hintMode = (aiGetActiveChat() && aiGetActiveChat().answerMode) === "hint";
    const fromMistake = !!(aiGetActiveChat() && aiGetActiveChat().attachedQuestion && aiGetActiveChat().attachedQuestion.studentAnswer);
    setTimeout(() => sendMessage(fromMistake ? "Why was my answer wrong?" : hintMode ? "Give me a hint for this question." : "Please solve this question step by step.", { noXP: true }), 120);
  } else if (PENDING_AI_PROMPT) {
    const prompt = PENDING_AI_PROMPT;
    PENDING_AI_PROMPT = null;
    setTimeout(() => sendMessage(prompt), 120);
  }
}

// Track the last chapter a person viewed, so a fresh AI Tutor chat can
// greet them with the right context ("You're currently studying Journal…").
// v83 — derived from the chapter registry, so Class 12 chapters track too.
(function trackLastChapter() {
  window.addEventListener("hashchange", () => {
    const route = window.location.hash.replace("#", "");
    if (route.indexOf("ch-") === 0) {
      const id = route.slice(3);
      if (ClassRegistry.classOfChapterId(id)) STATE.lastChapterViewed = id;
    }
  });
})();

/* ---------------------------------------------------------
   15. STUDY-TIME TRACKER (background, saves periodically)
   --------------------------------------------------------- */
setInterval(() => { STATE.studySeconds++; }, 1000);
setInterval(saveState, 15000);
window.addEventListener("beforeunload", saveState);

/* ---------------------------------------------------------
   15b. CLASS 12 CHAPTER RENDERER (v83)
   One data-driven renderer for all thirteen Class 12 chapters.
   It reuses every shared system the Class 11 chapters use (theory
   blocks, mind maps, quick revision, practice-bank cards, XP,
   Mistake Book, bookmarks, Ask-AI, mobile pager, section nav) and
   adds five deterministic activity engines — each chapter picks
   one engine in its content data, so every chapter gets a unique
   interactive activity with verified checking.

   Content schema (see data-12.js register() docs):
     content[chId] = {
       theory: { simple: [blocks], advanced: [blocks] },
       concepts: [{ title, body }],
       formats: [{ title, note?, head: [...], rows: [[...]] }],
       numericals: [{ id, difficulty, q, options, answerIndex, explanation }],
       activity: { type, title, instruction, ...engine fields },
       quickRevision: { ... }
     }
   Activity engine types: "journal" | "calc" | "statement" |
   "classify" | "match".
   --------------------------------------------------------- */
function c12ContentOf(chId) { return APP_DATA[chId] || C12_DATA.content[chId] || {}; }

function c12ParseNum(v) {
  const n = parseFloat(String(v == null ? "" : v).replace(/[^0-9.\-]/g, ""));
  return isFinite(n) ? n : NaN;
}
/* Money answers tolerate a paise-level slip; ratio answers tolerate
   one hundredth. Both defaults can be overridden per problem. */
function c12NumOk(got, want, tol) {
  if (!isFinite(got) || typeof want !== "number") return false;
  const t = (tol == null) ? Math.max(0.011, Math.abs(want) * 0.01) : tol;
  return Math.abs(got - want) <= t;
}

/* Per-tab, per-chapter transient state (reset when the chapter or
   data reference changes — the same pattern the Class 11 activities
   use, so a re-render never resurrects stale answers). */
let c12PBState = { chId: null, diff: "All" };
let c12ActState = { chId: null, ref: null };

/* One-XP-per-activity completion gate: the awarded registry lives in
   STATE.c12Activities so a revisit never farms XP again. */
function c12ActivityAwarded(meta, act, solved, total) {
  if (solved < total) return;
  const first = !STATE.c12Activities[meta.id];
  STATE.c12Activities[meta.id] = true;
  if (first) {
    addXP(15, `${meta.name} — ${act.title} completed`);
    toast(`${act.title} completed — +15 XP`, "xp", "puzzle");
    playSuccessSound();
  }
  logActivity({
    type: "activity", key: "c12act|" + meta.id,
    text: `${act.title} completed in ${meta.name}`,
    route: "ch-" + meta.id, tab: act.title, status: "completed"
  });
  saveState();
}

function renderC12Chapter(root) {
  const chId = String(currentRoute() || "").split("?")[0].replace(/^ch-/, "");
  const meta = ClassRegistry.chapterMeta(chId);
  if (!meta || ClassRegistry.classOfChapterId(chId) !== ClassRegistry.CLASS_12) {
    root.appendChild(el("div", "hero", `
      <span class="hero-eyebrow">Class 12</span>
      <h1>Chapter not found</h1>
      <p>This route does not match a Class 12 chapter. Head back to the chapter list to pick one.</p>
    `));
    const back = el("button", "btn-primary ripple-surface", `<i data-lucide="arrow-left"></i> Back to Chapters`);
    back.addEventListener("click", () => navigate("chapters-list"));
    root.appendChild(back);
    icons();
    return;
  }
  const data = c12ContentOf(chId);
  const accent = meta.color || "var(--ink)";
  const soft = chapterSoftVar(chId);

  root.appendChild(el("div", "hero", `
    <span class="hero-eyebrow">Class 12 · Chapter ${meta.num} · ${escapeHtml(meta.unit || "")}</span>
    <h1>${escapeHtml(meta.name)}</h1>
    <p>${escapeHtml(meta.tagline)}. Notes, mind map, practice bank, ${escapeHtml(((data.activity || {}).title) || "interactive activity")} and quick revision — aligned to the CBSE Class 12 Accountancy course for session 2026–27.</p>
  `));

  const activityName = (data.activity && data.activity.title) ? data.activity.title : "Activity Lab";
  const tabs = ["Introduction", "Theory", "Formulas & Rules", "Mind Map", "Practice Bank", activityName, "Quick Revision"];
  const tabBar = el("div", "", "");
  tabBar.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; margin-bottom:22px;";
  tabs.forEach((t, i) => {
    const chip = el("button", `chip ${i === 0 ? "active" : ""}`, escapeHtml(t));
    chip.dataset.tab = t;
    tabBar.appendChild(chip);
  });
  const journeyEl = renderJourneyStepper(root, chId);
  root.appendChild(tabBar);
  const panel = el("div", "");
  root.appendChild(panel);

  function showTab(name) {
    $all(".chip", tabBar).forEach(c => c.classList.toggle("active", c.dataset.tab === name));
    panel.innerHTML = "";
    updateJourneyStepper(journeyEl, chId, name);
    try {
      if (name === "Introduction") c12Intro(panel, data, meta);
      else if (name === "Theory") c12Theory(panel, data, meta);
      else if (name === "Formulas & Rules") c12Formats(panel, data, meta);
      else if (name === "Mind Map") renderMindMap(panel, chId);
      else if (name === "Practice Bank") c12PracticeBank(panel, data, meta);
      else if (name === activityName) c12Activity(panel, data, meta, name);
      else if (name === "Quick Revision") c12QuickRevision(panel, data, meta);
    } catch (err) {
      console.error("C12 tab render failed:", name, err);
      panel.appendChild(el("p", "", "This section could not be displayed. Try reloading the page."));
    }
    icons();
  }
  tabBar.addEventListener("click", e => {
    const chip = e.target.closest(".chip");
    if (chip) showTab(chip.dataset.tab);
  });
  showTab("Introduction");
}

function c12Intro(panel, data, meta) {
  panel.appendChild(sectionTitle("Meaning & fundamentals"));
  const simple = (data.theory && data.theory.simple) || data.intro || [];
  if (simple.length) renderCashBookTheoryBlocks(panel, simple, meta.color || "var(--ink)", chapterSoftVar(meta.id));
  else panel.appendChild(el("p", "", "Notes for this chapter are being prepared."));
  if (Array.isArray(data.concepts) && data.concepts.length) {
    panel.appendChild(sectionTitle("Key concepts at a glance"));
    const grid = el("div", "grid-3");
    data.concepts.forEach(c => {
      const card = el("div", "card liftable", "");
      card.style.padding = "22px";
      card.innerHTML = `<h4 style="font-size:1rem; margin-bottom:8px; color:${meta.color || "var(--ink)"};">${c.title}</h4><p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${c.body}</p>`;
      grid.appendChild(card);
    });
    panel.appendChild(grid);
  }
}

function c12Theory(panel, data, meta) {
  panel.appendChild(sectionTitle("Detailed theory & adjustments"));
  const adv = (data.theory && data.theory.advanced) || [];
  if (adv.length) renderCashBookTheoryBlocks(panel, adv, meta.color || "var(--ink)", chapterSoftVar(meta.id));
  else panel.appendChild(el("p", "", "Detailed theory for this chapter is being prepared."));
}

function c12Formats(panel, data, meta) {
  panel.appendChild(sectionTitle("Formats, formulas & rules"));
  const formats = data.formats || (typeof C12_DATA !== "undefined" && C12_DATA.formulas && C12_DATA.formulas[meta.id]) || [];
  if (!formats.length) { panel.appendChild(el("p", "", "No formats for this chapter — it is a theory chapter.")); return; }
  const hint = el("p", "", "Each structure below follows the standard board presentation. Scan or print this tab the day before an exam.");
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px;";
  panel.appendChild(hint);
  formats.forEach(fmt => {
    const card = el("div", "card-solid", "");
    card.style.cssText = "padding:22px; margin-bottom:16px;";
    const head = Array.isArray(fmt.head) ? fmt.head : ["Item", "Detail"];
    const rows = (fmt.rows || []).map(r => {
      const cells = Array.isArray(r) ? r : [r];
      return `<tr>${cells.map(c => `<td style="padding:7px 10px; border-bottom:1px solid var(--line); font-size:0.85rem; color:var(--ink-soft);">${c == null ? "" : c}</td>`).join("")}</tr>`;
    }).join("");
    card.innerHTML = `
      <h4 style="font-size:1rem; margin-bottom:6px; color:${meta.color || "var(--ink)"};">${fmt.title || "Format"}</h4>
      ${fmt.note ? `<p style="font-size:0.83rem; color:var(--ink-faint); margin-bottom:10px;">${fmt.note}</p>` : ""}
      <div style="overflow-x:auto;">
        <table class="ledger-table" style="width:100%;">
          <thead><tr>${head.map(h => `<th>${h}</th>`).join("")}</tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>`;
    panel.appendChild(card);
  });
}

function c12QuickRevision(panel, data, meta) {
  renderQuickRevision(panel, data, { accent: meta.color || "var(--ink)", soft: chapterSoftVar(meta.id) });
  if (!data.quickRevision) panel.appendChild(el("p", "", "Quick revision for this chapter is being prepared."));
}

/* ---- Practice bank — the same card UX as the Class 11 banks:
   difficulty filter, option chips, Check, explanation reveal, solved
   mark, bookmark, Ask-AI, XP (+4 / −1 penalty), Mistake Book. ---- */
function c12PracticeBank(panel, data, meta) {
  const qs = Array.isArray(data.numericals) ? data.numericals : [];
  panel.appendChild(sectionTitle(`${meta.short || meta.name} practice bank`));
  if (!qs.length) {
    panel.appendChild(el("p", "", "Practice questions for this chapter are being prepared."));
    return;
  }
  if (c12PBState.chId !== meta.id) c12PBState = { chId: meta.id, diff: "All" };
  const hint = el("p", "", `${qs.length} questions drawn from this chapter. Pick the correct option, then check your answer for a full explanation.`);
  hint.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin:-8px 0 18px; line-height:1.6;";
  panel.appendChild(hint);

  const filterBar = el("div", "", "");
  filterBar.style.cssText = "display:flex; gap:8px; margin-bottom:18px; flex-wrap:wrap;";
  ["All", "Easy", "Medium", "Hard"].forEach(d => {
    const chip = el("button", `chip ${d === c12PBState.diff ? "active" : ""}`, d);
    chip.addEventListener("click", () => { c12PBState.diff = d; c12PracticeBank(panel, data, meta); });
    filterBar.appendChild(chip);
  });
  panel.appendChild(filterBar);

  const list = qs.filter(q => c12PBState.diff === "All" || q.difficulty === c12PBState.diff);
  const countLabel = el("p", "", `Showing ${list.length} of ${qs.length} questions`);
  countLabel.style.cssText = "font-size:0.83rem; color:var(--ink-faint); margin-bottom:16px;";
  panel.appendChild(countLabel);

  list.forEach(q => {
    const solvedKey = `${meta.id}-${q.id}`;
    const alreadySolved = STATE.solved[solvedKey];
    let picked = null;
    const shuffledOrder = fisherYatesShuffle(q.options.map((_, i) => i));

    const card = el("div", "card q-card", "");
    card.innerHTML = `
      <div class="q-meta">
        <span class="diff-badge ${q.difficulty}">${q.difficulty}</span>
        <span class="q-id">Q${q.id}</span>
        ${alreadySolved ? `<span style="margin-left:auto; color:${meta.color || "var(--ink)"}; font-size:0.78rem; display:flex; align-items:center; gap:4px;"><i data-lucide="check-circle" style="width:13px;height:13px;"></i> Solved</span>` : ""}
        ${bookmarkButtonHTML(solvedKey, alreadySolved ? "" : "margin-left:auto;")}
      </div>
      <div class="q-body">${q.q || q.question}</div>
      <div style="margin-top:14px;">
        <div class="opt-group" data-role="answer" style="display:flex; flex-wrap:wrap; gap:8px;">
          ${shuffledOrder.map(i => `<button class="chip" data-val="${i}">${q.options[i]}</button>`).join("")}
        </div>
      </div>
      <div class="q-actions" style="margin-top:14px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Answer</button>
        ${aiAskBtn(`${meta.id}.numericals`, q)}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);

    card.addEventListener("click", (e) => {
      const optBtn = e.target.closest(".opt-group button[data-val]");
      if (optBtn) {
        const group = optBtn.closest(".opt-group");
        $all("button", group).forEach(b => b.classList.remove("active"));
        optBtn.classList.add("active");
        picked = parseInt(optBtn.dataset.val, 10);
        return;
      }
      const bookmarkBtn = e.target.closest("button[data-act='bookmark']");
      if (bookmarkBtn) { toggleBookmark(solvedKey, bookmarkBtn); return; }
      const checkBtn = e.target.closest("button[data-act='check']");
      if (checkBtn) {
        if (picked === null) {
          revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Pick an option first.</p></div>`;
          return;
        }
        const correct = picked === q.answerIndex;
        if (correct) {
          revealArea.innerHTML = `
            <div class="reveal-block">
              <h4>Correct!</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${q.explanation}</p>
            </div>`;
          playSuccessSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: true, attempts: 1 };
            saveState(); addXP(4, `${meta.name} Q${q.id} solved`);
            logActivity({ type: "practice", key: `c12q|${solvedKey}`, text: `${meta.name} Q${q.id} solved (${q.difficulty})`, route: "ch-" + meta.id, tab: "Practice Bank", qid: q.id, difficulty: q.difficulty, status: "solved" });
            refreshProgress();
          }
          mistakeBookRecordCorrect(solvedKey);
        } else {
          revealArea.innerHTML = `
            <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
              <h4>Not quite</h4>
              <p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">The correct answer is: <b>${q.options[q.answerIndex]}</b>.<br>${q.explanation}</p>
            </div>`;
          playErrorSound();
          if (!STATE.solved[solvedKey]) {
            STATE.solved[solvedKey] = { correct: false, attempts: 1 };
            if (!STATE.mistakes.includes(solvedKey)) STATE.mistakes.push(solvedKey);
            saveState(); addXP(-XP_WRONG_PENALTY, `Q${q.id} incorrect`); refreshProgress();
          }
          mistakeBookRecord({
            key: solvedKey, question: q.q || q.question, chapter: meta.id, chapterLabel: meta.name,
            topic: meta.name, type: `${meta.short || meta.name} Practice`,
            studentAnswer: q.options[picked],
            correctAnswer: q.options[q.answerIndex],
            explanation: q.explanation
          });
        }
        icons();
      }
    });
    panel.appendChild(card);
  });
  applyMobilePager(panel);
  icons();
}

/* ---- Activity dispatcher + shared completion chrome ---- */
function c12Activity(panel, data, meta, tabName) {
  const act = data.activity;
  if (!act || !act.type) {
    panel.appendChild(sectionTitle("Interactive activity"));
    panel.appendChild(el("p", "", "This chapter's activity is being prepared."));
    return;
  }
  panel.appendChild(sectionTitle(act.title || "Interactive activity"));
  if (act.instruction) {
    const ins = el("p", "", act.instruction);
    ins.style.cssText = "font-size:0.86rem; color:var(--ink-soft); line-height:1.65; margin:-6px 0 18px;";
    panel.appendChild(ins);
  }
  /* Reset transient state when the chapter (or the data object it
     points at) changes, so answers never leak across chapters. */
  if (c12ActState.chId !== meta.id || c12ActState.ref !== act) {
    c12ActState = { chId: meta.id, ref: act };
  }
  const progress = el("p", "", "");
  progress.className = "c12-act-progress";
  progress.style.cssText = "font-size:0.85rem; color:var(--ink-faint); margin-bottom:16px;";
  panel.appendChild(progress);
  const body = el("div", "");
  panel.appendChild(body);

  const engines = {
    journal: c12JournalLab,
    calc: c12CalcLab,
    statement: c12StatementLab,
    classify: c12ClassifyLab,
    match: c12MatchLab
  };
  const engine = engines[act.type];
  if (!engine) {
    body.appendChild(el("p", "", "Unknown activity type — please update the app."));
    return;
  }
  engine(body, act, meta, progress);
}

/* Engine 1 — Journal Lab: build each entry (Dr account, Cr account,
   amount) and check it against the author's answer key. */
function c12JournalLab(body, act, meta, progress) {
  const entries = act.entries || [];
  const solvedFlags = new Array(entries.length).fill(false);
  const refresh = () => {
    progress.textContent = `Entries verified: ${solvedFlags.filter(Boolean).length} of ${entries.length}`;
    if (solvedFlags.every(Boolean)) c12ActivityAwarded(meta, act, entries.length, entries.length);
  };
  entries.forEach((en, i) => {
    const card = el("div", "card q-card", "");
    card.style.marginBottom = "14px";
    let pickedDr = null, pickedCr = null;
    card.innerHTML = `
      <div class="q-meta"><span class="q-id">Entry ${i + 1}</span>
        <span class="entry-state" style="margin-left:auto; font-size:0.78rem;"></span></div>
      <div class="q-body">${en.prompt}</div>
      <p style="font-size:0.78rem; text-transform:uppercase; color:var(--ink-faint); margin:12px 0 6px;">Debit account</p>
      <div class="opt-group" data-role="dr" style="display:flex; flex-wrap:wrap; gap:8px;">
        ${(en.dr || []).map(a => `<button class="chip" data-val="${a}">${a}</button>`).join("")}
      </div>
      <p style="font-size:0.78rem; text-transform:uppercase; color:var(--ink-faint); margin:12px 0 6px;">Credit account</p>
      <div class="opt-group" data-role="cr" style="display:flex; flex-wrap:wrap; gap:8px;">
        ${(en.cr || []).map(a => `<button class="chip" data-val="${a}">${a}</button>`).join("")}
      </div>
      <div style="display:flex; align-items:center; gap:10px; margin-top:12px; flex-wrap:wrap;">
        <label style="font-size:0.8rem; color:var(--ink-faint);">Amount (₹)</label>
        <input type="text" class="c12-amt" inputmode="decimal" placeholder="e.g. 12000"
          style="width:130px; padding:8px 10px; border:1px solid var(--line); border-radius:8px; background:var(--paper-raised); color:var(--ink); font-size:0.88rem;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Entry</button>
        ${aiAskBtn(`${meta.id}.activity`, en, { chapterId: meta.id, index: i + 1 })}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);
    const stateTag = $(".entry-state", card);
    if (solvedFlags[i]) { stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Verified</span>`; }
    card.addEventListener("click", (e) => {
      const optBtn = e.target.closest(".opt-group button[data-val]");
      if (optBtn) {
        const group = optBtn.closest(".opt-group");
        $all("button", group).forEach(b => b.classList.remove("active"));
        optBtn.classList.add("active");
        if (group.dataset.role === "dr") pickedDr = optBtn.dataset.val; else pickedCr = optBtn.dataset.val;
        return;
      }
      const checkBtn = e.target.closest("button[data-act='check']");
      if (!checkBtn) return;
      if (!pickedDr || !pickedCr) {
        revealArea.innerHTML = `<div class="reveal-block hint-block"><p style="font-size:0.86rem;">Select both the debit and the credit account first.</p></div>`;
        return;
      }
      const amt = c12ParseNum($(".c12-amt", card).value);
      const ok = pickedDr === en.drAccount && pickedCr === en.crAccount && c12NumOk(amt, en.amount, 0.51);
      if (ok) {
        revealArea.innerHTML = `
          <div class="reveal-block"><h4>Correct entry!</h4>
          <p style="font-size:0.87rem; line-height:1.7; color:var(--ink-soft);">
            <b>Dr ${en.drAccount}</b> &nbsp;&nbsp;&nbsp; ₹${en.amount}<br>
            &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>To ${en.crAccount}</b> &nbsp;&nbsp;&nbsp; ₹${en.amount}</p>
          ${en.note ? `<p style="font-size:0.83rem; color:var(--ink-faint); margin-top:8px;">${en.note}</p>` : ""}</div>`;
        playSuccessSound();
        stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Verified</span>`;
        if (!solvedFlags[i]) { solvedFlags[i] = true; refresh(); }
      } else {
        const fixes = [];
        if (pickedDr !== en.drAccount) fixes.push(`Debit should be <b>${en.drAccount}</b>.`);
        if (pickedCr !== en.crAccount) fixes.push(`Credit should be <b>${en.crAccount}</b>.`);
        if (!c12NumOk(amt, en.amount, 0.51)) fixes.push(`Amount should be <b>₹${en.amount}</b>.`);
        revealArea.innerHTML = `
          <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
            <h4>Not yet</h4><p style="font-size:0.87rem; line-height:1.6; color:var(--ink-soft);">${fixes.join(" ")}</p></div>`;
        playErrorSound();
      }
      icons();
    });
    body.appendChild(card);
  });
  refresh();
}

/* Engine 2 — Calculation Bench: numeric problems with formula hints;
   every field is checked against the answer key within tolerance. */
function c12CalcLab(body, act, meta, progress) {
  const problems = act.problems || [];
  const solvedFlags = new Array(problems.length).fill(false);
  const refresh = () => {
    progress.textContent = `Problems solved: ${solvedFlags.filter(Boolean).length} of ${problems.length}`;
    if (solvedFlags.every(Boolean)) c12ActivityAwarded(meta, act, problems.length, problems.length);
  };
  problems.forEach((pr, i) => {
    const card = el("div", "card q-card", "");
    card.style.marginBottom = "14px";
    const inputs = (pr.inputs || []).map(inp =>
      `<label style="display:flex; align-items:center; gap:8px; font-size:0.85rem; color:var(--ink-soft);">
        <span style="min-width:170px;">${inp.label}</span>
        <input type="text" data-key="${inp.key}" inputmode="decimal" placeholder="${inp.placeholder || "₹ / number"}"
          style="width:120px; padding:8px 10px; border:1px solid var(--line); border-radius:8px; background:var(--paper-raised); color:var(--ink); font-size:0.88rem;">
      </label>`).join("");
    card.innerHTML = `
      <div class="q-meta"><span class="q-id">Problem ${i + 1}</span>
        <span class="entry-state" style="margin-left:auto; font-size:0.78rem;"></span></div>
      <div class="q-body">${pr.prompt}</div>
      <div style="display:flex; flex-direction:column; gap:10px; margin-top:12px;">${inputs}</div>
      ${pr.formula ? `<p style="font-size:0.83rem; color:var(--ink-faint); margin-top:10px;">Formula: <span class="tnum">${pr.formula}</span></p>` : ""}
      <div class="q-actions" style="margin-top:12px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check</button>
        ${aiAskBtn(`${meta.id}.activity`, pr, { chapterId: meta.id, index: i + 1 })}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);
    const stateTag = $(".entry-state", card);
    if (solvedFlags[i]) stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Solved</span>`;
    card.addEventListener("click", (e) => {
      const checkBtn = e.target.closest("button[data-act='check']");
      if (!checkBtn) return;
      const fields = $all("input[data-key]", card);
      const wrong = [];
      fields.forEach(f => {
        const want = (pr.answers || {})[f.dataset.key];
        if (want == null) return;
        if (!c12NumOk(c12ParseNum(f.value), want, pr.tolerance)) wrong.push(f.dataset.key);
      });
      if (!fields.length || wrong.length) {
        const bad = (pr.inputs || []).filter(inp => wrong.indexOf(inp.key) !== -1).map(inp => inp.label);
        revealArea.innerHTML = `
          <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
            <h4>Recheck ${bad.length ? bad.join(", ") : "your answers"}</h4>
            <p style="font-size:0.85rem; color:var(--ink-soft);">Re-enter the highlighted figures and check again — the working steps are shown once every figure is right.</p></div>`;
        playErrorSound();
      } else {
        revealArea.innerHTML = `
          <div class="reveal-block"><h4>All figures correct 🎯</h4>
          ${pr.working ? `<p style="font-size:0.87rem; line-height:1.7; color:var(--ink-soft);">${pr.working}</p>` : ""}
          ${pr.note ? `<p style="font-size:0.83rem; color:var(--ink-faint); margin-top:8px;">${pr.note}</p>` : ""}</div>`;
        playSuccessSound();
        stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Solved</span>`;
        if (!solvedFlags[i]) { solvedFlags[i] = true; refresh(); }
      }
      icons();
    });
    body.appendChild(card);
  });
  refresh();
}

/* Engine 3 — Statement Builder: choose each line's treatment (and
   amount where asked), assemble the statement, then verify. */
function c12StatementLab(body, act, meta, progress) {
  const statements = act.statements || [];
  let solvedCount = 0;
  const solvedFlags = new Array(statements.length).fill(false);
  const refresh = () => {
    progress.textContent = `Statements built: ${solvedFlags.filter(Boolean).length} of ${statements.length}`;
    if (solvedFlags.every(Boolean)) c12ActivityAwarded(meta, act, statements.length, statements.length);
  };
  statements.forEach((st, i) => {
    const card = el("div", "card q-card", "");
    card.style.marginBottom = "14px";
    const rowsHtml = (st.rows || []).map((r, ri) => `
      <tr data-row="${ri}">
        <td style="padding:8px 10px; border-bottom:1px solid var(--line); font-size:0.86rem;">${r.label}</td>
        <td style="padding:8px 10px; border-bottom:1px solid var(--line);">
          <div class="opt-group" data-role="treat" style="display:flex; flex-wrap:wrap; gap:6px;">
            ${(r.options || ["Add", "Less", "Ignore"]).map(o => `<button class="chip sm" data-val="${o}">${o}</button>`).join("")}
          </div>
        </td>
        ${st.needsAmount ? `<td style="padding:8px 10px; border-bottom:1px solid var(--line);">
          <input type="text" inputmode="decimal" placeholder="₹" data-amt
            style="width:100px; padding:7px 9px; border:1px solid var(--line); border-radius:8px; background:var(--paper-raised); color:var(--ink); font-size:0.85rem;"></td>` : ""}
      </tr>`).join("");
    const headCells = st.needsAmount ? ["Line item", "Treatment", "Amount (₹)"] : (st.head || ["Line item", "Treatment"]);
    card.innerHTML = `
      <div class="q-meta"><span class="q-id">${st.title || "Statement " + (i + 1)}</span>
        <span class="entry-state" style="margin-left:auto; font-size:0.78rem;"></span></div>
      ${st.prompt ? `<div class="q-body">${st.prompt}</div>` : ""}
      <div style="overflow-x:auto; margin-top:10px;">
        <table class="ledger-table" style="width:100%;">
          <thead><tr>${headCells.map(h => `<th>${h}</th>`).join("")}</tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>
      <div class="q-actions" style="margin-top:12px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Verify Statement</button>
        ${aiAskBtn(`${meta.id}.activity`, st, { chapterId: meta.id, index: i + 1 })}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);
    const stateTag = $(".entry-state", card);
    if (solvedFlags[i]) stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Verified</span>`;
    card.addEventListener("click", (e) => {
      const optBtn = e.target.closest(".opt-group button[data-val]");
      if (optBtn) {
        const group = optBtn.closest(".opt-group");
        $all("button", group).forEach(b => b.classList.remove("active"));
        optBtn.classList.add("active");
        return;
      }
      const checkBtn = e.target.closest("button[data-act='check']");
      if (!checkBtn) return;
      const trs = $all("tbody tr", card);
      const wrong = [];
      trs.forEach((tr, ri) => {
        const r = (st.rows || [])[ri];
        if (!r) return;
        const active = $(".opt-group button.active", tr);
        if (!active || active.dataset.val !== r.answer) wrong.push(`${r.label} → ${r.answer}`);
        if (st.needsAmount && r.amount != null) {
          const inp = $("input[data-amt]", tr);
          if (!c12NumOk(c12ParseNum(inp && inp.value), r.amount, 0.51)) wrong.push(`${r.label} = ₹${r.amount}`);
        }
      });
      if (wrong.length) {
        revealArea.innerHTML = `
          <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
            <h4>Not yet — check these lines</h4>
            <p style="font-size:0.85rem; line-height:1.7; color:var(--ink-soft);">${wrong.join("<br>")}</p></div>`;
        playErrorSound();
      } else {
        revealArea.innerHTML = `
          <div class="reveal-block"><h4>Statement verified ✅</h4>
          ${st.working ? `<p style="font-size:0.87rem; line-height:1.7; color:var(--ink-soft);">${st.working}</p>` : ""}</div>`;
        playSuccessSound();
        stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Verified</span>`;
        if (!solvedFlags[i]) { solvedFlags[i] = true; refresh(); }
      }
      icons();
    });
    body.appendChild(card);
  });
  refresh();
}

/* Engine 4 — Classifier: assign every item to its bucket. */
function c12ClassifyLab(body, act, meta, progress) {
  const sets = act.sets || [];
  const solvedFlags = new Array(sets.length).fill(false);
  const refresh = () => {
    progress.textContent = `Sets classified: ${solvedFlags.filter(Boolean).length} of ${sets.length}`;
    if (solvedFlags.every(Boolean)) c12ActivityAwarded(meta, act, sets.length, sets.length);
  };
  sets.forEach((set, i) => {
    const card = el("div", "card q-card", "");
    card.style.marginBottom = "14px";
    const rowsHtml = (set.items || []).map((it, ii) => `
      <tr data-item="${ii}">
        <td style="padding:9px 10px; border-bottom:1px solid var(--line); font-size:0.86rem;">${it.label}</td>
        <td style="padding:9px 10px; border-bottom:1px solid var(--line);">
          <select class="c12-bucket" style="width:100%; max-width:260px; padding:7px 9px; border:1px solid var(--line); border-radius:8px; background:var(--paper-raised); color:var(--ink); font-size:0.84rem;">
            <option value="">— choose —</option>
            ${(set.buckets || []).map(b => `<option value="${b}">${b}</option>`).join("")}
          </select>
        </td>
      </tr>`).join("");
    card.innerHTML = `
      <div class="q-meta"><span class="q-id">${set.title || "Set " + (i + 1)}</span>
        <span class="entry-state" style="margin-left:auto; font-size:0.78rem;"></span></div>
      ${set.prompt ? `<div class="q-body">${set.prompt}</div>` : ""}
      <div style="overflow-x:auto; margin-top:10px;">
        <table class="ledger-table" style="width:100%;">
          <thead><tr><th>Item</th><th>Classification</th></tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>
      <div class="q-actions" style="margin-top:12px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Classification</button>
        ${aiAskBtn(`${meta.id}.activity`, set, { chapterId: meta.id, index: i + 1 })}
      </div>
      <div class="reveal-area"></div>
    `;
    const revealArea = $(".reveal-area", card);
    const stateTag = $(".entry-state", card);
    if (solvedFlags[i]) stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Verified</span>`;
    card.addEventListener("click", (e) => {
      const checkBtn = e.target.closest("button[data-act='check']");
      if (!checkBtn) return;
      const trs = $all("tbody tr", card);
      const wrong = [];
      trs.forEach((tr, ii) => {
        const it = (set.items || [])[ii];
        if (!it) return;
        const sel = $(".c12-bucket", tr);
        if (!sel || sel.value !== it.bucket) wrong.push(`${it.label} → ${it.bucket}`);
      });
      if (wrong.length) {
        revealArea.innerHTML = `
          <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
            <h4>${wrong.length} to fix</h4>
            <p style="font-size:0.85rem; line-height:1.7; color:var(--ink-soft);">${wrong.join("<br>")}</p></div>`;
        playErrorSound();
      } else {
        revealArea.innerHTML = `
          <div class="reveal-block"><h4>Every item classified correctly 🎯</h4>
          ${set.working ? `<p style="font-size:0.87rem; line-height:1.7; color:var(--ink-soft);">${set.working}</p>` : ""}</div>`;
        playSuccessSound();
        stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Verified</span>`;
        if (!solvedFlags[i]) { solvedFlags[i] = true; refresh(); }
      }
      icons();
    });
    body.appendChild(card);
  });
  refresh();
}

/* Engine 5 — Match-Up: pair each left item with its right partner. */
function c12MatchLab(body, act, meta, progress) {
  const sets = act.sets || [];
  const solvedFlags = new Array(sets.length).fill(false);
  const refresh = () => {
    progress.textContent = `Sets matched: ${solvedFlags.filter(Boolean).length} of ${sets.length}`;
    if (solvedFlags.every(Boolean)) c12ActivityAwarded(meta, act, sets.length, sets.length);
  };
  sets.forEach((set, i) => {
    const pairs = set.pairs || [];
    const left = pairs.map(p => p.left);
    const right = fisherYatesShuffle(pairs.map(p => p.right));
    const links = {};        // leftIndex → rightIndex
    let selLeft = null;

    const card = el("div", "card q-card", "");
    card.style.marginBottom = "14px";
    card.innerHTML = `
      <div class="q-meta"><span class="q-id">${set.title || "Match-up " + (i + 1)}</span>
        <span class="entry-state" style="margin-left:auto; font-size:0.78rem;"></span></div>
      ${set.prompt ? `<div class="q-body">${set.prompt}</div>` : ""}
      <div class="c12-match-grid" style="display:grid; grid-template-columns:1fr 1fr; gap:20px; margin-top:12px;">
        <div class="c12-match-left" style="display:flex; flex-direction:column; gap:8px;"></div>
        <div class="c12-match-right" style="display:flex; flex-direction:column; gap:8px;"></div>
      </div>
      <div class="q-actions" style="margin-top:12px;">
        <button class="btn-primary sm ripple-surface" data-act="check"><i data-lucide="check"></i> Check Pairs</button>
        <button class="btn-ghost sm ripple-surface" data-act="reset">Clear</button>
        ${aiAskBtn(`${meta.id}.activity`, set, { chapterId: meta.id, index: i + 1 })}
      </div>
      <div class="reveal-area"></div>
    `;
    const leftCol = $(".c12-match-left", card);
    const rightCol = $(".c12-match-right", card);
    const revealArea = $(".reveal-area", card);
    const stateTag = $(".entry-state", card);
    if (solvedFlags[i]) stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Matched</span>`;

    function paint() {
      leftCol.innerHTML = "";
      rightCol.innerHTML = "";
      left.forEach((l, li) => {
        const linkedTo = links[li];
        const b = el("button", `chip ${selLeft === li ? "active" : ""}`, linkedTo != null ? `${l} ↔ ${right[linkedTo]}` : l);
        b.style.cssText = "text-align:left; justify-content:flex-start;";
        b.addEventListener("click", () => {
          if (linkedTo != null) { delete links[li]; }        // unlink on re-click
          selLeft = (selLeft === li) ? null : li;
          paint();
        });
        leftCol.appendChild(b);
      });
      right.forEach((r, ri) => {
        const used = Object.keys(links).some(k => links[k] === ri);
        const b = el("button", `chip ${used ? "c12-match-used" : ""}`, r);
        b.style.cssText = "text-align:left; justify-content:flex-start;" + (used ? "opacity:0.55;" : "");
        b.addEventListener("click", () => {
          if (selLeft === null) return;
          Object.keys(links).forEach(k => { if (links[k] === ri) delete links[k]; });
          links[selLeft] = ri;
          selLeft = null;
          paint();
        });
        rightCol.appendChild(b);
      });
      icons();
    }
    paint();

    card.addEventListener("click", (e) => {
      const checkBtn = e.target.closest("button[data-act='check']");
      if (checkBtn) {
        const wrong = [];
        left.forEach((l, li) => {
          if (links[li] == null || right[links[li]] !== pairs[li].right) wrong.push(l);
        });
        if (wrong.length) {
          revealArea.innerHTML = `
            <div class="reveal-block" style="background:var(--flag-soft); border-left-color:var(--flag);">
              <h4>${wrong.length} pair${wrong.length === 1 ? "" : "s"} still wrong</h4>
              <p style="font-size:0.85rem; color:var(--ink-soft);">Re-match: ${wrong.join(", ")}. Click a left item, then its right partner.</p></div>`;
          playErrorSound();
        } else {
          revealArea.innerHTML = `
            <div class="reveal-block"><h4>Every pair matches 🎯</h4>
            ${set.working ? `<p style="font-size:0.87rem; line-height:1.7; color:var(--ink-soft);">${set.working}</p>` : ""}</div>`;
          playSuccessSound();
          stateTag.innerHTML = `<span style="color:var(--c-ok);">✓ Matched</span>`;
          if (!solvedFlags[i]) { solvedFlags[i] = true; refresh(); }
        }
        icons();
        return;
      }
      const resetBtn = e.target.closest("button[data-act='reset']");
      if (resetBtn) {
        Object.keys(links).forEach(k => delete links[k]);
        selLeft = null;
        revealArea.innerHTML = "";
        paint();
      }
    });
    body.appendChild(card);
  });
  refresh();
}

/* ---------------------------------------------------------
   16. INIT
   --------------------------------------------------------- */
let preloaderFinished = false;
function finishPreloader() {
  if (preloaderFinished) return;
  preloaderFinished = true;
  const loader = $("#preloader");
  if (!loader) return;
  // The route has rendered, so the app is genuinely usable. Let the
  // first paint settle before revealing it instead of relying on a delay.
  requestAnimationFrame(() => requestAnimationFrame(() => loader.classList.add("hide")));
}

function setupBackToTop() {
  const button = $("#backToTop");
  if (!button) return;
  const update = () => {
    const visible = window.scrollY > 360;
    button.hidden = !visible;
    button.classList.toggle("show", visible);
  };
  window.addEventListener("scroll", update, { passive: true });
  button.addEventListener("click", () => window.scrollTo({ top: 0, behavior: STATE.reduceMotion ? "auto" : "smooth" }));
  update();
}

// A page cannot detect OS screenshots, external recorders, or phone
// captures. This only marks the page while this page itself uses the
// browser's display-capture API, which is the safe supported mechanism.
function setupCaptureWatermark() {
  const media = navigator.mediaDevices;
  const mark = $("#captureWatermark");
  if (!media || !mark || typeof media.getDisplayMedia !== "function") return;
  const original = media.getDisplayMedia.bind(media);
  media.getDisplayMedia = async function (...args) {
    const stream = await original(...args);
    mark.classList.add("capture-active");
    const clear = () => mark.classList.remove("capture-active");
    stream.getTracks().forEach(track => track.addEventListener("ended", clear, { once: true }));
    return stream;
  };
}

function init() {
  applyTheme();
  $("#xpCount").textContent = STATE.xp;
  refreshMistakeAlert();
  /* v83 — resolve the active class BEFORE anything renders: a saved
     choice is restored, a returning pre-v83 user is treated as the
     Class 11 student they always were, and a direct chapter link
     adopts its own class. A brand-new visitor stays undecided and is
     asked on home (see afterRouteRender → showClassSelector). */
  ensureClassForBoot();
  adoptClassFromRoute(currentRoute());
  refreshProgress();
  touchStreak();
  attachRipple(document.body);
  attachClickSound(document.body);
  setupBackToTop();
  setupCaptureWatermark();
  localReminderSchedule();   // fire today's local reminder if enabled and open past the hour
  /* v87 — reconcile push state honestly (browser is source of truth)
     and sync prefs/snapshot to the server when subscribed. Runs after
     touchStreak() so the snapshot carries today's streak. */
  if (window.ABAPush) ABAPush.onBoot();
  renderRoute();
  // Intro sound needs a user gesture on some browsers to unlock audio;
  // we attempt it immediately, and it will simply be silent (no error)
  // if the browser blocks autoplay-without-interaction — the very next
  // click anywhere re-attempts context resume via getAudioCtx().
  playIntroSound();
  /* v83 — sidebar class switcher + class-scoped chapter nav are built
     before the first route renders so the active class owns the whole
     shell from the very first paint. */
  const classSwitchHost = document.getElementById("classSwitchHost");
  if (classSwitchHost) buildClassSwitchBar(classSwitchHost);
  rebuildChapterNav();
  if (!STATE.userName && !needsClassSelection()) {
    // When the class selector owns the screen it chains this welcome
    // step itself once a class is chosen — never both at once.
    setTimeout(() => showWelcomeModal(), STATE.reduceMotion ? 400 : 900);
  }
}
document.addEventListener("DOMContentLoaded", init);
if (document.readyState !== "loading") init();
